export default [{"id":218,"question":"بعد معرفتنا لما يجب من زكاة الحُلِيّ المُعدَّة للزينة نرجو إيضاح الطريقة، فهل تُزكَّى بنصاب الذهب والفضَّة أو نصاب القيمة المالية؟ وجزاكم الله خيرًا","title":"ما نصاب زكاة الحُلِيّ المُعَدّ للزينة؟","answer":"الجواب: في وجوب الزكاة في الحُلِيّ خلافٌ بين العلماء، لكن الصواب أن فيه الزكاة إذا بلغ النِّصاب من الذهب والفضَّة، فإذا بلغ النصاب عشرين مثقالًا من الذهب، ومقداره بالجرام اثنان وتسعون جرامًا، ومقداره بالذهب بالجنيه السعودي العملة أحد عشر جنيهًا وثلاثة أسباع الجنيه، يعني: نصف جنيه؛ لأنَّ الكسر الذي بين الثلاثة أسباع والنصف يسير، فالنصف أوضح........، فإذا بلغ هذا المقدار وجبت فيه الزكاة، وهكذا إذا كان أكثر.\nثم الزكاة إن كان الذهبُ كثيرًا وأخرجها من الذهب؛ كفى، إذا كانت مثلًا زنةُ الحُلي أربعين جنيهًا، أخرج جنيهًا واحدًا وكفى، أو أخرج قيمة الجنيه، صرف الجنيه حسب سعر السوق بالعملة الورقية أو بالفضية وأخرج قيمته وكفى، فهو مُخيَّر: إذا كان الذهبُ يبلغ أربعين جنيهًا مثلًا ففيه جنيه واحد -ربع العشر- فإن شاء أخرج جنيهًا وأعطاه بعض الفقراء، وإن شاء أخرج القيمة من الورق ووزَّعها بين فقيرين أو أكثر.\nوهكذا لو كانت زنةُ الذهب ثمانين جنيهًا؛ وجب فيها جنيهان، فإن أخرجهما أو أخرج قيمتهما بالعملة حسب السعر ذلك الوقت؛ لا بأس.\nأما الألماس والجواهر الأخرى فليس فيها زكاة إذا كانت للبس، لا للتجارة، وإنما هذا في الذهب والفضَّة.","link":"https://binbaz.org.sa/fatwas/3999/ما-نصاب-زكاة-الحلي-المعد-للزينة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0225.mp3","categories":["زكاة النقدين"]},{"id":332,"question":"هل الذهب الذي تستعمله المرأةُ عليه زكاة، حتى ولو كان لا يوجد لديه مالٌ يُزكيه عنه، حيث إنه لا يدخر من راتبه الشَّهري؟","title":"حكم ومقدار زكاة الحلي المعد للزينة","answer":"الجواب: الصحيح: فيه الزكاة إذا بلغ النِّصاب، فيه خلافٌ بين العلماء، والصحيح أنَّ فيه زكاة –الذهب- سواء استُعمل أو ما استُعمل، والفضَّة كذلك فيها الزكاة على من يملكه من الرجال أو النساء إذا بلغ النِّصاب.\nوالنِّصاب عشرون مثقالًا، ومقداره بالعملة السعودية أحد عشر جنيهًا ونصفًا، سعودي، وبالجرام اثنان وتسعون جرامًا، فإذا بلغ هذا وجب أن يُزَكَّى، وإن كان لا يستعمل أو يستعمل كله واحد.\nأما الماس والجواهر النَّفيسة التي تُستعمل؛ فليس فيها زكاة إلا إذا كانت للتِّجارة.","link":"https://binbaz.org.sa/fatwas/4420/حكم-ومقدار-زكاة-الحلي-المعد-للزينة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0385.mp3","categories":["زكاة النقدين"]},{"id":849,"question":"هل على الذهب الذي تلبسه المرأةُ في الأفراح والأعياد زكاة، على أنَّ الغرض منه الزينة، وليس للادّخار والتِّجارة، وهو حسب العادة؟","title":"هل في ذهب المرأة للزينة والمناسبات زكاة؟","answer":"الجواب: الشيخ: كذلك المسألة فيها خلافٌ بين أهل العلم: من أهل العلم مَن رأى أنَّ فيها الزكاة، ومنهم مَن لم يرَ فيها الزكاة.\nوالمعلوم أنَّ المسائل التي فيها خلافٌ يجب ردُّها إلى الله والرسول، كما قال الله سبحانه: فَإِنْ تَنَازَعْتُمْ فِي شَيْءٍ فَرُدُّوهُ إِلَى اللَّهِ وَالرَّسُولِ [النساء:59]، وقال : وَمَا اخْتَلَفْتُمْ فِيهِ مِنْ شَيْءٍ فَحُكْمُهُ إِلَى اللَّهِ [الشورى:10]، وهذه المسألة إذا رددناها إلى الكتاب والسنة وجدنا في الكتاب والسنة ما يدل على أنه تجب الزكاة، فالأصل وجوب الزكاة في الذهب والفضة، فلا يجوز العدول عن ذلك إلا بدليلٍ.\nوقد جاء ما يُؤيد هذا في السنة في الحديث العام: ما من صاحب ذهبٍ ولا فضةٍ لا يُؤدي حقَّها -وفي اللفظ الآخر: لا يُؤدِّي زكاتها- إلا إذا كان يوم القيامة صُفحت له صفائح من نار الحديث، وهذا يعمُّها.\nوحديث صاحبة المسكتين: وهو حديث جيد، رواه أبو داود والنَّسائي بسندٍ جيدٍ: أن امرأةً دخلت على النبي ﷺ وبيدي ابنتها مسكتان من ذهبٍ –يعني: سوارين- فقال: أتُعطين زكاة هذا؟ قالت: لا، قال: أيسرك أن يُسورك الله بهما يوم القيامة سوارين من نارٍ؟! فألقتهما وقالت: هما لله ولرسوله.\nوحديث أم سلمة أنها كانت تلبس أوضاحًا من ذهبٍ، فقالت: يا رسول الله، أكنزٌ هذا؟ فقال ﷺ: ما بلغ أن يُزَكَّى فزُكِّيَ فليس بكنزٍ يعني: ما بلغ النِّصاب فزُكِّيَ فليس بكنزٍ، ولم يقل لها: ليس في الحلي زكاة.","link":"https://binbaz.org.sa/fatwas/20880/هل-في-ذهب-المراة-للزينة-والمناسبات-زكاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0675هل على ذهب الذي تلبسه المرأة في الأفراح والأعياد زكاة على أن الغرض الزينة وليس للادخار والتجارة.mp3","categories":["زكاة النقدين"]},{"id":1284,"question":"اختلفت آراء العلماء في زكاة الحُلي: كالذهب المُعدّ للزينة، فما رأي فضيلتكم؟ وهل تلزم عليه الزكاة أم لا؟","title":"ما حكم زكاة الذهب المُعَدُّ للزينة؟","answer":"الجواب:\nصحيح، اختلف فيه العلماء: منهم مَن رأى فيه الزكاة، ومنهم مَن لم يرَ فيه الزكاة وقال: إنه ممتهن، وإنه مثل البعير الذي يُمتهن، ومثل البقرة التي تُمتهن، لا زكاةَ في ذلك.\nوالصواب أن فيه الزكاة، الأرجح من قولي العلماء: أنَّ فيه الزكاة وإن كان للزينة، وإن كان للبس، إذا بلغ النِّصاب، هذا هو الأرجح، وهو الذي نُفتي به، وقد كتبنا فيه عدَّة مقالات؛ لقول النبي ﷺ، أولًا: لقول الله جلَّ وعلا: أَوَمَنْ يُنَشَّأُ فِي الْحِلْيَةِ وَهُوَ فِي الْخِصَامِ غَيْرُ مُبِينٍ [الزخرف:18]، بل الحلية من شأن المرأة، وقد أوجب الله الزكاة وعمَّم، ما قال: إلا حلية المرأة، فقال النبيُّ ﷺ: ما من صاحب ذهبٍ ولا فضَّةٍ لا يُؤدِّي زكاتها إلا إذا كان يوم القيامة صفحت له صفائح من نارٍ، فيُكوى بها جنبه وجبينه وظهره الحديث، وهذا يعمُّ ذهبَ المرأة وفضَّتها.\nوجاء أنه ﷺ لما دخلت عليه امرأةٌ ومعها ابنتان، عليها سواران من ذهبٍ، قال: أتُؤدِّين زكاةَ هذا؟ قالت: لا، قال: أيسرُّكِ أن يُسورك الله بهما يوم القيامة سوارين من نارٍ؟ فألقتهما وقالت: هما لله ولرسوله، قالت له أمُّ سلمة: يا رسول الله -وكانت عليها أوضاح من ذهبٍ- أكنزٌ هذا؟ قال: ما بلغ يُزَكَّى فزُكِّي فليس بكنزٍ، ولم يقل لها: إنَّ هذا حُلي ليس فيه زكاة.\nأما ما يُروى عن النبي ﷺ أنه قال: ليس في الحلي زكاة فهو حديثٌ ضعيفٌ احتجَّ به بعضُ الفقهاء، وهو حديثٌ ضعيفٌ، ليس في الحُلي زكاة هذا ليس بصحيحٍ.","link":"https://binbaz.org.sa/fatwas/21351/ما-حكم-زكاة-الذهب-المعد-للزينة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1094ما حكم زكاة الذهب المعد للزينة؟ ابن باز فتاوى.mp3","categories":["زكاة النقدين"]},{"id":2254,"question":"الذهب الأبيض فيه زكاة؟","title":"ما حكم الزكاة في الذهب الأبيض والألماس؟","answer":"الجواب:\nما أعرف الذهب الأبيض.\nس: يُباع في الأسواق باسم: الذهب الأبيض؟\nس: إذا بلغت قيمتُه نصابَ الذهب والفضة فبحسب القيمة، ولا يُسمَّى ذهبًا وإن سمَّاه الناس كذلك، فالذهب لا يكون إلا أحمر، فإذا كانت قيمته قيمة الذهب والفضة يُزَكَّى، إذا بلغ النِّصابَ بالقيمة.\nس: الألماس؟\nج: والماس والألماس وكل شيءٍ إذا بلغ النِّصابَ بالقيمة.","link":"https://binbaz.org.sa/fatwas/22377/ما-حكم-الزكاة-في-الذهب-الابيض-والالماس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الزكاة في الذهب الأبيض والألماس.mp3","categories":["زكاة النقدين"]},{"id":2636,"question":"نِصاب الوَرق؟","title":"ما مقدار نصاب زكاة الوَرِق (الفضة)؟","answer":"الجواب: النصاب ستة وخمسون ريالًا عربيًّا سعوديًّا، وإن أخرج مِن الوَرَق أجزأ، ستة وخمسين فما زاد يعني.\nس: الألف خمسة وعشرين ريالًا؟\nالشيخ: نعم، رُبْع العشر، المائة اثنان ونصف، والألف خمسة وعشرون، والأربعون ألف: ألف واحد، ربع العشر. إذا أخرج منها كالفضة أبرأ للذمة وأحوْط، كل مائة من الورق اثنين ونصف.\nس: يقول بعضهم أقل النصاب أربعمائة وخمسون ريال.\nالشيخ: لا لا، غلط، نصاب الفضة ستة وخمسون ريالًا. قيمتها من الدولار أو الورق الموجود، لكن لو أخرج من ستة وخمسين فأكثر اعتبرها كالفضة؛ طيب.","link":"https://binbaz.org.sa/fatwas/22771/ما-مقدار-نصاب-زكاة-الورق-الفضة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/نصاب الورق.mp3","categories":["زكاة النقدين"]},{"id":3387,"question":"يُصلى على المرأة الحائض في المسجد؟","title":"هل يُصَلّى على الحائض بالمسجد إذا ماتت؟","answer":"الجواب: نعم، لا بأس، النبي ﷺ صلى على النساء في المسجد ولم يسأل.","link":"https://binbaz.org.sa/fatwas/23555/هل-يصلى-على-الحاىض-بالمسجد-اذا-ماتت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يُصَلّى على المرأة الحائض في المسجد إذا ماتت.mp3","categories":["المساجد ومواضع السجود","زكاة النقدين","الصلاة على الميت","أحكام التعزية"]},{"id":5231,"question":"سائلٌ يسأل عن حُلي المرأة ويقول: كنتُ أسمع بعض المشايخ يُجيزون عدم زكاة حُلي المرأة التي تستعملها، وقد قرأتُ متأخِّرًا فتوى لسماحتكم بوجوب زكاة حُلي المرأة المُستعملة في الزينة، فأرجو تعليق سماحتكم على هذا الموضوع لأهميته وإفادتنا.","title":"ما حكم زكاة حُلي المرأة المُستعمل في الزينة؟","answer":"الجواب: حُلي النِّساء من الذهب والفضَّة اختلف فيها العلماء: منهم مَن جعل فيها الزكاة إذا كانت للبس، كما يجب فيها الزكاة لو كانت لغير اللبس، ومنهم مَن قال: إن كانت للّبس لم تجب فيها الزكاة، وإن كانت للادخار أو للتِّجارة وجبت فيها الزكاة. والذي دلَّت عليه الأدلة الشرعية حسب علمي هو أنها تجب فيها الزكاة مطلقًا، وبهذا قال جمعٌ من أهل العلم، وهو مرويٌّ عن عمر بن الخطاب  وجماعة من السلف، ومذهب أبي حنيفة الإمام وجماعة، وهو الأظهر من حيث الدليل؛ لعموم الأدلة الدالة على وجوب الزكاة في الذهب والفضَّة، مثل قوله ﷺ: ما من صاحب ذهبٍ ولا فضَّةٍ لا يُؤدِّي زكاتها إلا إذا كان يوم القيامة صفحت له صفائح من النار، فيُكوى بها جنبه وجبينه وظهره .. الحديث. ومنها ما رواه أبو داود والنَّسائي بإسنادٍ جيدٍ عن عبدالله بن عمرو بن العاص رضي الله تعالى عنهما: أن امرأةً أتت النبيَّ ﷺ ومعها ابنةٌ لها، وفي يدها مسكتان من ذهبٍ –يعني: سوارين من ذهبٍ- فقال عليه الصلاة والسلام: أتُؤدّين زكاة هذا؟ قالت: لا، قال: أيسُرّك أن يُسورك الله بهما يوم القيامة سوارين من نارٍ، فألقتهما وقالت: هما لله ورسوله. وهكذا ما ثبت عن أم سلمة أنها كانت تلبس أوضاحًا من ذهبٍ، وقالت: يا رسول الله، أكنزٌ هذا؟ فقال: ما بلغ يُزكّى، فزكّي فليس بكنزٍ، ولم يقل: ليس في الحُلي زكاة. أما الحديث الذي رواه البيهقي وجماعةٌ عن النبي ﷺ أنه قال: ليس في الحُلي زكاة، فهو حديثٌ عند أهل العلم ضعيفٌ غير صحيحٍ. وبهذا يُعلم أنَّ الصواب أنَّ فيه الزكاة، أنَّ الحُلي فيه الزكاة إذا بلغت النِّصاب وحال عليها الحول، في كل ألفٍ خمس وعشرون، ربع العشر، والنِّصاب أحد عشر جنيهًا ونصف، عشرون مثقالًا، أحد عشر جنيهًا وثلاثة أسباع الجنيه –يعني: النصف؛ لأنَّ ما بين الثلاثة أسباع والنصف شيءٌ يسيرٌ، والنصف أوضح- هذا هو النِّصاب، عشرون مثقالًا، أحد عشر جنيهًا سعوديًّا ونصف، اثنان وتسعون جرامًا، هذا هو النِّصاب، وما كان أقلَّ من هذا فليس فيه شيءٌ، وإنما تجب الزكاة كل حولٍ. لكن مثل الألماس والجواهر الأخرى إذا كانت للّبس فليس فيها زكاة، إنما الزكاة في الذهب والفضَّة خاصةً، أما الألماس واللؤلؤ وبقية الأحجار الكريمة التي ليست من الذهب والفضة فهذه ليس فيها زكاة إذا كانت مُعدَّةً للّبس لا للتجارة.","link":"https://binbaz.org.sa/fatwas/30175/ما-حكم-زكاة-حلي-المراة-المستعمل-في-الزينة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 286.mp3","categories":["زكاة النقدين"]},{"id":5238,"question":"وهذه سائلة تسأل وتقول: هل على حُلي المرأة زكاة إذا كانت تستعمله للبس فقط، وليس عندها مالٌ نقديٌّ تُزَكِّي منه إن كان فيه زكاة؟","title":"حكم زكاة الحُليّ المستعمل؟","answer":"الجواب: نعم، نعم، في الحُلي الزكاة، ولو كانت تستعمله، في أصحّ قولي العلماء، وفيها خلافٌ بين أهل العلم: بعض أهل العلم يرى أنه لا زكاةَ فيها، ولكن الصواب أن فيها الزكاة؛ لعموم الأدلة، مثل: قوله ﷺ: ما من صاحب ذهبٍ ولا فضةٍ لا يُؤدِّي زكاتها إلا إذا كان يوم القيامة صُفِّحَتْ له صفائح من نارٍ، فيُكوى بها جنبه وجبينه وظهره في يومٍ كان مقداره خمسين ألف سنةٍ، ثم يرى سبيله: إما إلى الجنة، وإما إلى النار الحديث؛ ولأنه ﷺ دخلت عليه امرأةٌ في يد ابنتها سِواران من ذهبٍ، فقال: أتُعْطِين زكاة هذا؟ قالت: لا، قال: أيسركِ أن يُسورك الله بهما يوم القيامة سوارين من نارٍ؟! فألقتهما وقالت: هما لله ولرسوله. ولا بأس بإسناده: رواه أبو داود والنَّسائي بإسنادٍ جيدٍ عن عبدالله بن عمرو بن العاص. وهكذا جاء من حديث أم سلمة: أنها كانت تلبس أوضاحًا من ذهبٍ، فقالت: يا رسول الله، أكنزٌ هذا؟ فقال عليه الصلاة والسلام: ما بلغ أن يُزَكَّى فزُكِّيَ فليس بكنزٍ. وإذا كان ما عندها شيءٌ تبيع من الحُلي وتُزكِّي، وإذا زكَّى عنها زوجُها، أو زكَّى عنها أبوها، أو ولدها، بإذنها ومُوافقتها فلا بأس، يكفي، إذا زكَّى عنها زوجُها بإذنها ومُوافقتها فلا بأس، وإلا باعت منها وزكَّت، أو اشترت حُليًّا لا زكاةَ فيها: كالماس، أو ما دون النِّصاب من الذهب، فإنَّ ما دون النِّصاب ليس فيه زكاة، مثل: إذا كانت الحُلية أقلّ من أحد عشر جنيهًا ونصف ما فيها زكاة، فإنَّ النصاب عشرون مثقالًا من الذهب، مقداره بالجنيه السعودي: أحد عشر جنيهًا ونصف، ومقداره بالجرام: اثنان وتسعون جرامًا، فإذا كان أقلَّ من ذلك فلا زكاةَ فيه، وإذا كان من الماس واللَّآلئ ونحوها التي غير الذهب فلا زكاةَ فيها إذا كانت للّبس، وهكذا في الفضَّة تُزَكَّى إذا بلغت النِّصاب، ولو كانت حُلِيًّا.","link":"https://binbaz.org.sa/fatwas/30585/حكم-زكاة-الحلي-المستعمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 353.mp3","categories":["زكاة النقدين"]},{"id":5675,"question":"اختلفت آراءُ العلماء في حكم زكاة الحُلي المستعمل وغير المستعمل، فما رأي سماحتكم في هذه المسألة؟ أفتونا مأجورين.","title":"ما الراجح في زكاة الحُلي المستعمل؟","answer":"الجواب: الراجح أنَّ فيه الزكاة، الحُلي مطلقًا: مُستعمل، أو غير مُستعمل، الواجب فيه الزكاة إن حال عليه الحول، وبلغ النِّصاب؛ لأنَّ الرسول ﷺ أمر المرأةَ التي لها حُلي أن تُزكيه، قالت له أمُّ سلمة لما عرضت حُليها، قال: ما بلغ يُزَكَّى فزُكِّي فليس بكنزٍ، وقال للمرأة التي عليها أسورة ما تُزكيها: أيسرك أن يُسورك الله بهما سوارين من نارٍ؟ فالواجب على مَن عندها حُلي تلبسه أو ما تلبسه أن تُزكيه إذا حال عليه الحول وبلغ النِّصاب.[1]","link":"https://binbaz.org.sa/fatwas/31768/ما-الراجح-في-زكاة-الحلي-المستعمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aldurus almuhima 021.mp3","categories":["زكاة النقدين"]},{"id":5754,"question":"هل يجمع بين الذهب والفضة في تمام النصاب؟ مثلًا عشرة مثاقيل زائد مائة درهم، هل عليها زكاة؟","title":"هل يجمع بين الذهب والفضة عند زكاتهما؟","answer":"الجواب: هذا هو الأولى؛ لأنهما شيء واحد في المعنى، إذا ضم بعضهما إلى بعض -كما قال جمع من أهل العلم- فحسن.","link":"https://binbaz.org.sa/fatwas/1079/هل-يجمع-بين-الذهب-والفضة-عند-زكاتهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_89.mp3","categories":["زكاة النقدين"]},{"id":5770,"question":"هل يجمع بين الذهب والفضة في تمام النصاب؟ مثلًا عشرة مثاقيل زائد مائة درهم، هل عليها زكاة؟","title":"هل يجمع بين الذهب والفضة عند زكاتهما؟","answer":"الجواب: هذا هو الأولى؛ لأنهما شيء واحد في المعنى، إذا ضم بعضهما إلى بعض -كما قال جمع من أهل العلم- فحسن.","link":"https://binbaz.org.sa/fatwas/1079/هل-يجمع-بين-الذهب-والفضة-عند-زكاتهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_89.mp3","categories":["زكاة النقدين"]},{"id":5838,"question":"ما هو حكم الإسلام فيما ذهب إليه الشيخ محمد عبده في إحلال الربا، وإلغاء تعدد الزوجات؟","title":"الرد على من يحل الربا ويمنع تعدد الزوجات","answer":"الجواب:  إحلال الربا أمر خطير لا يحل الربا إلا كافر، لكن من قال: إنه يحل الربا؟! من قال: إنه يمنع تعدد الزوجات؟! هذا يحتاج إلى مراجعة كتبه، ولا علينا من الأشخاص، إنما علينا من الحكم، حكم الله -جل وعلا- أما الأشخاص فكل يخطئ ويصيب، كل يغلط إلا من عصمه الله، وعافاه، وإلا فبنو آدم معرضون للخطأ، والأغلاط. ومحمد عبده له أغلاط، وغيره له أغلاط، لكن المقصود أن الربا لا يجوز إحلاله من الناس أبدًا، ومن أحله عن عمد، وعن بصيرة يعلم أنه ربا، ثم يحله، يعاند الله، ويخالف أمر الله؛ فيكون كافرًا -نعوذ بالله- كالذي يحل الزنا، أو يحل الخمر؛ يكون كافرًا. أما إذا غلط، واجتهد في بعض أنواع الربا، ورأى أن هذا جائز لأجل كذا وكذا، وشبه عليه؛ فهذا له حكم المجتهدين، إن أصاب؛ فله أجران، وإن أخطأ؛ فله أجر. وكذلك تعدد الزوجات كثير من المستشرقين النصارى، وغيرهم من اليهود، وغيرهم كتبوا في ذلك، وانتقدوا الإسلام! وانتقدوا الشريعة في تعدد الزوجات! وهم الغالطون، وهم المنتقدون، وهم الضالون، وكثير منهم يعرف ذلك، ولكن العناد، والحسد، والبغي، وإلا فكثير منهم يعرف أن ما جاءت به الشريعة من تعدد الزوجات هو الحق، وهو الحل لمشاكل الناس، وقد كتب في ذلك منصفوهم من رجال ونساء، واعترفوا أن ما جاء به الإسلام من التعدد هو الحق والهدى، وهو الطريق لإنقاذ البشرية مما وقعت فيه من الفساد في الأخلاق، ولكنهم يجحدون هذا في بعض الأحيان، إما خوفًا من رؤسائهم، وكبرائهم، وإما لأجل متاع يأخذونه من هناك، فيخافون أن يضيع عليهم، وإما لحسد المسلمين، والبغي على المسلمين، والعدوان على المسلمين -نعوذ بالله- هذه طريقة الكفرة، وإلا فالمنصفون منهم يعلمون أن تعدد الزوجات فيه مصالح كثيرة، وفيه خير كثير، وهو من أسباب حل المشاكل القائمة في العصر، من كثرة السفاح، والزنا، والفواحش. وكثير من هؤلاء النصارى الذين يزعمون أن التعدد منكر يتخذ زوجة واحدة، ويتخذ معها عشرات الخدينات، والمسافحات، فأي فرق بين هذا وهذا؟! المسلم يأخذ زوجات مسلمات، يأخذ زوجات أحلهن الله له، وأولئك يأخذون مسافحات، زانيات، فاجرات، فرق بين المسلم وبين هؤلاء، فالمسلم في خير عظيم إذا تزوج ثنتين، أو ثلاثًا، أو أربعًا على شرع الله، قد أباح الله له ذلك، وإن عدل فهو على خير عظيم، وأولئك الجهلة الظالمون ينتقدون الإسلام في تعدد الزوجات، وهم -والعياذ بالله- يتمتعون بالزانيات، والفاجرات بلا عدد يحصر، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/1173/الرد-على-من-يحل-الربا-ويمنع-تعدد-الزوجات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_171.mp3","categories":["الربا والصرف","زكاة النقدين","قضايا المرأة","شروح الحديث"]},{"id":6066,"question":"ما حكم زكاة الذهب، والفضة المستعملين، سواء أكانا الفضة للرجال، أو الذهب للنساء؟","title":"حكم زكاة الذهب والفضة المعدين للاستعمال والزينة","answer":"الجواب: الصواب في هذه المسألة أن الذهب، والفضة المستعملين تجب فيهما الزكاة عند جمع من أهل العلم. واختلف العلماء في ذلك: فذهب قوم إلى أن الحلي المستعمل للنساء، وهكذا للرجال لا زكاة فيها، وأنها بمثابة الإبل المستعملة، وأشباه ذلك؛ لأنها لم تعد للنمو، وإنما أعدت للعمل، والاستعمال، ونحو ذلك، أو يراد بها ذلك، وإن لم تستعمل، وهذا قال به جماعة من الصحابة -رضي الله عنهم وأرضاهم- وجماعة من أهل العلم.  وذهب آخرون من أهل العلم، ويروى عن جماعة من الصحابة إلى أنه لا بدّ من الزكاة للأدلة العامة، والخاصة، الأدلة العامة منها قوله ﷺ: ما من صاحب ذهب، ولا فضة لا يؤدي زكاتها إلا إذا كان يوم القيامة صفحت له صفائح من نار، فيكوى بها جنبه، وجبينه، وظهره مع عموم قوله سبحانه وتعالى: وَالَّذِينَ يَكْنِزُونَ الذَّهَبَ وَالْفِضَّةَ وَلَا يُنْفِقُونَهَا فِي سَبِيلِ اللَّهِ فَبَشِّرْهُمْ بِعَذَابٍ أَلِيمٍ [التوبة:34] وقد علم بالأدلة أن الكنز هو كل مال لا تؤدى زكاته، فهو كنز، وإن كان على وجه الأرض، فكل مال تؤدى زكاته، ويؤدى حقه فليس بكنز، وإن كان تحت الأرض. وأحاديث خاصة رويت في الباب أيضًا، قد روى أبو داود، والنسائي بسند جيد، عن عبدالله بن عمرو -رضي الله تعالى عنهما-: أن امرأة دخلت على النبي ﷺ وفي يدها مسكتان من ذهب، وفي رواية: أسوارين من ذهب، فقال: أتعطين هذا؟ قالت: لا، قال: يسرك أن يسورك الله بهما يوم القيامة بسوارين من نار، فألقتهما قالت: هما لله ورسوله وسنده لا بأس به، وهو مؤيد للعام، ودال على ما دل عليه العام. وهكذا ما روته أم سلمة أنها قالت يا رسول الله، ... أوضاح من ذهب، فقالت: يا رسول الله أكنز هذا؟ فقال لها النبي ﷺ: ما بلغ يزكى، فزكي؛ فليس بكنز ولم يقل إن الحلي ما فيها زكاة، فقال: ما بلغ يزكى، فزكي؛ فليس بكنز، فدل على أن ما لم يزكى؛ فهو كنز في أدلة أخرى، وهذا هو الأرجح -إن شاء الله- والأقرب: أن فيها زكاة في الحلي إذا بلغت النصاب. ونصاب الذهب عشرون مثقالًا، مقداره من الجنيه السعودي الآن، إحدى عشر جنيهًا، وثلاثة أسباع، جنيه يعني حول النصف، فإذا كان الذهب عندها يبلغ هذا المقدار، إحدى عشر جنيه وثلاثة أسباع جنيه من الذهب، زكته، وما كان أقل من هذا؛ فليس فيه شيء. والفضة مائة، وأربعون مثقالًا، فإذا كان لديها ما يبلغ من الفضة مائة، وأربعين مثقالًا، ستة وخمسين ريالاً فضة؛ يزكى وإن كان أقل من هذا، فليس بشيء، والواجب أن يزكى هذا ... وما فوقه، هذا بيان الأقل إحدى عشر جنيه، ونصف، وست وخمسون من  الفضة، هذا الأقل، فما زاد؛ فهو بحساب ذلك إلى الملايين، وآلاف الملايين. السؤال: الذين لا يزكون على القول الآخر هل يأثمون؟ الجواب: على حسب اجتهادهم، إن كان طالب علم، واجتهد، أو قلد بعض أهل العلم نرجو أن لا يأثم.","link":"https://binbaz.org.sa/fatwas/1476/حكم-زكاة-الذهب-والفضة-المعدين-للاستعمال-والزينة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_406.mp3","categories":["زكاة النقدين"]},{"id":6378,"question":"سماحة الشيخ، السلام عليكم ورحمة الله وبركاته، وبعد: رجل لديه زوجة، وبنات صغار، ويوجد لديه ذهب، فهل فيه زكاة؟ وكم هو مقدار النصاب، وفقكم الله؟","title":"حكم زكاة الحلي وما مقدار النصاب؟","answer":"الجواب: الذهب والفضة التي يتحلى بها النساء اختلف فيها العلماء -رحمة الله عليهم- على قولين: أحدهما: أن فيها الزكاة، وإن كانت تلبس. والثاني: ليس فيها زكاة؛ لأنها مستعملة. والصواب من القولين: هو أنه تجب فيها الزكاة لأدلة جاءت في ذلك منها: قوله -عليه الصلاة والسلام-: ما من صاحب ذهب، ولا فضة لا يؤدي زكاتها إلا إذا كان يوم القيامة؛ صفحت له صفائح من نار، فيحمى عليها في نار جهنم، فيكوى بها جبينه، وجنبه، وظهره... الحديث. ومنها: ما ثبت من حديث عبدالله بن عمرو بن العاص -رضي الله عنهما- أن امرأة دخلت على النبي ﷺ وفي يدها سواران من ذهب، فقال : أتعطين زكاة هذا، قالت: لا، قال: يسرك أن يسورك الله بهما يوم القيامة سوارين من نار؟ فألقتهما وقالت: هما لله، ولرسوله! وما ثبت أيضًا من حديث أم سلمة -رضي الله عنها- أنها كانت تلبس أوضاحًا من ذهب، فقالت: يا رسول الله أكنز هذا؟ فقال: ما بلغ يزكى فزكي فليس بكنز ولم يقل لها: هذه حلي ليس فيها زكاة. أما حديث: ليس في الحلي زكاة فهو حديث ضعيف عند أهل العلم، ولهذا ذهب جمع من أهل العلم من الصحابة، ومن بعدهم إلى أنها تجب فيها الزكاة لهذه الأدلة العامة، والخاصة، فإذا حال عليها الحول، وهي تبلغ النصاب؛ زكيت، وإن كانت أقل من النصاب؛ فلا زكاة فيها. والنصاب عشرون مثقالًا، وهي يقارب 92 غرامًا من الذهب، ومقداره بالجنية السعودي 11 جنيه، وثلاثة أسباع الجنيه، يعني إحدى عشر جنيهًا، ونصف، فإذا بلغت الحلي هذا المقدار؛ زكيت بربع العشر، من كل ألف خمس وعشرون، وإذا كانت أقل من ذلك؛ فلا زكاة فيها، والفضة مائة وأربعون مثقالًا، هذا نصابها ، ومقدارها بالدراهم الفضية ستة وخمسون ريالاً، فإذا بلغت العملة هذا المقدار؛ وجبت فيها الزكاة، وإلا فلا.  والزكاة ربع العشر في الجميع في الذهب، والفضة، وفي عروض التجارة ربع العشر من كل ألف خمس وعشرون، ومن كل مائة درهمان، ونصف.","link":"https://binbaz.org.sa/fatwas/1961/حكم-زكاة-الحلي-وما-مقدار-النصاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_748.mp3","categories":["زكاة النقدين"]},{"id":6551,"question":"الذهب والفضة المستعملة هل عليها زكاة؟ وكيف يزكى؟ هل يوزن، أو يزكى حسب قيمته السابقة؟","title":"حكم زكاة الذهب والفضة المستعملة","answer":"الجواب: الذهب والفضة فيه الزكاة على الصحيح، ولو كان يستعمل، ولو كان يلبس، فيه خلاف بين أهل العلم، لكن الصواب: أنه فيه الزكاة إذا بلغ النصاب، والنصاب عشرون مثقالًا من الذهب، ومائة وأربعون مثقالًا من الفضة، ومقداره من العملة السعودية إحدى عشر جنيهًا ونصف، هذا مقداره من العملة المعروفة الجنيه السعودي، ومن الفضة ستة وخمسون ريالًا، وما يعادلها من الورق.  فالمقصود: أن هذا هو الواجب عليه، وينظر في الوزن، فإذا عرف أن زنة هذه السلعة من الذهب أسورة، وغيرها تبلغ إحدى عشر جنيها ونصف، عشرين مثقالًا ينظر قيمتها في السوق .. عنها من الورق ما يكفي.","link":"https://binbaz.org.sa/fatwas/2423/حكم-زكاة-الذهب-والفضة-المستعملة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_950.mp3","categories":["زكاة النقدين"]},{"id":6583,"question":"الذهب والفضة المستعملة هل عليها زكاة؟ وكيف يزكى؟ هل يوزن، أو يزكى حسب قيمته السابقة؟","title":"حكم زكاة الذهب والفضة المستعملة","answer":"الجواب: الذهب والفضة فيه الزكاة على الصحيح، ولو كان يستعمل، ولو كان يلبس، فيه خلاف بين أهل العلم، لكن الصواب: أنه فيه الزكاة إذا بلغ النصاب، والنصاب عشرون مثقالًا من الذهب، ومائة وأربعون مثقالًا من الفضة، ومقداره من العملة السعودية إحدى عشر جنيهًا ونصف، هذا مقداره من العملة المعروفة الجنيه السعودي، ومن الفضة ستة وخمسون ريالًا، وما يعادلها من الورق.  فالمقصود: أن هذا هو الواجب عليه، وينظر في الوزن، فإذا عرف أن زنة هذه السلعة من الذهب أسورة، وغيرها تبلغ إحدى عشر جنيها ونصف، عشرين مثقالًا ينظر قيمتها في السوق .. عنها من الورق ما يكفي.","link":"https://binbaz.org.sa/fatwas/2423/حكم-زكاة-الذهب-والفضة-المستعملة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_950.mp3","categories":["زكاة النقدين"]},{"id":7055,"question":"زكاة الأسهم؟","title":"كيفية زكاة الأسهم","answer":"الجواب:\n\nإذا كانت للبيع؛ فيها الزكاة، مثل الأراضي المساهمة، في الأراضي فيها الزكاة حسب القيمة -قيمة الأراضي- التي للتجارة للبيع.\n\nأما الأسهم التي للاستثمار فهذا يزكي الأموال التي تجي عنده الأرباح، التي تجيه، إذا حال عليها الحول عنده؛ يزكيها، أو حال الربح عند الشركة، قد يحفظه، وفصلوه، وحال عليه الحول؛ يزكى، أما الأصول؛ فلا زكاة فيها، إذا كانت للاستثمار مثل الأصول في الكهرباء، أو في غيرها من الأشياء التي تستثمر ما هي للبيع، ليست للبيع.","link":"https://binbaz.org.sa/fatwas/3075/كيفية-زكاة-الاسهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1460.mp3","categories":["زكاة النقدين","زكاة عروض التجارة"]},{"id":7079,"question":"إن والدتي تملك حليّا من الذهب معد للاستعمال، وقد كنت أقول لها: إنه يجب عليها أن تزكيه، ولكنها تقول: إن العلماء مختلفين في زكاة الذهب المعد للاستعمال، هل تجب زكاة الذهب المعد للاستعمال، أم لا؟","title":"حكم زكاة الذهب المعد للاستعمال","answer":"الجواب:\n\nهذا مثل ما قالت أمك: فيه خلاف بين العلماء، منهم من قال: فيه الزكاة، ومنهم من قال: ليس فيه الزكاة.\n\nوالصواب: أن فيه الزكاة، تُعلمها، تقول لها: الصواب فيه الزكاة إذا بلغ النصاب، صار عندها حلي يبلغ -مثًلا- مائة جنيه، مائتين جنيه، أكثر أقل، يعني نصاب أكثر من عشرين دينارًا، عشرين دينارًا فأكثر، يعني عشرين مثقالًا، فأكثر، فعليها الزكاة على الصحيح، ربع العشر، ومقداره من الذهب: أحد عشر جنيهًا، وثلاثة أسباع الجنيه، يعني أحد عشر جنيهًا، ونصف أوضح، فإذا بلغ هذا؛ يزكى، وإن كان أقل؛ فلا زكاة فيه، إن كان ذهبًا.\n\nأما الماس واللؤلؤ والجواهر الأخرى؛ فهذه ما فيها زكاة، إذا كانت للبس، إنما الزكاة فيها إن كانت للبيع والتجارة، أما للبس؛ فلا زكاة فيها إذا كانت مثل ماس، أو لؤلؤ، أو أشياء أخرى، إنما الزكاة في الذهب والفضة، هذان المعدنان.\n\nالسؤال: طيب الزكاة، تأكل الحلي بالتالي، بعد كم سنة تقضي عليها؟\n\nالجواب: حتى تأكله.. إذا ما يصرف فيه تأكله الزكاة، دعها تأكله، إما يتسببون، يبيعون فيه ويشترون، وإلا تبيع عليه الحلي، تشتري حليًا قليلًا ما تبلغ النصاب، تشتري حليًا ما فيها أحد عشر جنيها، أقل من أحدى عشر جنيهًا ونصف، حتى لا يكون فيها زكاة.","link":"https://binbaz.org.sa/fatwas/3077/حكم-زكاة-الذهب-المعد-للاستعمال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1461.mp3","categories":["زكاة النقدين"]},{"id":7095,"question":"كيف توفقون فضيلتكم بين حديثي عمرو بن شعيب، وحديث عائشة -رضي الله عنهم- فإن الأول دال على وجوب الزكاة في حلي النساء المعد للاستعمال، والثاني عكس الحديث الأول؟ وهل أحد الحديثين ناسخ للآخر؟ وهل القول بالطعن في حديث عائشة خاف على الأئمة الثلاثة، وجماهير العلماء؟ وهل ترون فضيلتكم أن حديث عائشة غير مطابق، ومتفق مع قوله تعالى: وَمَا جَعَلَ عَلَيْكُمْ فِي الدِّينِ مِنْ حَرَجٍ [الحج:78] وغير ذلك من النصوص الدالة... إلى آخره، ألا ترون فضيلتكم أن القول بذلك فيه مشقة على النساء المزكيات لحليهن المعد للاستعمال مع، علمكم أن مضي الأعوام طويلة عليهن يدفعن الزكاة يأكل ثمن ما لديهن من الحلي؟","title":"القول الراجح في زكاة حلي النساء","answer":"الجواب:\n\nالله -جل وعلا- أرحم بعباده منا بالناس، الله أرحم بعباده وأعلم  وهو أرحم الراحمين وهو الذي شرع الشرائع جل وعلا وأوجب الزكاة في الذهب والفضة وفي أموال الزكاة الأخرى، ليس نحن أوجبنا، أوجبها الله .\n\nوحديث عائشة ضعيف لا يصح عند المحققين من أهل العلم، وحديث عمرو بن شعيب حديث صحيح جيد، لا بأس به، وله شواهد صحيحة أيضًا، منها حديث ما جاء في الصحيحين: ما من صاحب ذهب ولا فضة لا يؤدي زكاتها إلا إذا كان يوم القيامة صفحت له صفائح من نار الحديث إلى غير ذلك مما جاء في الباب. \n\nفالصواب: أن حلي النساء فيها الزكاة من الذهب، والفضة إذا بلغت النصاب، وحال عليها الحول، وأما كون الجمهور أخذوا بهذا، والأقلون أخذوا بهذا ليس بحجة، الله يقول: فَإِنْ تَنَازَعْتُمْ فِي شَيْءٍ فَرُدُّوهُ إِلَى اللَّهِ وَالرَّسُولِ إِنْ كُنْتُمْ تُؤْمِنُونَ بِاللَّهِ وَالْيَوْمِ الْآخِرِ ذَلِكَ خَيْرٌ وَأَحْسَنُ تَأْوِيلًا [النساء:59] فالاعتبار بالرد إلى الكتاب، والسنة لا بالأكثرية، نعم.\n\nالسؤال: كل سنة يا شيخ؟\n\nالجواب:  كل سنة نعم، كل سنة على الزوجة، على صاحبة الحلي، حتى إذا باعت منها، ولم يبق إلا قليل ما فيه زكاة، يعني ما بلغ النصاب، لا تزك، وإلا تزكي والحمد لله، نعم.","link":"https://binbaz.org.sa/fatwas/3116/القول-الراجح-في-زكاة-حلي-النساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1483.mp3","categories":["زكاة النقدين","الحكم على الأحاديث"]},{"id":7486,"question":"أيضاً السؤال الثاني للمرسلة (م. ح) يتعلق في الزكاة لكن زكاة الحلي، تقول: أسأل كذلك عن زكاة الحلي الذي اختلف فيه العلماء، والسؤال هو: إذا كانت المرأة تريد أن تزكي عن حليها كيف تزكي عنه، هل تجمع حليها وتزنه وتظهر على حسب وزنه؟ وهل يكون إذا حال عليه الحول؟ وإذا كان كذلك فإن كل شيء من حليها اشترته في زمن قد نسيت في أي شهر من السنة؟ أرشدوني كيف أزكي عن حليي؛ لأنني أريد ذلك رغم اختلاف العلماء في وجوب زكاة الحلي، وهل يصح ذلك في شهر رمضان، نظراً لأن كل نوع من هذه الحلي قد اشتري في شهر من شهور السنة؟","title":"كيفية إخراج زكاة الحلي","answer":"الجواب:  الحلي من الذهب والفضة في وجوب الزكاة عليه اختلاف بين أهل العلم كما قالت السائلة، ولكن الصواب أن فيه الزكاة، الصواب والأرجح من قولي العلماء أن في الحلي من الذهب والفضة الزكاة؛ لأنه ورد في الأحاديث الصحيحة عن رسول الله عليه الصلاة والسلام تدل على وجوب الزكاة في الحلي، من الذهب والفضة، ولو كانت تلبسه ولو كانت تعيره، هذا هو الصواب. ومن ذلك ما روى أبو داود و النسائي عن عبد الله بن عمرو بن العاص رضي الله تعالى عنهما: أن امرأة أتت النبي ﷺ وعليها سواران من ذهب، فقال: أتعطين زكاة هذا؟ قالت: لا. قال: أيسرك أن يسورك الله بهما يوم القيامة سوارين من نار؟ فألقتهما وقالت: هما لله ولرسوله فيه أحاديث أخرى تدل على ذلك.\nوالواجب أن تنظر في النصاب، فإذا كان يبلغ النصاب زكته كل سنة، على حسب قيمة الذهب، فإذا كان الذهب يبلغ أحد عشر جنيهاً وثلاثة أسباع جنيه يعني: حول النصف، يعني نصف جنيه تقريباً، إذا بلغ ذلك ففيه الزكاة، وما زاد فبحساب ذلك، فإذا كان عندها ذهب، يعني يقدر: بأربعين جنيه يكون فيه جنيه واحد أو قيمته، وهكذا ما زاد على ذلك، ويمكن سؤال الصاغة عن زنته؛ لأن النصاب عشرون مثقالاً، ومقدار ذلك بالجنيهات إحدى عشر جنيه وثلاثة أسباع جنيه، هذا مقدار العشرين مثقال من الذهب، فالزكاة تكون ربع العشر. أما الفضة فنصابها مائة وأربعون مثقالاً، مقداره من الذهب الفضي السعودي ستة وخمسون ريالاً فضياً، فإذا بلغ النصاب هذه الفضة أو هذا الورق بلغ ما قيمته ستة وخمسون ريال فضياً وجبت فيه الزكاة، وهكذا الذهب إذا كان عندها ذهب يبلغ أحد عشر جنيهاً وثلاثة أسباع جنيه وجبت فيه الزكاة كل سنة، ولو بلغ آلاف الجنيهات عليها أن تزكي ربع العشر من هذه الحلي؛ مثل القلائد من الذهب، أسورة أخراص.. غير ذلك، تجمع الجميع وتزكي عن الجميع ربع العشر، إذا كان يبلغ مثلاً مائة ألف ريال تزكي هذا المبلغ ألفين ونصف ربع العشر عن هذا الذهب الذي عندها.\nأما الماس واللؤلؤ والعقيق هذا لا زكاة فيه، إذا كان في حليها ماس أو عقيق أو شبه ذلك من اللآلي، هذا لا زكاة فيه، إنما الزكاة في الذهب خاصة، إذا كانت هذه الأمور لم تعد للتجارة، كاللؤلؤ ونحوه والماس إنما أعد للبس، هذا ليس فيه زكاة، وإنما الزكاة في الذهب خاصة والفضة عند أهل العلم، كما جاءت به الأخبار عن النبي عليه الصلاة والسلام.\nوالواجب ربع العشير في الذهب الموجود عندها كل سنة، ولا عبرة بأثمانها السابقة، العبرة بالقيمة وقت الزكاة ما يساوي هذا الذهب وقت الزكاة، في رمضان أو في غير رمضان. نعم.\nالمقدم: لكن سماحة الشيخ! الزكاة على الذهب والفضة إذا كانت حلياً هل يلزم أن تبلغ الذهب مثلاً إحدى عشر جنيه وثلاثة أسباع؟\nالشيخ: اللي أقل ما فيه شيء، نعم.\nالمقدم: اللي أقل ما فيه شيء، والفضة خمس أواق؟\nالشيخ: مائة وأربعين مثقالاً.\nالمقدم: إذا نقص وهو حلي فليس عليه شيء؟\nالشيخ: لا، ما كان أقل من هذا فليس فيه زكاة. نعم.","link":"https://binbaz.org.sa/fatwas/4331/كيفية-اخراج-زكاة-الحلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_005/00505.mp3","categories":["إخراج الزكاة وأهلها","زكاة النقدين"]},{"id":7488,"question":"هذه أيضاً رسالة وصلت وتستفسر المرسلة فيها عن كيف تخرج زكاة الذهب، والذهب والماس معاً، والبلاتين واللؤلؤ، وقد عرفنا في الإجابة الماضية كيف يخرج زكاة الذهب، وعرفنا أن اللؤلؤ والماس وما إلى ذلك لا زكاة فيه من سماحتكم؟","title":"حكم الزكاة في الماس واللؤلؤ وأشباهها","answer":"الجواب: هذا جوابه نعم؛ جوابه ما تقدم، الماس والبلاتين وأشباه ذلك مما ليس بذهب ولا فضة ليس فيه زكاة، إذا كان للبس وليس للتجارة، وإنما الواجب في الذهب المعروف وفي الفضة المعروفة، إذا حال الحول عليها وقد بلغت النصاب، ولو كانت في الحلي ولو كانت تلبس أو تعار، هذا هو الصحيح من أقوال العلماء. نعم.","link":"https://binbaz.org.sa/fatwas/4333/حكم-الزكاة-في-الماس-واللولو-واشباهها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_005/00507.mp3","categories":["زكاة النقدين"]},{"id":7578,"question":"يقول أيضاً عيسى بن علي بن المعتوق من الكويت: لي خمسة دنانير في البنك، وقد مر عليها الحول ولم أستفد منها، فهل عليها زكاة، علماً أن خمسة دنانير حوالي أربعين ريال سعودي؟","title":"لا زكاة فيما دون النصاب","answer":"الجواب: إذا كان عندك دراهم تكمل النصاب فعليك الزكاة إذا تم الحول، أما إذا كان ما عندك إلا هذه الدنانير فإنها ليس فيها زكاة؛ لأنها لا تبلغ النصاب، فإذا كان عندك دنانير تم عليها الحول تضم إلى هذه فلا بأس، إذا كان الجميع نصاباً وتم على الجميع الحول فإنك تزكي الجميع، أما إذا كان الذي عندك هذه الدنانير فقط الأربعة فإنها لا تبلغ النصاب فلا زكاة فيها. نعم.","link":"https://binbaz.org.sa/fatwas/4584/لا-زكاة-فيما-دون-النصاب ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_018/01802.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":7579,"question":"سؤاله الأخير يقول: كم مقدار المال الذي يجب عليه الزكاة وفقكم الله؟","title":"مقدار النصاب الذي تجب فيه زكاة المال","answer":"الجواب: النصاب الذي تجب فيه الزكاة من الذهب عشرون مثقالاً، أو ما يقوم مقامه من الدنانير الكويتية وغيرها، ومن الفضة مائة وأربعون مثقالا، ومقدار ذلك بالجنيه السعودي والفرنجي أحد عشر جنيه وثلاثة أسباع جنيه؛ لأن الجنيه مثقالان إلا ربع، والنصاب عشرون مثقالاً، فإذا كان عند الإنسان أحد عشر جنيهاً وثلاثة أسباع جنيه من الذهب فإنه تجب فيه الزكاة إذا حال عليه الحول، سواءً كان جنيهات بنفسها، أو كانت حلياً، أو كانت قطعاً غير مسبوكة، أو كان عنده ما يقابلها من العمل الورقية فإنه يزكي ذلك إذا حال عليها الحول، وهكذا الفضة إذا كان عنده منها ما يقابل مائة وأربعين مثقالاً، ومقدار ذلك ستة وخمسون ريال فضة من الدرهم السعودي، أو ما يقابل ذلك من العملة الورقية بحسب القيمة في الأسواق، فهذا هو الذي تجب فيه الزكاة، وما كان أقل من ذلك فإنه لا زكاة فيه.","link":"https://binbaz.org.sa/fatwas/4585/مقدار-النصاب-الذي-تجب-فيه-زكاة-المال ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_018/01803.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":7600,"question":"الرسالة هذه من سوريا من بلدة حمص وأرسلتها المستمعة فاطمة قرة يوسف تقول في رسالتها فاطمة: توفيت جدتي وكان عندها خمسة آلاف ليرة من المال وقد جمعتهم من الناس الذين يأتون عليها قبل وفاتها ويقدمون لها الزكاة؛ لأنهم كانوا يحسبون أنها محتاجة، وأنا أعلم بأن من ملك نصاب الزكاة لا يجوز أن يأخذ زكاة نهائياً، ولكن كان الذي معها أكثر من النصاب بكثير وكانت تأخذ الزكاة من الناس وبعدها توفيت، وأرادوا أولادها الوراثة، فهل يجوز أن يأخذوا هذا المال وهي كانت تأخذه حرام؛ لأنها مالكة النصاب، أفيدونا جزاكم الله خيراً؟","title":"حكم أخذ من يملك نصاب الزكاة زكاة غيره","answer":"الجواب: مثل هذه المرأة التي عندها خمسة آلاف ليرة هذه لا تعد غنية بل هذا قد لا يكفيها لسنتها يعني لو استمرت تنفق منه، وليس من ملك نصاباً من الزكاة يكون غنياً على الصحيح يكون غناه غنى وجوب الزكاة عليه، إذا ملك النصاب صار غنياً بالنسبة إلى وجوب الزكاة عليه، ولكن ليس غنياً بالنسبة إلى منعه من الزكاة، فالغنى قسمان: \n- عنى يوجب الزكاة ولكنه لا يحصل به الغنى عن الحاجة ولا يسد باب الحاجة. \n- والغنى الثاني: غنى يسد الحاجة ويغني عن الحاجة إلى الناس ويحصل به المقصود. \nفالذي يمنع الزكاة هو الثاني هو الغنى الذي لا يحتاج معه صاحبه إلى الدين ولا إلى سؤال الناس بل يكفيه ويكفي عائلته إذا كان له عائلة، هذا الغنى يمنع الزكاة ولا يعطى صاحبه، أما إذا كان عنده مال قليل يزكيه ولو أنفقه لأكله بسرعة فهو يزكيه لوجوده عنده كرأس مال يحفظه ويزكيه ولكنه لو أكله لذهب بسرعة، فلا بأس أن يعطى من الزكاة ما يسد حاجته ويغنيه عن الطواف على الناس، هذا هو الصواب: أن الغنى الذي يمنع الزكاة هو الغنى الذي تحصل به الكفاية لا الغنى الذي يحصل به الزكاة، فينبغي الفرق، يعني فهم الفرق بينهما، هذا هو الصواب، وقول بعض العلماء: من ملك النصاب تجب فيه الزكاة فهو غني لا يعطى. قول ضعيف مرجوح. نعم.","link":"https://binbaz.org.sa/fatwas/4653/حكم-اخذ-من-يملك-نصاب-الزكاة-زكاة-غيره ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_020/02008.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":7720,"question":"هذه الرسالة أو هذا المؤلف وردنا من المستمع مصلح بن عبد المعين الخرماني الحربي من وادي قديد البريكة، وقد جمع فيه ما يزيد على سبعين سؤال في ثمانية وعشرين صفحة.ونقول للأخ مصلح نحن نعتذر عن الإجابة على جميع هذه الأسئلة؛ لأنها تريد وقتاً طويلاً، وهي سوف تأتي من المستمعين، فعليك يا أخ بمتابعة البرنامج وستحصل على الإجابة عنها إن شاء الله تعالى، خصوصاً والمستمع يرجو إرسالها في البريد أيضاً.ومن أسئلة المستمع مصلح ، يقول: هل يجوز لشخص لا تحل له الزكاة أن يأخذها؟","title":"حكم أخذ الزكاة لمن لا تحل له","answer":"الجواب: إذا كان الرجل لا تحل له الزكاة يحرم عليه أخذها، ولو أراد أن يعطيها غيره، ليس له أخذها إلا بإذن صاحبها، إذا قال: أنا أريد أن أعطيها ناس فقراء، يوكله في ذلك، هذا من باب التوكيل، أما أنه يأخذها على أنه فقير ولكن في نيته أن يعطيها غيره فلا، الواجب عليه أنه لا يأخذها إلا إذا كان أهلاً لها، إلا إذا كان من باب الوكالة ليدفعها إلى أناس فقراء فليصرح لصاحب الزكاة بذلك وليخبره بذلك؛ حتى يوكله أو لا يوكله. نعم.","link":"https://binbaz.org.sa/fatwas/4919/حكم-اخذ-الزكاة-لمن-لا-تحل-له ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_031/03106.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":7797,"question":"السؤال الثاني في رسالة عبد الرحمن محمد حزام الشيباني من بحرة يقول: هل الذهب الملبوس التي تلبسه المرأة دائماً مثل البناجر والقلايد، هل يجوز الزكاة فيها أم لا، أفيدوني أفادكم الله؟","title":"حكم زكاة الحلي المعدة للزينة","answer":"الجواب: الحلي حلي الذهب والفضة الذي يلبسه النساء فيه خلاف بين العلماء بعض أهل العلم قال: فيه الزكاة وبعض أهل العلم قال: ما فيه زكاة، والحق والصواب: أن فيه الزكاة الراجح من أقوال العلماء أن فيه الزكاة إذا بلغ النصاب إذا بلغ الذهب عشرين مثقالاً ومقدارها أحد عشر جنيه ونصف من الذهب الجنيه السعودي هذا فيه الزكاة، وإن كان أقل من ذلك فليس فيه زكاة كما جاءت به السنة عن النبي عليه الصلاة والسلام.\nوهكذا الفضة إذا كان حلي من الفضة إذا بلغت مائة وأربعين مثقالاً مقدارها ستة وخمسون ريالاً من فضة فهذا فيه الزكاة، وإن كان أقل من ذلك فليس فيه زكاة، هذا هو الصواب، أما الحلي من اللآلي أو الماس أو العقيق أو ما أشبه ذلك هذا ما فيه زكاة إذا لم يكن للتجارة بل للبس هذا ليس فيه زكاة، وإنما الزكاة في الذهب والفضة خاصة إذا بلغ النصاب كما تقدم على القول المختار الصحيح. نعم.","link":"https://binbaz.org.sa/fatwas/5159/حكم-زكاة-الحلي-المعدة-للزينة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_050/05008.mp3","categories":["زكاة النقدين"]},{"id":7977,"question":"نبدأ أولاً: برسالة محمد جاسم محمد ، من العراق بغداد حيث يقول فيها: أنا موظف وعندي راتب شهري، فهل علي زكاة، أي: هل على الراتب الشهري زكاة، وما مقدارها مع العلم أن راتبي حوالي مائة دينار عراقي، وفقكم الله؟","title":"حكم زكاة المال الموفر من الراتب الشهري","answer":"الشيخ: بسم الله الرحمن الرحيم، الحمد لله، والصلاة والسلام على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: لا شك أن في الرواتب زكاة إذا حال عليها الحول، راتب الإنسان من الدنانير أو الدولارات أو الدراهم أو الجنيهات كل أنواع العمل فيها الزكاة إذا حال عليها الحول، فإذا حال على راتبك -أيها السائل- إذا جمعت منه مالاً وحال عليه الحول فإنه تجب فيه الزكاة ربع العشر، من كل أربعين دينار دينار واحد ربع العشر، أما إذا كنت تنفق راتبك في وقته ولا يبقى عندك شيء منه فليس عليك زكاة، إنما الزكاة فيما حال عليه الحول، إذا اجتمع من راتبك شيء يبلغ النصاب وحال عليه الحول فإنه يجب عليك الزكاة، أما إذا كنت لا تبقي شيئاً منه بل تنفقه في وقته فلا زكاة في ذلك. نعم.","link":"https://binbaz.org.sa/fatwas/5525/حكم-زكاة-المال-الموفر-من-الراتب-الشهري","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_072/07201.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":7985,"question":"نبدأ أولاً: برسالة محمد جاسم محمد ، من العراق بغداد حيث يقول فيها: أنا موظف وعندي راتب شهري، فهل علي زكاة، أي: هل على الراتب الشهري زكاة، وما مقدارها مع العلم أن راتبي حوالي مائة دينار عراقي، وفقكم الله؟","title":"حكم زكاة المال الموفر من الراتب الشهري","answer":"الشيخ: بسم الله الرحمن الرحيم، الحمد لله، والصلاة والسلام على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: لا شك أن في الرواتب زكاة إذا حال عليها الحول، راتب الإنسان من الدنانير أو الدولارات أو الدراهم أو الجنيهات كل أنواع العمل فيها الزكاة إذا حال عليها الحول، فإذا حال على راتبك -أيها السائل- إذا جمعت منه مالاً وحال عليه الحول فإنه تجب فيه الزكاة ربع العشر، من كل أربعين دينار دينار واحد ربع العشر، أما إذا كنت تنفق راتبك في وقته ولا يبقى عندك شيء منه فليس عليك زكاة، إنما الزكاة فيما حال عليه الحول، إذا اجتمع من راتبك شيء يبلغ النصاب وحال عليه الحول فإنه يجب عليك الزكاة، أما إذا كنت لا تبقي شيئاً منه بل تنفقه في وقته فلا زكاة في ذلك. نعم.","link":"https://binbaz.org.sa/fatwas/5525/حكم-زكاة-المال-الموفر-من-الراتب-الشهري","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_072/07201.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":8041,"question":"السؤال أيضاً يقول: بالنسبة لزكاة المال، إذا توفر معي بعض مصاريفي ومصاريف الأولاد خمسة آلاف ريال لمدة سنة، فهل علي زكاة علماً بأنني مقيم في الأحساء للعمل؟","title":"حكم الزكاة في المال الذي بلغ النصاب وحال عليه الحول","answer":"الجواب: نعم إذا توفر لديك ما يبلغ النصاب، وحال عليه الحول وجبت عليه الزكاة، والخمسة الآلاف لا شك أنها نصاب بل أنصب، فعليك أن تخرج زكاتها إذا حال عليها الحول، وهي ربع العشر. نعم.","link":"https://binbaz.org.sa/fatwas/5668/حكم-الزكاة-في-المال-الذي-بلغ-النصاب-وحال-عليه-الحول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_081/08104.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":8138,"question":"أخونا يقول: ما هو نصاب الزكاة بالنسبة للعملة العراقية الدينار؟ وهل تجب الزكاة على الشخص الذي تدفع له الزكاة في نفس الوقت؟","title":"نصاب زكاة المال وحكم أخذ الزكاة ممن تدفع له","answer":"الجواب: أما النصاب فقد وضحه النبي ﷺ، فالذهب نصابه عشرون مثقالاً، ومقدار ذلك بالغرام اثنان وتسعون غرام، وبالجنيه السعودي والفرنجي إحدى عشر جنيه وثلاثة أسباع الجنيه، يعني: إحدى عشر ونصف، الكسر اليسير لا يضر، إحدى عشر جنيه وثلاثة أسباع هي إحدى عشر جنيه ونصف؛ لأنه أوضح للحاسب، فهذا هو النصاب بالنسبة إلى الذهب، وبالفضة نصابها مائة وأربعون مثقالاً من الفضة، فما يقوم مقام ذلك من الدولار الأمريكي أو الدينار العراقي أو غير ذلك ما يقوم مقام هذا ويساوي هذا هو النصاب، ما يساوي مثلاً مائة وأربعين مثقال من الفضة أو يساوي إحدى عشر جنيه من الذهب إحدى عشر ونصف من الذهب هذا يسمى نصاباً، ويجب فيه ربع العشر في المائة اثنان ونصف، في المائتين خمسة، في الألف خمسة وعشرون ربع العشر، وإذا أحب أن يزكي ما عنده ولا ينظر إلى النصاب فالأمر في هذا واسع؛ لأن النصاب قليل، يعني: أقل نصاب هو شيء قليل، فإذا كان عند الإنسان أموال زكاها؛ لأن النصاب قليل جداً مقدار عشرين مثقال من الذهب أو مائة وأربعين مثقال من الفضة مقدارها ستة وخمسين ريال من السعودي، ستة وخمسون ريالاً من الفضة من العملة السعودية وهذا شيء قليل فلا يحتاج الإنسان إلى التكلف من جهة النصاب يزكي ما عنده والحمد لله؛ لأنه في الغالب قد بلغ النصاب، ويا أهل المئات والألوف قد بلغ النصاب عندكم، إنما قد يشتبه على أهل الدنانير القليلة، إذا كان عندهم شيء قليل فهؤلاء ينظرون في قيمتها بالنسبة إلى الجنيه الفرنجي والسعودي المعروف بالنسبة إلى عشرين مثقال من الذهب ماذا تساوي، فإذا كان ما عنده يساوي عشرين مثقال من الذهب وجب فيه الزكاة.\nأو يساوي مائة وأربعين مثقال من الفضة وجب فيه الزكاة، ويعرفون هذا بالنظر إلى أهل الذهب والفضة إذا راجعوهم أهل الذهب والفضة -الصيارفة- إذا راجعوه وسألوه عن قيمة عشرين مثقال من الذهب عن قيمة مائة وأربعين مثقال من الفضة عرفوا ذلك، ولا حاجة إلى التكلف إذا زكى ما عنده فالحمد لله. نعم.\nالمقدم: بارك الله فيكم، إذاً: لو قيل أيضاً لأخينا هذا عليه أن يزكي ربع العشر دائماً؟\nالشيخ: يكفي ولا يحتاج تكلف يسأل. نعم.\nالمقدم: بارك الله فيكم، الرسالة التالية باعثها أحد الإخوة يقول سعيد يوسف محمود .. ؟\nالشيخ: بقي في سؤاله هل يعطى له الزكاة؟\nالمقدم: أيوه عفواً نعم.\nالشيخ: نعم، إذا كان عليه زكاة وهو فقير يعطى إذا كان مثلاً إنسان عنده ألف دينار قلنا: عليك خمسة وعشرون زكاة، ربع العشر، ولكن هذا الألف الذي يتسبب فيه، يعمل فيه ما يكفيه عنده عائلة ما يكفيه هذا لو صرف هذا المال ما بقي عنده شيء، فهو يعمل في هذا المال في حاجات في بيع وشراء في سلع، فهو يعطى من الزكاة ما يقوم بحاله وتبقى هذه الجنيهات التي عنده أو الدولارات التي عنده يتسبب فيها حتى يستعين بها على حاجات البيت، فيعطى لأنه فقير ويزكي ما عنده من هذا المال الذي بلغ النصاب، فعنده ألف دينار مثلاً يزكيه خمسة وعشرين كل سنة إذا كان في حاجات يبيعها في الدكان أو في مبسط بقالة أو شيء يزكي هذا الشيء ويعطى من الزكاة ما يكمل حاجته؛ لأنها ربح الألف الدينار أو ألف الدولار أو ألف جنيه إسترليني أو نحوه ربحها وما يحصل فيها قد لا يقوم بحاله ولا يكفيه في حاجات البيت فيعطى من الزكاة ما يسد حاجته ولا يقال: عليك أن تنفق هذا وتبقى معطلاً، لا، يتجر في هذا ويتسبب في هذا المال الذي بيديه حتى يستعين بربحه في حاجات البيت ويعطى من الزكاة ما يقوم بحاله، وهكذا لو كان عنده قلنا: مثلاً مائة دينار وزكى منها اثنين ونص، المائة الباقية ما تساوي شيء بالنسبة إلى حاجته فيعطى ما يسد حاجته من إخوانه من زكاة إخوانه المسلمين ولا بأس هذا، هو الذي عليه جمهور أهل العلم.\nنعم، ذهب بعض أهل العلم إلى أن من زكى لا يعطى، وهذا قول ضعيف، الصواب: أنه يعطى إذا كان فقيراً ولو وجبت عليه الزكاة في مال عنده. نعم.\nالمقدم: بارك الله فيكم، نؤجل رسالة أخينا سعيد يوسف محمود من بيشة سبت العلايا إلى الحلقة القادمة إن شاء الله تعالى.\nسماحة الشيخ في ختام هذا اللقاء أتوجه لكم بالشكر الجزيل بعد الله سبحانه على تفضلكم بإجابة السادة المستمعين وآمل أن يتجدد اللقاء وأنتم على خير وعافية.\nالشيخ: إن شاء الله.","link":"https://binbaz.org.sa/fatwas/5933/نصاب-زكاة-المال-وحكم-اخذ-الزكاة-ممن-تدفع-له","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_103/10307.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":8210,"question":"أخذت من شخص قطعة أرض لكي أزرعها، واشترط علي أن أعطيه الزكاة، سواء كان فقيراً أم غنياً، فقد أعطيته، فهل أديت الواجب علي وهذه الحالة أم لا؟","title":"حكم اشتراط دفع زكاة العين المؤجرة للمؤجر","answer":"الجواب: هذا العقد باطل، لا يجوز أن تستأجر الأرض بشرط أنك تعطيه الزكاة، هذا لا يجوز، تتفق معه على الأجرة التي ترضاها ويرضاها ويكفي، أما شرط الزكاة فلا، ولو كان فقيراً ما يصير شرط الزكاة له ؛ لأن الفقراء كثيرون، وهذه إجارة، معاملة ما تكون بالزكاة تقوم بأجور أخرى، وإذا كان فقيراً فلك أن تعطيه بغير شرط، لك أن تعطيه من الزكاة إذا أردت ذلك من دون شرط ولا يلزم، بل لك أن تعطي غيره من الفقراء، المقصود: لا يجوز شرطها في الأجرة أبداً لا قليلاً ولا كثيراً، بل يجب أن تكون الأجرة من غير الزكاة متفقاً عليها بينكما، أما كونك تعطيه من الزكاة أم لا هذا شيء آخر، لك أن تعطيه إذا كان من أهلها، ولك أن تحرمه وتعطي غيره، ليس عليك جناح في هذا، ولا يجوز أن تربط بالإجارة من كل الوجوه. نعم.","link":"https://binbaz.org.sa/fatwas/6024/حكم-اشتراط-دفع-زكاة-العين-الموجرة-للموجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_095/09510.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":8219,"question":"رسالة وصلت إلى البرنامج من المدينة المنورة وباعثتها إحدى الأخوات المستمعات رمزت إلى اسمها بالحرفين (ع. س) الأخت لها مجموعة من الأسئلة، من بين أسئلتها سؤال يقول: هل يجوز زكاة الذهب الملبوس بالثمن الذي اشتري به؟","title":"حكم زكاة الحلي وكيفية إخراجها","answer":"الجواب: المسألة فيها خلاف بين أهل العلم في أصلها، هل يجب إخراج الزكاة عن حلي المرأة التي تلبسها أم ذلك ساقط عنها؟ هذا محل خلاف بين أهل العلم، والصواب أنه يجب إخراج الزكاة عن الحلي؛ لأن الأدلة الدالة على ذلك سليمة من المعارض وقوية وصحيحة.\nفالواجب على المرأة إخراج الزكاة من حليها إذا بلغت النصاب وحال عليها الحول، سواء كانت الحلي أسورة أو قلائد أو غير ذلك من أنواع الحلي، إذا بلغت النصاب وهو عشرون مثقالاً من الذهب مقداره بالجنيه السعودي: أحد عشر جنيه وثلاثة أسباع جنيه، يعني: نصف جنيه، إحدى عشر جنيه ونصف، وبالجرام: اثنان وتسعون غراماً، فإذا بلغ هذا المقدار وجبت الزكاة، وإن كان أقل لم تجب فيه الزكاة، وهذا كله على مقتضى أدلة حسب القول الراجح في هذه المسألة ولو كان ملبوساً، ولو كانت تلبسه، لكن الزكاة لا تكون بالثمن، يراعى فيها القيمة، فلو كانت اشترت مثلاً حلي بعشرة آلاف ريال، وعند تمام الحول لا يساوي إلا ثمانية آلاف لا تزكي إلا ثمانية لأنه نقص، وهكذا العكس لو كانت اشترته بعشرة وعند تمام الحول يساوي خمسة عشر زاد الذهب، غلا، تزكي خمسة عشر، القيمة التي موجودة عند تمام الحول، زائدة أو ناقصة. نعم.\nالمقدم: لكن الزكاة سماحة الشيخ من نفس المزكى، أو لا مانع من إخراج قيمته؟\nالشيخ: ما هو بلازم، ولو من الورق المعروف، العملة الورقية أو من الفضة لا بأس. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6033/حكم-زكاة-الحلي-وكيفية-اخراجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_096/09606.mp3","categories":["زكاة النقدين"]},{"id":8225,"question":"رسالة وصلت إلى البرنامج من المدينة المنورة وباعثتها إحدى الأخوات المستمعات رمزت إلى اسمها بالحرفين (ع. س) الأخت لها مجموعة من الأسئلة، من بين أسئلتها سؤال يقول: هل يجوز زكاة الذهب الملبوس بالثمن الذي اشتري به؟","title":"حكم زكاة الحلي وكيفية إخراجها","answer":"الجواب: المسألة فيها خلاف بين أهل العلم في أصلها، هل يجب إخراج الزكاة عن حلي المرأة التي تلبسها أم ذلك ساقط عنها؟ هذا محل خلاف بين أهل العلم، والصواب أنه يجب إخراج الزكاة عن الحلي؛ لأن الأدلة الدالة على ذلك سليمة من المعارض وقوية وصحيحة.\nفالواجب على المرأة إخراج الزكاة من حليها إذا بلغت النصاب وحال عليها الحول، سواء كانت الحلي أسورة أو قلائد أو غير ذلك من أنواع الحلي، إذا بلغت النصاب وهو عشرون مثقالاً من الذهب مقداره بالجنيه السعودي: أحد عشر جنيه وثلاثة أسباع جنيه، يعني: نصف جنيه، إحدى عشر جنيه ونصف، وبالجرام: اثنان وتسعون غراماً، فإذا بلغ هذا المقدار وجبت الزكاة، وإن كان أقل لم تجب فيه الزكاة، وهذا كله على مقتضى أدلة حسب القول الراجح في هذه المسألة ولو كان ملبوساً، ولو كانت تلبسه، لكن الزكاة لا تكون بالثمن، يراعى فيها القيمة، فلو كانت اشترت مثلاً حلي بعشرة آلاف ريال، وعند تمام الحول لا يساوي إلا ثمانية آلاف لا تزكي إلا ثمانية لأنه نقص، وهكذا العكس لو كانت اشترته بعشرة وعند تمام الحول يساوي خمسة عشر زاد الذهب، غلا، تزكي خمسة عشر، القيمة التي موجودة عند تمام الحول، زائدة أو ناقصة. نعم.\nالمقدم: لكن الزكاة سماحة الشيخ من نفس المزكى، أو لا مانع من إخراج قيمته؟\nالشيخ: ما هو بلازم، ولو من الورق المعروف، العملة الورقية أو من الفضة لا بأس. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6033/حكم-زكاة-الحلي-وكيفية-اخراجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_096/09606.mp3","categories":["زكاة النقدين"]},{"id":8231,"question":"أموال الناس التي في ذمتي ومضى عليها أكثر من سنتين، وهل تجب الزكاة فيها علي أو على أهلها؟","title":"حكم زكاة المال المقترض","answer":"الجواب: أموال الناس التي عليك ليس عليك زكاتها، إلا إذا كانت عندك موجودة في قبضتك وفي حوزتك، فهذه أموالك ليست أموالهم، أموالهم في الذمة، أما ما كان في حوزتك من النقود أو عروض التجارة ولو أنها جاءتك بالسلف أو بالاستدانة عليك أن تزكيها إذا حال عليها الحول.\nأما الديون التي في ذمتك للناس فهذه زكاتها عليهم إن كنت موسراً وباذلاً، وإن كنت معسراً أو مماطلاً فلا زكاة عليهم كما تقدم.","link":"https://binbaz.org.sa/fatwas/6053/حكم-زكاة-المال-المقترض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_097/09713.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":8235,"question":"أموالي الموضوعة في البنوك؟","title":"حكم الزكاة عن الأموال التي في البنوك","answer":"الجواب: فيها الزكاة، المال الذي في البنك فيه الزكاة، وليس لك أن تعامل بالربا، لكن مالك الذي وضعته في البنك كالأمانة عليك أن تزكيه؛ لأنك متى طلبته أخذته. نعم.","link":"https://binbaz.org.sa/fatwas/6054/حكم-الزكاة-عن-الاموال-التي-في-البنوك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_097/09714.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":8237,"question":"زكاة الأموال المتفرقة كالعمائر والأراضي والدكاكين ونحوها؟","title":"كيفية إخراج زكاة الأموال المتفرقة كالعمائر وغيرها","answer":"الجواب: هذه فيها تفصيل: إن كانت معدة للتجارة فعليك زكاتها، كل حول حسب القيمة غلاء ورخصاً، إن غلت تزكها غالية، وإن رخصت زكها رخيصة على حسب قيمتها عند تمام الحول إذا كانت للبيع.. للتجارة، أما إن كانت للسكن أو للتأجير لا للتجارة والبيع بل للسكن أو للتأجير أو عندك تردد لم تجزم بشيء فلا زكاة فيها، ولكن إذا كانت للتأجير تزكي الأجرة إذا حال عليها الحول. نعم.","link":"https://binbaz.org.sa/fatwas/6055/كيفية-اخراج-زكاة-الاموال-المتفرقة-كالعماىر-وغيرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_097/09715.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":8239,"question":"أموالي الموضوعة في البنوك؟","title":"حكم الزكاة عن الأموال التي في البنوك","answer":"الجواب: فيها الزكاة، المال الذي في البنك فيه الزكاة، وليس لك أن تعامل بالربا، لكن مالك الذي وضعته في البنك كالأمانة عليك أن تزكيه؛ لأنك متى طلبته أخذته. نعم.","link":"https://binbaz.org.sa/fatwas/6054/حكم-الزكاة-عن-الاموال-التي-في-البنوك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_097/09714.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":8241,"question":"زكاة الأموال المتفرقة كالعمائر والأراضي والدكاكين ونحوها؟","title":"كيفية إخراج زكاة الأموال المتفرقة كالعمائر وغيرها","answer":"الجواب: هذه فيها تفصيل: إن كانت معدة للتجارة فعليك زكاتها، كل حول حسب القيمة غلاء ورخصاً، إن غلت تزكها غالية، وإن رخصت زكها رخيصة على حسب قيمتها عند تمام الحول إذا كانت للبيع.. للتجارة، أما إن كانت للسكن أو للتأجير لا للتجارة والبيع بل للسكن أو للتأجير أو عندك تردد لم تجزم بشيء فلا زكاة فيها، ولكن إذا كانت للتأجير تزكي الأجرة إذا حال عليها الحول. نعم.","link":"https://binbaz.org.sa/fatwas/6055/كيفية-اخراج-زكاة-الاموال-المتفرقة-كالعماىر-وغيرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_097/09715.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":8257,"question":"أخ مصري اسمه أحمد عبد الشكور يقول: أرسلت زكاة الفطر الخاصة بي إلى أهلي لكي يخرجوها في البلد، فهل هذا العمل صحيح؟","title":"حكم إخراج الزكاة في غير بلد المزكي","answer":"الجواب: لا بأس، تجزئ إن شاء الله، ولكن إخراجها في محلك أفضل، كونك تخرجها في محلك يعني الذي أنت مقيم فيه لبعض الفقراء يكون أولى، وإذا بعثتها إلى أهلك ليخرجوها على الفقراء فلا بأس. نعم.","link":"https://binbaz.org.sa/fatwas/6068/حكم-اخراج-الزكاة-في-غير-بلد-المزكي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_098/09808.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":8350,"question":"لقد سمعت من فضيلتكم في حلقة سابقة من هذا البرنامج: أن مقدار نصاب الذهب هو اثنان وتسعون غرام، فأرجو من فضيلتكم أن توضحوا لنا كم تكون زكاة النصاب بالريال السعودي المتداول حالياً في الأسواق، جزاكم الله خيراً؟","title":"نصاب زكاة الذهب بالريال السعودي","answer":"الجواب: نعم النصاب، نصاب الذهب عشرون مثقالاً، وهو يقدر باثنين وتسعين غرام، ويقدر من جهة الجنيه بإحدى عشر جنيه وثلاثة أسباع جنيه- يعني: إحدى عشر جنيه ونصف-؛ لأن الفرق بين الثلاثة الأسباع والنصف شيء يسير، فإذا بلغ الذهب أحد عشر جنيهاً ونصف، سواءً كان أسورة أو غير ذلك اثنين وتسعين غرام وجبت فيه الزكاة، والزكاة ربع العشر من كل شيء، الزكاة ربع العشر من المائة اثنان ونصف، من الألف خمسة وعشرون، من الأربعين واحد، وهكذا، ربع العشر من الذهب والفضة جميعاً. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6168/نصاب-زكاة-الذهب-بالريال-السعودي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_113/11307.mp3","categories":["زكاة النقدين"]},{"id":8384,"question":"الرسالة التالية رسالة وصلت من جمهورية مصر العربية، السويس، وباعثها أخونا أحمد عبد الله، أخونا يقول: أنا موظف أعمل في إحدى الشركات، والشركة التي أعمل بها بعثت بي إلى الخارج للدراسة، وفي أثناء تواجدي في الخارج للدراسة، كانت الشركة تضع لي مرتبي الشهري وعلاواتي في البنك، وقد مضى عليها سنتان، وهي تتجمع في البنك، ولم آخذ منها إلا مبالغ قليلة أثناء تواجدي في بلدي، ثم أسافر لأكمل دراستي، والسؤال هنا: هل علي زكاة في هذا المال؟ علماً بأنني لا أدخره للتجارة، أو نحو ذلك، بل إنني أجمعه حتى تنتهي دراستي وأعود إلى بلادي نهائياً لكي أتزوج منه، وأبني أسرتي؟ وإن كانت هناك زكاة، فما هو المقدار فيها؟","title":"حكم زكاة الأموال التي تجمع للزواج وغيرها","answer":"الجواب: لا ريب أن الأموال التي يجمعها المؤمن إما لزواج، وإما لتعمير سكن، وإما لغير هذا، تجب فيها الزكاة؛ لأن الله جل وعلا أوجب الزكاة في النقدين، وما يقوم مقامهما من العمل، وهكذا أوجب الزكاة في بهيمة الأنعام السائمة، من الإبل والبقر والغنم، وأوجب الزكاة أيضاً في عروض التجارة المعدة للبيع، وأوجب الزكاة في الحبوب والثمار إذا بلغت النصاب.\nفهذه الأموال التي تحفظ في البنك وتودع في البنوك، ليستنفع بها صاحبها في قضاء دين، أو ليستنفع بها في زواج، أو في تعمير سكن، أو في غير ذلك، كلها تجب فيها الزكاة، ولا نعلم خلافاً بين أهل العلم في ذلك، إذا بلغت النصاب وحال عليها الحول، والواجب ربع العشر، في كل مائة اثنان ونصف، في الألف خمسة وعشرون، هذا هو الواجب عند جميع أهل العلم، ربع العشر، كما بينه النبي عليه الصلاة والسلام، قال: في كل مائتين خمسة دراهم هكذا قال عليه الصلاة والسلام. نعم.","link":"https://binbaz.org.sa/fatwas/6235/حكم-زكاة-الاموال-التي-تجمع-للزواج-وغيرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_116/11603.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":8398,"question":"رسالة من أحد الإخوة المستمعين يقول: لي دين عند أحد الإخوة، هل تلزمني زكاته أو أن هناك وقتاً محدداً؟","title":"تفصيل أحوال زكاة الدين","answer":"الجواب: إذا كان الدين الذي لك على موسرين باذلين، متى طلبته أعطوك حقك فعليك أن تزكيه كلما حال الحول، كأنه عندك، كأنه عندهم أمانة، أو كأنه في صندوق عليك أن تزكيه.\nأما إن كان من عليه الدين معسراً، لا يستطيع أداءه لك، أو كان غير معسر لكنه يماطلك ولا تستطيع أخذه منه، فالصحيح من أقوال العلماء: أنه لا يلزمك أداء الزكاة حتى تقبضه منه، من هذا المماطل أو من هذا المعسر، فإذا قبضته استقبلت به حولاً وأديت الزكاة بعد تمام الحول من قبضك له، وإن أديت الزكاة عن سنة واحدة من السنوات السابقة التي عند المعسر أو المماطل فلا بأس، قال هذا بعض أهل العلم، ولكن لا يلزمك إلا في المستقبل، متى قبضت المال من المعسر أو المماطل واستقبلت به حولاً ودار عليه الحول تلزمك الزكاة، هذا هو المختار. نعم.","link":"https://binbaz.org.sa/fatwas/6264/تفصيل-احوال-زكاة-الدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_117/11703.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":8399,"question":"أنا بعت ذهباً قديماً ولم أزكه من قبل، فأرجو أن توضحوا لنا كيف تكون زكاته؟ وإذا بعت بأربعة آلاف ريال فهل أدفع الزكاة من هذا المبلغ؟","title":"حكم من باع ذهباً ولم يزكه","answer":"الجواب: إذا كنت لم تعلمي وجوب الزكاة إلا بعد ذلك فلا شيء عليك، وإن كنت تعلمين ذلك فزكي هذه الأربعة، من كل ألف خمسة وعشرون عن السنة الواحدة، عن كل ألف خمسة وعشرون ربع العشر، وهكذا السنوات التي قبلها بحسب قيمة الذهب في السوق، الواجب ربع العشر تؤدي هذه الزكاة من العملة المعروفة.\nأما إذا كنت لا تعلمين ذلك إلا في السنة الأخيرة، فعليك الزكاة عن السنة الأخيرة من كل ألف خمسة وعشرون. نعم.","link":"https://binbaz.org.sa/fatwas/6269/حكم-من-باع-ذهبا-ولم-يزكه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_117/11704.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":8401,"question":"رسالة وصلت إلى البرنامج من نجران الخانق، باعثتها إحدى الأخوات من هناك، تقول: (ف. ن. ع) أختنا في الواقع عقبت برسالة أخرى على الرسالة الأولى، وتسأل عن مجموعة من القضايا من بينها: قضية الزكاة في الحلي لو تكرمتم سماحة الشيخ؟","title":"القول الفصل في زكاة الحلي","answer":"الجواب: الحلي من الذهب والفضة اختلف فيها العلماء: هل فيها الزكاة أم لا؟ على قولين مشهورين: والأرجح منهما: أن في الحلي الزكاة إذا بلغت النصاب، فإذا بلغ الذهب نصاب الذهب وهو عشرون مثقالاً، ومقدار ذلك بالعملة الذهبية السعودية إحدى عشر جنيه سعودي ونصف، ثلاثة أسباع جنيه، لكن النصف أوضح، إحدى عشر جنيه ونصف، وإن قلت: إحدى عشر جنيه وثلاثة أسباع فصحيح، ولكن النصف أوضح للناس، إحدى عشر جنيه ونصف، والفرق بين الثلاثة الأسباع والنصف شيء يسير. فإذا بلغت الحلي من الذهب هذا المقدار أحد عشر جنيه ونصف جنيه فأكثر فإن فيها الزكاة على الصحيح، وهي ربع العشر من كل ألف خمسة وعشرون، من المائة اثنان ونصف، ومقدار ذلك بالجرام اثنين وتسعين جرام، مقدار ذلك بالجرام المعروف اثنان وتسعون، فإذا بلغ الحلي هذا المقدار وجبت الزكاة، وهكذا الفضة، إذا كان عند المرأة حلي من الفضة تزكيها إذا بلغت مائة وأربعين مثقالاً، ومقدارها بالدرهم السعودي ستة وخمسون ريال سعودي، هذا هو الواجب؛ لأنه ثبت عن النبي ﷺ أنه قال: ما من صاحب ذهب ولا فضة لا يؤدي زكاتها، إلا إذا كان يوم القيامة صفحت له يوم القيامة صفائح من نار فيكوى بها جبينه وجنبه وظهره... الحديث، وهذا يعم الحلي وغير الحلي.\nكذلك ثبت عنه ﷺ: أنه دخلت عليه امرأة في يد ابنتها مسكتان من ذهب -يعني: سوارين من ذهب- فقال: أتعطيان زكاة هذا؟ قالت: لا، قال: أيسرك أن يسورك الله بهما يوم القيامة سوارين من نار؟ فألقتهما، وقالت: هما لله ولرسوله.\nوثبت أيضاً: أنه ﷺ سألته أم سلمة عن حلي كانت تلبسها من الذهب أكنز هذا؟ فقال: ما بلغ أن يزكى فزكي فليس بكنز فدل ذلك على أن الحلي تعتبر كنزاً إذا لم تزك.\nفالواجب على المرأة أن تزكي ما عندها من الحلي أي: من الذهب والفضة إذا بلغت النصاب كما تقدم وحال عليها الحول. نعم.","link":"https://binbaz.org.sa/fatwas/6279/القول-الفصل-في-زكاة-الحلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_117/11706.mp3","categories":["زكاة النقدين"]},{"id":8407,"question":"هل يصح أن يحتفظ بالزكاة من أجل إعطائها لأحد الفقراء الذين لم أتصل بهم بعد؟","title":"حكم تأجيل زكاة الأموال والأبدان لفقراء معينين","answer":"الجواب: إذا كانت المدة يسيرة غير طويلة فلا بأس، سيحتفظ بالزكاة حتى يعطيها بعض الفقراء من أقاربه، أو من هو أشد فقراً وحاجة، لكن لا تكون مدة طويلة، ...... أيام غير كثيرة. نعم.\nالمقدم: طيب وسواء في ذلك زكاة الأموال أو الأبدان سماحة الشيخ؟\nالشيخ: نعم نعم، لكن زكاة البدن لا، تقدم على العيد، زكاة البدن يجب تقديمها على صلاة العيد كما أمر النبي صلى الله عليه وسلم، وتخرج قبل العيد بيومين أو ثلاث لا بأس. نعم.\nالمقدم: لكن إذاً هي لا تؤجل؟\nالشيخ: لا تؤجل بعد العيد لا.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6291/حكم-تاجيل-زكاة-الاموال-والابدان-لفقراء-معينين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_117/11713.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":8408,"question":"هل يصح إعطاء الزكاة لذمي؟","title":"حكم إعطاء الذميين من الزكاة","answer":"الجواب: الزكاة على قول الجمهور: لا تعطى للذميين الكفرة، وهو الصواب، الزكاة مواساة للمسلمين، وعناية بسد حاجتهم وفقرهم، فيجب أن توزع على المسلمين؛ لسد حاجتهم وفقرهم. نعم.","link":"https://binbaz.org.sa/fatwas/6292/حكم-اعطاء-الذميين-من-الزكاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_117/11714.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":8496,"question":"ما صفة إخراج زكاة الحلي للنساء إذا لم يكن الذهب فيها خالصاً وحده، بل مرصعاً بأنواع عديدة من الفصوص والأحجار الكريمة، فهل يحسب وزن هذه الأحجار والفصوص مع الذهب؛ لأنه من الصعب فصل الذهب عنها في حالة إخراج زكاته؟","title":"كيفية زكاة الذهب المخلوط بغيره","answer":"الجواب: الذهب هو الذي فيه الزكاة إذا كان للبس، وأما الأحجار الكريمة من اللؤلؤ والماس وأشباه ذلك فهذه لا زكاةَ فيها، فإذا كانت القلائد أو غيرها فيها هذا وهذا، فإن المرأة أو زوجها أو أولياءها ينظرون ويتأملون ويُقدرون الذهب، فما غلب على الظن كفى في ذلك، فإذا بلغ النِّصاب زُكِّي. والنِّصاب عشرون مثقالًا، ومقداره في الجنيه السعودي والإفرنجي: أحد عشر جنيهًا سعوديًّا ونصفًا.\nوبالجرامات: اثنين وتسعين جرامًا.\nفإذا بلغت الحُلي من الذهب هذا المقدار ففيها الزكاة، وإذا كانت فيها فصوصٌ وماسٌ وأشباه ذلك قُدِّر الذهب بغالب الظن واجتهد، أو عُرض على أهل الخبرة، فإنه قد يكون تمييزهم أكثر حتى يُقدروا الذهب، فإذا بلغ الذهب هذا المقدار -يعني: اثنين وتسعين جرامًا، عشرين مثقالًا، أحد عشر جنيهًا سعوديًّا، هذا هو النِّصاب- يُزكَّى كل سنةٍ.\nوفيه ربع العُشر، في كل ألفٍ خمسٌ وعشرون، هذا هو الصحيح من أقوال أهل العلم فيما يتعلق بالحُلي. أما إن كانت للتجارة فإنها تُزكَّى كلها، إذا كانت الحُلي للتجارة، وما فيها من لآلئ أو ماس أو غير هذا للتجارة فإنها تُزكَّى كلها حسب القيمة كسائر عروض التجارة عند جمهور أهل العلم، وحكاه بعضهم إجماع أهل العلم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6556/كيفية-زكاة-الذهب-المخلوط-بغيره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_126/12610.mp3","categories":["زكاة النقدين"]},{"id":8576,"question":"تسأل سؤالها الثاني وتقول: هل على الذهب المعد للاستعمال زكاة، وإذا كانت فما قيمتها بالريال السعودي؟","title":"حكم زكاة الحلي المعد للاستعمال ومقدارها","answer":"الجواب: الذهب المعد للبس وهكذا الفضة الصواب أن فيهما الزكاة، فيه قول لبعض أهل العلم أنه لا زكاة في ذلك إذا كانت معدة للبس أو تلبس، ولكن الصواب أن المعد للبس والملبوس وغيرهما كلها فيها الزكاة؛ لأنه ثبت عن النبي ﷺ ما يدل على ذلك، فإذا كان عند المرأة ذهب يبلغ النصاب وهو عشرون مثقالاً ومقداره من الجنيه السعودي أحد عشر جنيه ونصف، ومن الغرام اثنين وتسعين غرام إذا كان يبلغ هذا ففيه الزكاة، وهكذا لو كان أكثر، وهي ربع العشر، في الألف خمسة وعشرون سواءً كان ملبوساً أو معداً للبس أو غير ذلك، هذا هو الصواب.\nوقد ثبت عنه ﷺ أنه رأى امرأة على ابنتها سواران من ذهب فقال: أتعطين زكاة هذا؟ قالت: لا. قال: أيسرك أن يسورك الله بهما يوم القيامة سوارين من نار، فألقتهما وقالت: هما لله ولرسوله وقال عليه الصلاة والسلام: ما من صاحب ذهب ولا فضة لا يؤدي زكاتها -وفي اللفظ الآخر: حقها- إلا إذا كان يوم القيامة صفحت له صفائح من نار فيكوى بها جنبه وجبينه وظهره.. الحديث، وهذا يعم الحلي وغيرها من أنواع الذهب والفضة، وفي الباب أحاديث أخرى تدل على ذلك.\nأما إن كان الموجود أقل من النصاب، إن كان الحلي أقل من أحد عشر جنيه ونصف، أو كانت الفضة أقل من النصاب، ونصاب الفضة مائة وأربعون مثقالاً، ومقداره بالريال السعودي ستة وخمسون ريالاً من الفضة أو ما يعادلها من العمل الأخرى، إذا كان أقل من ذلك فلا زكاة فيه، فإن كان يبلغ هذا ستة وخمسين ريال فضة أو أكثر وجبت الزكاة فيه إذا حال عليه الحول، نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/6654/حكم-زكاة-الحلي-المعد-للاستعمال-ومقدارها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_208/20802.mp3","categories":["زكاة النقدين"]},{"id":8749,"question":"هذه رسالة وردتنا من السائل (أ. م. س) من الرياض يقول في رسالته: أنا شاب موظف لي دخل شهري محدود آخذ منه ما أحتاجه والباقي أضعه في البنك حتى يتكون لدي مبلغ أشتري به أرض أقيم عليها مسكناً أسكنه عندما أتزوج، وفعلاً تكون لدي مبلغ خمسة وخمسون ألف ريال وكانت قيمة الأرض مائة وخمسة آلاف فاستلفت المبلغ الباقي، وبعد سنة من شراء الأرض كنت قد سددت المبلغ المطلوب، ولكن بعد أيام فكرت في بيع الأرض لأشتري في موقع أقرب من الأول وفعلاً بعتها ووضعت المبلغ في البنك، وصرت أجمع على ثمن هذه الأرض التي بعتها من رواتبي إلى أن يظهر اسمي من صندوق التنمية العقاري والآن لي سنة ف هل علي زكاة في هذه السنوات الثلاث؛ لأنني سمعت أن من يجمع المال حتى يتزوج أو يبني مسكناً يسكنه لا زكاة عليه؟","title":"حكم زكاة المال المجموع لغرض زواج أو بناء بيت","answer":"الجواب: هذا غلط الصواب أن عليه زكاة، إذا جمع مالاًَ ليتزوج أو ليبني مسكناً أو ليوفي ديناً فالزكاة عليه إذا حال الحول على المال المجموع، فإذا جمعت من رواتبك أو ثمن الأرض التي بعتها ورصدتها في البنك أو في غير البنك تنتظر التعمير أو تنتظر شراء أرض أخرى أو تنتظر الزواج أو ما أشبه ذلك؛ فإن عليك الزكاة إذا حال الحول، كل مال حال عليه الحول من النقود فإنه يجب عليك زكاته سواء كان من الرواتب أو ثمن أرض أو ثمن بيت أو غير ذلك، ولو كنت أعددت هذا المال لشراء أرض أو لعمارة أرض أو للزواج أو لغير ذلك، عليك الزكاة إذا حال الحول عن كل مال حال عليه الحول. نعم.\nالمقدم: بارك الله فيكم وجزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6909/حكم-زكاة-المال-المجموع-لغرض-زواج-او-بناء-بيت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_217/21706.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":8755,"question":"الأخ (ع. ش) من الرياض يسأل أيضاً ويقول: هل الزكاة على قيمة الأسهم بتمام الحول، أم على الخمسة عشر بالمائة التي توزع من الأرباح، في مثل: شركات الغاز والكهرباء، أم أن الزكاة فقط على الخمسة عشر بالمائة إذا حال عليها الحول؟ وإذا كان هناك بيت يؤجر فهل الزكاة على قيمة البيت وإيجاره أم على الإيجار فقط أفيدونا أفادكم الله؟","title":"حكم زكاة أسهم الشركات وإيجار البيوت","answer":"الجواب: الشركات التي يقصد منها الاستثمار لا البيع مثل: شركات الكهرباء وأشباه ذلك، هذه الزكاة فيما يحصل من المال ما يقسم من المال والأرباح التي يعطاها المساهمون هي التي فيها الزكاة إذا حال عليها الحول بعد حصولها وملك رجل لها، فإذا ملكها وحال عليها الحول يزكيها.\nأما الأصل وهو السهام التي في الشركة فليس عليها زكاة؛ لأنها شركة استثمارية يراد منها الربح لا يراد بيع أصولها، بخلاف الأراضي التي يشترك فيها للبيع، فإن المراد منها بيع أصولها والفائدة من أرباحها، فهذا يزكي الأصل والربح جميعاً في الأرض التي يراد بيعها والسيارة التي يراد بيعها وهكذا العمارة وما أشبه ذلك.\nأما الشركات التي يقصد منها الاستثمار والأصول باقية، فهذه الزكاة فيما يحصل من الثمرة من الفلوس التي تحصل أرباحاً، فتزكى من حين اجتمعت وحصلت لأهلها تزكى إذا حال عليها الحول. نعم.\nالمقدم: وبالنسبة للبيت؟\nالشيخ: والبيت كذلك يزكى الأجرة أما الأصل فلا يزكى إذا كان للاستئجار لا للبيع وإنما هو معد للإيجار ليؤجره وينتفع بالأجرة فالزكاة في الأجرة إذا حال عليها الحول، أما لو أنفقها ولم يحل عليها الحول فلا زكاة فيها أو قضى بها ديناً أو نحو ذلك لا زكاة فيها إلا إذا حال عليها الحول بعد عقد الإجارة تم عليها سنة بعد تمام العقد. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6906/حكم-زكاة-اسهم-الشركات-وايجار-البيوت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_217/21704.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":8808,"question":"السؤال الثاني في رسالة الأخ سعد يقول فيه: يوجد عندي حولي من نوع الفضة لزوجتي وهي لا تلبسه إلا في أوقات العيد والمناسبات، علماً أنه يمضي بعض الأحيان إلى ثمانية أشهر أو سنة كاملة لا تلبسه، فهل يجوز عليه الزكاة أفيدونا جزاكم الله خيراً؟","title":"حكم زكاة الحلي المتخذ للزينة","answer":"الجواب: نعم إذا حال عليه الحول وهو يبلغ النصاب فإنها تزكيه، والنصاب في الفضة مائة وأربعون مثقالاً مقداره بالدرهم السعودي ستة وخمسون ريال سعودي من الفضة أو ما يعادلها، فإذا كانت هذه الحلية تبلغ هذا المقدار فإنها تزكى كل سنة ربع العشر في كل مائة ريالان ونصف هكذا، هذا هو الصحيح من أقوال أهل العلم.\nفي خلاف بين أهل العلم في الحلية للنساء هل تزكى أم ما تزكى، لكن الصواب: أنها تزكى إذا بلغت النصاب وحال عليها الحول، هذا هو الأرجح من أقوال أهل العلم في ذلك. نعم.","link":"https://binbaz.org.sa/fatwas/6957/حكم-زكاة-الحلي-المتخذ-للزينة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_222/22204.mp3","categories":["زكاة النقدين"]},{"id":8930,"question":"فضيلة الشيخ عبدالعزيز بن عبدالله بن باز حفظه الله ورعاه، السلام عليكم ورحمة الله وبركاته، سمعت في البرنامج المحبوب لدى الجميع: نور على الدرب في حلقة سابقة: أن حلي المرأة يزكى إذا بلغ النصاب وحال عليه الحول، فنرجو من سماحتكم ترغيب نساء المسلمين وحثهن على الاقتصاد في لبس الذهب أي دون النصاب واعتبار أن زيادة ذلك -أي: عن النصاب- إسراف وتبذير؛ لأن هناك كتاباً للشيخ البليهي عنوانه: يا فتاة الإسلام أقري حتى لا تخدعي، حيث ذكر في ذلك الكتاب أن المرأة يجب عليها أن لا تنخدع بالمظاهر وأن لا تكون كالمعرض للمجوهرات والذهب، وجزاكم الله خيراً. من الزلفي- عبد المحسن العبد الرحمن ؟","title":"هل لبس المرأة للذهب يكون فيما دون النصاب؟","answer":"الجواب: المرأة يباح لها من الحلي ما تدعو الحاجة إليه، الله أباح لها الحلي؛ لأنها في حاجة إلى التزين لزوجها، ولهذا قال جل وعلا في كتابه العظيم: أَوَمَنْ يُنَشَّأُ فِي الْحِلْيَةِ [الزخرف:18]، فهي تنشأ في الحلية وتزين بالحلية حتى تكون أرغب للأزواج وحتى تكون عند زوجها مرغوبة محبوبة، وقال عليه الصلاة والسلام في الحديث الصحيح: أحل الذهب والحرير لإناث أمتي وحرم على ذكورهم.\nفالمرأة محتاجة إلى التزين بالحلي وإذا اقتصدت في ذلك واكتفت بما يكفي في الزينة ويرغب في اتصال الزوج بها وأنسه بها فهذا يعتبر شيئاً طيباً وحسناً.\nأما القول بأن ما زاد على ما يبلغ النصاب يكون إسرافاً فهذا لا أعلم له أصلاً ولا دليل عليه، فلها أن تلبس ما يبلغ النصاب والنصابين والثلاثة وأكثر من ذلك، ثم هو مال تحفظه له ينفعها في المستقبل، الحلي مال ينفعها في المستقبل فلا حرج عليها في لبس ما دعت الحاجة إليه أو ما جرت العادة به في بلادها من قلائد أو أسورة أو خواتم أو غير هذا مما جرت به العادة، ولا نعلم بأساً في شيء من ذلك ولا نعلم حداً محدوداً لحلي المرأة، لكن متى بلغ النصاب عليها الزكاة في أصح قولي العلماء.\nوفي القول الآخر: لا زكاة عليها فيما يلبس.\nوالقول الثاني: أن عليها الزكاة، هو الصواب وهو الأرجح لما ثبت عنه ﷺ أنه قال: ما من صاحب ذهب ولا فضة لا يؤدي زكاتهاا إلا إذا كان يوم القيامة صفحت له صفائح من نار فيكوى بها جنبه وجبينه وظهره، وقوله ﷺ: لما دخلت عليه امرأة وفي يد ابنتها مسكتان من ذهب، قال: أتعطين زكاة هذا؟ قالت: لا، قال: أيسرك أن يسورك الله فيهما يوم القيامة بسوارين من نار؟ فألقتهما وقالت: هما لله ورسوله، وكانت أم سلمة تلبس أوضاحاً من ذهب، فقالت: يا رسول الله أكنز هذا؟ قال: ما بلغ أن يزكى فزكي فليس بكنز، ولم يقل لها: إن الحلي ليس فيها زكاة.\nأما ما يروى عنه ﷺ أنه قال: ليس في الحلي زكاة، فهو حديث ضعيف عند أهل العلم لا يحتج به، فالزكاة واجبة في الحلي إذا بلغت النصاب، والنصاب من الذهب: عشرون مثقالاً، ومقداره بالجنيه السعودي: أحد عشر جنيه وثلاثة أسباع جنيه، يعني: إحدى عشر ونص، وبالجرام مقداره اثنان وتسعون جراماً، اثنان وتسعون بعد التحليل، بلغ اثنين وتسعين غرامًا، فهذا هو النصاب، فإذا كان الذي عليها من الذهب يبلغ هذا ففيه الزكاة ربع العشر في كل ألف خمسًا وعشرون ريال، وفي المائة اثنان ونصف، وإذا كان الذي عليها أقل من ذلك فلا زكاة عليها، وإن كان أكثر فبالحساب، كل ما زاد فعليها ربع العشر، فإذا كان الذي عليها يبلغ أربعين ألفاً فعليها ألف واحد كل سنة وهكذا..\nوالفضة كذلك فيها الزكاة إذا بلغت النصاب؛ وهو مائة وأربعون مثقالًا ومقداره بالدراهم ستة وخمسون ريال فضة بالذهب السعودي، إذا بلغت النقود الفضية ستة وخمسين وجبت فيها الزكاة، وهكذا ما يعادلها من العمل التي يتعامل بها الناس من الدولار والجنيه الاسترليني والجنيه المصري والريال السعودي.. وغير ذلك، متى بلغت النصاب من الذهب أو الفضة وجبت فيها الزكاة. نعم.","link":"https://binbaz.org.sa/fatwas/7088/هل-لبس-المراة-للذهب-يكون-فيما-دون-النصاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_143/14305.mp3","categories":["زكاة النقدين"]},{"id":8938,"question":"أخونا عبدالعزيز السديس يقول: ساهمت بمبلغ في مساهمة عقارية ربحت في بداية الأمر فتركت المبلغ وتركت ربحه لعله يكسب مرة أخرى، لكن خسرت المساهمة الثانية، والمبلغ الآن مشكوك في سلامته وفي عودته، فهل عليه زكاة وعلى ربحه أم كيف أتصرف؟","title":"حكم زكاة المال المساهم به والمشكوك في أرباحه وعودته","answer":"الجواب: ما دامت المساهمة للتجارة والفائدة والربح فإن على المساهم الزكاة كل سنة بحسابها، عليه أن يزكي السنة التي فيها الربح حسب قيمة العقار، والسنة التي خسرت وضعف فيها الربح لها زكاتها أيضاً، فإذا كانت في السنة الأولى تساوي الأرض مائة ألف عليه زكاة مائة ألف؛ ألفين ونص، ربع العشر، فإذا كانت في السنة الثانية نزلت صار ما تساوي إلا خمسين عليه زكاة الخمسين، والمعلوم أن عشرها خمسة آلاف، ربع العشر ألف ومائتان وخمسون، وهكذا.. لو كانت في السنة الثانية أربعين ألف زكى أربعين فيها ألف واحد.\nفالمقصود أن الزكاة تدور مع القيمة، فإذا غلت القيمة ارتفعت الزكاة وإذا نزلت القيمة نزلت الزكاة على حسبها ربع العشر، وهذا في العقار وغير العقار مما يعد للتجارة، قد يشتري سيارات للتجارة مثلاً تبقى عنده سنة وهي للتجارة قيمتها مثلاً مائة ألف أو أكثر ثم تنزل قيمتها لوجود موديل جديد فتنزل قيمتها فيزكيها في السنة الثانية على حسب قيمتها الجديدة الأخيرة التي نزلت وهكذا غيرها، فالأرض والسيارة وسائر السلع دربها واحد، تدور الزكاة مع القيمة، إن ارتفعت ارتفعت الزكاة، وإن نزلت نزلت الزكاة. نعم.\nالمقدم: أخونا يقول: إن رأس المال والربح مشكوك في عودته؟\nالشيخ: هذا يختلف، إن كانت مبيعته صارت عند إنسان مماطل ما يدرى أن يعطيه أو ما يعطيه لا ما عليه زكاة حتى يسلم له المال أو عند إنسان فقير معسر ما عليه زكاة على الصحيح حتى يستلف المال ويستقبل به حولاً من المعسر أو المماطل، فإذا قبضه يستقبل به حولاً مستقبلاً يعني.\nالمقدم: حول جديد؟\nالشيخ: إيه جديد. قال بعض أهل العلم: إنه يؤدي عن زكاة سنة واحدة، إن أدى عن سنة واحدة فهذا حسن، إذا زكى عن سنة واحدة من السنوات الماضية التي بقي له المال عند هذا المماطل أو عند المعسر، إذا زكى عن عام واحد هذا حسن، قاله جماعة من أهل العلم، وإلا فالصواب أنه لا يلزمه شيء، يستقبل حولاً جديداً، إذا يسر الله له المال من هذا المعسر أو من هذا المماطل فإنه يزكيه من جديد إذا حال عليه الحول.\nأما إن كانت الأرض موجودة ولكن رخص سعرها، وهو يشك في حصول رأس المال يزكي الموجود، اشتراها بمائة ألف ولكن ما تساوي الآن إلا خمسين ألف، كسدت الأراضي يزكي خمسين ألف، يزكي الخمسين التي تساوي في الأرض، حتى ولو ما تساوي إلا عشرة وهي بمائة ألف، يزكي العشرة التي حال عليها الحول وهي بهذه القيمة. نعم.","link":"https://binbaz.org.sa/fatwas/7096/حكم-زكاة-المال-المساهم-به-والمشكوك-في-ارباحه-وعودته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_144/14404.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":9007,"question":"السؤال الثالث والأخير في رسالة الأخت خمرية من العراق تقول فيه: أملك صيغة ذهبية قيمتها تقدر بتسعين ديناراً، وقد اشتريتها في زمان الرخص، فما هي قيمة الزكاة، وهل صحيح أنه في كل سنة تدفع زكاة عنها، أفيدونا أفادكم الله؟","title":"قيمة النصاب في زكاة الحلي","answer":"الجواب: نعم، الصواب أنها تزكى فيه خلاف بين العلماء، بعض أهل العلم يرون أن الحلي من الذهب والفضة ليس فيها زكاة، ولكن الراجح والصواب أن فيه الزكاة إذا بلغت النصاب، فهذه الحلية التي عندك فيها الزكاة، ومقدارها ربع العشر، من كل ألف خمساً وعشرون، إذا كانت تساوي ألفاً خمساً وعشرون، ألفين خمسون وهكذا ربع العشر، هكذا بينها النبي عليه الصلاة والسلام.\nفالواجب على من لديها الحلية التي تبلغ النصاب إذا حال عليها الحول أن تخرج ربع العشر من قيمتها، وربع العشر خمسة وعشرون في الألف، خمسون في الألفين وهكذا. نعم.","link":"https://binbaz.org.sa/fatwas/7165/قيمة-النصاب-في-زكاة-الحلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_223/22308.mp3","categories":["زكاة النقدين"]},{"id":9022,"question":"أخونا يقول: حكم زكاة الذهب الملبوس أو الذي يلبس في المناسبات فقط؟","title":"حكم زكاة الذهب الذي يلبس في المناسبات فقط","answer":"الجواب: نعم، يزكى ولو أنه ملبوس، الصحيح في الحلي أنها تزكى مطلقاً إذا بلغت النصاب وحال عليها الحول تزكيها المرأة ولو كانت للبس فقط؛ لأن الأحاديث الواردة في هذا الباب كلها تدل على أن الحلي تزكى ذهباً أو فضة، ولو كانت للبس فقط، هذا هو المختار والأرجح من أقوال أهل العلم. نعم.","link":"https://binbaz.org.sa/fatwas/7180/حكم-زكاة-الذهب-الذي-يلبس-في-المناسبات-فقط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_147/14715.mp3","categories":["زكاة النقدين"]},{"id":9140,"question":"السؤال الثاني يقول فيه: هل يجوز دفع الزكاة للأخ حين لا يرث، أفيدونا أفادكم الله؟","title":"حكم دفع الزكاة للأخ الفقير","answer":"الجواب: الأخ الفقير يعطى الزكاة حتى ولو كان وارثاً على الأصح، إذا كان فقيراً يعطى من الزكاة كالعم والخال وابن الأخ والأخت ونحوهم، أما الآباء والأمهات والأجداد والجدات والأولاد وأولاد البنين وأولاد البنات هؤلاء لا يعطون؛ لأنهم من أهل البيت فلا يعطون من زكاة الولد، لا يعطي أصله من زكاته ولا فرعه من زكاته، هذا هو المعروف عند أهل العلم وقد حكى عليه الحافظ ابن المنذر رحمه الله الإجماع في الجملة. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/7305/حكم-دفع-الزكاة-للاخ-الفقير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_230/23008.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":9206,"question":"هل تجوز الزكاة لفتاة عمرها عشرون سنة، وكم يكون مقدارها وما هو وقتها؟","title":"عدم ورود سن محددة لمستحقي الزكاة","answer":"الجواب: نعم. الزكاة لها ولغيرها من الفقراء ليس للزكاة سن مشروط، فالفقير يعطى وإن كان صغيرًا وإن كان طفلًا، إذا كان عند أهله الفقراء يعطى.\nفالمقصود: أنه ليس هناك سن معينة للفقير، فالفتاة التي لها عشرون أو خمسة عشر أو عشر أو أقل أو أكثر إذا كانت فقيرة تعطى من الزكاة، يعطى القائم عليها المتوليها، إلا إذا كان القائم عليها غنيًا كأبيها أو أخيها فالنفقة عليهم، لكن لو كانت المرأة فقيرة عند أناس قد أحسنوا إليها وحضنوها يرجون ما عند الله وهم ليسوا أقارب لها، فإنها تعطى من الزكاة ولو كانت كبيرة، وهكذا لو كانت وحدها تعطى من الزكاة صغيرة أو كبيرة إذا كانت فقيرة قد توافرت فيها شروط أهل الزكاة. نعم.","link":"https://binbaz.org.sa/fatwas/7366/عدم-ورود-سن-محددة-لمستحقي-الزكاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_181/18113.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":9365,"question":"ننتقل إلى موضوع آخر ورسالة أخرى، الموضوع هو: من الأخ طلال العبد الرحمن من المنطقة الشرقية يقول: لدي مبلغ من المال أودعته بالبنك الإسلامي وهو يدر علي ربحاً جيداً في نهاية كل سنة، هل أزكي عن رأس المال العامل كله أو على ما يدره هذا المبلغ من ربح فقط، أرجو إفادتي جزاكم الله خيراً؟","title":"كيفية زكاة الأموال التي في البنوك الإسلامية","answer":"الجواب: يزكى الجميع؛ الأصل والربح؛ لأن الأصل معد للبيع فيزكي هذا وهذا، يزكي أصل ماله ويزكي الربح، والربح تابع للأصل ولو ما حال عليه الحول. نعم.","link":"https://binbaz.org.sa/fatwas/7529/كيفية-زكاة-الاموال-التي-في-البنوك-الاسلامية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_156/15607.mp3","categories":["زكاة النقدين"]},{"id":9577,"question":"يسأل أخيراً ويقول: شخص مات وفي ذمته دين ولا يوجد له تركة لقضاء دينه، هل يقضى دينه من الزكاة؟","title":"حكم قضاء الدين عن المدين من الزكاة","answer":"الجواب: في هذا خلاف بين العلماء، والصواب: أنه لا حرج أن يقضى من الزكاة؛ لأنه من الغارمين، والغارمون: صنف من أصناف الزكاة بنص الآية الكريمة إِنَّمَا الصَّدَقَاتُ لِلْفُقَرَاءِ [التوبة:60] الآية، فإذا صرفت الزكاة في قضاء دينه فلا حرج إن شاء الله في أصح قولي العلماء.\nالمقدم: بارك الله فيكم، وجزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/7738/حكم-قضاء-الدين-عن-المدين-من-الزكاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_247/24710.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":9602,"question":"هذه رسالة من (م. ع. م. ش) لم يذكر عنواناً، يقول في رسالته: ما حكم من عليه دين يقضيه كل شهر من راتبه، وعند زوجته ذهب تلبس بعضه دائماً وبعضه الآخر تلبسه في المناسبات، فهل عليه زكاة أم لا؟ وفيه بعض هذا الذهب من سنتين أو أكثر لم نزك عنه أفيدونا أفادكم الله؟","title":"حكم زكاة حلي المرأة المستعمل وغير المستعمل","answer":"الجواب: الذهب فيه الزكاة ولو كانت المرأة تلبسه سواء لبسته أو حفظته للحاجة، فيه الزكاة كل سنة إذا بلغ النصاب، والنصاب عشرون مثقالاً، مقداره اثنان وتسعون غرام، ومقداره بالجنيه السعودي إحدى عشر جنيه ونصف، إحدى عشر جنيه وثلاثة أسباع جنيه، يعني: إحدى عشر ونصف للإيضاح، فإذا بلغ الموجود عندها من الحلي الذهب إحدى عشر جنيه ونصف، وجب عليها أن تزكي كل سنة، وليس على زوجها ذلك إنما عليها هي من مالها، فإذا اتفقت مع زوجها وأخرجها عنها من ماله فلا بأس وهو مشكور لا بأس، وإلا فالواجب عليها هي، لكن إذا سلم الزكاة عنها زوجها أو أبوها بإذنها أو أخوها فلا حرج، وإلا فعليها أن تزكي ولو ببيع شيء من مالها حتى تزكي. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7781/حكم-زكاة-حلي-المراة-المستعمل-وغير-المستعمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_249/24908.mp3","categories":["زكاة النقدين"]},{"id":9603,"question":"هذا محمد بن شائع بن محمد بن إدريس من الجنوب بلاد قحطان، بعث بهذه الرسالة، ونص بعرضها على سماحتكم، يقول: ثارت أمور كثيرة، وأقوال متعددة في الفتوى بذهب النساء، وكثير من النساء تقتني لديها من الذهب ما يزيد قيمته عن خمسين ألف ريال، ويلبسنه للزينة، وأحياناً لا يلبس إلا في السنة مرة، ف ما القول الفصل، هل تجب فيه الزكاة؟ أم لا تجب؟ أفيدونا أفادكم الله؟","title":"القول الراجح في زكاة الحلي المباح","answer":"الجواب: العلماء رحمة الله عليهم قديماً وحديثا اختلفوا في وجوب الزكاة في حلي النساء الذي يلبس أو يعار، والصواب من القولين في ذلك، وجوب الزكاة في ذلك؛ لأن الأدلة العامة تعم الحلي الذي يلبسه النساء، وفيه أدلة خاصة أيضا تدل على ذلك، فالصواب من قولي العلماء أن الزكاة واجبة في الحلي إذا بلغ النصاب، وحال عليه الحول.\nوأما قول من قال: إنه لا تجب فيه الزكاة فهو قول مرجوح، هذا هو الصواب، ومن الأدلة في ذلك، قول النبي ﷺ: ما من صاحب ذهبٍ ولا فضة لا يؤدي زكاتها، إلا إذا كان يوم القيامة صفحت له صفائح من نار، فيكوى بها جبينه وجنبه وظهره، في يومٍ كان مقداره خمسين ألف سنة. الحديث، وهذا يعم الحلي وغير الحلي، وهكذا ما ثبت من حديث عبد الله بن عمرو بن العاص رضي الله عنهما: أن امرأةً دخلت على النبي صلى الله عليه وسلم وفي يد ابنتها مسكتان -يعني: سواران من ذهب- غليظان، فقال النبي ﷺ: أتؤدين زكاة هذا؟ قالت: لا، قال: أيسرك أن يسورك الله بهما يوم القيامة سوارين من نار؟! فألقتهما، وقالت: هما لله ولرسوله  فهذا نص صريح في وجوب الزكاة في حلي النساء.\nوهكذا حديث أم سلمة رضي الله عنها: أنها كانت تلبس أوضاحاً من ذهب، فقالت: يا رسول الله! أكنز هذا؟ فقال: ما بلغ أن يزكى فزكي فليس بكنز ولم يقل لها (ليس بكنز)، قال: ما بلغ أن يزكى، فزكي فليس بكنز فدل على أن الحلي كنز يعذب به إذا لم يزك.\nفالواجب على النساء أن يزكين ما بلغ النصاب وذلك ربع العشر، فإذا كان على المرأة حلي تبلغ، يعني: زنتها خمسين ألفاً، يعني تبلغ ما يعادل خمسين ألفاً من الذهب، أو قيمة الخمسين ألف، تزكي.\nفالحاصل: أن الحلي إذا بلغ النصاب وجب فيه الزكاة، والنصاب أحد عشر جنيهاً وثلاثة أسباع جنيه، يعني: نصف جنيه، بالتحديد أحد عشر جنيه ونصف جنيه، هذا هو النصاب، عشرين مثقالاً، وبالغرام اثنين وتسعين غرام، فإذا بلغ النصاب زكي، وإذا كان أقل من هذا فليس فيه زكاة، هذا هو الواجب في كل سنة. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7766/القول-الراجح-في-زكاة-الحلي-المباح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_271/27103.mp3","categories":["زكاة النقدين"]},{"id":9604,"question":"هذه رسالة من (م. ع. م. ش) لم يذكر عنواناً، يقول في رسالته: ما حكم من عليه دين يقضيه كل شهر من راتبه، وعند زوجته ذهب تلبس بعضه دائماً وبعضه الآخر تلبسه في المناسبات، فهل عليه زكاة أم لا؟ وفيه بعض هذا الذهب من سنتين أو أكثر لم نزك عنه أفيدونا أفادكم الله؟","title":"حكم زكاة حلي المرأة المستعمل وغير المستعمل","answer":"الجواب: الذهب فيه الزكاة ولو كانت المرأة تلبسه سواء لبسته أو حفظته للحاجة، فيه الزكاة كل سنة إذا بلغ النصاب، والنصاب عشرون مثقالاً، مقداره اثنان وتسعون غرام، ومقداره بالجنيه السعودي إحدى عشر جنيه ونصف، إحدى عشر جنيه وثلاثة أسباع جنيه، يعني: إحدى عشر ونصف للإيضاح، فإذا بلغ الموجود عندها من الحلي الذهب إحدى عشر جنيه ونصف، وجب عليها أن تزكي كل سنة، وليس على زوجها ذلك إنما عليها هي من مالها، فإذا اتفقت مع زوجها وأخرجها عنها من ماله فلا بأس وهو مشكور لا بأس، وإلا فالواجب عليها هي، لكن إذا سلم الزكاة عنها زوجها أو أبوها بإذنها أو أخوها فلا حرج، وإلا فعليها أن تزكي ولو ببيع شيء من مالها حتى تزكي. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7781/حكم-زكاة-حلي-المراة-المستعمل-وغير-المستعمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_249/24908.mp3","categories":["زكاة النقدين"]},{"id":9605,"question":"هذا محمد بن شائع بن محمد بن إدريس من الجنوب بلاد قحطان، بعث بهذه الرسالة، ونص بعرضها على سماحتكم، يقول: ثارت أمور كثيرة، وأقوال متعددة في الفتوى بذهب النساء، وكثير من النساء تقتني لديها من الذهب ما يزيد قيمته عن خمسين ألف ريال، ويلبسنه للزينة، وأحياناً لا يلبس إلا في السنة مرة، ف ما القول الفصل، هل تجب فيه الزكاة؟ أم لا تجب؟ أفيدونا أفادكم الله؟","title":"القول الراجح في زكاة الحلي المباح","answer":"الجواب: العلماء رحمة الله عليهم قديماً وحديثا اختلفوا في وجوب الزكاة في حلي النساء الذي يلبس أو يعار، والصواب من القولين في ذلك، وجوب الزكاة في ذلك؛ لأن الأدلة العامة تعم الحلي الذي يلبسه النساء، وفيه أدلة خاصة أيضا تدل على ذلك، فالصواب من قولي العلماء أن الزكاة واجبة في الحلي إذا بلغ النصاب، وحال عليه الحول.\nوأما قول من قال: إنه لا تجب فيه الزكاة فهو قول مرجوح، هذا هو الصواب، ومن الأدلة في ذلك، قول النبي ﷺ: ما من صاحب ذهبٍ ولا فضة لا يؤدي زكاتها، إلا إذا كان يوم القيامة صفحت له صفائح من نار، فيكوى بها جبينه وجنبه وظهره، في يومٍ كان مقداره خمسين ألف سنة. الحديث، وهذا يعم الحلي وغير الحلي، وهكذا ما ثبت من حديث عبد الله بن عمرو بن العاص رضي الله عنهما: أن امرأةً دخلت على النبي صلى الله عليه وسلم وفي يد ابنتها مسكتان -يعني: سواران من ذهب- غليظان، فقال النبي ﷺ: أتؤدين زكاة هذا؟ قالت: لا، قال: أيسرك أن يسورك الله بهما يوم القيامة سوارين من نار؟! فألقتهما، وقالت: هما لله ولرسوله  فهذا نص صريح في وجوب الزكاة في حلي النساء.\nوهكذا حديث أم سلمة رضي الله عنها: أنها كانت تلبس أوضاحاً من ذهب، فقالت: يا رسول الله! أكنز هذا؟ فقال: ما بلغ أن يزكى فزكي فليس بكنز ولم يقل لها (ليس بكنز)، قال: ما بلغ أن يزكى، فزكي فليس بكنز فدل على أن الحلي كنز يعذب به إذا لم يزك.\nفالواجب على النساء أن يزكين ما بلغ النصاب وذلك ربع العشر، فإذا كان على المرأة حلي تبلغ، يعني: زنتها خمسين ألفاً، يعني تبلغ ما يعادل خمسين ألفاً من الذهب، أو قيمة الخمسين ألف، تزكي.\nفالحاصل: أن الحلي إذا بلغ النصاب وجب فيه الزكاة، والنصاب أحد عشر جنيهاً وثلاثة أسباع جنيه، يعني: نصف جنيه، بالتحديد أحد عشر جنيه ونصف جنيه، هذا هو النصاب، عشرين مثقالاً، وبالغرام اثنين وتسعين غرام، فإذا بلغ النصاب زكي، وإذا كان أقل من هذا فليس فيه زكاة، هذا هو الواجب في كل سنة. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7766/القول-الراجح-في-زكاة-الحلي-المباح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_271/27103.mp3","categories":["زكاة النقدين"]},{"id":9629,"question":"له سؤال ثالث يقول فيه: كم عدد النقود التي تخرج منها الزكاة؟ وكم يمر عليها من الزمن لذلك؟","title":"نصاب المال","answer":"الجواب: نصاب الذهب عشرون مثقالاً، ومقداره بالجنيه السعودي إحدى عشر جنيه وثلاثة أسباع جنيه، يعني: قرب النصف إحدى عشر جنيه ونصف، فإذا بلغ هذا المقدار وجبت فيه الزكاة كلما حال الحول، ربع العشر في كل أربعين جنيه جنيه واحد، أو قيمته من الفضة أو الورق، ومقداره بالجرام اثنان وتسعون جرام هذا هو النصاب، والواجب ربع العشر في القليل والكثير إذا بلغ النصاب وحال عليه الحول، ففي أربعين جنيه واحد جنيه، وفي مائة جنيهان ونصف ونص وهكذا، وإن أخرج الذهب فهو أفضل وإن أخرج قيمته من الفضة أو من الورق المستعمل فلا بأس في ذلك ويجزئه ذلك.\nأما الفضة فنصابها مائة وأربعون مثقالاً، ومقداره بالريال السعودي ستة وخمسون ريالاً، فإذا كان عند الإنسان ستة وخمسون أو أكثر وحال عليها الحول وجب فيها الزكاة ربع العشر، في كل مائة اثنان ونص، في الألف خمسة وعشرون، وهكذا في العشرة آلاف مائتان وخمسون، في مائة الألف ألفان وخمسمائة وهكذا.\nوالواجب على المسلم أن يتقي الله وأن يخرج الزكاة عن طيب نفس وإخلاص، وأن يدفعها إلى مستحقيها من الفقراء والمساكين والغارمين وأبناء السبيل، ونحوهم من أهل الزكاة. نعم.\nالمقدم: بارك الله فيكم، ذكرتم سماحة الشيخ أن نصاب الفضة يعادل بالريال السعودي ستة وخمسين، فهل يقصد بهذا الريال الفضة.\nالشيخ: الفضي وما يقوم مقامه.\nالمقدم: يقوم مقامه الورقي؟\nالشيخ: نعم.\nالمقدم: يعني بقيمته ....\nالشيخ: لأنها عملته؛ لأنها عملة مستقيمة بدل الذهب والفضة. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7795/نصاب-المال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_250/25006.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":9634,"question":"له سؤال ثالث يقول فيه: كم عدد النقود التي تخرج منها الزكاة؟ وكم يمر عليها من الزمن لذلك؟","title":"نصاب المال","answer":"الجواب: نصاب الذهب عشرون مثقالاً، ومقداره بالجنيه السعودي إحدى عشر جنيه وثلاثة أسباع جنيه، يعني: قرب النصف إحدى عشر جنيه ونصف، فإذا بلغ هذا المقدار وجبت فيه الزكاة كلما حال الحول، ربع العشر في كل أربعين جنيه جنيه واحد، أو قيمته من الفضة أو الورق، ومقداره بالجرام اثنان وتسعون جرام هذا هو النصاب، والواجب ربع العشر في القليل والكثير إذا بلغ النصاب وحال عليه الحول، ففي أربعين جنيه واحد جنيه، وفي مائة جنيهان ونصف ونص وهكذا، وإن أخرج الذهب فهو أفضل وإن أخرج قيمته من الفضة أو من الورق المستعمل فلا بأس في ذلك ويجزئه ذلك.\nأما الفضة فنصابها مائة وأربعون مثقالاً، ومقداره بالريال السعودي ستة وخمسون ريالاً، فإذا كان عند الإنسان ستة وخمسون أو أكثر وحال عليها الحول وجب فيها الزكاة ربع العشر، في كل مائة اثنان ونص، في الألف خمسة وعشرون، وهكذا في العشرة آلاف مائتان وخمسون، في مائة الألف ألفان وخمسمائة وهكذا.\nوالواجب على المسلم أن يتقي الله وأن يخرج الزكاة عن طيب نفس وإخلاص، وأن يدفعها إلى مستحقيها من الفقراء والمساكين والغارمين وأبناء السبيل، ونحوهم من أهل الزكاة. نعم.\nالمقدم: بارك الله فيكم، ذكرتم سماحة الشيخ أن نصاب الفضة يعادل بالريال السعودي ستة وخمسين، فهل يقصد بهذا الريال الفضة.\nالشيخ: الفضي وما يقوم مقامه.\nالمقدم: يقوم مقامه الورقي؟\nالشيخ: نعم.\nالمقدم: يعني بقيمته ....\nالشيخ: لأنها عملته؛ لأنها عملة مستقيمة بدل الذهب والفضة. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7795/نصاب-المال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_250/25006.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":9705,"question":"الرسالة التالية وصلت إلى البرنامج من المستمع عبدالمحسن أحمد من مدينة جدة، يقول الأخ عبدالمحسن في رسالته: أنا مدير محلات تجارية وصاحب هذه المحلات يطرح الزكاة عندي سنويًا وله ناس مخصصين يأتونه في كل سنة يعطيهم الزكاة وأسماؤهم مسجلة عندي في كشف وصاحب المحلات يسافر في شهر رمضان إلى الخارج ويقول: لا تعطي الزكاة إلا من كان اسمه مسجل في الكشف، وفي هذه السنة لم يأت البعض لأخذ الزكاة والزكاة عندي موجودة أفيدوني أفادكم الله؟","title":"وجوب عمل الوكيل بأمر الموكل","answer":"الجواب: عليك أن تعتمد ما قال لك صاحب الزكاة فتعطيها الأشخاص الذين سماهم وسجلهم لديك ولا تعط غيرهم؛ لأنك وكيل والوكيل يلتزم بما قاله الموكل، لكن إذا علمت أن بعضهم غني وأنه لا يصلح للزكاة تنصحه وتقول له: فلان لا يصلح، فلانة لا تصلح، وإذا تأخر بعضهم تخبره، إذا تأخر بعضهم فماذا أفعل؟ هل أعطيها من أرى أنه فقير؟ أو يسمي لك أشخاصًا آخرين فتعطيهم، أما أنت لا تتصرف بدون إذنه، لابد من إذنه في ذلك لأنك وكيل والوكيل لابد يلتزم بأمر الموكل ولكن عليك النصيحة إذا علمت أن بعض الأشخاص المسميين عندك لا يصلحون لغناهم أو كفرهم أو أشياء أخرى تمنعهم من الزكاة بينها للشخص صاحب التجارة حتى تتفق معه على الأشخاص الذين ينبغي أن تدفع لهم الزكاة ومن تأخر منهم تحفظ حصته وتبقى عندك حتى تستشير صاحب الزكاة في ذلك فيعمدك بما يرى في هذا الأمر. نعم.","link":"https://binbaz.org.sa/fatwas/7851/وجوب-عمل-الوكيل-بامر-الموكل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_195/19503.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":9726,"question":"يقول يا سماحة الشيخ هذا السائل: ما معنى بلوغ النصاب في الزكاة؟ هل الزكاة غير الإنفاق؛ لأن الإنفاق تكرر كثيراً في الجزء الثالث من سورة البقرة؟","title":"معنى النصاب في الزكاة، والفرق بين الإنفاق والزكاة","answer":"الجواب: النصاب غير الإنفاق، الإنفاق: ينفق مما أعطاه الله من المال غير الزكاة، أما الزكاة فشيء فرضه الله لأصناف معينين ثمانية ذكرهم الله في سورة التوبة: إِنَّمَا الصَّدَقَاتُ لِلْفُقَرَاءِ وَالْمَسَاكِينِ وَالْعَامِلِينَ عَلَيْهَا... الآية [التوبة:60]، والزكاة تختلف في النقود ربع العشر يعني: سهم من أربعين هذا في النقود، الذهب والفضة وعروض التجارة سهم من أربعين ربع العشر.\nوفي الحبوب والثمار إن كانت بمئونة بالمكائن وأشباهها نصف العشر، يعني: سهم من عشرين، وإن كانت بالأمطار سقي الزروع بالأمطار والأنهار فهذا العشر كاملاً واحد من عشرة فيه كله، عشرة واحد يعني: عشرة أوسق فيها العشر وهكذا في الحبوب والثمار.\nأما الإبل والبقر والغنم لها زكاة خاصة بينها الرسول ﷺ إذا كانت راعية سائمة، فالإبل لها زكاة والغنم لها زكاة والبقر لها زكاة مبينة في كتب العلماء وفي الأحاديث الصحيحة. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/7881/معنى-النصاب-في-الزكاة-والفرق-بين-الانفاق-والزكاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_272/27217.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":9737,"question":"هذه رسالة وردت من فالح بن سعيد بن جويعد البلوي من العلا الشمالية كما يقول، يقول في رسالته: أنا رجل تقي مقيم لحدود الله، ولفرائضه من الصلاة والزكاة والصيام والحج، وعندي أسرة أعولها ولي أرض، لكن لا أعرف قيمة الزكاة وقيمة زكاة الغنم والأنواع التي يجب أن أخرج منها الزكاة من أملاكي، أفيدوني أفادكم الله؟","title":"زكاة الخارج من الأرض وزكاة الأنعام","answer":"الجواب: الحمد لله، نسأل الله لك التوفيق، والإنسان لا يمدح نفسه ويقول: أنا تقي، يقول: أنا والحمد لله أؤدي فرائض الله وأدع محارم الله، أما أن يزكي نفسه ويقول: أنا تقي وأنا طيب وأنا كذا فالأولى ترك ذلك؛ لأن الله يقول: فَلا تُزَكُّوا أَنفُسَكُمْ [النجم:32] لكن يقول: إني بحمد الله أدع المحارم، وأؤدي الفرائض وأسأل الله أن يتقبلها مني.\nأما الزكاة فعليك الزكاة في أموالك التي فيها الزكاة، أما الأرض إن كانت للزراعة أو للسكن فليس فيها زكاة، إنما الزكاة فيما يخرج منها من الحبوب إذا بلغت النصاب، إذا كانت الحبوب تبلغ ثلاثمائة صاع يعني: خمسة أوسق بصاع النبي ﷺ ثلاثمائة صاع فإنك تزكيها، وهكذا إذا كان فيها نخل .... تمر خمسة أوسق يعني ثلاثمائة صاع بصاع النبي عليه الصلاة والسلام تزكيها، بنصف العشر، إذا كنت تسقيها بالمكائن، تخرج من كل ألف خمسين، من ألف كيلو تمر، أو ألف كيلو حنطة، أو غير ذلك من الحبوب تخرج نصف العشر إذا كنت تسقيها بالمكاين.\nأما إن كنت تسقيها بالمطر أو بعيون جارية لا تكلف ففيها العشر في كل ألف مائة، في كل ألف صاع مائة صاع، ألف كيلو فيه مائة كيلو العشر.\nوأما الأغنام والإبل والبقر فلها أنصبة معلومة إذا كانت ترعى، أما إذا كانت تعلف ولا ترعى ما تخرجها لترعى بل في الأحواش وفي المزرعة تأكل من المزرعة فهذه ليس فيها زكاة إذا كانت للدر والنسل والحاجة للذبح منها، أما إن كانت للبيع للتجارة زكها زكاة التجارة، تزكي قيمتها من كل ألف خمسة وعشرون ربع العشر، وهكذا؛ لأنها زكاة تجارة كالنقود، أما إن كانت ترعى في البرية الحول كله أو أكثر الحول، فإنك تزكيها زكاة السائمة، زكاة الإبل والبقر والغنم، وهي متفاوتة.\nتستطيع أن تطلب من القاضي عندكم يفصل لك زكاتها، في الخمس من الإبل شاة واحدة، في العشر شاتان، في الخمسة عشر ثلاث شياه، في العشرين أربع شياه، فإذا بلغت خمساً وعشرين من الإبل ففيها بنت مخاض، أنثى، تم لها سنة، تسمى: .......... وفيها تفصيل يمكن أن تكتب لنا تفصل لنا ما عندك حتى نكتب لك الجواب أو تسأل فضيلة القاضي الذي عندكم بالمحكمة وتعلمه.\nهكذا البقر إذا كانت ترعى غالب الحول في الثلاثين تبيع قد تم له سنة أو تبيعة وفي الأربعين مسنة تم لها سنتان إلى آخره.\nوهكذا الغنم فإذا كانت ترعى غالب الحول أو كل الحول فيها الزكاة إذا كانت تبلغ أربعين، أما إن كانت تبلغ أقل من أربعين فليس فيها زكاة، لكن إذا بلغت أربعين من الغنم ففيها شاة واحدة، إلى مائة وعشرين، وإذا زادت على مائة وعشرين واحدة وصارت مائة وإحدى وعشرين ففيها شاتان، إلى المائتين، فإذا زادت على المائتين واحدة ففيها ثلاث شياه في مائتين وواحدة أو أكثر ثلاث شياه، وهكذا في كل مائة شاة، فإذا بلغت أربعمائة صار فيها أربع شياه، وإذا بلغت خمسمائة ففيها خمس شياه، وهكذا في الغنم الراعية، أما إن كانت تعلف غالب الحول أو كل الحول فإنها لا زكاة فيها زكاة السائمة، ولكن فيها زكاة التجارة إذا كانت للتجارة للبيع والشراء فيها زكاة التجارة، في كل ألف من قيمتها خمس وعشرون ريال، في كل ألف، وإن كانت للأكل والدر والنسل والأكل للضيوف ونحو ذلك ليست للبيع، فليس فيها زكاة إذا كانت لا ترعى، والله ولي التوفيق. نعم.\nالمقدم: أثابكم الله.","link":"https://binbaz.org.sa/fatwas/7900/زكاة-الخارج-من-الارض-وزكاة-الانعام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_254/25409.mp3","categories":["زكاة بهيمة الأنعام","زكاة الحبوب والثمار","زكاة النقدين"]},{"id":9859,"question":"استفساره الرابع والأخير في هذه الرسالة يقول فيه: هل يجب دفع زكاة على حلي النساء إذا كان يوجد بقيمة عشرة آلاف فما فوق؟","title":"حكم الزكاة على حلي المرأة","answer":"الجواب: نعم، حلي النساء من الذهب والفضة فيها الزكاة على الصحيح، فيها خلاف بين أهل العلم لكن الصحيح من أقوال العلماء: أن فيها الزكاة إذا بلغت النصاب، والنصاب عشرون مثقالًا، ومقداره أحد عشر جنيه ونصف بالجنيه السعودي، أو اثنان وتسعون غرام، اثنان وتسعون غرام يقوم مقام أحد عشر جنيه ونصف.\nفالحاصل أنه إذا بلغ النصاب هذا الذهب تزكيه في كل ألف خمسة وعشرون، وهكذا الفضة إذا بلغت الفضة ستة وخمسين ريال فأكثر زكاها بربع العشر، وهكذا إذا كثر المال يزكى بربع العشر من كل ألف خمسة وعشرون، وإذا كان عشرة آلاف فزكاتها مائتان وخمسون؛ لأن عشرها ألف، وربع العشر مائتان وخمسون من العشرة الآلاف. نعم.\nالمقدم: وهل يدفع الزوج زكاة حلي زوجته؟\nالشيخ: لا يلزمه لا، الزكاة عليها، لكن إذا ساعدها بذلك وسمحت ورضيت فلا بأس أن يزكي عنها إذا سمحت وإلا فالزكاة عليها لحليها؛ لأن الأحاديث الدالة على ذلك تدل على أن الزكاة عليها، وقد جاءت النصوص دالة على وجوب الزكاة في الحلي. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8023/حكم-الزكاة-على-حلي-المراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_198/19812.mp3","categories":["زكاة النقدين"]},{"id":9867,"question":"وهذه رسالةٌ من السائل الذي رمز لاسمه بـ(ص. م. م) من القصيم يسأل عن الزكاة في حُلي النساء، وعما تتركه المرأة في بيتها لا تستعمله إلا مرةً واحدةً في السنة، وما تستعمله دائمًا، ويقول: قد كثر الجدل في ذلك.ويؤيد هذا السؤال أيضًا سؤالٌ من الفتاة المؤمنة (س. م. أ) من دولة الكويت، والتي أرسلت بعدة أسئلةٍ في رسالتها، من ضمنها: هل حُلي المرأة فيه زكاةٌ؟فنأمل الإفادة في ذلك، بارك الله فيكم.","title":"حكم حلي النساء","answer":"الجواب: نعم، الصحيح: فيه الزكاة، حُلي المرأة فيه الزكاة إذا بلغ النِّصاب، هذا هو الصواب. والنِّصاب: عشرون مثقالًا من الذهب، ومئةٌ وأربعون مثقالًا من الفضة. فإذا بلغ الحُلي الذي عندها النِّصاب؛ وهو أحد عشر جنيهًا ونصف الجنيه السعودي، أو الجنيه الإفرنجي، إذا بلغ أحد عشر جنيهًا ونصفًا وجبت فيه الزكاة، أو اثنين وتسعين جرامًا وجبت فيه الزكاة، وما كان أقلَّ من ذلك فليس فيه زكاةٌ، حتى ولو كان ملبوسًا تُزكيه، ولو كان ملبوسًا، هذا هو الصواب. والمسألة فيها خلافٌ بين أهل العلم، لكن هذا هو الحق، وهذا هو الصواب؛ لأنه ثبت عن النبي ﷺ من حديث عبدالله بن عمرو، ومن حديث أم سلمة رضي الله عنهما ما يدل على وجوب الزكاة في الحلي، مع عموم قوله ﷺ: ما من صاحب ذهبٍ ولا فضةٍ لا يؤدي زكاتها إلا إذا كان يوم القيامة صُفِّحت له صفائح من نارٍ، فيُكوى بها جنبه وجبينه وظهره ... الحديث. وهذا حديثٌ عامٌّ يعم حُلي النساء، ويعم غيرها؛ ولهذا أخذ جمعٌ من أهل العلم بوجوب الزكاة في حُلي المرأة؛ أخذًا من هذه الأحاديث وعملًا بها. نعم.","link":"https://binbaz.org.sa/fatwas/8031/حكم-حلي-النساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_199/19902.mp3","categories":["زكاة النقدين"]},{"id":9933,"question":"وهذه رسالة من السائل أحمد صالح زيد من اليمن الشمالي ومقيم في مدينة حفر الباطن في المملكة العربية السعودية يقول في رسالته: إذا كنت في الغربة مثلًا أنا في السعودية وأهلي في اليمن فهل أزكي عن نفسي وأهلي أم أزكي عن نفسي فقط وأهلي يزكون عن أنفسهم، أفيدونا بارك الله فيكم؟","title":"الموطن الذي يؤدي فيه المغترب الزكاة عنه وعن أهله","answer":"الجواب: أنت مخير إن زكيت عن نفسك وعنهم في محل الغربة فلا بأس؛ لأنهم تابعون لك وأنت المسئول عنهم، فإذا زكيت عنهم يعني زكاة الفطر مع زكاتك كفى ذلك؛ لأنك مسئول، وإن عمدتهم بإخراج الزكاة عن أنفسهم هناك أجزأ ذلك، إذا عمدتهم أن يخرجوا الزكاة عندهم وفي فقرائهم فلا بأس، والأصل وجوبها عليك أنت تزكي عنهم. نعم.","link":"https://binbaz.org.sa/fatwas/8093/الموطن-الذي-يودي-فيه-المغترب-الزكاة-عنه-وعن-اهله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_199/19907.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":10014,"question":"هل تجوز الزكاة في المال الدين الذي ليس عند صاحبه؟","title":"حكم زكاة مال القرض الذي ليس في اليد","answer":"الجواب: الدين أقسام: تارة يكون عند عاجز لا يستطيع الوفاء هذا لا زكاة فيه حتى يقبضه صاحبه، لأنها مواساة ولا تجب على المواساة في دين لا يستطيع قبضه.\nالحال الثاني: أن يكون عند مماطل هو يقدر ولكن ما يعطي ما يوفي يماطل فهذا كالفقير لا تلزمك الزكاة حتى تقبض من هذا المماطل.\nالثالث: أن يكون عند مليء باذل متى طلبته أعطاك فهذا تجب عليك الزكاة فيه وإن كان عنده، كالأمانة عليك أن تزكي كل سنة ما دام عند مليء باذل فعليك الزكاة، أما إذا كان عند فقير معسر أو غني لكن مماطل لا يوفي ويتعبك فليس عليك زكاة حتى تقبض ثم تستقبل حولًا. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8183/حكم-زكاة-مال-القرض-الذي-ليس-في-اليد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_332/33202.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":10016,"question":"هل ذهب المرأة الذي يستعمل للزينة، والذهب غير المستعمل للزينة هل في ذلكم زكاة أو لا؟","title":"نصاب زكاة الذهب والفضة","answer":"","link":"https://binbaz.org.sa/fatwas/8185/نصاب-زكاة-الذهب-والفضة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_276/27604.mp3","categories":["زكاة النقدين"]},{"id":10022,"question":"أم عاتكة من المدينة المنورة بعثت برسالة وضمنتها جمعاً من الأسئلة، في أحدها تقول: استدنت من امرأة مبلغًا من المال، وكنت أضع لها من مرتبي الشهري مبلغًا أحتفظ به عندي، وهي على علم بذلك، حتى إذا ما جمع مبلغ كبير أقدمه لها سدادًا للدين فهي تسأل كيف تزكي هذا المال؟ هل تزكيه شهريًا، أم عندما تستلمه دفعة واحدة؟","title":"كيفية إخراج الدائن ماله الذي لدى المدين","answer":"الجواب: إذا مر عليه الحول، إذا مر عليه الحول تزكي سواءً عندها أو عند المرأة أو عند غير المرأة، مادام عند شخص مليء يعطيها حقها، تزكيه إذا حال عليه الحول سواء كان عندها أو عند المدين. نعم.\nالمقدم: لكنه يسدده على أقساط شهرية؟\nالشيخ: كلما حال الحول على المال اللي عند المدين يزكى، ولو ما سدده.\nالمقدم: بارك الله فيكم، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8192/كيفية-اخراج-الداىن-ماله-الذي-لدى-المدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_276/27609.mp3","categories":["زكاة النقدين"]},{"id":10135,"question":"تقول: أملك بعض الحلي من الذهب ومنها طقم ذهب، ولكنه يحتوي على فصوص كثيرة ليست ذهب، فهل أخرج الزكاة على وزن الطقم كله أم على وزن الذهب فقط من غير الفصوص، وإذا كان الذهب من عيار ثمانية عشر فكيف أخرج زكاته؟","title":"كيفية زكاة الذهب المشتمل على فصوص ليست من الذهب","answer":"الجواب: عليك إخراج الزكاة عن الذهب فقط، بما يساوي صرفه في السوق، تخرجين الزكاة عن الذهب فقط أما فصوص والماس فلا زكاة فيه إذا كان للاستعمال، فإذا كان الذهب يبلغ النصاب من عيار ثمانية عشر أو أكثر فإنه يزكى، والنصاب عشرون مثقالاً اثنان وتسعون من الذهب، اثنان وتسعون غرام من الذهب ومقداره بالجنيه السعودي أحد عشر جنيه سعودي ونصف، أما إذا كان أقل فلا زكاة فيه. نعم.","link":"https://binbaz.org.sa/fatwas/8301/كيفية-زكاة-الذهب-المشتمل-على-فصوص-ليست-من-الذهب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_305/30507.mp3","categories":["زكاة النقدين"]},{"id":10327,"question":"نعود مع مطلع هذه الحلقة إلى رسالة المستمع (ح. م. ن) من الدوادمي أخونا عرضنا له جمع من الأسئلة وبقي له أيضاً عدد آخر، في أحد أسئلته المتبقية يقول: كيف يزكى الذهب والفضة الذي تلبسه النساء؟ وما هو نصاب العملة الورقية؟","title":"مقدار النصاب في زكاة الحلي والعمل الورقية","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فإن الصواب من قولي العلماء في شأن الحلي: أنها تزكى ولو كانت تستعمل، فعلى النساء أن يزكين حليهن من الذهب والفضة إذا بلغت النصاب، هذا هو القول الصواب لعموم الأدلة، ولأدلة أخرى خاصة تدل على وجوب الزكاة فيها إذا بلغت النصاب، ونصاب الذهب أحد عشر جنيه سعودي ونصف يعني: عشرين مثقالاً، ومقدار ذلك بالغرام اثنان وتسعون غراماً.\nأما الفضة فنصابها مائة وأربعون مثقالاً وهي مائتا درهم في عهد النبي صلى الله عليه وسلم، وفي عهدنا الآن ستة وخمسون ريالاً سعودياً من الفضة أو ما يعادلها من الورق، ما يعادل ستة وخمسين ريال فضة من الورق من العمل الورقية الدولار والريال السعودي والدينار وغيره من العمل، إذا بلغت ستة وخمسين قيمتها ستة وخمسين ريال فضة أو إحدى عشر جنيه ونصف سعودي زكيت.\nوالواجب ربع العشر والزكاة على المرأة، فإن زكى عنها زوجها برضاها أو أبوها أو غيرهما فلا بأس، وإلا فالزكاة واجبة عليها لأنها المالكة، وما كان أقل من هذا فليس في زكاة، ما كان أقل من أحد عشر جنيه ونصف سعودي من الذهب أو أقل من ستة وخمسين ريال فضة من الفضة فلا زكاة فيه، وهكذا ما يعادل ذلك من العمل ما كان أقل من قيمة الذهب إحدى عشر جنيه ونصف وكانت قيمتها أقل من ستة وخمسين ريال من الفضة لا زكاة فيه. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8488/مقدار-النصاب-في-زكاة-الحلي-والعمل-الورقية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_314/31401.mp3","categories":["زكاة النقدين"]},{"id":10332,"question":"من المستمع محمود أحمد روثة بعث برسالة وضمنها ثلاثة أسئلة: في أحدها يقول: جاء في بعض الأحاديث عن زكاة الركاز، فما هو الركاز؟","title":"حكم زكاة الركاز","answer":"الجواب: الركاز دفن الجاهلية الأموال التي توجد في بعض الخربات أو في بعض الصحارى من دفن الجاهلية، عليها علامات الجاهلية الكفار، إما ذهب أو فضة أو أواني أو سلاح أو غير ذلك من الأموال، تكون مدفونة في الأرض عليها علامة تدل على أنها من دفن الجاهلية عليها علامة الدولة الكافرة يعني: علامة الكفار، هذه تسمى: ركاز، يعني: مركوز في الأرض، يعني: مدفون فيها، ركاز معناه: مركوز، المعنى: أنه يجده مدفوناً في الأرض ليس معدناً لا، مدفون، فهذا فيه الخمس لولي الأمر إذا كان في بلاد إسلامية يعطي ولي الأمر الخمس، أما إن كان في غير بلاد إسلامية يتصدق بالخمس، يتصدق بالخمس على الفقراء والأربعة له، الخمس كالزكاة يتصدق على الفقراء وإن كان في بلاد إسلامية فيها والي مسلم يعطيه إياه لبيت المال، والأربعة الأخماس له، هذا يسمى: ركاز.\nأما المعدن اللي من أصل الأرض معدن ذهب أو فضة هذا لا يسمى ركاز، هذا لمن استخرجه.. من استخرجه يكون له، وإذا استخرج ذهباً يبلغ النصاب زكاه إذا حال عليه الحول، أو استخرج فضة زكاه إذا حال عليها الحول، أما إذا كان شيء آخر من المعادن كبريت أو غير ذلك يكون له، ما أخذه من هذا المعدن يكون له، إذا كان في أرض ميتة ليست مملوكة لأحد. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8506/حكم-زكاة-الركاز","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_315/31506.mp3","categories":["زكاة النقدين"]},{"id":10359,"question":"آخر سؤال لأختنا تقول فيه: يقولون: إن الإنسان إذا لم يتخذ بيتًأ وجمع أموالًأ بقصد أن يتخذ منزلًأ فلا زكاة عليه، ما صحة هذا القول؟","title":"حكم زكاة المال المعد لشراء منزل","answer":"الجواب: هذا القول غلط، إذا جمع الإنسان مالًأ ليشتري بيتًأ أو ليتزوج أو ليشتري سيارة أو يشتري دكانا يعني: حانوت أو يشتري نخلا أو غير ذلك، فعليه أن يزكيه إذا حال عليه الحول، إذا حال عليه الحول قبل أن يصرف في الجهة التي أعد لها فإنه يزكى، والقول بأنه لا يزكى قول غلط لا وجه لا ولا أصل له، فإذا اجتمع مثلًأ عنده أربعون ألفًأ أو خمسون ألفًأ أو أكثر أو أقل ليشتري بيتًأ له أو دكانًأ أو سيارة أو ما أشبه ذلك، فإنه يزكيه إذا حال عليه الحول، ولا يجوز له ترك الزكاة. نعم.\nالمقدم: جزاكم الله خيرًأ.","link":"https://binbaz.org.sa/fatwas/8526/حكم-زكاة-المال-المعد-لشراء-منزل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_338/33810.mp3","categories":["زكاة النقدين"]},{"id":10366,"question":"من الجزائر المستمع عزيز عبدالرحمن بعث يسأل ويقول: توجد ظاهرة في منطقتنا وهي: أن النساء أكثرهن يجعلن مهورهن ذهباً، وعلى شكل حلي، ولا تلبسها إلا في المناسبات، ويدعون بأنه لا زكاة عليها وذلك استنادًا على أقوال بعض العلماء، شريطة أن تلبس المرأة هذا الحلي ثلاث مرات في السنة؟","title":"القول بعدم وجوب زكاة الحلي ضعيف","answer":"الجواب: الصواب: أن فيها الزكاة، الخلاف موجود بين العلماء بعض أهل العلم يرى أن الحلي لا زكاة فيها، لكن الصواب أن فيها الزكاة، إذا حال عليها الحول، فالواجب على المرأة أن تزكي الحلي لبستها أو لم تلبسها، لقول النبي ﷺ للمرأة التي رأى عليها الحلي: أتعطين زكاة هذا؟ قالت: لا، قال: أيسرك أن يسورك الله بهما يوم القيامة سوارين من نار، ولقوله لـأم سلمة لما ذكرت له أنها تلبس أوضاحاً من الذهب قالت: يارسول الله! هل هذا كنز؟ قال: ما زكي فليس بكنز دل على أنها تزكى، وأنها تكون كنزاً إذا لم تؤد زكاتها، سواء كانت أسورة أو قلائد، أو خواتم أو غير ذلك إذا بلغت النصاب، والنصاب عشرون مثقالاً من الذهب، مقداره إحدى عشر جنيه ونصف بالسعودي، وبالغرام اثنان وتسعون غرام، والفضة مائة وأربعون مثقالًا، مائة وأربعون مثقالًا من الفضة، مقدارها بالريال السعودي الفضي ستة وخمسون ريال، هذا أقل نصاب.\nفالواجب على من عنده حلي من الذهب أو الفضة، رجل كان أو امرأة أن يزكي إذا بلغ النصاب المذكور، وهكذا العمل التي عند الإنسان من دولارات جنيهات دنانير يعني العملة الورقية تقوم مقام الذهب والفضة، فيها الزكاة. نعم.\nالمقدم: جزاكم الله خيراً وأحسن إليكم، سماحة الشيخ من عمل بقول القائلين بعدم وجوب الزكاة ما هو تعليقكم يحفظكم الله؟\nالشيخ: القول ذاك ضعيف، القول هذا ضعيف والصواب أن فيها الزكاة، الصواب أن على من كانت عنده الحلي التي تبلغ النصاب الزكاة، وليس كل خلاف جاء معتبراً، الله يقول: فَإِنْ تَنَازَعْتُمْ فِي شَيْءٍ فَرُدُّوهُ إِلَى اللَّهِ وَالرَّسُولِ [النساء:59]، ويقول جل وعلا: وَمَاا اخْتَلَفْتُمْ فِيهِ مِنْ شَيْءٍ فَحُكْمُهُ إِلَى اللَّهِ [الشورى:10]. نعم.\nالمقدم: إذاً: من عمل بذلك القول بماذا تنصحونه؟\nالشيخ: غلط نقول له: الوجب عليه ترك ذلك، والعمل بما دل عليه النص. نعم.\nالمقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8538/القول-بعدم-وجوب-زكاة-الحلي-ضعيف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_279/27915.mp3","categories":["زكاة النقدين"]},{"id":10452,"question":"المستمع علي حسين من العراق سبق وأن عرضنا جملة من أسئلته، وفي هذه الحلقة يسأل ويقول: ما هو مقدار نصاب الزكاة في الذهب؟ وهل الرجل هو المسئول عن دفع زكاة حلي وذهب امرأته أم هي؟ وهل عليه أن يجبرها على دفع زكاة ذهبها أم يتركها وهي تتصرف؟","title":"نصاب الذهب في الزكاة ومن المسؤول عن دفع زكاة الحلي؟","answer":"الجواب: النصاب عشرون مثقالاً، نصاب الذهب عشرون مثقالاً عند أهل العلم، وقدره بالعملة الموجودة إحدى عشر جنيه ونص سعودي، وإفرنجي أيضاً، إحدى عشر جنيه ونصف؛ لأن الجنيه مثقالان إلا ربع، وإذا حسبت صار إحدى عشر جنيه وثلاثة أسباع جنيه يكون هو النصاب، ثلاثة أسباع حول النص، التعبير بالنص يكون أوضح للمخاطب، إحدى عشر جنيه ونص هذا النصاب، وبالجرامات اثنان وتسعون جراماً هذا هو النصاب، وإذا كان أقل من ذلك وليس عندها شيء يضاف إلى الحلي فلا يجب عليها شيء، أما إن كان عندها ذهب آخر تضيف إلى الحلي، يكمل النصاب فإنها تزكي.\nوالزكاة عليها هي في مالها هي، ليست على الزوج، هذا مالها والزكاة عليها، وإذا أخرج عنها برضاها وموافقتها فلا بأس كالوكيل إذا سمح أن يخرج عنها الزكاة من ماله برضاها وموافقتها فلا بأس، أو أخرج عنها أبوها أو أخوها فلا بأس إذا رضيت بذلك، وإلا فالزكاة في مالها هي، وعليه نصيحتها بإخراج الزكاة وتوجيهها إلى الخير وتعليمها، وإذا لم تزكي فالإثم عليها، ليس عليه، إنما عليه النصيحة؛ لأن هذه المسألة فيها خلاف بين العلماء، وقد تكون أخذت بقول بعض العلماء الذين يقولون: لا زكاة في الحلي؛ لأن الحلي فيها خلاف بين العلماء، منهم من يرى فيها الزكاة، ومنهم من لا يرى فيها الزكاة، ويراها مستعملة لا زكاة فيها، ولكن الأصح من قولي العلماء أنها تزكى، فإذا زكت فهذا هو الأبرأ لذمتها والأحوط لها، وإن لم تزكي فالإثم عليها ليس عليك أنت، أنت عليك النصيحة، وهي عليها أن تجتهد في براءة ذمتها، وإذا اطمأنت إلى قول من قال: (لا زكاة فيها) لأنها .. طالبة علم وعندها بصيرة واطمأنت إلى أن القول بعدم الزكاة أصح فلا حرج عليها، هي مسئولة عما تعلم من دينها، أما إذا كانت عامية لا تعلم، فالأحوط لها والواجب عليها أن تأخذ بالأحوط وأن تزكي. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8630/نصاب-الذهب-في-الزكاة-ومن-المسوول-عن-دفع-زكاة-الحلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_319/31908.mp3","categories":["زكاة النقدين"]},{"id":10475,"question":"يسأل سماحتكم سؤالًا آخر فيقول: ما الرأي في الدين الذي يمضي عليه الحول وهو عند المدين ولم أستلم، هل أخرج الزكاة أم كيف أتصرف جزاكم الله خيرًا؟","title":"حكم إخرج الدائن زكاة ماله الذي عند المدين","answer":"الجواب: إذا كان الدين على إنسان معسر، فلا زكاة فيه حتى تقبضه، وهكذا لو كان الدين على إنسان مماطل، تطلبه الحق ولا يعطيك، فإنه لا زكاة عليك حتى تقبضه وتستقبل به عامًا جديدًا، أما إذا كان الدين على إنسان مليء غير مماطل متى طلبته أعطاك فإن الواجب عليك الزكاة، متى تم الحول عليك أن تزكي ولو ما قبضته؛ لأنه كالذي عندك، ما دام عند إنسان مليء غير مماطل، فهو كالذي عندك فيه الزكاة متى تم عليه الحول.\nالمقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8650/حكم-اخرج-الداىن-زكاة-ماله-الذي-عند-المدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_281/28102.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":10481,"question":"هل يجوز أن أزكي الذهب الذي أستعمله كزينة مثل: القلائد والخواتم وما شابه ذلك؟","title":"حكم زكاة الحلي من الذهب والفضة","answer":"الجواب: نعم إذا بلغ النصاب وجبت الزكاة، إذا كان الحلي من الذهب أو الفضة يبلغ النصاب وجب عليك الزكاة في أصح قولي العلماء، ولو أنه حلي، والنصاب عشرون مثقالًا، مقدارها أحد عشر جنيه وثلاثة أسباع جنيه من الجنيه السعودي، يعني إحدى عشر جنيه ونصف، من الجنيه السعودي يقال: هذا نصاب، وهكذا ما أكثر منه يزكى، ومقداره بالغرام اثنان وتسعون غراماً، فالمقصود أن الحلي إذا بلغت النصاب تزكى سواء كان من الذهب أو الفضة، والفضة نصابها مائة وأربعون مثقالًا، مقدارها ستة وخمسون ريال فضة وما يقوم مقامها من العمل. فالواجب على من لديها حلية من أسورة أو قلائد أو غير ذلك تبلغ النصاب أن تزكي ذلك، وذلك ربع العشر، فإذا كانت قيمة الحلي تبلغ عشرة آلاف مثلاً تزكيها مائتين وخمسين ربع العشر؛ لأن عشرها ألف وربع العشر مائتان وخمسون، وإذا كانت تساوي أربعين ألفًا فعليها الزكاة ألف واحد ربع العشر، وفق الله الجميع. نعم.\nالمقدم: اللهم آمين، جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8656/حكم-زكاة-الحلي-من-الذهب-والفضة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_281/28108.mp3","categories":["زكاة النقدين"]},{"id":10499,"question":"مستمع يقول سوداني مقيم في المملكة يقول: إن له نصيب في الزكاة فيما يرى لكنه يرفض أخذها فما الحكم؟","title":"حكم رفض الفقير أخذ الزكاة.","answer":"الجواب: هذا يخضع لما يقدر من المصالح، فإذا كان يرى أن ترك هذا خير من هذا المال من الزكاة، فيه مصلحة له فلا بأس، يعني ينظر لما هو الأصلح، ما هو بلازم أنه يأخذ من الزكاة، إذا كان عنده ما يسد حاله أو زكاة أخرى تيسرت له من جهات أخرى، وهذا الذي بيأخذ منه الزكاة قد يعني يضره، أو يمن عليه أو يؤذيه أو ما أشبه ذلك، إذا كان ترك ذلك لأسباب بينة واضحة فلا بأس، المقصود ينظر ما هو الأصلح، يأخذ من هذا ولا يأخذ من هذا، ينظر ما هو الأصلح في دينه وسمعته وعدم إيذاء المعطي له، أو منته عليه أو ما أشبه ذلك، ... أن يتحرى ما هو أصلح، يتحرى ما هو أصلح.\nالمقدم: جزاكم الله خيرًا، يقول: إنه يخشى أن تعوده الخمول والكسل؟\nالشيخ: إذا كان يخشى ذلك يترك ويعمل يجتهد، إذا كان يستطيع أن يعمل ويكتسب، يعمل ويكتسب لعله يدرك ما يكفيه ويستغني عن الصدقة عن الزكاة، إذا كان عنده قدرة فالواجب عليه أن يعمل ويجتهد ولا يلجأ للصدقات، بل يعمل حتى يدرك حاجته. نعم.\nالمقدم: جزاكم الله خيراً وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8674/حكم-رفض-الفقير-اخذ-الزكاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_282/28207.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":10513,"question":"تقول أختنا في سؤالها الثاني: إذا كان للإنسان محلات وشقق مؤجرة فكيف تكون زكاتها؟","title":"كيفية زكاة الشقق والبيوت المؤجرة","answer":"الجواب: الزكاة في الأجرة إذا كانت الشقق للقنية والاستفادة والتأجير ليس فيها زكاة، ولكن الزكاة تكون في الأجرة إذا حال عليها الحول زكاها، فإذا أجر الشقة مثلاً بألف ريال، إذا حال الحول على الألف وهو عنده ما خرجه ولا أنفقه يخرج زكاته ربع العشر، إذا حال الحول على الأجرة إذا بقيت عنده حتى حال عليها الحول، أما إذا أوفى بها دينًا، أو أنفقها في حاجاته قبل الحول فلا زكاة فيها.\nالمقدم: جزاكم الله خيراً وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8688/كيفية-زكاة-الشقق-والبيوت-الموجرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_283/28302.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":10623,"question":"أخونا يقول: إنه طيلة الثلاث السنوات جمع بعض المال ولم يزكه حتى الآن، بم تنصحونه؟","title":"حكم من جمع مالاً طيلة ثلاث سنوات ولم يزكه","answer":"الجواب: الواجب عليه الزكاة، الواجب عليك يا أخي! أن تزكي المال عن السنوات الثلاث، إذا كان قد بلغ النصاب فعليك الزكاة عن السنوات الثلاث، في كل مائة اثنان ونصف، في الألف خمسة وعشرون، يعني: ربع العشر. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8793/حكم-من-جمع-مالا-طيلة-ثلاث-سنوات-ولم-يزكه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_327/32705.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":10765,"question":"عندي مبلغ من المال وقد أقرضته بعض المحتاجين له، وقد صرفوا هذا المال ولم يبق معهم شيء، هل علي زكاة في هذا المال أم لا، أرجو الإفادة جزاكم الله خيراً؟","title":"حكم الزكاة في الدين الذي على معسر","answer":"الجواب: ما داموا معسرين فليس عليك زكاة إذا كان المقترض معسراً فليس عليك زكاة، أو كان موسراً لكنه يماطل ما أعطاك تطلبه ولا يعطيك، فلا زكاة عليك حتى تقبضه، ثم تستقبله حولاً جديداً، فتزكيه بعد ذلك، أما إذا كان الذي عليه القرض مليئاً باذلاً فعليك الزكاة، ولو مكث عنده سنوات عليك أن تزكي عن كل سنة ما دام مليئاً لو طلبته أعطاك ليس بمماطل، فإنك تزكيه كأنه أمانة، أما إذا كان معسراً فإن الدين الذي عليه ما تجب زكاته؛ لأنه ليس في يدك والزكاة مواساة، وأنت لا تملك الآن قبضه فلا زكاة عليك، وهكذا إذا كان يستطيع لكنه يماطل ولم يعطك ولم يقم بالواجب الذي عليه من دفع حقك، فإنه لا زكاة عليك؛ لأن المماطل كالمعسر فلا زكاة عليك حتى تقبضه ثم تستقبل به حولاً كاملاً وتزكيه بعد ذلك. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8946/حكم-الزكاة-في-الدين-الذي-على-معسر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_348/34806.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":10767,"question":"هل على الذهب الذي تستعمله المرأة للزينة زكاة علماً بأنه يصل إلى مائة جرام نرجو الإفادة جزاكم الله خيرا؟","title":"حكم زكاة الحلي المستعمل","answer":"الجواب: نعم الصواب فيه الزكاة، حلي المرأة من الذهب والفضة فيه الزكاة وهي ربع العشر، ولو أنها تستعمل هذا هو الصواب، فيه خلاف بين العلماء، بعض أهل العلم يرى أنه لا تجب الزكاة في الحلي، ولكن الصواب أنها تجب فيها الزكاة إذا بلغت النصاب، والنصاب: اثنان وتسعون غرام تقريباً عشرون مثقالاً، وبالجنيه السعودي إحدى عشر جنيه ونصف، وبالريال الفضة العربي ستة وخمسون ريال من الفضة وما يعادلها، فإذا كانت الحلي تبلغ نصاب الزكاة وجبت فيها الزكاة على الصحيح.\nوقد ثبت عنه ﷺ أنه دخلت عليه امرأة وعلى ابنتها مسكتان من ذهب -يعني: سوارين من ذهب- فقال ﷺ: أتعطين زكاة هذا؟ قالت: لا. قال: أيسرك أن يسورك الله بهما يوم القيامة سوارين من نار؟ فألقتهما وقالت: هما لله ورسوله وقد قال ﷺ: ما من صاحب ذهب ولا فضة لا يؤدي زكاتها، إلا إذا كان يوم القيامة صفحت له صفائح من نار فيكوى به جنبه وجبينه وظهره الحديث، وهذا يعم الحلي التي من الذهب والفضة.\nوالمقصود: أن الراجح والصواب أن الحلي ولو أنها مستعملة الواجب أن تزكى، إذا بلغت النصاب كل حول، في الألف خمسة وعشرون، وفي الألفين خمسون وهكذا، تعرف قيمة الذهب وقت الحول ويزكى، حسب قيمته. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8947/حكم-زكاة-الحلي-المستعمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_348/34807.mp3","categories":["زكاة النقدين"]},{"id":10886,"question":"تركت أمي بعد وفاتها بعض الحلي هو ملكها، لا أعرف مقداره بالجرامات، ونحن لا نستعمله، فهل تجب في هذا الحلي زكاة، وما هو المقدار الذي تجب فيه الزكاة من الحلي؟","title":"حكم زكاة الحلي ومقدارها","answer":"الجواب:  مثلما تقدم تجب فيه الزكاة إذا كان يبلغ عشرين مثقالًا من الذهب، والمثقال: يعادل اثنتين وسبعين شعيرة معتدلة، وهو يعرف بالذي يعرفه الصاغة بالوزن، يعرفون المثاقيل، فينبغي إذا كانت الحلي تبلغ النصاب -كما تقدم- عشرين مثقالًا من الذهب، وهو يعادل إحدى عشر جنيهًا سعوديًا وإفرنجيًا وثلاثة أسباع جنيه، يعادل النصاب أحد عشر جنيهًا وثلاثة أسباع جنيه بالعملة السعودية، أو الإفرنجية، وبالفضة يعادل مائة وأربعين مثقالًا، ويعادل ستة وخمسين ريالًا فضيًا من العملة السعودية. فإذا كانت الحلي تزيد على هذا تزكى، وفيها ربع العشر حسب قيمتها في الأسواق ..... تساوي مثلًا ألف دولار، أو ألف ريال سعودي، أو ألف دينار عراقي، أو أردني، أو ما أشبه ذلك من العمل التي في بلاد الإسلام، يزكي ربع العشر يخرج ربع العشر منها من كل ألف خمسة وعشرون، هذا ربع العشر، والصواب: أن الحلي فيها الزكاة وإن كانت معدة للاستعمال ... هذا هو الأرجح من أقوال أهل العلم. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9062/حكم-زكاة-الحلي-ومقدارها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_359/35908.mp3","categories":["زكاة النقدين"]},{"id":10936,"question":"المستمعة (م. ن. ع) من الكويت بعثت برسالة تقول فيها: هل يجوز إخراج الزكاة قبل حلول موعد إخراجها بشهر أو شهرين؟ وهل يصح أن تكون راتبةً لبعض المحتاجين بصفة دائمة، خاصةً وأنهم لا يزالون بحاجة إليها؟","title":"حكم إخراج الزكاة قبل موعدها وبصورة دائمة لفقراء معينين","answer":"الجواب:  نعم لا حرج في إخراج الزكاة قبل موعدها للمصلحة الشرعية، فقد تعجل النبي ﷺ زكاة عمه العباس قبل موعدها، فإذا أخرج الإنسان الزكاة قبل موعدها؛ لوجود فقراء محتاجين عجل لهم الزكاة، أو لمجاهدين، أو لفقراء من أقاربه اشتدت حاجتهم، أو نحو ذلك، فكل هذا لا بأس، بل ذلك مشروع، وفيه خير كثير. ويجوز أن تكون الزكاة راتبًا لبعض المحتاجين يدفعها إليه كل سنة صاحب الزكاة، إذا عرف حاجته، وأن حاجته مستمرة، فيعطيه إياه كل سنة، عادة سنوية؛ لعلمه بحاجته وأنه من أهل الزكاة لا حرج في ذلك، بل هذا في محله وصاحبه مأجور إذا تحرى حاجة إخوانه المساكين وأعطاهم إياها كل سنة؛ لحاجتهم وفقرهم حتى تزول الحاجة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9115/حكم-اخراج-الزكاة-قبل-موعدها-وبصورة-داىمة-لفقراء-معينين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_362/36212.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":10959,"question":"المستمع جابر محمد محمود مصري بعث برسالة يقول فيها: إنني أعمل خارج بلدي، وبحمد الله استطعت أن أجمع مبلغًا لا بأس به من المال، وأحب أن أخرج الزكاة، لكني لا أعرف مقدار الزكاة الواجبة، ولا لمن تعطى، هل تعطى للمساكين المتجمعين أمام المساجد، أم للمحتاجين من الأقرباء؟ وهل يجوز لي أن أرسلها لمن أرى أنه يستحقها من أبناء بلدي خارج البلد الذي أعمل فيه؟ أرجو الإفادة عن هذه القضايا جزاكم الله خيرًا.","title":"حكم زكاة المال وصرفها لفقراء الأقارب من خارج البلد","answer":"الجواب:  أما الزكاة فهي ربع العشر بالنص عن الرسول ﷺ وبإجماع المسلمين، في مسألة النقود، وعروض التجارة، يعني: سهم من أربعين سهمًا، ربع العشر من الذهب والفضة، وما يقوم مقامها من العمل، وقيمة عروض التجارة كالسيارات والأراضي وأشباه ذلك تعرف القيمة، ثم بعد معرفة القيمة يكون فيها ربع العشر، في المائة اثنان ونصف، في الألف خمسة وعشرون، وهكذا ربع العشر يعني: سهم من أربعين، هذا هو الواجب في النقود، وما يقوم مقامها من العمل الورقية، وهو الواجب أيضًا في عروض التجارة، وعروض التجارة هي الأموال التي تعد للبيع من أراضٍ، أو سيارات، أو خام، أو حبوب، أو غير ذلك من الأمتعة، هذه يقال لها: عروض التجارة، إذا كانت معدة للبيع، يقال لها: عروض التجارة، فإذا حال الحول عليها وجبت الزكاة في قيمتها، ربع العشر . فإذا كان عنده سيارات للبيع، وعند تمام الحول بلغت قيمتها مليونًا، زكى المليون، ربع العشر، خمسة وعشرين ألفًا من المليون؛ لأن عشر المليون مائة ألف، والربع خمسة وعشرون، هذا ربع العشر.  وهكذا لو كان عنده أراضٍ تساوي مليونًا، أعدها للبيع إذا حال عليها الحول يزكي ربع العشر، يزكي ربع قيمتها، وإذا كانت تساوي مليونًا فيها خمسة وعشرون ألفًا، وإذا كانت تساوي مائة ألف فيها ألفان ونصف، ألفان وخمسمائة، وهكذا. المقصود ربع العشر وهو سهم من أربعين سهمًا، هذه الزكاة في النقود من الذهب والفضة، وفيما يقوم مقامهما من العمل الورقية، وفي عروض التجارة وهي الأموال المعدة للبيع. أما زكاة الحبوب والثمار فهذه نوع آخر. وهي نصف العشر فيما يسقى بالمؤونة كالمكائن والسواني، والعشر فيما يسقى بالمطر والأنهار الجارية، والبعل الذي على مطر، هذا يكون فيه العشر كاملًا.  فإذا كان ألف كيلو تكون مائة كيلو، وهكذا، عشرة آلاف كيلو تكون ألفًا، الزكاة العشر، فيما يسقى بلا مؤونة، بلا كلفة بالأنهار، بالمطر، بالبعل كونه يبذر في الأرض، ويصلح على بذارة الأرض التي فيها الماء، من غير حاجة إلى مكائن، ولا سواني، ولا تعب، هذا فيه العشر كاملًا، لقول النبي ﷺ لما سئل عن ذلك: فيما سقي بالنضح نصف العشر، وفيما سقي بالأنهار العشر. فالمقصود أن هذا هو الحكم فيما يسقى بالمؤونة، وبغير مؤونة، ما يسقى بالمؤونة من السواني والمكائن فيه نصف العشر، وما يسقى بلا مؤونة ولا كلفة فيه العشر كاملًا. وأما الحيوانات فلها زكاة أخرى نوع آخر أيضًا، إذا كانت سائمة راعية من الإبل والبقر والغنم مفصلة في الأحاديث، وفي كلام أهل العلم. والسائل إنما سأل عن النقود وهذا بيان النقود كما سمعت ربع العشر. أما إخراجها فإنها تصرف في الفقراء والمساكين وغيرهم ممن سمى الله في قوله -جل وعلا-: إِنَّمَا الصَّدَقَاتُ لِلْفُقَرَاءِ وَالْمَسَاكِينِ وَالْعَامِلِينَ عَلَيْهَا وَالْمُؤَلَّفَةِ قُلُوبُهُمْ وَفِي الرِّقَابِ وَالْغَارِمِينَ وَفِي سَبِيلِ اللَّهِ وَاِبْنِ السَّبِيلِ فَرِيضَةً مِنَ اللَّهِ وَاللَّهُ عَلِيمٌ حَكِيمٌ [التوبة:60]. فإذا كان في بلده فقراء من أقاربه، أو غيرهم هم أولى من غيرهم، الفقراء في البلد أولى من غيرهم، وإذا كانوا من الأقارب فهم أولى، صدقة وصلة، تعتبر في حقهم صدقة وصلة، وإذا دعت الحاجة إلى نقلها إلى فقراء خارج البلد، أو أقارب فقراء خارج البلد؛ لأنهم أشد حاجة، وأشد ضرورة، فلا بأس بنقلها على الصحيح، وهكذا لو نقلها إلى المجاهدين في أفغانستان، وفي أرض في فلسطين فلا بأس بذلك؛ لأنهم في حاجة، ونقلها إليهم فيه مصلحة عظيمة. ومتى اجتهد صاحب الزكاة وفرقها في بلده، أو في فقراء خارج بلده من أقارب وغيرهم، فكل ذلك بحمد الله جائز والحمد لله، نعم. المقدم: جزاكم الله خيرًا، إنما سماحة الشيخ تفضلون إذا كان هناك أقارب فقراء تفضلون أن يكون الصرف عليهم؟ الشيخ: نعم إذا كان في البلد فقراء هم أفضل وأولى، وإذا كانوا أقارب فالصدقة فيهم أفضل أيضًا؛ لأنها صدقة وصلة رحم جميعًا، ولكن يجوز نقلها للمصلحة الراجحة، يجوز أن تنقل من بلد إلى بلد إذا كانت لمصلحة أرجح، لأقارب بعيدين أو لمجاهدين محتاجين، أو فقراء حاجتهم شديدة، فينقلها مثلاً من مكة إلى جدة، من الرياض إلى الخرج إلى الأحساء إلى أبها إلى غير هذا، نعم. المقدم: بارك الله فيكم سماحة الشيخ يذكر الفقراء الذين يتجمعون على أبواب المساجد، وهؤلاء يغلب على حالهم أنهم اتخذوا السؤال صنعة، توجيهكم شيخ عبدالعزيز ؟ الشيخ: من أظهر الفقر والحاجة ..... ممن يعرف أنه كاذب يعطى، سواء كان ممن يتجمع حول المساجد، أو في أي مكان، من ادعى الفقر والحاجة والعلامة الظاهرة عليه، ولا يوجد ما يكذبه فلا بأس أن يعطى، والنبي ﷺ لما اشتكى إليه رجلان وطلبا منه الزكاة، ورآهما جلدين يعني: نشيطين، قال: إن شئتما أعطيتكما، ولا حظ فيها لغني، ولا لقوي مكتسب. والإنسان قد يكون جلدًا، ولكن ما عنده مال، ما وجد... حرفة ولا وجد عملًا، فيعطى إذا أظهر الحاجة والفقر، ولا يوجد ما يدل على أنه كاذب يعطى؛ لأنه قد يكون صادقًا، ما وجد عملًا، ما حصل له شيئًا . فالحاصل أن من أظهر الفقر والحاجة، وسأل ولا يوجد ما يدل على كذبه يعطى، نعم. المقدم: جزاكم الله خيرًا، ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/9140/حكم-زكاة-المال-وصرفها-لفقراء-الاقارب-من-خارج-البلد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_364/36407.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":11044,"question":"هذا السائل عيظة عبدالله من بلجرشي، يقول سماحة الشيخ: يوجد عمارة بها شقق يتم تأجيرها بالشهر، وتارة تبقى الشقق بدون إيجار لعدة شهور، ويخرج المستأجر، ويأتي آخر بعد شهر، أو أكثر فكيف نؤدي زكاة إيجار تلك الشقق، وما حكم المصاريف على تلك الشقق من ناحية إصلاحها بالنسبة للزكاة؟ مأجورين.","title":"كيفية زكاة العين المؤجرة","answer":"الجواب:  متى أجرت بأجرة حال عليها الحول تزكى الأجرة، أما إذا تعطلت ما فيها زكاة؛ لأنها للإيجار، ما هي للبيع، إذا تعطلت ليس فيها زكاة، لكن إذا أجرها مدة سنة، أو أكثر يزكي، يزكي الأجرة إذا حال عليها الحول، أما لو زكاها بأجرة مستعجلة، وأكلها، أنفقها في حاجاته، ما فيها زكاة، الزكاة في الأجرة إذا بقيت حتى يحول عليها الحول، يزكيها إذا كانت نصابًا، والنصاب ستة وخمسون ريالًا من الفضة فأكثر، أو ما يقوم مقامها من الأوراق، من العمل الورقية، نعم.","link":"https://binbaz.org.sa/fatwas/9222/كيفية-زكاة-العين-الموجرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_287/28726.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":11233,"question":"السائل محمد إسماعيل يقول: سؤالي الأول: زوج وزوجة الزوج فقير جدًا والزوجة غنية، هل يجوز إعطاء زكاة أموالها لزوجها؟","title":"حكم إعطاء الزوجة الغنية زكاة مالها لزوجها الفقير","answer":"الجواب:  فيه خلاف بين أهل العلم، والصواب أنه يجوز لحديث ابن مسعود لا بأس أن تعطي زكاتها لزوجها. نعم.","link":"https://binbaz.org.sa/fatwas/9404/حكم-اعطاء-الزوجة-الغنية-زكاة-مالها-لزوجها-الفقير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_291/29114.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":11273,"question":"هل يصح للابنة أن تخرج زكاة الحلي عن والدتها وتعطيه لشقيقتها؟","title":"حكم إخراج البنت زكاة حلي والدتها وإعطائه لشقيقتها","answer":"الجواب:  إذا سمحت والدتها وأذنت لها أن تزكي عنها فلا بأس، ولا بأس أن تعطيها شقيقتها الفقيرة، أما إذا كانت شقيقتها غير فقيرة أو لها أب ينفق عليها أو زوج ينفق عليها فلا تعطى، أما إن كانت أخت فقيرة ليس لها من يقوم عليها فلا بأس أن تعطيها الزكاة، وقد أخرج النبي صلى الله عليه وسلم الزكاة عن عمه العباس . نعم.  المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9454/حكم-اخراج-البنت-زكاة-حلي-والدتها-واعطاىه-لشقيقتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_375/37505.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":11307,"question":"يقول أحد الإخوة المستمعين: يوجد لدي مبلغ من المال، فهل عليه زكاة إذ أنه ليس بحوزتي الآن بل هو أسلاف لدى الناس.الشيخ: أعد.المقدم: يقول: يوجد لي مبلغ من المال، هل عليه زكاة إذ أنه ليس بحوزتي الآن بل هو أسلاف عند الناس؟ جزاكم الله خيرًا.","title":"حكم زكاة المال إذا كان دينًا في ذمة آخرين","answer":"الجواب:  هذا فيه تفصيل، إن كانوا أغنياء فإذا قبضت فزكِ، وإن كان ما عندك شيء كل ما قبضت تزكي، أما إن كانوا لا، ليسوا بأغنياء، معسرين أو مماطلين فليس عليك شيء حتى تقبض، فإذا قبضت تستقبل حولًا جديدًا، نسأل الله السلامة. المقدم: اللهم آمين جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9485/حكم-زكاة-المال-اذا-كان-دينا-في-ذمة-اخرين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_376/37617.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":11371,"question":"هل يصح للابن أن يخرج زكاة الحلي عن والدته؟","title":"حكم إخراج الابن زكاة الحلي عن والدته","answer":"الجواب:  نعم إذا رضيت بذلك يصح أن يخرجها عنها زوجها وولدها وأخوها وبنتها وغيرهم إذا أخرجها عنها غيرها من الناس بإذنها فهو وكيل فلا بأس. نعم. المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9578/حكم-اخراج-الابن-زكاة-الحلي-عن-والدته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_379/37921.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":11378,"question":"هل يصح للابن أن يخرج زكاة الحلي عن والدته؟","title":"حكم إخراج الابن زكاة الحلي عن والدته","answer":"الجواب:  نعم إذا رضيت بذلك يصح أن يخرجها عنها زوجها وولدها وأخوها وبنتها وغيرهم إذا أخرجها عنها غيرها من الناس بإذنها فهو وكيل فلا بأس. نعم. المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9578/حكم-اخراج-الابن-زكاة-الحلي-عن-والدته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_379/37921.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":11418,"question":"يسأل سماحتكم عن الزكاة، وعن زكاة الراتب بالذات كيف يخرجها؟ جزاكم الله خيرًا.","title":"كيفية إخراج زكاة المرتبات الشهرية للموظف","answer":"الجواب: إذا كان الراتب يحفظ حتى تمر عليه السنة؛ يزكى إذا كان يبلغ النصاب، أكثر من ست وخمسين فضة ريالًا، أو ما يقوم مقامها من النقود، إذا حال عليه الحول؛ يزكي، أما إذا أنفقه قبل أن يتم الحول؛ فلا زكاة فيه. المقدم: بارك الله فيكم، يزكي زكاة محرم في محرم؟ أو كيف يكون الحال؟ الشيخ: إذا جاء الراتب في المحرم؛ زكاة في المحرم، في كل مائة اثنان ونصف، في المائة اثنان ونصف، وإذا كان في صفر صفر، ربيع ربيع وهكذا، إذا تمت السنة؛ يزكي ربع العشر، ولو أنها مائة ريال، ولو أنها مائتين ريال، نعم. المقدم: الله المستعان، بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/9599/كيفية-اخراج-زكاة-المرتبات-الشهرية-للموظف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_380/38017.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":11451,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين من الرياض، رمز إلى اسمه بحرفين هما (س. أ) أخونا له جمع من الأسئلة تصل إلى سبعة أسئلة في أحدها يقول: أسأل سماحتكم عن نصاب الذهب، لدي ما يقرب من مائة جرام لزوجتي، هل الزكاة تجب في هذا المقدار، أم تجب فيما زاد عن النصاب؟ وأنا أعلم أن النصاب ثلاثة وثمانون جرامًا.","title":"حكم زكاة الحلي وبيان نصاب الذهب","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد.  فنصاب الذهب كما بين أهل العلم عشرون مثقالًا، ومقدار المثقال بالجنيه السعودي أحد عشر جنيهًا وثلاثة أسباع الجنيه؛ لأن الجنيه مثقالان إلا ربع، وهي تحصل من إحدى عشر جنيه وثلاثة أسباع، يكون الجميع عشرين مثقالًا، والمعنى: إحدى عشر جنيهًا ونصف؛ لأن الكسر اليسير يغتفر في هذا، إحدى عشر جنيهًا ونصف، هذا النصاب من الذهب بالجنيه. أما بالجرام قد اختلف المقدرون لذلك على حسب ضبطهم للجرام، والذي نفتي به: أن النصاب اثنان وتسعون غرامًا بعدما سألنا كثيرًا من أهل الخبرة عن زنة الغرام، فالجميع اثنان وتسعون، هذا هو النصاب للجرام، فإذا بلغت الحلي من الذهب هذا المقدار؛ وجبت فيها الزكاة، سواء كانت أسورة، أو قلائد، أو غير ذلك المرأة تجمعها، فإذا بلغ الجميع إحدى عشر جنيهًا ونصف، اثنان وتسعين غرامًا؛ وجب عليها الزكاة، في جميع ما لديها، سواء كانت تلبسها، أو لا تلبسها، أو تلبس بعضها، وتدخر بعضها، الجميع فيه الزكاة على الصحيح من أقوال أهل العلم. وذهب بعض أهل العلم إلى أنها إذا كانت تلبسها؛ لا زكاة فيها، والصواب أن فيها الزكاة مطلقًا؛ لعموم قوله ﷺ: ما من صاحب ذهب، ولا فضة لا يؤدي زكاتها وفي لفظ: حقها إلا إذا كان يوم القيامة، صفحت له صفائح من نار ..، الحديث؛ ولأنه ﷺ: دخلت عليه امرأة في يدها مسكتان من ذهب -يعني: سوارين من ذهب- فقال: أتعطين زكاة هذا؟ قالت: لا، قال: أيسرك أن يسورك الله بهما يوم القيامة سوارين من نار؟ فألقتهما قالت: هما لله ولرسوله، خرجه النسائي -رحمه الله- وأبو داود بإسناد صحيح، من حديث عبدالله بن عمرو بن العاص، رضي الله عنهما. وأخرجه الترمذي بإسناد آخر ضعيف، ولكن العمدة على رواية النسائي، وأبي داود . ولحديث أم سلمة -رضي الله عنها- أنها قالت: يا رسول الله -وكانت تلبس أوضاحًا من ذهب- أكنز هذا؟ فقال ﷺ: ما بلغ أن يزكى فزكي؛ فليس بكنز هو لم يقل لها: ليس فيه زكاة؛ لأنه حلي، بل قال: ما بلغ أن يزكى يعني إذا بلغ النصاب فزكي فليس بكنز. يعني، وأما ما لم يزك؛ فإنه يسمى: كنزًا، يعني: يعذب به صاحبه، ولو كان حليًا، والنبي  يشير بهذا إلى قوله -جل وعلا- في سورة التوبة: وَالَّذِينَ يَكْنِزُونَ الذَّهَبَ وَالْفِضَّةَ وَلا يُنفِقُونَهَا فِي سَبِيلِ اللَّهِ فَبَشِّرْهُمْ بِعَذَابٍ أَلِيمٍ [التوبة:34]، فالكنز ما لم يزك، وإن كان على وجه الأرض، وإن كان في الصناديق، وإن كان في البنوك؛ يسمى: كنزًا، وما زكي؛ فليس بكنز، ولو كان في بطن الأرض، ما يسمى كنزًا، وذلك إذا أدي حقه. أما حديث أنه ﷺ قال: ليس في الحلي زكاة فهو حديث ضعيف عند أهل العلم، لا يصح الاعتماد عليه. والزكاة ربع العشر في المائة، اثنان ونصف، وفي الألف خمسة وعشرون، وهكذا، ربع العشر كل سنة، فإذا كان أقل من النصاب؛ فلا شيء عليه، وإذا كان الموجود نصابًا، فأكثر عليه ربع العشر، سهمان ونصف من المائة، خمسة وعشرون من الألف، وهكذا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9631/حكم-زكاة-الحلي-وبيان-نصاب-الذهب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_295/29501.mp3","categories":["زكاة النقدين"]},{"id":11457,"question":"يسأل ويقول: إذا كان لدي مال، فهل يجوز أن أصرف زكاته في بناء مسجد، أو لابد من صرفها على الفقراء؟ جزاكم الله خيرًا.","title":"حكم صرف الزكوات في بناء المساجد","answer":"الجواب: الزكاة لا تصرف في عمارة المساجد والمدارس، ولكن تصرف في الأصناف الثمانية المذكورة في قوله تعالى: إِنَّمَا الصَّدَقَاتُ لِلْفُقَرَاءِ وَالْمَسَاكِينِ وَالْعَامِلِينَ عَلَيْهَا وَالْمُؤَلَّفَةِ قُلُوبُهُمْ وَفِي الرِّقَابِ وَالْغَارِمِينَ وَفِي سَبِيلِ اللَّهِ وَاِبْنِ السَّبِيلِ فَرِيضَةً مِنَ اللَّهِ وَاللَّهُ عَلِيمٌ حَكِيمٌ [التوبة:60]، فأنت يا أخي، اصرفها في الفقراء والمساكين، والحمد لله، نعم. المقدم: الحمد لله، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9638/حكم-صرف-الزكوات-في-بناء-المساجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_381/38112.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":11472,"question":"يسأل سؤالًا يقول: إذا مضى علي أكثر من سنة، ولم تزكي امرأتي حليها، فماذا أفعل؟","title":"ما يفعل من مر على حلي زوجته أكثر من سنة ولم تزك؟","answer":"الجواب:  الزكاة عليها ليست عليك، الزكاة على المرأة المالكة للحلي، إن وجدت مالًا؛ وإلا تبيع من الحلي، وتزكي، تبيع من الحلي وتزكي، وإذا نقص وزن الحلي عن النصاب؛ سقطت الزكاة بعد ذلك. أما إن زكيت عنها بإذنها، وموافقتها؛ فجزاك الله خيرًا؛ لا بأس، أو زكى عنها أبوها، أو أخوها بإذنها ورضاها؛ فلا بأس. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9654/ما-يفعل-من-مر-على-حلي-زوجته-اكثر-من-سنة-ولم-تزك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_295/29502.mp3","categories":["زكاة النقدين"]},{"id":11537,"question":"يشوش على بعض الناس في هذا الموضوع سماحة الشيخ، كون بعض الباحثين يقول: إنه لا زكاة في الحلي المستعمل؟","title":"الراجح في مسألة زكاة الحلي","answer":"الجواب:  قد أوضحنا هذا لكن في مسألة خلاف بين العلماء، لكن الله يقول -جل وعلا- في كتابه العظيم: فَإِنْ تَنَازَعْتُمْ فِي شَيْءٍ فَرُدُّوهُ إِلَى اللَّهِ وَالرَّسُولِ إِنْ كُنتُمْ تُؤْمِنُونَ بِاللَّهِ وَالْيَوْمِ الآخِرِ ذَلِكَ خَيْرٌ وَأَحْسَنُ تَأْوِيلًا [النساء:59]، رددناه إلى الكتاب العظيم، فالله يقول -جل وعلا-: وَأَقِيمُوا الصَّلاةَ وَآتُوا الزَّكَاةَ [البقرة:43]، هذا عام في الأموال من الذهب والفضة، ويقول سبحانه: وَالَّذِينَ يَكْنِزُونَ الذَّهَبَ وَالْفِضَّةََ وَلا يُنفِقُونَهَا فِي سَبِيلِ اللَّهِ فَبَشِّرْهُمْ بِعَذَابٍ أَلِيمٍ [التوبة:34]. والنبي ﷺ قال: كل مال لا يؤدى زكاته؛ فهو كنز وهذا مال يسمى مالًا، فإذا لم تؤد زكاته؛ هو كنز، وعرضناه على السنة أيضًا في حديث عبدالله بن عمرو فوجدنا فيه أن في الحلي زكاة، وفي الأحاديث العامة في الذهب والفضة، فعمتها، عمت الحلي، والله يقول: وَمَا اخْتَلَفْتُمْ فِيهِ مِنْ شَيْءٍ فَحُكْمُهُ إِلَى اللَّهِ [الشورى:10]، هذا حكم الله فيما ظهر لمن قال بهذا القول من أهل العلم، وهو الراجح أن فيها الزكاة لهذه الأدلة، نعم. المقدم: جزاكم الله خيرًا، من اعتمد على قول أولئك هل يأثم لكونه لم يزك؟ الجواب: على حسب اجتهاده، إذا كان عاميًا عليه أن يأخذ بالحق الذي سمعه، ويطمئن إليه من أهل العلم، يتأمل، فإذا اطمأن إلى من أفتاه من أهل العلم أخذ بقوله؛ لأن العامي يقتدي بمن أفتاه، ويأخذ بمن أفتاه من أهل العلم، وإذا سمع القولين؛ فعليه أن يحتاط لدينه، وأن يخرج الزكاة حتى يسلم من العهدة، والقولان في الأخذ بالزكاة الأخذ بقول الرسول ﷺ. أما الذين قالوا بعدم الزكاة فليس عندهم إلا القياس على العوامل التي تعمل من الإبل أو البقر ولا ترعى، تكون تستعمل سواني ...، هذه ليس فيها زكاة؛ لأنها عوامل ليست ....... فلا يقاس عليها.  فالحاصل أنه ليس في أيديهم فيما نعلم إلا أقيسة، وليس في أيديهم حجة من الرسول ﷺ أو من الكتاب العظيم على أنه لا زكاة فيها، نعم معهم بعض أقوال الصحابة، وأقوال الصحابة ليس فيها حجة إذا خالفت النص، النص مقدم على أقوال الصحابة، وعلى غيرهم. نعم. المقدم: جزاكم الله خيرًا، إذًا: الأحوط لدين الإنسان أن يزكي الحلي؟ الشيخ: نعم. المقدم: جزاكم الله خيرًا، ماذا في حكم الحلي سماحة الشيخ؟ الجواب: الحلي جائزة للنساء، من الذهب والفضة، بل هي من زينتهن. المقدم: أقصد ما هي الأشياء التي تدخل في الحكم مثل الحلي بالنسبة للرجال مثلًا؟ الشيخ: الرجال مثل لو كان عنده خواتيم لهم يبيعها، أو يستعمل ما شاء منها تبلغ النصاب يزكيها من الفضة يعني إذا بلغ نصاب الفضة، أو كان عنده سلاح فيه ذهب يزكي الذهب الذي يبلغ النصاب، إذا كان عنده سلاح فيه ذهب، أو أدوات أخرى فيها ذهب، كأواني، أو غيرها يلزمه أن يزكي الذهب، وليس له استعمال اشترى الأواني، بل عليه أن يكسرها حتى يستفيد من ذهبها وفضتها؛ لأن الرسول ﷺ حرم استعمال الأواني من الذهب والفضة، نعم -عليه الصلاة والسلا- نعم. المقدم: الله صل وسلم عليه، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9719/الراجح-في-مسالة-زكاة-الحلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_295/29503.mp3","categories":["زكاة النقدين"]},{"id":11683,"question":"يقول: معي مبلغ من الدنانير الأردنية مضى عليها نصف الحول، فهل أدفع الصدقة عنها أو الزكاة في البلد الذي أقيم فيه، أم في بلدي وبالقيمة التي يجب دفعها؟ وجهوني جزاكم الله خيرًا.","title":"شروط إخراج الزكاة وأين تخرج","answer":"الجواب:  إذا حال عليها الحول تؤدي الزكاة في محلك الذي أنت فيه، سواء كنت في بلدك، أو في غيرها، إذا حال عليها الحول السنة، فعليك أن تؤدي زكاتها ربع العشر، في المائة اثنان ونصف، وفي الألف خمسة وعشرون، في المحل الذي أنت فيه تعطيه الفقراء في بلدك، وإن نقلتها إلى بلد آخر أجزأت والحمد لله، نعم. المقدم: جزاكم الله خيرًا يقول: إنه لم يمض عليها إلا نصف الحول؟ الشيخ: ما عليها زكاة حتى تكمل الحول، ليس عليها زكاة الدنانير والدراهم، وجميع أموال الزكاة، ليس فيها زكاة حتى تكمل الحول، إلا الحبوب والثمار هذه فيها زكاتها إذا نضجت، إذا نضجت فعليه زكاتها، وإذا جعلها في البيدر، ويبست أخرج زكاتها.  المقصود: أن الثمار من الحبوب والتمور والعنب زكاتها تجب إذا استوت، ونضجت وجبت فيها الزكاة، وأما الأموال الأخرى الذهب والفضة والإبل والبقر والغنم الراعية وعروض التجارة هذه لا بد فيها من السنة، الزكاة لا تجب إلا في السنة مرة، كل سنة يزكيها. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9863/شروط-اخراج-الزكاة-واين-تخرج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_390/39012.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":11776,"question":"شخص عليه دين كثير، والشخص يشتغل بالتجارة، وفي كل عام يخرج الزكاة، ويعطيها لصاحب الدين حتى يقضي عنه دينه، هل هذا العمل مشروع؟","title":"حكم إعطاء المدين زكاته لدائنه","answer":"الجواب: إذا تواطؤوا على ذلك لا، أما إذا أعطاه لفقره، أعطى إنسانًا لفقره، ثم هو رأى أن يوفي منها من غير تواطؤ، ولا اتفاق؛ فلا حرج، أما أن يقول له .... حتى تعطينيها ما يصلح، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9956/حكم-اعطاء-المدين-زكاته-لداىنه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_394/39418.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":11889,"question":"رسالة بعث بها مستمع رمز إلى اسمه بالحروف (ب. ج. ع) يقول: عندي مبلغ من المال، وهذا المبلغ هو زكاة أموالي، وأنا بعيد عن وطني، وأعرف أناسًا من أقربائي هم في أمس الحاجة، إلى الزكاة، هل أرسلها لهم نقودًا، أو ملابس؟ أو بماذا توجهونني؟ جزاكم الله خيرًا، وما الحكم فيما إذا أرسلتها قبل حلول الحول؟ جزاكم الله خيرًا.","title":"حكم إرسال الزكاة للأقارب الفقراء وتعجيلها قبل حلولها","answer":"الجواب:  الأفضل أن تفرقها في محلك إذا كان فيه فقراء محتاجين، وإن نقلتها إلى أقاربك الفقراء في بلدك؛ لشدة حاجتهم؛ فلا حرج في ذلك، بعد التأكد من حاجتهم إلى الزكاة. والأفضل أن ترسلها نقودًا إليهم، فإن كانت الحاجة ماسة إلى أن ترسلها ملابس، أو طعامًا بواسطة الثقات؛ لأنهم نساء، أو أيتامًا يخشى أن يتلاعبوا بالنقود؛ فلا بأس، ولكن الأفضل إرسال النقود بواسطة الثقة حتى يسلمها لهم نقودًا، إذا كانوا أهلًا لذلك. أما إذا كانوا أيتامًا؛ فتسلم لوكيل الأيتام، وإن كانوا نساءً مرشدات؛ فتسلم لأيديهن، فإن كن ليس مرشدات؛ فبيد الوكيل الذي لهن، وإذا رأيت أن الأصلح أن تدفع لهم الزكاة ملابس أو طعامًا خشية التلاعب بالنقود؛ فلا بأس بذلك، ولا حرج في ذلك. ولا مانع من تقديمها قبل الحول، لا مانع من تقديم الزكاة لهم قبل تمام الحول، لا حرج في التعجيل. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10073/حكم-ارسال-الزكاة-للاقارب-الفقراء-وتعجيلها-قبل-حلولها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_425/42510.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":11901,"question":"إحدى الأخوات المستمعات رمزت إلى اسمها بالحروف (م) و (ز. ح) لها رسالة وضمنتها قضيتين: القضية الأولى تقول فيها: هل يجوز إعطاء الأخ جزءًا من الزكاة زكاة المال؟ علمًا بأنه موظف، لكن دخله لا يكفي لأسرته، جزاكم الله خيرًا.","title":"حكم إعطاء المرأة زكاة مالها لأخيها الفقير","answer":"الجواب:  لا حرج في ذلك إذا كان الأخ أو العم أو الخال فقيرًا ومرتبه ضعيف لا يقوم بحاله؛ لا بأس أن يعطي من الزكاة، وهكذا ابن العم، أما الأب والأم لا، والأولاد لا، يعطون من مالك؛ لأن مالك غير الزكاة، أما إذا كان الأخ ضعيفًا فقيرًا أو الخال أو العم أو ابن العم، أو ما أشبه ذلك من الأقارب فالصدقة لهم .... من الزكاة صدقة وصلة، يعطون من الزكاة، ويكون لك أجران: أجر الزكاة، وأجر صلة الرحم، والحمد لله، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10085/حكم-اعطاء-المراة-زكاة-مالها-لاخيها-الفقير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_426/42602.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":11908,"question":"عندي مبلغ من المال، وأحفظه لأقوم بأي مشروع به، هل تجب الزكاة على هذا المال إذا حال عليه الحول؟ جزاكم الله خيرًا.","title":"حكم زكاة المال المحفوظ لإقامة مشروع ما","answer":"الجواب:  نعم عليك الزكاة إذا حال عليه الحول حتى تصرفه في المشروع، ما دام عندك، ولم تنفقه؛ فعليك الزكاة إذا حال عليه الحول، حتى تصرفه في مشروع عمارة مسجد، أو مدرسة، أو تصدق به على الفقراء، أو نحو ذلك. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10092/حكم-زكاة-المال-المحفوظ-لاقامة-مشروع-ما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_426/42609.mp3","categories":["زكاة النقدين"]},{"id":11909,"question":"هل يجوز أن أعطي أختي زكاة مالي التي لا دخل لها غير معاش والدي المتوفى؟","title":"حكم إعطاء الأخت من الزكاة","answer":"الجواب:  إذا كانت أختك مستقلة في بيت وحدها، عاجزة، ما عندها ما يقوم بحالها، لك أن تعطيها الزكاة، أما إن كانت عندك في البيت تنفق عليها؛ فلا، لا تعطيها زكاتك؛ هي غنية بنفقتك عليها، وإن أنفقت عليها من مالك، وأعطيت الزكاة لغيرها؛ فهذا أحسن، وأحوط إذا كنت قادرًا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10093/حكم-اعطاء-الاخت-من-الزكاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_426/42610.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":11943,"question":"ما هو حكم من يقوم بجمع أموال الزكاة، ويعطي منها لوالديه الفقيرين، علمًا بأنه لا يستطيع الإنفاق عليهما؟","title":"حكم إعطاء الابن والديه الفقيرين مما جمعه من الزكاة","answer":"الجواب:  إذا كان يطلب من الناس المساعدة لإخوانه الفقراء ومن جملتهم والداه، وهما فقيران؛ فهو مأجور، هو وكيل يكون وكيلًا لمن دفع إليه الزكاة، فإذا كان صادقًا متحريًا لأهل الحاجة؛ فلا بأس عليه، يعطي والديه، وغير والديه إذا كانا فقيرين، نعم.","link":"https://binbaz.org.sa/fatwas/10128/حكم-اعطاء-الابن-والديه-الفقيرين-مما-جمعه-من-الزكاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_428/42807.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":11944,"question":"جمعنا أموال الزكاة، وأقمنا بها مسجدًا يتعلم فيه الناس الصلاة، علمًا بأنه ليس هناك من يستحق هذه الزكاة في المكان الذي جمعت منه، فهل في ذلك حرج؟","title":"حكم تعمير المساجد من أموال الزكاة","answer":"الجواب:  المساجد لا تبنى من الزكوات في أصح قولي العلماء عند جمهور أهل العلم، فالذي قدم الزكاة لبناء المسجد؛ يجب عليه أن يعيد ذلك، وأن يزكي زكاة أخرى، للفقراء والمساكين، أو للغارمين، أو غيرهم من أصناف الزكاة، وهذه النفقة التي صرفها للمسجد تكون صدقة مطلقة، له أجرها وفضلها عند الله  وعليه أن يخرج الزكاة في أصنافها بدلًا من المال الذي صرفه في تعمير المسجد، هذا هو الذي عليه جمهور أهل العلم، وهو أصح قولي العلماء؛ لأن تعمير المساجد ليس من أصناف الزكاة الثمانية، وأما قوله سبحانه: وَفِي سَبِيلِ اللَّهِ [التوبة:60] فالمراد به: الجهاد كما هو قول جمهور أهل العلم. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10129/حكم-تعمير-المساجد-من-اموال-الزكاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_428/42808.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":11945,"question":"هل يجوز لفرد ما أن يأخذ من أموال الزكاة إذا كان عليه دين، ولا يستطيع أن يسدده؟","title":"حكم أخذ المديون العاجز عن القضاء من الزكاة","answer":"الجواب:  نعم، له أن يأخذ من مال الزكاة، له أن يأخذ من مال الزكاة ما يقضي به الدين إذا كان عاجزًا عن قضاء الدين، وليس له صرفه في غير ذلك، فإذا أخذ من إخوانه الطيبين مساعدة في قضاء دينه من الزكاة، فالواجب عليه صرف ذلك في قضاء الدين، لا في حاجاته الأخرى. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10130/حكم-اخذ-المديون-العاجز-عن-القضاء-من-الزكاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_428/42809.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":12009,"question":"من أم علاء في البحرين رسالة وتقول فيها: والدتي متوفاة من سنوات طويلة، ولها تركة، قليل من المال والذهب، ولم تقسم تركتها إلا هذه السنة عن طريق المحكمة لخلاف الإخوة والمحكمة أيضًا، إنني لا أدري إذا كانت والدتي كانت تخرج زكاة هذا المال، مع العلم أنها جمعته مما تحصله من أولادها جميعًا، وكانت تريد بذلك أن تشتري بيتًا تسكنه بدل بيت الإيجار، ولكن قضاء الله وقدره فوق كل شيء، وسؤالي: هل يجب علينا بعد أن نستلم من المحكمة التركة، هل يجب علينا أن نزكي، أم كيف توجهوننا؟ جزاكم الله خيرًا.","title":"تركة المتوفى هل يجب إخراج الزكاة منها؟","answer":"الجواب:  ليس عليكم زكاة، إلا إذا كان أوصت بإخراج الزكاة عنها سنة، أو سنتين، أما ما دمتم لا تعلمون فليس عليكم شيء، نعم. الحمد لله، الأصل أنها زكت، والحمد لله. المقدم: الحمد لله، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10194/تركة-المتوفى-هل-يجب-اخراج-الزكاة-منها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_431/43123.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":12063,"question":"يقول: يوجد لدى بعض النساء كميات كبيرة من الفضة، وهي التي كانت تدفع لهن مهور، ولوحظ أنهن لا يزكين هذا الحلي، فهل تنصحونهن بالزكاة؟ أم كيف يكون توجيهكم؟ جزاكم الله خيرًا.","title":"حكم زكاة حلي المرأة من الفضة","answer":"الجواب:  الواجب على النساء والرجال الذين عندهم فضة تبلغ النصاب بنفسها، أو بغيرها، يجب عليهم أن يزكوا، فالذي عنده فضة تبلغ النصاب، وهو ستة وخمسون ريال فضة عربي سعودي، يعني: مائة وأربعون مثقالًا، هذا النصاب مائة و أربعون مثقالًا، فإذا كان عند المرأة فضة تبلغ ستة وخمسين ريالًا من الفضة السعودي يعني: مائة وأربعون مثقالًا؛ وجبت الزكاة، أو عندها بعض الفضة، لكنها لا تبلغ النصاب، لكن عندها نقود أخرى من الورق إذا ضمت إليها؛ بلغت النصاب؛ وجبت الزكاة على الرجل والمرأة جميعًا، سواءً كان من الورق المعروفة، أو من الفضة، أو منهما جميعًا، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10248/حكم-زكاة-حلي-المراة-من-الفضة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_434/43412.mp3","categories":["زكاة النقدين"]},{"id":12091,"question":"يسألون أيضًا عن النساء المتزوجات، واللاتي لا دخل لهن سوى ما يتكرم به قريب أو زوج، هل يجوز صرف الزكاة لمثل هذا النوع من الزوجات، ولاسيما إذا كان الزوج لا يعطيها شيئًا سوى ما تأكل، أو تشرب، أو تكتسي؟ جزاكم الله خيرًا.","title":"حكم دفع الزكاة لامرأة فقيرة متزوجة","answer":"الجواب:  لا يجوز أن تعطى ذات الزوج من الزكاة، وإنما يعطى الزوج، إذا كان الزوج فقيرًا؛ يعطى ما ينفقه على زوجته، أما هي فلا تعطى؛ لأنها غنية بزوجها، وإذا كان زوجها لا يقوم باللازم؛ ففي إمكانها أن تطلب المحكمة إنصافها، أو من أوليائها حتى يناصحوه، أو من جيرانها حتى يناصحوه. المقصود: عليها أن تسعى في حل المشكلة من أي طريق، من طريق نصيحة الجيران، أو الأقارب والأصدقاء، أو فيما بينها وبينه تخوفه من الله، وتطلب منه أن يعطيها حقها، أما أن تعطى من الزكاة لا؛ لأنه كثير من النساء يتساهلن في هذا الأمر، قد تطلب من الزكاة وهي تلعب بالمال، وعندها ما يكفيها، أو تشتري بها أشياء، حاجات أخرى لا ضرورة إليها. المقصود: أن الزكاة لا تدفع للزوجة ما دام عندها زوج هو المسؤول عنها، لكن إذا كان فقيرًا يعطى هو وهو الذي ينفق على زوجته، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10276/حكم-دفع-الزكاة-لامراة-فقيرة-متزوجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_436/43605.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":12092,"question":"كيف يكون صرف الزكاة للفقير، هل يعطى حتى يغتني، أو توزع على أكثر من فقير إذا كان المال المزكى يعطي مبلغًا كبيرًا هو الزكاة؟","title":"مقدار ما يعطاه الفقير من الزكاة","answer":"الجواب:  الواجب أن يعطى الفقير ما يسد حاجته سنته كلها، عامه كله، وإذا كان الفقير عنده ما يكفيه نصف السنة؛ أعطي ما يكفيه لبقية السنة، وإذا كان صاحب الزكاة لا يعرف حاله، ولكن يعلم أنه فقير؛ فيعطيه، ويكفي، يعطيه ما تيسر من الزكاة، ويكفي، أما إذا كان يعرف حاله، وعنده زكاة كبيرة يستطيع أن يعطيه ما يسده في العام؛ فإنه يعطيه ما يسده في العام، ويحرم على الفقير أن يسأل بعد ذلك، يكتفي بما أعطي، ويحرم عليه أن يسأل زكاة بعد ذلك، وهو عنده ما يكفيه من الزكاة التي وصلت إليه، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10277/مقدار-ما-يعطاه-الفقير-من-الزكاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_436/43606.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":12093,"question":"إذا اجتمع أناس مثلًا وجمعوا مبلغًا معينًا من أموال الزكاة، ليشتروا بها بيتًا لأيتام فقراء، هل يجوز هذا، أو لا يجوز سماحة الشيخ؟","title":"حكم صرف أموال الزكاة في شراء بيت لأيتام","answer":"الجواب:  ما في مانع، يشترون به بيتًا، أو يستأجرون به بيتًا للأيتام؛ لا بأس، نعم؛ لأن الحاجة ماسة إلى السكن، نعم. المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10278/حكم-صرف-اموال-الزكاة-في-شراء-بيت-لايتام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_436/43607.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":12119,"question":"من الإمارات العربية المتحدة رسالة بتوقيع إحدى المستمعات تقول: (هـ. أ. أ) مصرية، أختنا بعثت بثلاث رسائل دفعة واحدة،، ولكن لرداءة خطها لم أستطع إلا فهم هذا السؤال، تقول: إنها تعطي جزءًا من راتبها كزكاة لأقاربها، فهل يجزئ ذلك، أو لا؟ جزاكم الله خيرًا؟","title":"حكم صرف الزكاة في الأقربين","answer":"الجواب:  إذا كان أقاربها فقراء؛ فلا بأس، الزكاة تجزئ فيهم، إذا كانوا ليسوا من عمودي النسب، ليسوا من آبائها وأجدادها، ولا من أمهاتها وجداتها، وليسوا من أولادها، وأولاد أولادها؛ فلا بأس، الإخوة والأعمام والأخوال وبني العم، وبني الخال، ونحو ذلك، إذا كانوا فقراء، وأعطتهم الزكاة؛ فهذه صدقة وصلة طيب، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10304/حكم-صرف-الزكاة-في-الاقربين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_438/43804.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":12162,"question":"تسأل سماحتكم فتقول: ما مقدار النصاب في الأموال النقدية؟ وما الحكم إذا أضفت إلى نصابي مبالغ أخرى خلال سنة؟ كيف أخرجها؟ أرجو الإفادة جزاكم الله خيرًا.","title":"مقدار نصاب الذهب والفضة وحكم ضم الأموال إلى غيرها","answer":"الجواب:  أما نصاب الذهب فهو عشرون مثقالًا، مقداره أحد عشر جنيهًا سعوديًا ونصف، يقال له: نصابًا، أحد عشر جنيهًا ونصف، يقال له: نصابًا، عشرون مثقالًا، وبالغرام اثنين وتسعين، مقداره بالغرام اثنان وتسعون غرامًا، هذا هو النصاب للذهب، فإذا كان أقل من هذا؛ فلا زكاة فيه. ولا تجب الزكاة إلا إذا حال الحول، إذا حال الحول على هذا الذهب؛ وجبت الزكاة، مثلًا: ..... على الإنسان ثمن مبيع، تم البيع، وأعطوه القيمة مائة جنيه، أو هبة مائة جنيه، أو امرأة صداقًا لها مائة جنيه، إذا حال الحول؛ زكاها ربع العشر. أما الفضة فنصابها مائة وأربعون مثقالًا، مقداره ستة وخمسون ريالًا فضة، بالريال السعودي، ستة وخمسون ريالًا فضة بالريال السعودي، فما بلغ هذا المقدار، أو قيمته؛ يكون نصابًا، إذا حال عليه الحول؛ يزكى، وإذا جاءته نقود متأخرة يكون لها حول آخر. فالإنسان الذي عنده مثلًا عشرة آلاف ريال اقترضها من إنسان، أو أعطيت له مساعدة، أو ما أشبه ذلك، إذا حال عليها الحول؛ زكاها، وإذا جاءت إليه دراهم أخرى بعد هذه الدراهم .. شهر، أو شهرين، يكون حولها إذا تم حولها، يكون حولها إذا مضى عليها سنة بعد مجيئها، أعطي عشرة آلاف في أول رمضان مساعدة، وفي شوال أعطي عشرة آلاف أخرى مساعدة، كل شيء له حوله، الذي في رمضان حولها رمضان، والذي في شوال حولها شوال، وهكذا، نعم.","link":"https://binbaz.org.sa/fatwas/10347/مقدار-نصاب-الذهب-والفضة-وحكم-ضم-الاموال-الى-غيرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_441/44112.mp3","categories":["زكاة النقدين"]},{"id":12218,"question":"تقول: إننا عائلة نتألف من سبعة إخوة، أنا أكبرهم، عمري ثمان عشرة سنة، وأب متوفى، تربينا أمي، وجدتي امرأة كبيرة، وتملك بيتًا نعيش فيه، وراتب شهري نصرف منه، قدره مائتان وثمانون دينارًا، ولدينا بعض الحلي القليلة، فما هو مقدار الزكاة التي يجب علينا دفعها للفقراء؟","title":"زكاة النقود والحلي","answer":"الجواب: إذا كان المال الذي عندكم بقدر الحاجة، ولا يبقى ما يحول عليه الحول، وهو نصاب ما في زكاة، لابد أن يكون الحول على نصاب، فإذا بقي عندكم ما يساوي أحد عشر جنيهًا سعوديًا ونصف، ما يساوي اثنين وتسعين غرامًا، وحال عليها الحول؛ يزكى من هذه النقود. وأما إذا كان الباقي قليلًا لا يبلغ هذا المقدار؛ فليس فيه زكاة، وهكذا الحلي التي على المرأة إذا كان دون النصاب، دون اثنين وتسعين غرامًا؛ فليس فيها زكاة، إنما الزكاة فيما بلغ النصاب، وحال عليه الحول. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10404/زكاة-النقود-والحلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_446/44606.mp3","categories":["زكاة النقدين"]},{"id":12230,"question":"رسالة مطولة بعض الشيء وصلت إلى البرنامج من أحد الإخوة المستمعين ضمنها أربعة أسئلة، وكلها تدور حول زكاة الذهب، أستأذن سماحة الشيخ في قراءة الرسالة كاملة مع أسئلتها.الشيخ: نعم.المقدم: يقول: رجل متزوج وله ابنة، زوجته تمتلك حليًا ذهبية، بعضها كان في حوزتها قبل الزواج، سواءً من أبيها، أو هدية من الرجل في فترة الخطوبة، والبعض الآخر اشتراه لها كهدية بعد الزواج، وكذلك اشترى لابنته بعض الحلي الذهبية، والسؤال الآن: كيف تخرج الزكاة عن هذه الحلي؟ هل يجمع ما تمتلكه الزوجة والابنة ويحسب النصاب، أم كل على حدة؟ وإن كان النصاب يحسب لكل من الزوجة والابنة منفردين فمن يخرج زكاة حلي الزوجة، هل الزوج، أم تخرجه هي من نفس ذهبها؟ علمًا بأنها ليس لديها مال، ثم تقول: ما هي قيمة النصاب؟ وعلى أي عيار من عيارات الذهب يحسب؟ علمًا بأن الذهب الموجود عيارات مختلفة، وهل الزكاة تخرج عن كل الذهب، أو على ما زاد عن النصاب فقط؟ وإذا اشترى الرجل لزوجته ذهبًا ليس من باب الهدية، ولكن من باب حفظ المال على أساس بيعه وقت الحاجة، فهل يضم إلى مالها، أو يبقى مع ماله؟ وإذا كان من ماله فهل تجمع قيمته على أمواله النقدية عند حساب النصاب؟ وإذا كان لهذا الرجل أولاد ذكور فهل يعد شراؤه ذهبًا لابنته دونهم ظلمًا لهم؟ وهل يلزمه شراء مقابل مساوٍ لهم؟ أفيدونا أفادكم الله.","title":"وجوب زكاة الحلي على من يملكه","answer":"الجواب:  أما الأول فإن الزكاة تكون على ذهب الزوجة وحدها، وعلى ذهب البنت وحدها إذا بلغ النصاب، كل عليه زكاته، فالزوجة عليها زكاة ذهبها، ولا فرق بين كونه عيار ثمانية عشر، أو عيار واحد عشرين، أو عيار أكثر من ذلك، كله يزكى على حسب ما يصرف في السوق، قيمته في السوق، فعليها أن تزكي ذهبها إذا بلغ النصاب، وعلى البنت زكاة ذهبها إذا بلغ النصاب. والنصاب عشرون مثقالًا، ومقداره بالجنيه السعودي: أحد عشر جنيهًا ونصف، أحد عشر جنيهًا، وثلاثة أسباع جنيه، يعني النصف؛ لأن الكسر يسير، أحد عشر جنيهًا ونصف، هذا هو النصاب، وهو عشرون مثقالًا، وهو إحدى وتسعون غرامًا وكسور، يعني: اثنان وتسعون على سبيل الاحتياط، اثنان وتسعون غرامًا. فإذا بلغ الذهب الذي عند المرأة هذا المقدار أحد عشر جنيهًا ونص، اثنين وتسعين غرامًا؛ فعليها أن تزكيه من مالها، فإن كان ما عندها مال؛ تبيع من هذا الذهب، وتزكي، أو تقترض، أو يزكي عنها زوجها إذا سمح، إذا هداه الله وزكى عنها بإذنها؛ فلا بأس، أو أبوها، أو أخوها بإذنها؛ فلا بأس، وإلا فتبقى الزكاة دينًا في ذمتها حتى تخرجها ببيع شيء من مالها حتى تزكي. أما إن كان الذهب أقل من النصاب، أقل من أحد عشر جنيهًا ونص؛ فلا زكاة عليها، وهكذا البنت؛ يوزن فإذا بلغ النصاب أحد عشر جنيهًا ونص؛ يزكى، وزكاتها عليها من مالها، تبيع من هذا الذهب وتزكي، إلا إذا زكى عنها زوجها، أو أخوها، أو غيرهما؛ فلا بأس. وليس للأب أن يخص البنات بذهب وعطايا دون البنين، بل إذا أعطى البنات شيئًا يعطي البنين، ولا يخصهم بشيء؛ لأن الرسول  قال: اتقوا الله، واعدلوا بين أولادكم وإنما يلزمه النفقة، ينفق على البنت ما دامت في حسابه، وما دامت عنده، وليس عندها مال ينفق عليها، فإذا أغناها الله ما بقي؛ عليه نفقة، وهكذا الولد ينفق عليه ما دام فقيرًا، وإذا أغناه الله فليس له نفقة، والنفقة تختلف نفقة الصغيرة غير نفقة الكبيرة، نفقة الصغير غير نفقة الكبير. والنفقة واجبة عليه على الأب ما دام الأولاد فقراء، فإذا أغناهم الله، أغنى الله البنت بالزوج، أو بمال آخر؛ فلا نفقة لها عليه، وهكذا الولد إذا أغناه الله بوظيفة، أو بتجارة؛ فلا نفقة له على والده. والذهب كما تقدم يزكى مطلقًا على أي عيار كان، من الذهب الرديء والطيب، وينظر في السوق ماذا يساوي، ويخرج زكاته، في الألف خمسة وعشرون، وإذا كان الذهب يبلغ أربعين مثلًا جنيهًا؛ زكاته واحد جنيه، ربع العشر، فإذا كان أقل أو أكثر؛ فلا مانع من إخراجه بالنقود الورقية، ما هو بلزوم أن يخرج من الذهب، لو أخرج القيمة من النقود الورقية؛ فلا بأس بذلك، ولا حرج في ذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10418/وجوب-زكاة-الحلي-على-من-يملكه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_447/44706.mp3","categories":["زكاة النقدين"]},{"id":12231,"question":"رسالة أخرى حول نفس الموضوع تقريبًا -سماحة الشيخ- تقول مرسلتها: أنا مصرية مقيم في إحدى القرى بالمملكة مع زوجي الذي يعمل مدرسًا، ولي قدر من الحلي الذهبية، ومنذ شرائها وأنا أعلم أن الحلي ليس فيها زكاة، وقد سمعت في برنامجكم من أحد العلماء الأفاضل: أن الحلي لا زكاة فيها، وفي حلقة أخرى سمعت أن الحلي فيها زكاة، فأحضرت كتاب تلخيص الحبير، وقد وجدت في صفحة واحد حديث روي أنه ﷺ قال: لا زكاة في الحلي ثم روى حديثًا آخر عن أسماء بنت يزيد قالت : دخلت أنا وخالتي على النبي ﷺ وعلينا أساور من ذهب، فقال لنا: أتعطيان زكاته؟ فقلنا: لا، قال: أما تخافان أن يسوركما الله بسوار من نار! أديا زكاته أرجو أن تفيدوني مأجورين؛ لأني قلقلة جدًا بالنسبة لهذا الموضوع، جزاكم الله خيرًا.","title":"القول الراجح في مسألة زكاة الحلي","answer":"الجواب:  نعم، اختلف العلماء في زكاة الحلي: فبعض أهل العلم -رحمهم الله- قالوا: إنه لا زكاة فيها؛ لأنها تستعمل؛ فأشبهت الإبل التي تستعمل، والبقر التي تستعمل؛ فلا زكاة فيها، واحتجوا بحديث: ليس في الحلي زكاة وقالوا: إن هذا يؤيد الأصل وهو أن المستعمل، ليس محل زكاة، وبما روي عن جماعة من الصحابة عن عائشة وأسماء وجماعة أنهم قالوا: لا زكاة في الحلي. وقال آخرون من أهل العلم: إن في الحلي الزكاة إذا بلغت النصاب، واحتجوا بحديث أسماء بنت يزيد، وما جاء في معناه، وأن الرسول ﷺ أمرها بالزكاة، وهكذا حديث أم سلمة قال لها النبي ﷺ لما سألته عن الحلي قال: ما بلغ أن يزكى فزكي؛ فليسس بكنز وجاء في حديث عن عائشة -رضي الله عنها- ما يدل على ذلك أيضًا، مع عموم الحديث الصحيح وهو قوله ﷺ: ما من صاحب ذهب ولا فضة لا يؤدي زكاتها إلا إذا كان يوم القيامة صفحت له صفائح من نار.. الحديث. وهذا القول هو الأصح، هذا القول هو الأصح أن فيها الزكاة لحديث أسماء، وما جاء في معناه، إذا بلغت النصاب، والنصاب عشرون مثقالًا، ومقداره بالجنيه السعودي: أحد عشر جنيهًا ونصفًا، وبالغرام: اثنين وتسعين غرامًا إلا يسيرًا، فهذا هو النصاب. فالواجب عليها أن تزكي ما بلغ هذا المقدار، سواءً من نفس الذهب، أو من العمل الورقية، أو من الريال الفضي، كله واحد، عليها أن تزكي ربع العشير، فإذا كان ذهبها الذي عليها يساوي مثلًا ألف ريال؛ فعليها الزكاة خمسة وعشرون، ربع العشر، وإذا كانت تساوي عشرين ألفًا؛ فعليها ربع العشر، وهو خمسمائة ريال؛ لأن عشر العشرين ألفان، وربع العشر خمسمائة ريال، فإذا كان يساوي أربعين جنيهًا؛ فعليها الربع، ربع العشر جنيه واحد؛ لأن عشر الأربعين أربعة، وربع العشر واحد، جنيه واحد. فالمقصود: أن عليها ربع العشر من قيمة الحلي، سواءً أخرجت ذلك ذهبًا، أو فضة، أو من العمل الورقية، وهذا هو القول المختار، وهو الأصح بالدليل، وأما حديث: ليس في الحلي زكاة فهو حديث ضعيف، لو صح؛ لكان كافيًا، لكنه ليس بصحيح، وهو حديث ضعيف عند أهل العلم؛ فلا يحتج به، نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10419/القول-الراجح-في-مسالة-زكاة-الحلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_447/44707.mp3","categories":["زكاة النقدين"]},{"id":12310,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المستمع (ع. م. السعدون) يقول: حدثونا عن زكاة الأسهم كيف تكون الزكاة فيها؟ هل يزكى الربح مع رأس المال، أم الربح وحده، ورأس المال وحده؟ وهل تجب الزكاة من حين الاكتتاب، أم عند رأس الحول؟وجهونا، جزاكم الله خيرًا.","title":"كيفية زكاة الأسهم","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد.  فشركة المساهمة فيها تفصيل: إن كانت السهام للبيع، وطلب الربح، فهذه تزكى إذا حال الحول على أصلها، كلما حال الحول تعرف قيمة السهام من أراضي، أو سيارات، أو عمارات، أو غير ذلك، كلما حال الحول على أصل المال الذي جعل في السهام؛ تزكى بعد معرفة القيمة لهذه الأرض، أو لهذه السيارات، أو لهذه العمارات، أو ما أشبه ذلك، تزكى مع ربحها، فإذا كان السهم اشتراه بعشرة آلاف، وعندما حال الحول؛ صار يساوي عشرين ألفًا؛ يزكي عشرين ألفًا، والعكس كذلك، لو اشتراه بعشرة، ولكن عند الحول نقص، وصار يساوي ثمانية، أو سبعة؛ فإنه يزكي القيمة الناقصة، فالعبرة في الزكاة بقيمة المبيع يعني: السهم حين تمام الحول. أما إن كانت السهام لا إنما هي للاستثمار، والبقاء، وليس للبيع، كأن يساهم في أرض ليعمر فيها سكنًا، أو يؤجرها، ولا أراد البيع، ولكنهم أرادوا بهذه الأرض أن يعمروها، ويجعلوها مساكن لأنفسهم، أو ليؤجروها، فهذه ليس فيها زكاة، إنما الزكاة فيما يحصل لهم من الأجور، إذا حصل لهم أجور، وحال عليها الحول؛ زكى الأجور. أما رقبة الأرض فلا زكاة فيها، وهكذا لو كانت المساهمة في عمائر لم يقصدوا بيعها، وإنما ساهموا ليؤجروا؛ فالزكاة في الإيجار إذا حال عليه الحول، وهكذا في السيارات إذا ساهموا في سيارات ليستعملوها تكاسي، أو ليؤجروها بصفة خاصة على من يستعملوها؛ فالزكاة في الأجرة إذا حال عليها الحول، نعم. المقدم: جزاكم الله خيرًا، إذا كان السهم نفسه عرضة للبيع والشراء سماحة الشيخ، فكيف يزكى؟ الشيخ: حسب النية، إن كان نيته البيع؛ فيزكيها زكاة العروض، تكون عروض تجارة، وإن كان حين المساهمة ما نوى البيع، إنما نوى الاستثمار لهذا السهم، فلا يزكى إلا الثمرة، الأجرة يعني. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/10510/كيفية-زكاة-الاسهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_454/45401.mp3","categories":["زكاة النقدين"]},{"id":12324,"question":"المستمع مصطفى شلبي إبراهيم من أبها بعث يسأل عن السيارة الخاصة، هل يؤدى عنها زكاة، وعن سيارة الأجرة أيضًا، جزاكم الله خيرًا.","title":"حكم زكاة السيارات المتخذة للاستعمال وللأجرة","answer":"الجواب:  السيارة الخاصة للاستعمال، وسيارات الأجرة ليس فيهما زكاة، لكن الأجرة إذا حال عليها الحول، وهي تبلغ النصاب يزكيها صاحبها، إذا صار عنده دراهم اكتسبها من السيارة، وحال عليها الحول، وهي تبلغ النصاب، ستة وخمسين ريالًا فضة، فأكثر، أو ما يعادلها يزكها، أما نفس السيارات .... السيارة ليس فيه زكاة؛ لأنه ما عد للبيع إنما أعد للاستعمال، والزكاة إنما تجب في العروض المعدة للتجارة للبيع، فإذا أعد السيارة للبيع؛ وجبت فيها الزكاة، وهكذا إذا أعد البيت، أو الأرض للبيع وجبت فيها الزكاة. أما إذا كان البيت معدًا للإيجار، أو السيارة للإيجار؛ فلا زكاة فيهما، لكن الأجرة إذا حال عليها الحول وهي تبلغ النصاب؛ زكيت. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10526/حكم-زكاة-السيارات-المتخذة-للاستعمال-وللاجرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_398/39813.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":12341,"question":"بالنسبة للزكاة المالية أو العينية أو كل ما وجبت فيه الزكاة، مما لا شك فيه أنها تزكى كلما دار عليها الحول، ولكن هل يتوجب، أو يتعين على المزكي أن يخرج الزكاة في وقت، أو في يوم معين، يكون له الأفضيلة من أيام السنة، أو أشهر السنة، مثل شهر رمضان مثلًا؟","title":"وقت إخراج الزكاة","answer":"الجواب:  الواجب إخراج الزكاة حين يتم الحول في أي وقت، والبدار بها من حين يتم الحول، هذا هو الواجب، والتأخير اليسير يعفى عنه، وإذا تم الحول في آخر شعبان، وأخرجها في رمضان، الأمر في هذا واسع -إن شاء الله- الأيام اليسيرة، وإلا فالواجب البدار بإخراجها؛ لأنها وجبت عليه، فالتأخير قد يعرض الرجل إلى أخطار قد يموت ولا يخرجها الورثة، قد يذهب المال، إلى غير ذلك. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10545/وقت-اخراج-الزكاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_399/39904.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":12345,"question":"إحدى الأخوات تقول: أنا المستمعة (م. س. ع) من بلاد زهران جرداء بني علي تقول: عندي حلي من الذهب والفضة، حيث أنني أتزين بها، ولا أريد أن أخزنها إلى وقت الحاجة، فهل عليها زكاة؟ جزاكم الله خيرًا.","title":"حكم زكاة الحلي المعد للزينة","answer":"الجواب:  الصواب فيها الزكاة إذا بلغت النصاب، وبعض أهل العلم: يرى ليس فيها زكاة، ولكن الصواب والراجح: أن فيها الزكاة، سواء كانت ذهبًا، أو فضة إذا بلغت النصاب، والنصاب في الذهب إحدى عشر جنيهًا ونص، يعني: عشرون مثقالًا، اثنان وتسعون جرامًا، فإذا بلغت الحلي من الذهب هذا المبلغ عشرين مثقالًا، يعني: إحدى عشر جنيهًا ونص أحد عشر جنيهًا ونص سعوديَا، اثنين وتسعين غرامًا؛ يكون فيها الزكاة إذا حال عليها الحول، سواء كانت أسورة أو غيرها، هذا هو الصحيح. أما الفضة فنصابها مائة وأربعون مثقالًا، ومقداره بالريال السعودي ستة وخمسون ريالًا من فضة، وما زاد على ذلك، ستة وخمسون هذا أقل النصاب، وما يعادل ذلك من العمل، الدولار، والدينار، والجنيه الإسترليني وغيره، العمل السعودية الورق ما يعادل ذلك. وذهب بعض أهل العلم إلى أنه لا زكاة فيها؛ لأنها تراد للاستعمال، ولكنه قول مرجوح، والصواب: أن فيها الزكاة؛ لأن النبي ﷺ قال لامرأة دخلت عليه وعلى ابنتها أسورة قال: أتعطين زكاة هذا؟ قالت: لا، قال: أيسرك أن يسورك الله بهما يوم القيامة سوارين من نار فألقتهما، وقالت: هما لله ولرسوله.  وقال لأم سلمة لما سألته عن الحلي: أكنز هذا؟ قال: ما بلغ أن يزكى فزكي فليس بكنز ولم يقل لها: هذه الحلي ما فيها زكاة، اللهم صل عليه وسلم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10548/حكم-زكاة-الحلي-المعد-للزينة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_399/39907.mp3","categories":["زكاة النقدين"]},{"id":12369,"question":"بالنسبة لرجل لديه تجارة، وعليه ديون، هل يسدد الزكاة، أم يسدد الديون التي عليه من زكاته؟","title":"حكم الزكاة على من لديه تجارة وعليه دين","answer":"الجواب:  الواجب عليه أن يزكي، والدين يبقى في الذمة، ولا يمنع الزكاة، هذا الصواب، الذي عليه المحققون من أهل العلم الدين لا يمنع الزكاة، ولكن عليه أن يزكي الأموال التي في يده، والله يوفي عنه  لكن لو أراد أن يسدد الدين؛ فلا مانع أن يخرج الدين قبل وجوب الزكاة، قبل ميعاد الزكاة، يوفي الدين ثم يزكي الباقي. المقدم: لكن إخراج الدين من نفس الزكاة، أو من حر ماله؟ الشيخ: من نفس المال. المقدم: من نفس المال. الشيخ: يخرج الزكاة من نفس المال الذي إذا كان عنده مال آخر ... زكاة يوفيه من المال الذي عنده، إذا كان عنده ما يقابل؛ فليزكه من المال ... فالمقصود: أن هذا المال الذي للزكاة يزكي إذا حال عليه الحول، ولا يمنعه الدين، لكن لو أن هذا المال الذي أعد للزكاة مثل عروض، أو فيه زكاة قد حال عليها الحول، لو أراد أن يخرج منه قضاء الدين؛ فلا بأس، قبل أن يحول الحول مثلًا الحول يحول في رمضان، وأوفى الدين من هذا المال في شعبان، أو في رجب؛ فإنه تسقط زكاة الذي أخرج في وفاء الدين. المقدم: بارك الله فيكم، لكن كونه يسدد الدين من زكاة المال ما حكم هذا؟  الشيخ: لا يسدد من زكاة المال، .... يسدد من المال. المقدم: هو يسأل عن هذا حفظكم الله؟ الشيخ: لا. يسدد من المال الذي عنده، أما الزكاة يعطيها المستحقين، إنما التسديد من المال نفسه للغرماء إذا كان قبل حول الزكاة، زكى الباقي، أما إذا حال الحول؛ فيزكي الموجود، ولا يمنعه الدين. المقدم: بارك الله فيكم، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10564/حكم-الزكاة-على-من-لديه-تجارة-وعليه-دين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_400/40002.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":12371,"question":"هل يجوز دفع الزكاة، أو الصدقة للإخوة الأشقاء الصغار الذين ليس لهم من يعولهم سوى أخوهم؟","title":"حكم دفع الزكاة أو الصدقة للإخوة الأشقاء","answer":"الجواب:  إن أنفق عليهم من ماله؛ فهو أحوط، إذا كان يستطيع وإلا جاز أن يعطيهم من الزكاة، جاز أن يعطيهم من الزكاة، وينفق عليهم من الزكاة، لكن إن أنفق عليهم من ماله غير الزكاة إذا كان يستطيع؛ فهو أحوط وأطيب. المقدم: بارك الله فيكم، يسأل عن النفقة هل تجب عليه جزاكم الله خيرًا؟  الشيخ: الوجوب فيه نظر، لكن إذا أنفق عليهم فهذا أطيب؛ لأنه إذا كان يرثهم، ليس لهم وارث سواه، فبعض أهل العلم يوجب عليه النفقة، لكن إذا أنفق عليهم، وتحرى حاجاتهم من غير إسراف، ولا تبذير من ماله؛ فهذا هو الأفضل له، والأحوط له، وإن أنفق عليهم من الزكاة؛ فلا حرج على الصحيح، إن شاء الله.  المقدم: الحمد لله، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10575/حكم-دفع-الزكاة-او-الصدقة-للاخوة-الاشقاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_400/40013.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":12373,"question":"يقول: هل يمكن أن نقدم الزكاة بسنة أو سنتين؟","title":"حكم تقديم الزكاة","answer":"الجواب:  لا مانع إذا كان للمصلحة، تقدم الزكاة لا بأس، نعم. المقدم: بارك الله فيكم وجزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10565/حكم-تقديم-الزكاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_400/40003.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":12388,"question":"هل الذهب يزكى بقدر قيمته، أم بقدر وزنه بالجرام، وإذا كان بالوزن، فكم مقدار الوزن الذي تجب فيه الزكاة؟","title":"نصاب الزكاة في الذهب","answer":"الجواب:  إن زكى بالذهب زكى من الذهب إذا كان أربعين جنيهًا؛ زكاة جنيهًا واحدًا ويكفي، أما إذا كان زكى بالقيمة؛ فإنه يزكي بالقيمة مثلًا عندها عشرين جنيهًا، زكاتها نصف جنيه، النصف الجنيه ما يتيسر إخراجه، ما هناك أنصاف، فإنه يخرج نصف القيمة، نصف قيمته في السوق، ما يساوي جنيهًا في السوق إذا كان.. الجنيه يساوي مائة؛ يخرج خمسينًا، أما إذا كان الجنيهات كثيرة، عنده أربعين؛ يخرج واحدًا، ربع العشر، كان عنده ستينًا؛ يخرج واحدًا، وقيمة النصف الباقي عليه هو جنيه ونص من الستين، فعليه أن يخرج جنيهًا برأسه، ويخرج نصف القيمة، وإن أخرج القيمة كلها، وفرقها بين الفقراء كله طيب. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10589/نصاب-الزكاة-في-الذهب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_401/40108.mp3","categories":["زكاة النقدين"]},{"id":12420,"question":"مستمع بعث برسالة يقول: (ص. ع) من عرعر يقول: قمت بتجميع جزء من رواتبي، فحال عليها الحول، وصرفت جزءًا من هذا المال قبل مضي الحول، وبقي لدي جزء آخر، هل أخرج الزكاة عن المال المتبقي؟ جزاكم الله خيرًا.","title":"المجموع الذي حال عليه الحول","answer":"الجواب:  المال المتبقي الذي حال عليه الحول يجب عليك إخراج زكاته، إذا كان يبلغ النصاب أكثر من ستة وخمسين ريالًا، إذا كان يبلغ النصاب عليك أن تخرج الزكاة، وهي ربع العشر من كل ألف خمسة وعشرون، والذي أخرجته قبل أن يتم الحول ما عليه زكاة، الذي أنفقته في حاجات بيتك مثلًا، أو قضيت به دينًا قبل أن يتم الحول؛ ليس فيه زكاة، لكن الذي بقي حتى تم عليه الحول؛ عليك أن تخرج زكاته، تطلب مرضات الله، وأداء الحق الذي عليك لله سبحانه، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10628/المجموع-الذي-حال-عليه-الحول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_402/40216.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":12421,"question":"يسأل: هل تعطى الزكاة للقريب، مثل الأخ، أو الجد، أو الخالة؟","title":"إعطاء الزكاة للأقارب","answer":"الجواب:  نعم يعطاها القريب الفقير صدقة وصلة، يقول النبي ﷺ: الصدقة على المسكين صدقة، وعلى ذي الرحم اثنتان صدقة وصلة الأخ الفقير، الخالة، العمة، ابن العم، ابن الخال، كل هؤلاء إذا كانوا فقراء يعطون. لكن لا تعطي أولادك، ولا تعطي أباك، ولا أمك، ولا جدك، ولا جدتك، هؤلاء لا، الأصول والفروع لا يعطون، تعطيهم من مالك ما هو من الزكاة، الذرية وإن كانوا فقراء تعطيهم من مالك، أو ذرية البنات تعطيهم من مالك، أو أمك، أو الأب، أو الجد، أو الجدة هؤلاء لا تعطيهم من الزكاة، تعطيهم من مالك، بارك الله فيك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10629/اعطاء-الزكاة-للاقارب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_402/40217.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":12443,"question":"تقول: عندي بعض الحلي التي أستعملها، وقد سمعت في برنامجكم أنه تجب الزكاة في الحلي، وقد مر علي سنين وأنا لا أزكي، فكيف تكون زكاتهها؟ أي: زكاة الذهب، أرجو إعلامي بذلك، وإذا كانت زكاتها بدفع مبلغ من المال، فأنا لا أملك أي مال، وزوجي لا يعطيني، فهل أبيع منها وأزكيها؟","title":"حكم امرأة عندها حلي وجهلت وجوب الزكاة فيه","answer":"الجواب:  عليك الزكاة في المستقبل، الماضي ليس عليك فيه، لأنك لم تعلمي، فعليك الزكاة في المستقبل، حين علمت؛ تبيعين من الحلي، وتزكين، والحمد لله، تبيعين منها، وتزكين عن السنة الحاضرة، وما بعدها بعد العلم، في كل ألف خمسة وعشرون، في الألف خمسة وعشرون ريالًا، وفي الألفين خمسون ريالًا، وهكذا. نعم. المقدم: جزاكم الله خيرًا، يا أم خالد معذرة، فقد تأخر الرد على رسالتك كثيرًا، معذرة لك ولكل مستمع تأخر الرد على رسالته.","link":"https://binbaz.org.sa/fatwas/10647/حكم-امراة-عندها-حلي-وجهلت-وجوب-الزكاة-فيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_456/45604.mp3","categories":["زكاة النقدين"]},{"id":12465,"question":"مستمع رمز إلى اسمه بالحروف (س. م. ع) يقول: أنا لدي عامل راعي غنم، هل يجوز أن أعطيه زكاة المال من هذه الماشية؟ أفيدوني بارك الله فيكم.","title":"حكم من أعطى زكاته لمن يعمل عنده لفقره","answer":"الجواب:  إذا كنت تعلم أنه فقير، وأن معاشه لا يكفيه، فلا مانع أن تعطيه من الزكاة، لكن إذا كنت تعطيه لأجل يبقى عندك، قد يكون معاشه قليلًا، تعطيه الزكاة حتى يرغب ويبقى؛ فلا يجوز، والأحوط أن تعطي الزكاة غيره، ويكفيه معاشه، يكفيه راتبه؛ لأني أخشى أن تكون هذه العطية من أجل بقائه لديك، فتكون نوعًا من زيادة الأجرة، فالزكاة أعطها الفقراء الذين ليس لك شبهة في إعطائهم، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10662/حكم-من-اعطى-زكاته-لمن-يعمل-عنده-لفقره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_404/40403.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":12526,"question":"زوجي يمر هذه السنة بظروف مادية صعبة، رغم أن راتبه جيد، ولكن عليه بعض الديون، هذا مع إيجار البيت، رغم أن الديانة لا يطالبونه بالدين، ولكني أراه مهمومًا أحيانًا، هل أعطيه زكاة ذهبي هذه السنة، أم لا يجوز ذلك، جزاكم الله خيرًا؟","title":"حكم إعطاء المرأة زكاة حليها لزوجها المديون","answer":"الجواب:  إذا كان غارمًا، وليس عنده وفاء؛ فلا بأس، إن كان عليه دين ثابت، وهو معسر بالقضاء؛ لأن الدخل حده البيت، نفقة البيت؛ فلا بأس أن تعطيه زكاتك، هذا هو الصواب، هذا هو الحق، لا بأس أن تعطي زوجك زكاتك إذا كان فقيرًا، أو غارمًا، عليه دين، ليس له قضاء، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10730/حكم-اعطاء-المراة-زكاة-حليها-لزوجها-المديون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_408/40809.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":12630,"question":"رسالة وصلت إلى البرنامج من جدة، وباعثها مستمع رمز إلى اسمه بالحروف: (ع. ع. ح. ش) يقول: يوجد طالب علم وداعية إلى الله، وهو يريد أن يتفرغ لطلب العلم والدعوة إلى الله، لكنه يشتغل عند أحد التجار بأجر شهري؛ لأنه ليس عنده ما يصرف منه على نفسه، وعلى عائلته، وقد اتفقت معه على أن أعطيه راتبًا شهريًا نصفه من الزكاة، ونصفه من رأس المال على أن يدع العمل، ويتفرغ لطلب العلم، والدعوة إلى الله، ويكون أجر الدعوة إلى الله بيننا مشتركًا، هل هذا العمل صحيح؟ وجهونا، جزاكم الله خيرًا.","title":"حكم إعطاء طلبة العلم من أموال الزكاة","answer":"الجواب:  نعم نعم، هذا العمل صحيح وطيب، وأنت مأجور، وهو مستحق للزكاة، وإذا تفرغ الإنسان لطلب العلم، وليس عنده ما يقوم بحاله؛ فإنه يعطى من الزكاة ما يقوم بحاله، والحمد لله، نعم. المقدم: جزاكم الله خيرًا، بالنسبة لكون الأجر مشترك؟ الشيخ: كله على حسب نفقته، الحمد لله، إذا كان أنصاف النفقة أنصاف، الحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10840/حكم-اعطاء-طلبة-العلم-من-اموال-الزكاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_415/41504.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":12631,"question":"أعمل في التجارة مستمع آخر هو: ناصر محمود حامد اندجاني يقول: أعمل في التجارة، فهل أقوم بإخراج الزكاة عن رأس مالي، أم أنني أخرج الزكاة عن رأس المال، والأرباح سويًا، علمًا بأن هذه الأرباح لم يمض عليها الحول؟","title":"حكم إخراج الزكاة من الأرباح التي لم يحل عليها الحول","answer":"الجواب:  الواجب على التاجر أن يزكي الأموال التي عنده، التي يقصد بها التجارة وأرباحها، يزكيها ويزكي أرباحها، وإن لم يحل الحول على الأرباح؛ لأن الربح تابع للأصل، فإذا كان الأصل -مثلاً- عشرة آلاف وربحت في آخر الحول قبل تمام الحول ألفًا، فصارت أحد عشر ألفًا؛ يزكي الجميع، الأصل والربح، كما أن نتاج الإبل والبقر والغنم يتبعها. فإذا كان عنده -مثلاً- تسعًا من الإبل، ونتجت منها واحدة؛ صارت عشرًا قبل تمام الحول؛ وجب عليه شاتان؛ لأنه تم النصاب قبل تمام الحول بهذا النتاج الجديد، فوجب عليه شاتان؛ لأنه في كل خمس شاة. فالمقصود: أن الربح يتبع الأصل، إذا كان فيه زكاة يتبعه الربح، وهكذا الإبل والبقر والغنم إذا كان الأصل فيه الزكاة يتبعها النتاج، ولا يحتاج إلى حول جديد. أما الأشياء التي ليست للتجارة، بل هي أدوات تستعمل في التجارة، كالميزان والأشياء التي لا تباع إنما هي موجودة للحاجة إليها، كالدكان نفسه الحانوت، والأدوات التي يفرشها، أو يجلس عليها، أو الميزان، أو ما أشبه ذلك من الأشياء التي ليست للربح، ولا للتجارة، هذه ليس فيها زكاة، إنما الزكاة في السلع المعدة للبيع، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10841/حكم-اخراج-الزكاة-من-الارباح-التي-لم-يحل-عليها-الحول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_415/41505.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":12634,"question":"المستمع (أ. ع. ل) يقول: لي صديق اشترى بيتًا له، وكلفه مبلغًا من المال، وصل إلى ثلاثمائة ألف، أو يزيد، ولكنه لم يستطع تسديد المبلغ بالكامل، فقد بقي مدينًا قرابة الخمسين ألفًا، فهل يحق أن يأخذ من الزكاة التي تأتي من المسلمين، مع العلم أنه يملك أرضًا وبيته القديم؟","title":"حكم الزكاة على من يملك بيتاً وأرضاً وعليه دين","answer":"الجواب:  إذا كان اشترى البيت الجديد للتجارة، أو لمزيد الدنيا، وعنده بيت يكفيه؛ فلا يستحق الزكاة، بل يبيع بيته الجديد، ويوفي ما عليه من الدين، أو يلتمس ذلك من جهات أخرى؛ لأنه ليس فقيرًا ما دام عنده السكن، فإنه يبيع هذا البيت، ويسدد ما عليه من الدين، ويستعمل الباقي في حاجاته، ولا يسمى فقيرًا، وعنده أرض، وعنده هذا البيت الجديد، وعنده السكن. الزكاة لابد أن يكون صاحبها فقيرًا، ليس عنده ما يقوم بحاله ويغنيه عن الزكاة، أما إذا كان عنده ما يغنيه من كسب يسد حاجته، أو وظيفة تسد حاجته، أو أموال يستطيع أن يبيع منها ويسد حاجته؛ فلا يعطى، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10844/حكم-الزكاة-على-من-يملك-بيتا-وارضا-وعليه-دين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_415/41508.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":12724,"question":"من البحرين الأخت المستمعة (ن. ج. ق) بعثت تسأل وتقول: هل يجوز إعطاء الزكاة للمسلمين خارج البلد الذي نعيش فيه، مثل مكة والمدينة أثناء الحج، أو العمرة، أو هل يجوز إرسالها إلى منكوبي الجفاف، أو إلى مجاهدي أفغانستان وفلسطين وغيرهم؟","title":"حكم إخراج الزكاة في غير بلد المزكي","answer":"الجواب:  فقراء البلد أولى؛ لأنهم في حاجة إليها، والرسول -عليه الصلاة والسلام- قال: تؤخذ من أغنيائهم، فترد لفقرائهم ولأنها مواساة، فالغني يواسي فقيره الذي عنده في بلده، فإذا كان الفقراء في البلد قليلين، وقد حصل لهم ما يكفي؛ فلا مانع من نقلها إلى بلاد أخرى، كالمجاهدين الأفغان، والمجاهدين في داخل فلسطين، وغير ذلك، أو كان له أقارب حاجتهم شديدة، فنقلها إليهم، أو فقراء يعرف عنهم أن حاجتهم شديدة، أشد من حاجة فقراء البلد؛ فلا حرج في ذلك، وإلا فالأصل أن فقراء البلد هم أولى. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10937/حكم-اخراج-الزكاة-في-غير-بلد-المزكي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_460/46012.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":12732,"question":"يقول: سمعت شيخًا يقول: إنه يجب على المسلم الزكاة على الحلي التي تلبس إذا بلغت النصاب، وحال عليها الحول، فما هو النصاب، وما قيمته، وكيف أخرج الزكاة عن الحلي الملبوسة إذا كنت لا أعرف قيمتها؟ أفيدونا أثابكم الله خيرًا.","title":"حكم زكاة الحلي المعدة للزينة ومقدار زكاته","answer":"الجواب:  الصواب: أن فيها الزكاة الحلي من الذهب والفضة، والنصاب عشرون مثقالًا من الذهب، ومقداره اثنان وتسعون غرامًا من الغرامات، ومقداره بالجنيه السعودي إحدى عشر ونصف، أحد عشر جنيهًا ونصف السعودي، الجنيه السعودي، والواجب ربع العشر، في كل ألف خمسة وعشرون؛ إذا حال الحول، إذا تمت السنة، وهو يبلغ النصاب في كل ألف خمسة وعشرون. أما الماس والجواهر الأخرى فليس فيها زكاة، إذا كانت للبس، إنما الزكاة في الذهب والفضة خاص. أما الفضة فنصابها مائة وأربعون مثقالًا، ومقداره بالعملة السعودية ستة وخمسون ريالًا من الريال الفضي، فإذا بلغت قيمة الحلي هذا النصاب من ذهب، أو فضة زكاه يستعين في ذلك بالمختصين أصحاب الذهب والفضة، يسألهم ويعطيهم الذهب الذي عنده والفضة حتى يعرفوا زنتها، ويعلموه ويخبروه. أما إن كان الحلي من غير الذهب والفضة، بل ماس، أو جواهر أخرى من العقيق ونحوها هذه لا زكاة فيها، إلا إذا كانت للبيع والتجارة؛ ففيها زكاة التجارة، أما إذا كانت للبس؛ فليس فيها زكاة، إنما الزكاة في الذهب والفضة على الصحيح، في أصح قولي العلماء. نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10946/حكم-زكاة-الحلي-المعدة-للزينة-ومقدار-زكاته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_461/46104.mp3","categories":["زكاة النقدين"]},{"id":12830,"question":"من أعطى زكاته إلى أخيه، أو أبناء أخيه، وهم في حاجة، وعليهم دين، وهما لا يشاركون المزكي، هل يجوز، أم لا؟","title":"حكم إعطاء الزكاة للأخ أو أبناء الأخ الفقراء","answer":"الجواب:  نعم إذا أعطى أخاه أو أولاد أخيه وهم فقراء لا بأس إذا كانوا مستقلين ليسوا شركاء له، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11044/حكم-اعطاء-الزكاة-للاخ-او-ابناء-الاخ-الفقراء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_463/46318.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":12934,"question":"سماحة الشيخ هذا سائل من الرياض رمز لاسمه بـ (ع. أ. أ) يقول: رجل لديه أموال طائلة، ولا يزكي عليها لعدة سنوات وأكثر من عشر سنوات، لم يزك عليها، وعندما نصحناه قلنا: زك هذه الأموال، قال: سأزكي عليها بعد كل خمسة عشر سنة، ونرجو منكم التوجيه في هذا؟","title":"عقوبة من يتكاسل عن إخراج زكاة أمواله","answer":"الجواب:  هذا منكر لا يجوز، فالواجب على المسلم أن يزكي كل سنة، ولا يجوز التأخير لا سنتين ولا أكثر، يجب أن يزكي عند نهاية كل عام عن جميع الأموال التي عنده من الذهب والفضة وعروض التجارة، وهكذا إذا كان يزرع؛ يزكي زكاة الزرع .. زكاة التمور، زكاة العنب، كل سنة في سنتها إذا بلغت النصاب، هذا هو الواجب؛ لأن الله قال -جل وعلا-: وَآتُوا حَقَّهُ يَوْمَ حَصَادِهِ [الأنعام:141] قال: وَأَقِيمُوا الصَّلاةَ وَآتُوا الزَّكَاةَ [البقرة:43] هذه للفورية، أقيموا الصلاة في وقتها، وآتوا الزكاة في وقتها. وأخبر -جل وعلا- أن الذين يكنزون الذهب والفضة، ولا ينفقونها في سبيل الله أنهم موعودون بالعذاب الأليم، قال -جل وعلا-: وَالَّذِينَ يَكْنِزُونَ الذَّهَبَ وَالْفِضَّةَ وَلا يُنفِقُونَهَا فِي سَبِيلِ اللَّهِ فَبَشِّرْهُمْ بِعَذَابٍ أَلِيمٍ  ۝  يَوْمَ يُحْمَى عَلَيْهَا فِي نَارِ جَهَنَّمَ فَتُكْوَى بِهَا جِبَاهُهُمْ وَجُنُوبُهُمْ وَظُهُورُهُمْ هَذَا مَا كَنَزْتُمْ لِأَنفُسِكُمْ فَذُوقُوا مَا كُنتُمْ تَكْنِزُونَ [التوبة:34-35] هذا جزاء من بخل بالزكاة، ولم يخرج حقها، كل مال لا تؤدى زكاته؛ فهو كنز، يعذب عليه صاحبه يوم القيامة. وفي الحديث الصحيح: «أن الذين لا يؤدى الزكاة يوم القيامة يعذبون، تحمى عليهم تلك الأموال من الذهب والفضة، وما يقوم مقامها، فيعذبون بها، في يوم كان مقداره خمسين ألف سنة، حتى يقضى بين الناس، ثم يرى سبيله إما إلى الجنة وإما إلى النار، وصاحب الإبل والبقر والغنم يبطح لها بقاع قرقر تمر عليه تطؤه بخفافها وأظلافها، الإبل بخفافها، والبقر والغنم بأظلافها، تنطحه البقر والغنم بقرونها، وتعظه الإبل بأفواهها، كلما مرت عليه أخراها؛ عادت عليه أولاها في يوم كان مقداره خمسين ألف سنة» هذا جزاؤه، نسأل الله العافية. فالواجب على من كان عنده مال زكوي أن يخرج الزكاة كل سنة، وعلى هذا الشخص أن يتوب إلى الله، وأن يخرج الزكاة عما مضى من السنين، عليه التوبة والندم والإقلاع والاستغفار والبدار بإخراج الزكاة عن السنوات الماضية، نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11150/عقوبة-من-يتكاسل-عن-اخراج-زكاة-امواله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_501/50109.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":12989,"question":"يسأل سؤاله الأخير ويقول: هل يجوز دفع زكاة المال على الخدم لإرسالها لأهلهم وأقاربهم؟","title":"حكم إعطاء الزكاة للخادم","answer":"الجواب:  هذا فيه تفصيل: إذا كنت تعرف الخادم، وأنه فقير، وأن أهله فقراء، وعندك يقين في هذا لا بأس، إذا كان مسلمًا، وأهله مسلمون. أما الخدم الذين لا تعرف حالهم، ولا حال أهلهم فلا، الواجب أن تلتمس الفقراء المعروفين بالإسلام حتى تدفع إليهم على بصيرة في بلدك، والخادم تكفيه أجرته، والحمد لله. لكن لو تيقنت أنه فقير، وأن الأجرة ضعيفة، وأن لديه عائلة، أو والدان فقراء، وهم مسلمون... هذا شيء لا شك فيه؛ فلا مانع أن يعطى من الزكاة بشرط أن لا تكون وقاية لمالك؛ حتى لا تزيد في الأجرة؛ حتى لا يطالبك بأجرة زيادة، نعم. المقدم: جزاكم الله خيرًا، سماحة الشيخ! من المعروف أن الخدم إذا نالوا شيئًا من الزكاة تتحسن خدماتهم، فما هو توجيهكم لو سمحتم؟ الشيخ: إذا لم يكن شرطًا؛ فلا بأس، وإن خاف؛ فيعطيها غيرهم، يعطيها غيرهم؛ احتياطًا لدينه.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11207/حكم-اعطاء-الزكاة-للخادم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_470/47014.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":13012,"question":"تقول في سؤال آخر: لدي مبلغ مدخر، وقدره عشرة آلاف ريال، وتمام الحول يكون شوال أي: بعد رمضان، ولكن لدي الرغبة في أن أخرج زكاته في رمضان، فهل يجوز ذلك، وكم أخرج زكاة العشرة الآلاف؟ وهل أخرج قيمة الزكاة من راتبي، أم من نفس المبلغ؟ أرجو الإفادة، جزاكم الله عني وعن المسلمين خيرًا.","title":"حكم تعجيل الزكاة وما مقدارها؟","answer":"الجواب:  تعجيل الزكاة لا بأس به، تعجيل الزكاة للمصلحة لا بأس، فإذا كان الحول يتم في شوال، وأحب المسلم أن يخرج الزكاة في رمضان؛ فلا حرج في ذلك، لأجل فضل رمضان، أو صادف فقراء حاجتهم شديدة قبل تمام الحول، فعجل لهم الزكاة، أو عجلها للمجاهدين، كل هذا طيب، وما أشبهه، ولا بأس بذلك. والواجب في عشرة الآلاف ربع العشر مثل غيرها، الواجب ربع العشر، ففي العشرة الواجب مائتان وخمسون؛ لأن عشرها ألف وربع الألف مائتان وخمسون، هذه زكاة العشرة الآلاف، وفي الألف الواحد خمسة وعشرون، وفي المائة اثنان ونص، فالزكاة ربع العشر. ولا يجب إخراجها من نفس المال، فإذا أخرجت الزكاة من راتبك، أو من مال آخر؛ فلا حرج، ليس إخراج الزكاة من نفس المال المحفوظ في بنك، أو غيره لازمًا لا، إذا أخرج الزكاة من مال آخر، أو من راتبه؛ فلا حرج في ذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11229/حكم-تعجيل-الزكاة-وما-مقدارها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_471/47108.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":13037,"question":"الواقع تطرقتم إلى الزكاة سماحة الشيخ، وأخونا يسأل عنها يقول: هل يجوز إعطاء الزكاة للمساجد؟","title":"حكم دفع الزكاة في بناء المساجد","answer":"الجواب: لا، تصرف في غير المساجد، تبنى من غير الصدقات، لكن يصرف الزكاة في أهلها، في الفقراء، في المجاهدين في أبناء السبيل، في عتق الرقاب، في فك أسرى المسلمين، في الغارمين المدايين المحتاجين العاجزين، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11254/حكم-دفع-الزكاة-في-بناء-المساجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_472/47217.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":13041,"question":"المستمعة (زهرة . ح. ج) تقول: سماحة الشيخ! هل يجوز أن أخرج زكاة ذهبي لزوجي الذي عليه ديون كثيرة، أفتوني مأجورين؟","title":"حكم إخراج المرأة زكاتها لزوجها المدين","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فلا حرج في إعطاء الزوج الزكاة إذا كان فقيرًا، لا حرج في ذلك على الصحيح من أقوال العلماء، إذا كان فقيرًا؛ يعطى الزكاة من زوجته، نعم. المقدم: وإذا كان عليه ديون يا شيخ؟ الشيخ: إذا كان عليه ديون لا يقضيها فهو فقير، إذا كان عليه ديون عاجز عن قضائها؛ فهو غارم فقير، نعم يعطى الزكاة.","link":"https://binbaz.org.sa/fatwas/11258/حكم-اخراج-المراة-زكاتها-لزوجها-المدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_505/50501.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":13139,"question":"تقول هذه السائلة: هل يجوز إخراج الزكاة على مؤخر صداق المرأة، علمًا بأنها لا تستطيع أن تطالب الزوج بهذا الصداق؟ ومن الذي يجب عليه إخراج الزكاة في مثل هذه الحالة يا سماحة الشيخ؟","title":"حكم إخراج الزكاة عن مؤخر الصداق","answer":"الجواب:  ليس عليها زكاة؛ لأن هذا الدين غير مقدور عليه، ليس في قدرتها، فهو مثل الدين الذي على المعسر، ليس في قدرة صاحبه الحصول عليه، ومثله المال الضائع لا زكاة فيه، أما الدين المؤجل الذي يقدر عليه صاحبه عند الأجل؛ فهذا يزكى، إذا كان على مليء.  أما الصداق المؤجل الذي لا تستحقه إلا بالفراق؛ فليس عليها زكاة له؛ لأنها لا تقدر على قبضه الآن، ولا في وقته الحقيقي؛ لأنه أمر مؤجل، لا يدرى متى يحصل، نعم.","link":"https://binbaz.org.sa/fatwas/11393/حكم-اخراج-الزكاة-عن-موخر-الصداق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_510/51003.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":13143,"question":"سؤاله الأخير يقول: لدى زوجتي بعض الحلي من الذهب، ولنا ثلاث سنوات لم نزكه، هل يجب على حلي النساء زكاة، وما مقدارها؟","title":"حكم زكاة الحلي ومقدارها","answer":"الجواب: الصواب أن فيها الزكاة على الراجح من أقوال العلماء، فيها خلاف بين أهل العلم، لكن الصواب أن فيها الزكاة، في كل ألف خمس وعشرون، فإذا بلغت النصاب؛ زكيت، والنصاب عشرون مثقالًا، ومقداره: اثنان وتسعون غرامًا، وبالجنيه السعودي إحدى عشر جنيهًا ونص. فإذا بلغت الحلي النصاب وحال عليها الحول؛ وجبت فيها الزكاة في أصح أقوال أهل العلم، يعطاها الفقراء كسائر الزكوات، وعليكم أن تزكوا عن السنوات الماضية، إذا كانت المرأة قد علمت بهذا في السنوات الماضية؛ فعليها أن تزكي عن السنوات الماضية، أما إذا كانت لم تعلم إلا أخيرًا؛ فإنها تزكي في المستقبل، والحمد لله، والماضي يعفو الله عنه لعدم العلم. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11397/حكم-زكاة-الحلي-ومقدارها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_474/47418.mp3","categories":["زكاة النقدين"]},{"id":13154,"question":"هذه السائلة تقول في هذا السؤال سماحة الشيخ: عندي ذهب هدية، فهل فيه زكاة؟","title":"حكم الزكاة في الذهب المكتسب عن طريق الهدية","answer":"الجواب:  نعم، إذا حال الحول على الهدية، وهي تبلغ النصاب، وجبت الزكاة فيها، فإذا أهدى إنسان إلى إنسان ما يبلغ النصاب من الذهب، أو الفضة، وحال عليها الحول؛ وجبت عليه الزكاة؛ لأنه صار ماله بالهدية، إذا قبلها؛ صارت مالًا له. فإذا حال الحول بعد قبوله الهدية، وقبضه لها؛ فإنه يزكي الهدية، سواءً كانت ذهبًا أو فضة، أو مالًا آخر نوى به التجارة والبيع، فإذا حال عليه الحول وجبت الزكاة. نعم. المقدم: جزكم الله خيرًا، سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11408/حكم-الزكاة-في-الذهب-المكتسب-عن-طريق-الهدية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_510/51014.mp3","categories":["زكاة النقدين"]},{"id":13201,"question":"هذا السائل صالح حسن يقول: ما هو نصاب زكاة النقود بالريال سماحة الشيخ؟","title":"مقدار نصاب النقود","answer":"الجواب:  زكاة النقود من الفضة مائة وأربعون مثقالًا، ومقدارها بالفضة بالريال السعودي الفضي ستة وخمسون ريالًا، وبالعملة الورقية ما يقابل ذلك، ما يساوي ستة وخمسين ريالًا فضة فيه الزكاة، وقال بعض أهل العلم: ستة وخمسون ريالًا ورقًا فيها الزكاة كالفضة؛ لأنها قامت مقامها.  وبكل حال فإذا كان عنده من الورق -سواء عملة الريال أو عملة العشرة أو عملة ما فوق العشرة كالخمسين- إذا كان عنده عملة تساوي ستة وخمسين ريالًا فضة؛ فهذا نصاب، وما زاد على ذلك فبحسابه، نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11469/مقدار-نصاب-النقود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_512/51207.mp3","categories":["زكاة النقدين"]},{"id":13203,"question":"يقول هذا السائل: أعطيت شخصًا خمسين ألف ريال للاستثمار، وكانت هذه أول مرة أتعامل معه، فلم أكن متأكدًا ما إذا كنت سآخذ هذه الأموال، أم لا، وظلت هذه النقود عنده لمدة عامين، ثم أخذتها منه دون زيادة، أو نقصان، فهل أخرج الزكاة عن العامين السابقين، أم أستقبل بهما عامًا جديدًا؟","title":"حكم الزكاة عن المال إن كان مقروضاً","answer":"الجواب:  عليك إخراج زكاتها عن العامين؛ لأنها في ملكك، وهي عندك كالأمانة؛ لأنه لم يعمل فيها شيئًا؛ فهي كالأمانة، بس عليك زكاتها، نعم، أما لو عمل فيها، وربحت؛ عليك زكاتها، وزكاة الربح، لكن مادامت بقيت عنده، ولم يعمل شيئًا؛ فهي مثل الوديعة تزكيها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11474/حكم-الزكاة-عن-المال-ان-كان-مقروضا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_512/51208.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":13265,"question":"هذا سائل للبرنامج يقول: أرجو التكرم بالإجابة على سؤالي: هل يجوز أن أعطي والدي وأخي من زكاة مالي، مع العلم بأنه يوجد عندهم أرض زراعية تنتج محصولًا كل ستة شهور، ولكن في وسط الستة شهور يكونون في احتياج لبعض المصاريف، فهل أعطيهم زكاة من مالي، أم أعطيهم جزءاً منه، وأوزع الباقي على بعض الأقارب، والمحتاجين؟","title":"حكم إخراج الزكاة للوالد والأخ","answer":"الجواب: أما أبوك لا، لا تعطيه، تعطيه من مالك، لا تعطيه الزكاة، عليك أن تعطيه من مالك، تنفق عليه من مالك إذا كان محتاجًا، لا من الزكاة، وأما أخوك فيه تفصيل: إن كان في بيتك، وتنفق عليه؛ فلا تعطه من الزكاة، أما إن كان مستقلًا، وهو محتاج فقير؛ تعطيه من الزكاة. أما الأب والجد والأم والجدة والأولاد فإنك لا تعطيهم من زكاتك؛ لأنهم أنت وإياهم شيء واحد، الزكاة لغيرهم، ولو غضبا، توضح لهما، تبين لهما أن هذا أمر الله، وهذه عبادة لله -عز وجل- فتستسمحهما حتى يسمحا، ويأذنا في إعطاء الزكاة لغيرهما. فالمقصود: أن والديك تنفق عليهما من مالك، والزكاة لغيرهما، أما الأخ ففيه تفصيل: إذا كان في بيتك، وفي نفقتك؛ لا بأس، تنفق عليه من مالك، ولا تعطيه زكاة؛ لأنك قد كفيته المؤنة، فالواجب أن تعطيه من مالك؛ لأنه من تبع عيالك، أما إذا كان مستقلًا، وفقيرًا؛ فلا بأس أن تعطيه من الزكاة. نعم.","link":"https://binbaz.org.sa/fatwas/11549/حكم-اخراج-الزكاة-للوالد-والاخ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_514/51405.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":13401,"question":"هذا السائل أبو مازن من الإمارات العربية المتحدة له سؤالان: السؤال الأول يقول: بأنه شاب مقتدر، وله عقارات كثيرة وغيرها، هل يجوز أن يعطي من زكاة ماله لوالده ووالدته؟","title":"حكم إعطاء الزكاة للوالدين","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد.  فليس للرجل ولا للمرأة دفع الزكاة إلى والديهم، وإلى أولادهم، وإنما تدفع للأقارب الآخرين إذا كانوا فقراء، وليسوا في حوزته، وليسوا في نفقته تكون صدقة وصلة، أما دفعها لوالديه، أو أولاده، أو أولاد بناته؛ فليس له ذلك، بل يجب عليه أن ينفق عليهم من ماله إذا احتاجوا له، وأما إعطاؤهم من الزكاة فلا، لكن إذا كان له أخ فقير، أو عم، أو خال فقير، وليس في بيته من ينفق عليهم؛ فلا بأس أن يعطيهم من زكاته. نعم.","link":"https://binbaz.org.sa/fatwas/11690/حكم-اعطاء-الزكاة-للوالدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_526/52601.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":13423,"question":"هذا سائل للبرنامج (عبدالرحمن أ. أ) يقول: هل تعتبر كفالة الأيتام من مصارف الزكاة سماحة الشيخ؟","title":"هل اليتيم من مصارف الزكاة؟","answer":"الجواب: إذا كان اليتيم فقيرًا هو من مصارف الزكاة، داخلة في الفقراء والمساكين، إذا كان فقيرًا ما خلف له والده ما يقوم بحاله، ولا عنده من ينفق عليه من أقاربه يعطى، أما إذا كان له مال اليتيم ينفق عليه منه، ما يعطى من الزكاة.","link":"https://binbaz.org.sa/fatwas/11717/هل-اليتيم-من-مصارف-الزكاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_527/52703.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":13435,"question":"كيف يؤدي المرء زكاة ماله إذا كان راتبه مثلًا سبعمائة ريال شهريًا؟","title":"كيف تُخرج زكاة الراتب؟","answer":"الجواب: إذا كان هذا الراتب يصرف لحاجاته، ولا يبقى عنده شيء؛ ما عليه زكاة، أما إذا كان يحفظه؛ لأنه في بيت ينفق عليه كأبيه، أو غيره، ويحفظ هذه الرواتب؛ فإنه يزكيها كلما حال الحول، فإذا حال الحول على راتب رمضان؛ زكاه في رمضان المقابل، وإذا حال الحول على راتب شوال؛ زكاه في شوال، وإذا حال الحول على راتبه في ذي القعدة؛ زكاه في ذي القعدة، وهكذا، كل راتب يزكى في الحول الذي يقابل حوله، يعني: عند تمام السنة، فإن زكى المتأخر مع المتقدم، وعجل زكاة المتأخر مع المتقدم؛ كان له فضل في ذلك، ولا بأس. مثلًا أخرج زكاة شوال مع زكاة رمضان، أو أخرج زكاة ذي القعدة وشوال مع زكاة رمضان عجلها، هذا طيب، ومجزئ، ولا بأس، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11731/كيف-تخرج-زكاة-الراتب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_477/47714.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":13532,"question":"السائلة أم عثمان من اليمن تقول في هذا  سماحة الشيخ! إذا تعارضت أقوال الأئمة في مسألة ما، كاختلاف الأئمة مثلًا في زكاة الحلي، فالبعض يوجب زكاة الحلي مطلقًا، الملبوس والمكنوز والمستعمل وغير ذلك، والبعض يوجب زكاة الحلي المكنوز فقط دون المستعمل، فبأيهما نأخذ يا سماحة الشيخ، بالأحوط أم بالأيسر، أو يكون لنا الخيار؛ لأن البعض يقول: يجب أن نأخذ بالأحوط اتقاء الشبهة، والبعض من الناس يقول: نأخذ بالأيسر؛ لأن الله يريد بنا اليسر، ولا يريد منا العسر. وجهونا في ضوء هذا السؤال الذي اختلف على كثير من الناس سماحة الشيخ عبدالعزيز .","title":"هل يؤخذ في زكاة الحلي بالأحوط أم الأيسر؟","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فهذه المسألة وأشباهها من مسائل الخلاف بين العلماء، الواجب عرضها على الكتاب والسنة، والحكم فيها بالدليل؛ لقول الله -جل وعلا-: وَمَا اخْتَلَفْتُمْ فِيهِ مِنْ شَيْءٍ فَحُكْمُهُ إِلَى اللَّهِ[الشورى:10] ولقوله : فَإِنْ تَنَازَعْتُمْ فِي شَيْءٍ فَرُدُّوهُ إِلَى اللَّهِ وَالرَّسُولِ إِنْ كُنتُمْ تُؤْمِنُونَ بِاللَّهِ وَالْيَوْمِ الآخِرِ ذَلِكَ خَيْرٌ وَأَحْسَنُ تَأْوِيلًا [النساء:59]. فالواجب على أهل العلم أن يردوا مسائل النزاع إلى الأدلة الشرعية، وإذا كان المكلف قد خفي عليه الأمر، ولم تتضح له الأدلة؛ فإنه يأخذ بالأحوط، والأبعد عن الشبهة؛ لقوله ﷺ: دع ما يريبك إلى ما لا يريبك .. من اتقى الشبهات؛ فقد استبرأ لدينه وعرضه. العامي وهو من تشتبه عليه الأدلة يأخذ بالأحوط، وهو ترك المشتبه، والاستبراء لدينه؛ لهذين الحديثين: دع ما يريبك إلى ما لا يريبك والحديث الثاني: من اتقى الشبهات؛ فقد استبرأ لدينه وعرضه. وهذه المسألة -مسألة الحلي- الصواب فيها: أن فيها الزكاة؛ لأنه جاء فيها نص يدل على وجوب الزكاة في الحلي من الذهب والفضة، سواء كانت تستعمل، أم لا تستعمل، الحكم واحد؛ لأنه ﷺ قال لامرأة عليها بعض الحلي: أتؤدين زكاة هذا؟ قالت: لا، قال: أيسرك أن يسورك الله بهما يوم القيامة سوارين من نار؟ فألقتهما وقالت: هما لله ولرسوله، فأخبر أنها إذا لم تزك؛ فهي معرضة للنار. وقالت أم سلمة وعليها أوضاح من ذهب: يا رسول الله! أكنز هذا؟ قال ﷺ: ما أديت زكاته فليس بكنز فدل على أن الحلي كنز إذا لم تؤد زكاته، وهذا إشارة إلى قوله -جل وعلا-: يا أَيُّهَا الَّذِينَ آمَنُوا إِنَّ كَثِيرًا مِنَ الأَحْبَارِ وَالرُّهْبَانِ لَيَأْكُلُونَ أَمْوَالَ النَّاسِ بِالْبَاطِلِ وَيَصُدُّونَ عَنْ سَبِيلِ اللَّهِ وَالَّذِينَ يَكْنِزُونَ الذَّهَبَ وَالْفِضَّةَ وَلا يُنفِقُونَهَا فِي سَبِيلِ اللَّهِ فَبَشِّرْهُمْ بِعَذَابٍ أَلِيمٍ [التوبة:34]. الحديث يدل على أنها كنز لا بد أن تؤدى زكاته، فالحلي التي تبلغ النصاب من الذهب والفضة إذا لم تؤد زكاته؛ فهو كنز، هذا هو الأرجح من قولي العلماء في هذه المسألة أن الحلي من الذهب والفضة، سواء كان أسورة، أو كانت قلائد، أو غير ذلك إذا بلغ النصاب إحدى عشر جنيهًا، ونص من الذهب؛ هذا فيه الزكاة، وهو عشرون مثقالًا، أو من الفضة بلغ مائة وأربعين مثقالًا، ستة وخمسين ريالًا فضة، يعني: فضة غير العملة الورقية، إذا بلغ قيمة ستة وخمسين من الفضة، هذا نصاب من الفضة. والحاصل: أنه إذا بلغ الذهب والفضة نصابًا؛ وجب فيه الزكاة وإن كان حليًا تلبس، هذا هو الأرجح من قولي العلماء. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11848/هل-يوخذ-في-زكاة-الحلي-بالاحوط-ام-الايسر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_532/53201.mp3","categories":["زكاة النقدين","أصول الفقه"]},{"id":13638,"question":"من أسئلة هذا السائل يقول: ما حكم المال المؤخر، والغير مقبوض من المهر؟","title":"حكم المال المؤخر وغير المقبوض من المهر","answer":"الجواب: هذا حكمه حكم الديون، إن كان على موسر على زوج موسر متى طلبته أعطاها إياه عليها زكاته، فإن كان على معسر، أو ليس لها حق فيه إلا بعد حضور الأجل يعني: بينها وبينه أجل إلى الطلاق، أو إلى الموت؛ فإنها غير قادرة، فليس عليها زكاته كالدين الذي على معسر. أما الدين المؤجل في التجارة والبيع والشراء فهذا يزكى إذا كان على موسر، أما الدين الذي بين المرأة والرجل إذا كان لها دين عليه، وهو معسر؛ فليس عليها زكاة، أو مماطلًا ما أعطاها الدين؛ ليس عليها زكاة، أما إذا كان موسرًا، وليس بمماطل؛ فعليها زكاة الدين الذي لها على زوجها.  والخلاصة: أن الدين إذا كان على معسر، أو إنسان مماطل؛ فلا زكاة على صاحبه، أما إن كان الذي عليه الدين موسرًا، ومتى طلب؛ أدى -سلم- فإن على صاحب الدين أن يزكي هذا الدين كأنه عنده. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11970/حكم-المال-الموخر-وغير-المقبوض-من-المهر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_528/52813.mp3","categories":["الصداق","زكاة النقدين","قضايا المرأة"]},{"id":13720,"question":"الذهب إذا لم يبلغ نصابًا، بل ادخرته للاحتياج فقط، فهل عليه زكاة؟","title":"حكم الزكاة في الذهب المدخر إذا لم يبلغ النصاب","answer":"الجواب: إذا كان ما يبلغ النصاب، ليس فيه زكاة، أما إن كان يبلغ النصاب بنفسه، أو بإضافة حلي عندها، أو فضة فإنه يزكى، أما إذا كان ما عندها شيء إلا هو، هو ينقص عن النصاب أقل من إحدى عشر جنيهًا ونصف؛ فهذا لا زكاة فيه، إذا حفظته لحاجتها ما فيه زكاة؛ حتى يبلغ النصاب بنفسه، أو بضمه إلى نقود أخرى، أو عروض تجارة أعدتها للبيع. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12091/حكم-الزكاة-في-الذهب-المدخر-اذا-لم-يبلغ-النصاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_481/48110.mp3","categories":["زكاة النقدين","قضايا المرأة"]},{"id":13739,"question":"تقول السائلة من دمشق: هل في صداق المرأة زكاة؟ وإن كانت لم تقبضه، ولكن زوجها قادر على إيفائه، فوجهونا في ضوء هذا السؤال؟","title":"هل في الصداق الذي لم يقبض زكاة؟","answer":"الجواب: نعم، فيه الزكاة إذا كانت تستطيع أن تقبضه، وهو عند مليء؛ فعليها الزكاة، أما إن كان عند معسر، أو ماطلها، ومنعها؛ فليس عليها زكاة، أما إذا كان موسرًا، وتستطيع أن تقبضه منه؛ فهذا عليها الزكاة، تزكي كل سنة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12125/هل-في-الصداق-الذي-لم-يقبض-زكاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_535/53518.mp3","categories":["الصداق","زكاة النقدين","قضايا المرأة"]},{"id":13744,"question":"تقول السائلة من دمشق: هل في صداق المرأة زكاة؟ وإن كانت لم تقبضه، ولكن زوجها قادر على إيفائه، فوجهونا في ضوء هذا السؤال؟","title":"هل في الصداق الذي لم يقبض زكاة؟","answer":"الجواب: نعم، فيه الزكاة إذا كانت تستطيع أن تقبضه، وهو عند مليء؛ فعليها الزكاة، أما إن كان عند معسر، أو ماطلها، ومنعها؛ فليس عليها زكاة، أما إذا كان موسرًا، وتستطيع أن تقبضه منه؛ فهذا عليها الزكاة، تزكي كل سنة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12125/هل-في-الصداق-الذي-لم-يقبض-زكاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_535/53518.mp3","categories":["الصداق","زكاة النقدين","قضايا المرأة"]},{"id":13778,"question":"نرجو الإفادة عن زكاة المال، وإذا أمكن إيراد ذلك بالجنيه المصري؟","title":"نصاب زكاة المال","answer":"الجواب: زكاة المال ربع العشر في الذهب والفضة وما يقوم مقامهما من العمل، الواجب في النقدين -الذهب والفضة- ربع العشر، والنصاب في الفضة مائة وأربعون مثقالًا، وفي الذهب عشرون مثقالًا وما يقوم مقام هذه المثاقيل، هذا أقل نصاب، والواجب على من عنده مال يبلغ النصاب إخراج ربع العشر سواء كان جنيه مصري أو إسترليني أو دولار أو عملة سعودية أو غير ذلك الواجب ربع العشر؛ في المائة اثنان ونص.. في المائتين خمسة.. في الألف خمسة وعشرون، هذه الزكاة الواجبة.. وهكذا كلما زاد زادت الزكاة وهي ربع العشر، يعني: سهم من أربعين. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12145/نصاب-زكاة-المال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_601/60105.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":13816,"question":"السائل حازم من الأردن يقول في هذا  هل يجب إخراج الزكاة عن السيارة التي تحت تصرفي، وكيف يكون ذلك؟","title":"حكم إخراج الزكاة عن السيارة","answer":"الجواب:  إذا كانت السيارة للبيع تخرج الزكاة، إذا كانت للبيع والتصرف والفائدة، أما إذا كانت لا، للاستعمال ما فيها زكاة، تستعملها في حاجاتك ما فيها زكاة، أما إذا تشتري السيارات تطلب الفائدة فهذه فيها الزكاة، اعتبارًا بأصل الدراهم التي عندك، إذا كانت الدراهم عندك مثلًا من محرم واشتريت السيارات في صفر أو في ربيع إذا جاء دور الدراهم محرم تزكي السيارات، بعد تعرف قيمتها.\nالمقصود: أن السيارات التي تشترى للبيع والشراء والفائدة تزكى، أما إذا كان شراؤها للاستعمال فليس فيها زكاة. نعم.\nالمقدم: شكر الله لكم سماحة الشيخ، وبارك الله فيكم وفي علمكم، ونفع بكم المسلمين.","link":"https://binbaz.org.sa/fatwas/12181/حكم-اخراج-الزكاة-عن-السيارة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_536/53625.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":13827,"question":"في آخر أسئلة السائل من اليمن يقول في هذا  أرجو من سماحة الشيخ أن يحدثنا عن حلي النساء، وهل فيه زكاة أم لا؛ لأننا نسمع البعض يقول: بأن عليه زكاة، وهل إذا كان معد للزينة فهل تزكي عليه المرأة؟ وإذا كانت تزكي عليه فما هو المقدار الذي يزكى عليه؟ وإذا لم يكن لديها مال فهل يزكي عنها الزوج، أو الأب، أو الأخ؟ وهل يجوز أن تبيع منه وتزكي عنه؟","title":"حكم زكاة الحلي والبيع منه لأجل الزكاة","answer":"الجواب: الزكاة في الحلي مسألة خلاف بين العلماء، والأرجح والأصح فيما يظهر لي من دلالة الأدلة الشرعية وجوب الزكاة في الحلي من الذهب والفضة، وهو الذي أفتي به من دهر طويل ولم أفت بغيره، وهو وجوب الزكاة في الحلي إذا بلغ الذهب نصابًا أو الفضة، والنصاب عشرون مثقالًا من الذهب، ومائة وأربعون مثقالًا من الفضة، ومقدار ذلك أحد عشر جنيهًا وثلاثة أسباع جنيه من الجنيه السعودي، ومن الفضة ستة وخمسون ريالًا من الفضة أو ما يقوم مقامها من العُمَل الورقية، وإذا كانت الزوجة لا تستطيع الزكاة؛ لعدم وجود مال عندها تبيع منه وتزكي، وإن زكى عنها زوجها بإذنها كفى والحمد لله، إذا زكى عنها زوجها أو أبوها أو ولدها بإذنها كفى وإلا فعليها أن تزكي إما باقتراض من غيرها، أو ببيع شيء منه وتزكي. نعم.\nالمقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/12194/حكم-زكاة-الحلي-والبيع-منه-لاجل-الزكاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_537/53708.mp3","categories":["الصداق","زكاة النقدين","قضايا المرأة"]},{"id":13952,"question":"تقول أختنا: أنا فتاة مؤمنة ولله الحمد لي أخ متزوج ووالده هو الذي يصرف عليه؛ لأن أخي هذا لا يزال يدرس في الثانوية والمصروف الذي يعطيه والده قد لا يكفيه، فهل يجوز لي أن أدفع له الزكاة؟","title":"هل يجوز دفع الزكاة للأخ؟","answer":"الجواب: ليس لك أن تدفعي له الزكاة بل عليه أن يطالب أباه بحاجته أو يقتصد؛ لأن هذا قد يفضي إلى تساهل أو إسراف، فينبغي في مثل هذا إرشاده إلى الاقتصاد أو سؤال أبيه باللطف والكلام الطيب الزيادة التي يحتاجها، أما أنت فادفعي الزكاة إلى من تعرفي أنه محتاج وفقير ولا تتساهلي فيها، والولد في إمكانه أن يتصل بأبيه ويطلب منه الزيادة أو يقتصد في النفقة. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12362/هل-يجوز-دفع-الزكاة-للاخ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_604/60410.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":13965,"question":"الأخت المستمعة أم أحمد من المنطقة الشمالية رفحا بعثت برسالة وعرضنا جزءًا من أسئلتها في حلقة مضت: أملك بعض الحلي من الذهب أكثر من النصاب، ولكني لا أستعمله كله، حيث أحتفظ ببعضه كي ينفع أولادي البنين عند زواجهم، حيث أنهم ما زالوا في مرحلة التعليم، والنقود سرعان ما نتصرف فيها بعكس الذهب، وسؤالي: هل أدفع زكاة الذهب الذي لا أستعمله فقط حتى وإن كان أقل من النصاب، أم يجب علي دفع زكاة جميع ما عندي من ذهب؟","title":"حكم الزكاة في الذهب المدخر والمستعمل","answer":"الجواب: الصواب: أن عليك زكاة الجميع، وقد ذهب بعض أهل العلم إلى أن الحلي المستعملة لا زكاة فيها، ولكنه قوله مرجوح، والصواب الذي عليه الأدلة الشرعية: أن الحلي تزكى، سواء كانت مدخرة أو مستعملة أو معارة، الواجب أداء الزكاة فيها إذا بلغت النصاب، والنصاب عشرون مثقالًا من الذهب، ومقداره بالجنيه السعودي: إحدى عشر جنيهًا وثلاثة أسباع جنيه، يعني: إحدى عشر جنيهًا ونص، فإذا بلغت الحلي هذا المقدار؛ وجبت الزكاة فيها، ربع العشر كل سنة، فإذا كانت ..... تبلغ عشرة آلاف مثلاً، إذا كانت الحلي تبلغ عشرة آلاف؛ ففيها مائتان وخمسون، ربع العشر، ربع الألف العاشر مائتان وخمسون، وهكذا، وهي بالغرام قريب من اثنين وتسعين غرامًا، يعني: إحدى وتسعون غرامًا وكسور، فإذا زكت ما بلغ هذا المقدار، اثنين وتسعين غرامًا تقريبًا، وهو إحدى عشر جنيهًا ونص سعودي، فإذا زكت هذا المقدار فهو الواجب عليها، وهكذا ما زاد عليه.\nأما إذا كان أقل من ذلك، فليس فيه شيء؛ لأن النصاب شرط في وجوب الزكاة، وقد ثبت عنه ﷺ أنه قال: ما من صاحب ذهب ولا فضة لا يؤدي حقها؛ إلا إذا كان يوم القيامة صفحت له صفائح من نار، فيكوى بها جنبه وجبينه وظهره، في يوم كان مقداره خمسين ألف سنة، ثم يرى سبيله إما إلى الجنة، وإما إلى النار.. الحديث، متفق على صحته.\nوجاءته ﷺ امرأة ومعها ابنتها وفي يدها سواران من ذهب قال: أتعطين زكاة هذا؟ قالت: لا. قال: أيسرك أن يسورك الله بهما يوم القيامة سوارين من نار؛ فألقتهما وقالت: هما لله ولرسوله. وسألته أم سلمة رضي الله عنها، وكانت تلبس أوضاحًا من ذهب فقالت: يا رسول الله! أكنز هذا؟ فقال عليه الصلاة والسلام: ما بلغ أن يزكى فزكي؛ فليس بكنز، فدل ذلك على أن ما لا يزكى يعتبر كنز، يستحق صاحبه العقوبة، فالحلي التي لا تزكى من الكنوز، كالجنيهات المحفوظة، وقطع الذهب المحفوظة إذا بلغ النصاب يسمى كنزًا، وإن كان على وجه الأرض، وإن كان في المخازن الظاهرية في الصناديق، كل شيء لا تؤدى زكاته -وهو من أموال الزكاة- يعتبر كنزًا؛ يعذب به صاحبه يوم القيامة. نسأل الله العافية.\nفعليكِ أيها الأخت في الله! أن تؤدي الزكاة عن الملبوس والمحفوظ جميعًا، إذا بلغ الجميع النصاب، وفقك الله ويسر أمرك. نعم.\nالمقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12380/حكم-الزكاة-في-الذهب-المدخر-والمستعمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_605/60504.mp3","categories":["الصداق","زكاة النقدين","قضايا المرأة"]},{"id":13981,"question":"يسأل أخونا ويقول: هل تجب الزكاة على الذهب الخاص بالزوجة والبنات، والمشترى بقصد استعماله للزينة، أم لا تجب في ذلك زكاة؟","title":"هل تجب الزكاة في الذهب المشترى للزينة؟","answer":"الجواب: هذه مسألة اختلف فيها العلماء رحمة الله عليهم، منهم من أوجب فيها الزكاة؛ لعموم الأدلة، ولأدلة خاصة، ومنهم من قال: إنها لا تجب؛ لأنها مستعملة.\nوالصواب أنها تجب الزكاة في الحلي إذا بلغ النصاب ولو أنه مستعمل؛ لعموم قوله ﷺ: ما من صاحب ذهب ولا فضة لا يؤدي زكاتها إلا إذا كان يوم القيامة صفحت له صفائح من نار؛ فيكوى بها جنبه وجبينه وظهره.. الحديث.\nولما ثبت عنه ﷺ: أنه جاءته امرأة وفي يد ابنتها مسكتان من ذهب -يعني: سوارين من ذهب- فقال: أتعطين زكاة هذا؟ قالت: لا. قال: أيسرك أن يسورك الله بهما يوم القيامة سوارين من نار، فألقتهما، وقالت: هما لله ولرسوله.\nفالمقصود أن الحلي داخلة في عموم الأدلة الدالة على وجوب الزكاة في الذهب والفضة، ومن هذا ما في حديث أم سلمة أنها قالت: يا رسول الله! -كانت تلبس أوضاحًا من ذهب، فقالت: يا رسول الله! أكنز هذا؟ فقال عليه الصلاة والسلام: ما بلغ أن يزكى فزكي فليس بكنز، ولم يقل لها: ليس في الحلي زكاة.\nأما حديث: «ليس في الحلي زكاة»، فهو حديث لا يصح عن النبي عليه الصلاة والسلام.\nوالخلاصة: أن الصحيح من قولي العلماء: أن في الحلي زكاة -في الذهب والفضة- إذا بلغت النصاب، والنصاب عشرون مثقالًا، ومقدار ذلك بالجنيه السعودي: أحد عشر جنيهًا وثلاثة أسباع جنيه، يعني: أحد عشر جنيهًا ونص؛ لأن الفرق يسير، ومن الفضة: مائة وأربعون مثقالًا، ومقدار ذلك بالفضة بالريال السعودي: ستة وخمسون ريالًا من الفضة، وما يعادلها من العمل.  فإذا بلغت الحلي هذا المقدار؛ وجب على صاحبتها الزكاة إذا حال عليها الحول، والواجب ربع العشر، فإذا كانت الحلي تبلغ عشرة آلاف؛ ففيها مائتان وخمسون، ربع العشر، وإذا كانت تبلغ عشرين ألفًا؛ ففيها خمسمائة ربع العشر، وهكذا، وذلك يزيدها خيرًا ويبرئ ذمتها. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12396/هل-تجب-الزكاة-في-الذهب-المشترى-للزينة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_606/60602.mp3","categories":["الصداق","زكاة النقدين","قضايا المرأة"]},{"id":13997,"question":"يسأل ويقول: ما قيمة العشرين مثقالًا من الذهب بالغرامات، فقد سمعنا في ذلك أربعة أقوال، منها ما يقول: بأن مقدار العشرين مثقالًا من الذهب يساوي ثمانين غرامًا، وقول يقول: خمسة وثمانين، وآخر: اثنين وتسعين، ورابع ستة وتسعين، فأيها الصحيح؟ وما مقدار درهم الفضة بالغرامات؟","title":"مقدار نصاب الذهب والفضة بالغرامات","answer":"الجواب: الأقرب اثنان وتسعون غرام هذا هو نصاب الذهب، وهو عشرون مثقالًا وقيمتها بالغرام اثنان وتسعون غرامًا، هذا هو الذي حررناه مع أهل الخبرة وعليه الفتوى، اثنان وتسعون غراماً هي مقدار عشرين مثقال، نصاب الذهب، وبالجنيه إحدى عشر جنيه وثلاثة أسباع جنيه، يعني: نصف جنيه، لأن الكسر اليسير لا يضر، إحدى عشر جنيه ونصف الجنيه، إحدى عشر جنيه ونصف الجنيه هذا عشرون مثقالًا وهو نصاب الذهب، سواء كان الذهب حليًا أو غير حلي، تجب فيه الزكاة على الراجح وإن كان حليًا.\nأما الدرهم الفضة فهو نصف مثقال خمس مثقال، ولهذا نصاب الفضة مائة وأربعون مثقالًا، مائة وأربعون مثقالا، وإذا ضربت مائة وأربعون مثقالًا على مقدار العشرين مثقال اثنين وتسعين، فإنها تكون إذا كل عشرين مثقال اثنان وتسعون، يعني: تسعون تضرب في سبعة، يحصل بذلك سبعمائة غرام، ينزل منها ستة وخمسون، يكون الجميع ستمائة غرام وأربعة وأربعون غرامًا، هذا نصاب الفضة؛ ستمائة غرام وأربعة وأربعون غرامًا. نعم، من ضرب سبعةٍ في، نضرب اثنين وتسعين في سبعة. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12410/مقدار-نصاب-الذهب-والفضة-بالغرامات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_483/48304.mp3","categories":["زكاة النقدين"]},{"id":14002,"question":"هل تزكى حلي المرأة كل عام؟ أم يكفي تزكيتها مرةً واحدة في العمر؟","title":"حكم زكاة الحلي في كل عام","answer":"الجواب: كل عام، الواجب كل عام، مثل بقية الذهب، كل عام تزكى، مثل بقية الذهب والفضة إذا كان غير حلي، هذا هو الصواب. نعم، إذا كان يبلغ النصاب.\nالمقدم: لسؤاله تكملة يقول فيها: مع العلم أنها لو زكيت كل عام، لكان معنى ذلك أن المرأة تدفع ثمنًا آخر لحليها، وقيمة الحلي ثابتة لا تنمو؟\nالشيخ: نعم عليها أن تدفع الزكاة ولو ما نمت، مثل الذي عنده ذهب في الصندوق، يزكيه ولو أنه في الصندوق، كل سنة يزكيه ولو ما نما، عليه الزكاة من يمنعه من التنمية، فالحلي الذي يبلغ النصاب عليها أن تزكيه، مواساة للفقراء والمحاويج، وإذا نقص عن النصاب ما فيه زكاة، أما مادام يبلغ النصاب عشرين مثقالًا اثنين وتسعين غرامًا فإنها تزكيه ربع العشر، في كل ألف خمسة وعشرون، في المائة اثنين ونص، هذا ظاهر الأحاديث الصحيحة عن رسول الله ﷺ، بعض أهل العلم يرى أنه لا زكاة في الحلي لأنها مستعملة، ولكن الصواب: أن فيها الزكاة لعموم الأدلة، لقوله ﷺ: ما من صاحب ذهب ولا فضة لا يؤدي زكاتها، إذا كان يوم القيامة صفحت له صفائح من نار. الحديث، ولم يستثن الحلي، ولقوله ﷺ لما رأى امرأةً عليها أسورة: أتعطين زكاة هذا؟ قالت: لا، قال: أيسرك أن يسورك الله بهما يوم القيامة سوارين من نار، فألقتهما، قالت: هما لله ولرسوله. ولم يقل لها: ما عليها زكاة، بل أمرها بالزكاة، وهي حلي في أيديها، هكذا أم سلمة رضي الله عنها، كان عليها أوضاحًا من ذهب، فقالت: يا رسول الله! أكنز هذا؟ قال: ما بلغ أن يزكى فزكي فليس بكنز . قال: (فزكي) ولم يقل: أن الحلي ليست من الكنز، ولم يقل لها: .. لا زكاة فيها. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12416/حكم-زكاة-الحلي-في-كل-عام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_483/48306.mp3","categories":["الصداق","زكاة النقدين","قضايا المرأة"]},{"id":14057,"question":"شيخ عبد العزيز ! كثير من إخواننا المستمعين لهذا البرنامج يتمنون أن لا يكون هناك خلاف في الفتاوى بين العلماء، فأختنا أيضًا في رسالتها تقول: إنني سمعت في البرنامج أنه ليس هنالك زكاة على الحلي المعد للزينة، وقال المفتي في تلكم الحلقة: إن هذا معمول به في المملكة، وهنالك كتاب يتحدث عن زكاة الحلي، مستدلًا بأحاديث وآثار صحيحة، وأقوال علماء من الحاضرين، وسؤالي مرة أخرى: هل للحلي المعد للزينة زكاة، وما رأيكم في الكتاب الذي يتحدث عن زكاة الحلي؟ جزاكم الله خيرًا.","title":"أسباب اختلاف العلماء في الفتوى وحكم زكاة الحلي","answer":"الجواب: الاختلاف لا بد منه في بعض المسائل الفرعية، ولا تمكن السلامة من ذلك، فقد كان موجودًا في عهد الصحابة  ومن بعدهم، بسبب اختلاف الفهم، وبسبب خفاء الأدلة على بعض أهل العلم، فلهذا يقع بعض الخلاف؛ فإن بعض أهل العلم قد يبلغه الحديث عن رسول الله ﷺ وقد لا يبلغ الآخر، وكذلك قد يفهم من الآية ومن الحديث فهمًا لم يفهمه الآخر في بعض المسائل، فلهذا تقع الخلافات بين أهل العلم في بعض المسائل الفرعية.\nأما العقائد والأمور الأصولية؛ فالحمد لله ليس فيها خلاف بين أهل العلم، وإنما تقع الخلافات في مسائل فرعية قد يخفى فيها الدليل على بعض أهل العلم، وقد يختلف فيها الفهم، فعلى طالب العلم وعلى السائل وعلى المستفيد أن يتحرى، ويجتهد في الاستيضاح من أهل العلم؛ حتى يطمئن قلبه إلى ما وقع فيه الخلاف، وحتى يعرف الصواب، ومن ذلك: مسألة الخضاب بالسواد -كما تقدم في السؤال السابق-.\nومن ذلك: مسألة الحلي هل فيها زكاة أم لا؟ فإن جماعة من أهل العلم قالوا: ليس فيها زكاة؛ لأنها تستعمل، فأشبهت الإبل التي تستعمل والبقر التي تستعمل وليست سائمة؛ فلا زكاة فيها، وقال آخرون: بل فيها الزكاة؛ لأنها داخلة في عموم الذهب والفضة، الذين أوجب الله فيهما الزكاة؛ ولأنه ليس هناك دليل يخص الحلي باستثنائها من وجوب الزكاة، ولأنه قد ورد في أحاديث تدل على أن الحلي فيها الزكاة، مثلما رواه أبو داود والنسائي بإسناد صحيح عن عبد الله بن عمرو بن العاص رضي الله تعالى عنهما: أن امرأة أتت النبي ﷺ وفي يد ابنتها سواران ضخمان من الذهب، -وفي رواية: مسكتان غليظتان من الذهب- فقال: أتعطين زكاة هذا؟ قالت: لا. قال عليه الصلاة والسلام: أيسرك أن يسورك الله بهما يوم القيامة سوارين من نار؟؛ فألقتهما، قالت: هما لله ولرسوله.\nوثبت من حديث أم سلمة رضي الله عنها أنها كانت تلبس أوضاحًا من ذهب، فقالت: يا رسول الله! أكنز هذا؟ فقال عليه الصلاة والسلام: ما بلغ أن يزكى فزكي؛ فليس بكنز، ولم يقل: ليس عليك فيه زكاة، ولم يقل: ليس في الحلي زكاة؛ فدل ذلك على أن الواجب أداء الزكاة عن الحلي إذا بلغت النصاب، وقد كتبنا في هذا رسالة أوضحنا فيها الأدلة، وكتب بعض أهل العلم في ذلك أيضًا.\nفالمقصود: أن الصواب هو القول بأن الزكاة واجبة في الحلي من الذهب والفضة، إذا بلغت النصاب -وهو عشرون مثقالاً- ومقداره أحد عشر جنيهًا وثلاثة أسباع جنيه من الجنيه السعودي، أحد عشر جنيه وثلاثة أسباع، يعني: نص، أحد عشر جنيه ونص؛ لأن الكسر يسير بين الثلاثة الأسباع والنصف، فالمقصود: أنه إذا بلغ إحدى عشر جنيه ونصفًا؛ فإن الحلي فيه الزكاة، وهو يقارب اثنين وتسعين غرام، فإذا كانت الحلي أقل من ذلك؛ فلا زكاة فيها والحمد لله.\nوالمؤمن يذهب إلى ما هو أحوط لدينه، وأقرب إلى سلامته في كل شيء، إلا إذا وضح الدليل في أن هذا الشيء ليس فيه شيء فالحمد لله، ومادام أن هناك شبهة وهناك خلافًا، ولم يتضح للمؤمن ما يبرئ ذمته؛ فإنه يحتاط، ويأخذ بالفتوى التي فيها السلامة والحيطة، والخلوص من الواجب، والله ولي التوفيق. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12489/اسباب-اختلاف-العلماء-في-الفتوى-وحكم-زكاة-الحلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_608/60808.mp3","categories":["زكاة النقدين","أصول الفقه"]},{"id":14066,"question":"المستمع محمد شريف محمد من الخبر الجنوبية بعث برسالة ضمنها جمعًا من الأسئلة، في أحد أسئلته يقول: هل يجوز أن نعطي للعمال القادمين إلى المملكة زكاة أموالنا وزكاة أبداننا أم لا يجوز؟","title":"حكم دفع الزكاة لمن يعمل لدى المزكي","answer":"الجواب: إذا عرفت أنهم فقراء ومحتاجون وأن الرواتب التي لهم قليلة لا تقوم بحالهم وحال عوائلهم وهم مسلمون لا بأس أن تعطيهم من الزكاة، زكاة المال وزكاة الفطر، أما إن كنت لا تعرف أحوالهم، أو تشك هل رواتهم تكفيهم أو لا تكفيهم فلا تعطهم، أعط غيرهم ممن تعرف أنهم فقراء ولا تخاطر بمالك لا تخاطر بزكاتك، أما إذا عرفت أنهم فقراء وأنهم من أهل الصدق، وأنهم محتاجون رواتبهم لا تكفيهم لكثرة عوائلهم، وظهر له منهم الصدق والاستقامة وصلاح الأحوال فلا بأس إذا اطمأننت إليهم أن تعطيهم، نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12494/حكم-دفع-الزكاة-لمن-يعمل-لدى-المزكي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_484/48407.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":14074,"question":"المستمع عيسى أحمد عبد الكريم يذكر في رسالة بعث بها أن لديه مبلغ عشرة آلاف ريال سعودي، ويريد أن يخرج زكاتها، لكنه لا يعرف كيف يخرجها، وهل يجوز أن يبقيها حتى يرجع إلى بلده ويخرج زكاتها هناك؟ أم لا يجوز ذلك؟ وفقكم الله.","title":"مقدار الزكاة في المال وحكم تأخير إخراجها","answer":"الجواب: الواجب على المسلم البدار بإخراج الزكاة، إذا حال الحول يجب أن يبادر في أي محل كان، ويلتمس الفقراء والمحاويج، ويسأل عنهم أهل الثقة والأمانة في بلده الذي هو فيه، ثم يخرج الزكاة، سواء كان في اليمن أو في الشام أو في مصر أو في الجزيرة أو في أي مكان، الله أوجب عليه إخراج الزكاة. وإذا كان المال عشرة آلاف؛ فالزكاة مائتان وخمسون، ربع العشر؛ لأن الألف هو العشر وربعه مائتان وخمسون، فيلتمس بعض الفقراء، ويدفع إليه الزكاة، ويستعين في ذلك بأهل الثقة والأمانة من أصحابه وإخوانه؛ حتى يدلوه على الفقراء ويرشدوه إليهم، فإن لم يتيسر له الفقراء؛ أرسلها إلى من يعرفهم من الفقراء في بلاده، أو في بلاد أخرى، بواسطة الثقات الذين يؤدونها إلى الفقراء والمحاويج، ولا يتساهل ولا يؤجل، بل يبادر بإخراجها في وقتها. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12512/مقدار-الزكاة-في-المال-وحكم-تاخير-اخراجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_609/60908.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":14100,"question":"تقول أختنا: عندي ست حبات بناجر وقلادة ذهب، هل يجب عليها زكاة؟","title":"وجوب الزكاة فيما بلغ النصاب من الحلي","answer":"الجواب: نعم، الصواب فيها الزكاة إذا بلغت النصاب، ولو كانت تلبس أو تعار، الصواب فيها الزكاة إذا كانت تبلغ أحد عشر جنيهًا ونص، عشرين مثقالا، وذلك ما يقارب اثنين وتسعين غرامًا، فإذا كانت تبلغ هذا؛ ففيها الزكاة، وأما إن كانت أقل من هذا المقدار، يعني: أقل من أحد عشر جنيهًا ونص، أقل من تسعين غرامًا؛ فليس فيها زكاة. نعم.\nوالزكاة ربع العشر، الزكاة ربع العشر، في المائة اثنان ونص، في الألف خمسة وعشرون، في العشرة الآلاف مائتان وخمسون، وهكذا ربع العشر، يعني: سهم من أربعين. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12534/وجوب-الزكاة-فيما-بلغ-النصاب-من-الحلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_610/61007.mp3","categories":["الصداق","زكاة النقدين","قضايا المرأة"]},{"id":14147,"question":"السائلة التي رمزت لاسمها (مريم . أ. أ) تقول: بأنها إنسانة تبيع وتشتري في الذهب، وفي أحد الأيام باعت مجموعة من الحلي على الصائغ ثم اشترت منه حليًا وزاد على القيمة الأولى، فما الحكم يا سماحة الشيخ وما معنى الحديث: الذهب بالذهب مثلاً بمثل سواء بسواء وهل على الذهب زكاة بالتفصيل؟ جزاكم الله خيراً.","title":"حكم بيع الذهب بالذهب وحكم الزكاة فيه","answer":"الجواب: يجب عليها أن تأخذ قيمته ثم تشتري ذهبًا آخر حتى لا يكون وسيلة إلى بيع الذهب بالذهب أو بيع الفضة بالفضة، فإذا باعت عليه الذهب تقبض الثمن ثم تشتري ما شاءت منه، إن شرت ذهب يدًا بيد، إن شرت فضة بذهب يدًا بيد، إن شرت ذهبًا بذهب يكون متماثلًا، سواء بسواء وزنًا بوزن.\nالمقصود أنها إذا باعت عليه الذهب تقبض الثمن حتى لا يكون حيلة، تقبض الثمن ثم تشتري منه ما شاءت. نعم.\nالمقدم: تقول سماحة الشيخ: ما معنى: الذهب بالذهب مثلًا بمثل؟\nالشيخ: معناه أنه سواء بسواء، يعني: مثقال بمثقال، مثقالان بمثقالين، ثلاثة بثلاثة، جنيه بجنيه، جنيهين بجنيهين على السواء، وزنًا بوزن سواء بسواء يدًا بيد مثلما قال ﷺ: الذهب بالذهب مثلًا بمثل سواء بسواء وزنًا بوزن فليس لها الزيادة ولا غيرها، لابد أن يكونا متماثلين، وزنًا بوزن، سواء كان حلي أو نقود لابد وزنًا بوزن، والفضة كذلك، أما إذا اختلفا ذهب بفضة فلا حرج، يدًا بيد.\nالمقدم: والجواب يا سماحة الشيخ عبد العزيز في زكاة الذهب؟\nالشيخ: نعم؟\nالمقدم: هل تجب فيه الزكاة -الذهب-؟\nالشيخ: نعم، تجب زكاة الذهب والفضة، تجب الزكاة فيهما إذا حال عليهما الحول وبلغا النصاب، كانا نقودًا أو حليًا أو غير ذلك. نعم.","link":"https://binbaz.org.sa/fatwas/12588/حكم-بيع-الذهب-بالذهب-وحكم-الزكاة-فيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_546/54612.mp3","categories":["الربا والصرف","زكاة النقدين"]},{"id":14189,"question":"هذه السائلة (ن. ح) رمزت لاسمها بهذا الرمز تقول: أهدتني إحدى الأخوات أسورة ولم ألبسها إلا مرتين، وكذلك أعطتني المدرسة سبيكة ذهبية صغيرة فهل علي في هذا الذهب إخراج للزكاة، وكيف أقوم بإخراجه علمًا بأنني لم أشتريه بل أهدي إلي وهو عندي من حوالي أربع سنوات؟","title":"حكم الزكاة في الذهب المُهدى","answer":"الجواب: نعم، عليك الزكاة، إذا بلغت النصاب هذا الهدية أو عندك ما يكمل النصاب فعليك الزكاة كل سنة، من حين ملكتها لكن إذا كنت جاهلة سقطت الزكاة عنك في هذا الحلي حتى يتم الحول بعدما علمت ووجهت إلى الخير، وإن زكيت عما مضى فهو أحوط، أما الوجوب فلا يجب عليك إلا بعدما علمت؛ لأن زكاة الحلي فيها خلاف بين أهل العلم، وأنت لم تعلمي فليس عليك شيء حتى بلغك العلم.\nفالمقصود أنك تزكين هذه إذا حال عليها الحول وكانت تبلغ النصاب أو عندك ما يكمل النصاب. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12642/حكم-الزكاة-في-الذهب-المهدى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_547/54721.mp3","categories":["الصداق","زكاة النقدين","قضايا المرأة"]},{"id":14209,"question":"في ثاني أسئلته يقول: من هم الذين لا تجب لهم الزكاة أو الصدقة حتى ولو كانوا محتاجين؟","title":"بيان الذين لا يعطون من الزكاة","answer":"الجواب: أهل البيت لا يعطون الصدقة بنو هاشم رهط النبي ﷺ لا يعطون من الزكاة، وهكذا والداك وأولادك وزوجتك تنفق عليهم من مالك لا من الزكاة، إذا كانوا محتاجين تنفق عليهم من مالك على أبيك وأمك وجدك وجدتك وأولادك لا من الزكاة، الزكاة لغيرهم، للفقراء من أقاربك الآخرين، إخوتك الفقراء، بني عمك جيرانك، الفقراء الآخرين الأجناب من المسلمين تعطيهم من الزكاة، أما والداك أبوك وأمك وجدك وجدتك وأولادك هؤلاء تنفق عليهم من مالك لا من الزكاة، وهكذا كل غني لا يعطى من الزكاة وإنما يعطاها الفقراء، نعم، والكافر لا يعطاها إلا إذا كان مؤلفًا على الإسلام، يؤلف على الإسلام يعطى الزكاة تأليفًا له للدخول في الإسلام، أو لقوة إيمانه ويقينه. نعم.","link":"https://binbaz.org.sa/fatwas/12658/بيان-الذين-لا-يعطون-من-الزكاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_548/54810.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":14276,"question":"المستمع سودان فراج الحارثي بعث يسأل ويقول: يوجد عند زوجتي ذهب تقدر قيمته بأكثر من خمسين ألف ريال، هل تجب فيه الزكاة علمًا بأنها تلبسه دائمًا وهي تقصد منه الاستعمال للزينة فقط؟","title":"حكم زكاة الحلي ومقدار نصابها","answer":"الجواب: الواجب في الحلي الزكاة في أصح قولي العلماء ولو كانت تستعمل ذلك، الواجب عليها الزكاة هذا هو الصحيح وهي ربع العشر من الأربعين ألف ألف واحد، ومن عشرة آلاف مائتان وخمسون، يعني: ألف ومائتان وخمسون في الخمسين الألف ربع العشر.\nوالله جل وعلا أوجب على عباده الزكاة في الذهب والفضة وفي الإبل والبقر والغنم الراعية وفي عروض التجارة، فلا يجوز للمؤمن أن يتساهل في هذه الأمور، وهكذا أوجبها عليهم في الحبوب والثمار، وقد ثبت عنه ﷺ أنه قال: ما من صاحب ذهب ولا فضة لا يؤدي حقها وفي لفظ آخر: لا يؤدي زكاتها إلا إذا كان يوم القيامة صفحت له صفائح من نار فيكوى بها جنبه وجبينه وظهره في يوم كان مقداره خمسين ألف سنة حتى يقضى بين الناس ثم يرى سبيله إما إلى الجنة وإما إلى النار. وهذا وعيد عظيم يعم ذهب الحلي وفضة الحلي وغيرها، ولأنه ثبت عنه ﷺ أنه دخلت عليه امرأة في يد ابنتها مسكتان من ذهب -يعني: سوارين من ذهب- فقال: أتؤدين زكاة هذا؟ قالت: لا، قال: أيسرك أن يسورك الله بهما يوم القيامة سوارين من نار، فألقتهما وقالت: هما لله ولرسوله. رواه الإمام أبو داود والإمام النسائي رحمة الله عليهما في سننهما بإسناد صحيح.\nوثبت عن أم سلمة رضي الله عنها أنها كانت تلبس أوضاحًا من ذهب فقالت: يا رسول الله! أكنز هذا؟ فقال ﷺ:  ما بلغ أن يزكى فزكي فليس بكنز، ولم يقل لها: ليس في الحلي زكاة بل قال: ما بلغ أن يزكى يعني: ما بلغ النصاب فزكي فليس بكنز، أما ما لم يزك وقد بلغ النصاب فإنه كنز يعذب به صاحبه يوم القيامة، يشير إلى قوله جل وعلا: وَالَّذِينَ يَكْنِزُونَ الذَّهَبَ وَالْفِضَّةَ وَلا يُنفِقُونَهَا فِي سَبِيلِ اللَّهِ فَبَشِّرْهُمْ بِعَذَابٍ أَلِيمٍ [التوبة:34].\nفالحاصل: أن الحلي من الذهب والفضة التي تستعملها النساء فيها الزكاة إذا بلغت النصاب والنصاب عشرون مثقالًا ومقداره أحد عشر جنيه ونصف، ومقداره بالغرامات اثنان وتسعون غرامًا فإذا كان الذهب أقل من هذا فلا زكاة فيه. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12736/حكم-زكاة-الحلي-ومقدار-نصابها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_486/48611.mp3","categories":["الصداق","زكاة النقدين","قضايا المرأة"]},{"id":14282,"question":"رسالة من إحدى الأخوات المستمعات تقول: المرسلة ليلى مطر تسأل هي أيضًا عن وزن ومبلغ الحلي الذي تخرج زكاته؟","title":"نصاب زكاة الحلي","answer":"الجواب: تقدم بيان ذلك في الجواب السابق وأن الحلي التي فيها الزكاة هي التي تبلغ النصاب، إذا كانت الحلي تبلغ أحد عشر جنيهًا وثلاثة أسباع جنيه يعني: نصف جنيه، أحد عشر جنيه ونصف الجنيه هذه تخرج زكاتها، أما إذا كانت أقل فليس فيها زكاة، ومقدارها بالغرام اثنان وتسعون غرامًا، فإن كانت الحلي أقل من هذا فليس فيها زكاة، أما إن كانت أكثر ففيها الزكاة بالحساب ربع العشر في كل ألف خمسة وعشرون وفي عشرة الآلاف مائتان وخمسون في العشرين ألف خمسمائة في الأربعين ألف ألف واحد وهكذا. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12743/نصاب-زكاة-الحلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_486/48613.mp3","categories":["زكاة النقدين"]},{"id":14473,"question":"يسأل في رسالته عن الزكاة الواجبة في العقار قائلًا: هل الزكاة على قيمة كامل العقار المؤجر، أم أنها على دخله السنوي فقط؟ وبإيضاح أكثر: لو افترضنا أن لدي عمارة قيمتها خمسمائة ألف ريال، ومؤجرة بخمسين ألف ريال، هل الزكاة على الخمسمائة ألف، أم على الخمسين ألف فقط؟ أفيدونا، جزاكم الله خيرًا.","title":"كيفية زكاة العقار المؤجر","answer":"الجواب: العقار إذا كان للتأجير ليس فيه شيء، وإنما الزكاة في أجرته، فهذا العقار الذي بخمسمائة ألف ليس فيه زكاة، إذا كان للتأجير لا للبيع، ولكن أجرته التي هي خمسون ألف مثلًا فيها الزكاة إذا حال عليها الحول، أما لو أخذها صاحبها، وأنفقها في حاجاته، أو قضى بها دينًا عليه قبل أن يحول عليها الحول، فليس فيها زكاة حتى الأجرة نفسها، وإنما تجب فيها الزكاة إذا دار عليها الحول بعد العقد.\nوهكذا جميع العقارات التي للسكن أو للأجار ليس فيها زكاة، إنما الزكاة في العقارات التي للبيع؛ كأن يشتري العمارة بخمسمائة ألف، يريد بيعها للاستفادة منها، فيزكيها إذا حال عليها الحول، يزكي قيمتها التي تساويها، عند حوالها حولان، يعني: عند رأس السنة، هكذا الأراضي، الدكاكين، الحوانيت إذا كانت للبيع إذا تم الحول تعرف قيمته حسب السعر الحاضر، وتزكى كالسيارات ونحوها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12968/كيفية-زكاة-العقار-الموجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_632/nour_63206.mp3","categories":["زكاة النقدين"]},{"id":14517,"question":"هل يجوز صرف الزكاة على الابن والأخ الذي يرث من أمه، أو الأخت التي ليس لها زوج؟نرجو أن توجهونا، جزاكم الله خيرًا، وكذلك الابن إذا كان محتاجًا؟","title":"حكم دفع الزكاة للابن والأخ والأخت","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد: فلا حرج في صرف الزكاة للأخ الفقير، والأخت الفقيرة، وبقية الأقارب الفقراء كالأخوال والأعمام، وابن العم ونحوهم لعموم الأدلة، ومنها قوله -جل وعلا-: إِنَّمَا الصَّدَقَاتُ لِلْفُقَرَاءِ وَالْمَسَاكِينِ [التوبة:60] فهم يدخلون في هذه الآية الكريمة. أما الابن فلا، أما الأولاد لا؛ لأنهم بضعة من الرجل، فلا يصرف فيهم الزكاة وعليه نفقتهم، فأولاد الإنسان من ذكور وإناث وأولاد أولاده وإن نزلوا كلهم لا يعطون الزكاة إذا كانوا فقراء، يعطيهم من ماله ينفق عليهم من ماله ولا يعطيهم من الزكاة، هذا هو الذي عليه أهل العلم، وهكذا الآباء والأمهات والأجداد والجدات لا يعطون من الزكاة، ينفق عليهم ولدهم أيضًا من غير الزكاة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12995/حكم-دفع-الزكاة-للابن-والاخ-والاخت","audio":"https://files.zadapps.info/binbaz.org.sa/old/audio/noor/070801.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":14518,"question":"يقول: هل تجب الزكاة على رأس المال المستثمر في شركة في شكل أسهم، أم أنّ الزكاة على الربح فقط إذا بلغ النصاب؟ وما مقدار النصاب؟","title":"هل تجب الزكاة في الأسهم؟ أم في أرباحها؟","answer":"الجواب: هذا فيه تفصيل: فإن كانت السهام للبيع وجبت الزكاة فيها والأرباح جميعًا.\nوالنصاب في الذهب عشرون مثقالًا، وفي الفضة مائة وأربعون مثقالاً، ومقداره من الذهب بالجنيه السعودي إحدى عشر جنيه، وثلاثة أسباع الجنيه، ومثله من الفضة ستة وخمسون ريالًا، فضة سعودي. فالزكاة تجب في السهام، وفي الأرباح إذا كانت للبيع، كأن يساهم في أرض للبيع، أو يساهم في سيارات للبيع، أو ما أشبه ذلك للبيع فيزكي الجميع، أما إذا كانت المساهمة في شيء للاستغلال لا للبيع، مثل الأرض ساهم فيها يستغلونها للزراعة ونحوها أو بالتأجير، فهذه الزكاة في نتاجها في الزراعة إذا بلغت النصاب، الحبوب يزكوها، وإن كانت تمور زكوها إذا بلغت النصاب، وهكذا. المقصود: إذا كانت المساهمة في أرض ليست للبيع مثلًا، بل للاستغلال بالزراعة ونحوها أو بالتأجير، فليس فيها زكاة، إنما الزكاة في نتاجها، الأجرة التي تؤخذ عنها إذا بلغت النصاب تزكى إذا حال عليها الحول، الحبوب والثمار التي فيها تزكى إذا بلغت النصاب وهكذا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12998/هل-تجب-الزكاة-في-الاسهم-ام-في-ارباحها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_489/48902.mp3","categories":["زكاة النقدين"]},{"id":14521,"question":"هل تجب الزكاة على المال الشبه ضائع، والذي في علم الغيب، ولا يعرف هل سيعود إلى صاحبه أو لا؟","title":"حكم زكاة المال الضائع والدين","answer":"الجواب: المال الضايع لا زكاة فيه، مثل الإبل الضايعة، أو غنمًا ضائعة، أو بقرًا ضائعة، أو نقودًا ضاعت، لا يدري أين ذهبت؟ ليس عليه زكاة حتى يجدها، ثم يستقبل حولًا جديدًا، إذا وجدها يبدأ الحول. وهكذا الديون التي على المعسرين كالضايع، الدين الذي على المعسر الذي لا يستطيع الأداء ليس عليه زكاة حتى يسلم له، حتى يقبضه منه فيستقبله حولاً كاملاً.\nوهكذا الديون التي على المماطلين الذين لا يعطون الحق، يماطلون وما يعطون الحق، ليس فيه زكاة حتى يقبض المال، فالمماطل من جنس المعسر، صاحبه تعبان معه ليس عنده مال في الحقيقة حتى يقبضه فإذا قبضه زكاه إذا حال عليه الحول بعد قبضه. والخلاصة: أنّ المال الضائع والمفقود الذي ما يدري أين ذهب؟ وسواء كان نقودًا أو إبلًا أو بقرًا أو غنمًا ما فيه زكاة حتى يجده ربه، ثم يستقبله حولاً كاملاً، ومن ذلك ما كان على المعسرين، ديون على المعسرين لا زكاة فيها حتى تقبض ويستقبلها حولاً كاملاً، أو على المماطلين الذين لا يؤدون الحق إلا بالتعب، هذا لا زكاة فيه حتى يعطوه حقه، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13004/حكم-زكاة-المال-الضاىع-والدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_489/48903.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":14560,"question":"إذا دفعت الزكاة لشخص أعتقد أنه فقير، وتبين غير ذلك، هل أكون قد أديت الزكاة؟","title":"هل تجزء الزكاة لمن دفعها لغني ظنًا أنه فقير؟","answer":"الجواب: نعم الصحيح أنه يجزئ؛ لأن ضبط فقر الناس فيه تعب، فإذا ظن أنه فقير بالعلامات، أو بشهادة بعض الناس، ثم بان أنه غني يجزئه ما أخرج، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13057/هل-تجزء-الزكاة-لمن-دفعها-لغني-ظنا-انه-فقير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_489/48910.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":14561,"question":"هل إذا كان لدى امرأة مال في حدود ثلاثة آلاف ريال وربما أقل، هل تجب فيه الزكاة حينئذٍ؟","title":"حكم الزكاة في العُمل الورقية","answer":"الجواب: نعم في الثلاثة ألف وما دونها أيضًا، متى صار عنده نصاب وجبت عليه الزكاة إذا حال عليه الحول ولو قليل، لو حال الحول عليه وعنده مائة ريال يزكيها ريالين ونصف، أو ألف ريال يزكيها خمسة وعشرون.  المقصود: إذا حال الحول وعنده نصاب وجبت عليه الزكاة ولو كان قليلًا. المقدم: جزاكم الله خيرًا، يبدو أنه لا يعرف النصاب؛ ولهذا يعتقد أن الثلاثة الآلاف ليس فيها زكاة؛ ولذلك سأل فنذكرهم بالأنصبة لو تكرمتم؟\nالشيخ: نعم النصاب من الفضة ستة وخمسون ريال فضة، وما يقوم مقامها من العمل المعروفة من الدولار، أو الريال السعودي الورق أو من الدنانير، ما يقوم مقامها يزكى، ستة وخمسين ريال، ما يقوم مقامها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13058/حكم-الزكاة-في-العمل-الورقية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_489/48911.mp3","categories":["زكاة النقدين"]},{"id":14571,"question":"في ثاني أسئلة هذا السائل من الجزائر يقول في سؤاله: هل يخول الشرع الزوجة الناشز في كل ما تطلبه من أغنام ولباس وأواني أكل وطبخ وغطاء وأثاث؟وجهونا في ضوء هذا السؤال.","title":"هل يجب إعطاء الناشز شيئًا من المهر؟","answer":"الجواب: الناشز لا حق لها في مهرها، إذا كانت ناشزة بغير حق ظالمة؛ ولهذا لما نشزت امرأة ثابت بن قيس على زوجها ثابت قال النبي ﷺ: أتردين عليه حديقته؟ قالت: نعم، فقال لزوجها: اقبل الحديقة، وطلقها تطليقة لأنها نشزت عليه بغضًا له وسخطًا، لم يتعد عليها، ولم يظلمها، إنما هي مبغضة، فأمرها النبي ﷺ أن ترد عليه مهره. فالناشز بغير حق عليها أن ترد المهر كله، فيطلقها الزوج؛ لأن هذا خير له من وجودها معه، وهي تبغضه، فإذا ردت عليه ماله يؤمر بطلاقها، ولا حق لها في مهرها، سواء كان مهرها نقودًا أو بيتًا أو أرضًا أو أمتعة عليها أن ترد عليه مهره إلا إذا سمح بالبعض، ورضي بالنصف أو بالربع فلا بأس.  أما إذا أبى إلا مهره كله فإنها تعطيه مهره كله إذا لم يظلمها إنما هي مبغضة له، أما إذا ظلمها فهذا ينظر فيه القاضي يتحاكما إلى المحكمة والمحكمة تنظر في الأمر. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13068/هل-يجب-اعطاء-الناشز-شيىا-من-المهر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_556/55609.mp3","categories":["الصداق","زكاة النقدين","قضايا المرأة"]},{"id":14805,"question":"إذا كان عندي مبلغ خمسة عشر ألف ريال سعودي، في شهر محرم، عام ألف وأربعمائة وثمانية، ودخل العام الذي بعده وهو عام ألف وأربعمائة وتسعة، يعني: هذا المبلغ أكمل عام من غير أن أمس منه شيئًا، كيف نخرج منه الزكاة؟ ومتى يجب إخراجها؟","title":"وقت إخراج الزكاة لمن ملك ما يبلغ النصاب","answer":"الجواب: ما دمت ملكته في المحرم، فعليك الزكاة في المحرم، إذا تم السنة، ولو أنه لم يتصرف فيه، ولو أنه في الصندوق، أو في البنك، محفوظًا أمانة، عليك أن تخرج زكاته ربع العشر، في كل ألف خمسة وعشرون، إذا تم الحول، إذا كان هذا المال جاءك هبة، أو ورث، فإنه إذا دار عليه الحول، تمت السنة، تخرج زكاته.  فأما إن كان هذا المال ثمن سلعة معدة للبيع، فالحول حول السلعة التي أعددتها للبيع، متى تمت السنة؛ زكيت المال. فالحاصل: أن الزكاة تجب في المال، في النقود، إذا تم الحول عليها، وفي السلع المعدة للبيع: سيارات، أو فرش، أو أواني، أو غير ذلك، فعليك الزكاة فيها إذا تم حولها، حسب قيمتها. المقدم: التي هي عروض التجارة. الشيخ: وهي عروض التجارة، تنظر في قيمتها عند الحول، فإذا كانت قيمتها مثلًا: عشرة آلاف، زكيت عشرة آلاف، وإذا كانت قيمتها مائة ألف، زكيت مائة ألف، عند الحول، وهذا هو الواجب عليك وعلى أمثالك، نعم.\nالمقدم: جزاكم الله خيرًا، وأيضًا عن الزكاة، عندما ذهبت في إجازتي السنوية في شهر فبراير من عام ثمانية وثمانين، فتحت حساب في أحد البنوك الإسلامية في السودان، ووضعت فيه مبلغ عشرين ألف وثمانمائة جنيه سوداني، وفي نفس العام أخذت منه تسعة آلاف جنيه، أصبح المتبقي إحدى عشر ألف وثمانمائة جنيه حتى بداية العام الجديد تسعة وثمانين، كيف تكون طريقة إخراج الزكاة في هذا المبلغ؟ ومتى يجب إخراجها؟\nالشيخ: عليك أن تخرج الزكاة من حين تم الحول، والمبلغ الذي أخذته قبل تمام الحول، ليس فيه زكاة، لكن الذي تم عليه الحول، بعدما ملكت هذا المال، عليك زكاته، وهي ربع العشر، في كل ألف خمسة وعشرون، فلا زكاة في مال حتى يحول عليه الحول، يعني: النقود وأشباهه كعروض التجارة، وكالإبل، والبقر، والغنم، السائمة، الراعية، كل هذه لا زكاة فيها إلا إذا تمت السنة، كلما تمت السنة؛ وجبت الزكاة. أما الحبوب والثمار فتجب فيها الزكاة إذا استوت ونضجت، الحبوب إذا استوت، واشتدت، ثم حصدها ويرعاها وطابت، ونظفت، تجب فيها الزكاة بعد دريها، وتخليصها مما هي فيه من قصب ونحوه، حتى تصفيها، ويخرج زكاتها. وهكذا الثمار، كالتمر والعنب، يزكيه إذا استوى، ونضج، ووضع في البيدر، يعني في الجرين ، في محل تيبيسه، ثم يخرج زكاته إذا بلغ النصاب، خمسة أوسق، وإذا كان يسقى بالمكائن ونحوها فيه نصف العشر، في الألف خمسون، في الألف وزنة، أو الكيلو خمسون، وفي الألفين مائة، نصف العشر، وإذا كان يسقى بالمطر والأنهار الجارية، يكون فيه العشر، في الألف مائة، وفي الألفين مائتان، وهكذا، هكذا جاءت السنة عن النبي -عليه الصلاة والسلام-، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13306/وقت-اخراج-الزكاة-لمن-ملك-ما-يبلغ-النصاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_642/nour_64207.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":14813,"question":"إذا كان عندي مبلغ خمسة عشر ألف ريال سعودي، في شهر محرم، عام ألف وأربعمائة وثمانية، ودخل العام الذي بعده وهو عام ألف وأربعمائة وتسعة، يعني: هذا المبلغ أكمل عام من غير أن أمس منه شيئًا، كيف نخرج منه الزكاة؟ ومتى يجب إخراجها؟","title":"وقت إخراج الزكاة لمن ملك ما يبلغ النصاب","answer":"الجواب: ما دمت ملكته في المحرم، فعليك الزكاة في المحرم، إذا تم السنة، ولو أنه لم يتصرف فيه، ولو أنه في الصندوق، أو في البنك، محفوظًا أمانة، عليك أن تخرج زكاته ربع العشر، في كل ألف خمسة وعشرون، إذا تم الحول، إذا كان هذا المال جاءك هبة، أو ورث، فإنه إذا دار عليه الحول، تمت السنة، تخرج زكاته.  فأما إن كان هذا المال ثمن سلعة معدة للبيع، فالحول حول السلعة التي أعددتها للبيع، متى تمت السنة؛ زكيت المال. فالحاصل: أن الزكاة تجب في المال، في النقود، إذا تم الحول عليها، وفي السلع المعدة للبيع: سيارات، أو فرش، أو أواني، أو غير ذلك، فعليك الزكاة فيها إذا تم حولها، حسب قيمتها. المقدم: التي هي عروض التجارة. الشيخ: وهي عروض التجارة، تنظر في قيمتها عند الحول، فإذا كانت قيمتها مثلًا: عشرة آلاف، زكيت عشرة آلاف، وإذا كانت قيمتها مائة ألف، زكيت مائة ألف، عند الحول، وهذا هو الواجب عليك وعلى أمثالك، نعم.\nالمقدم: جزاكم الله خيرًا، وأيضًا عن الزكاة، عندما ذهبت في إجازتي السنوية في شهر فبراير من عام ثمانية وثمانين، فتحت حساب في أحد البنوك الإسلامية في السودان، ووضعت فيه مبلغ عشرين ألف وثمانمائة جنيه سوداني، وفي نفس العام أخذت منه تسعة آلاف جنيه، أصبح المتبقي إحدى عشر ألف وثمانمائة جنيه حتى بداية العام الجديد تسعة وثمانين، كيف تكون طريقة إخراج الزكاة في هذا المبلغ؟ ومتى يجب إخراجها؟\nالشيخ: عليك أن تخرج الزكاة من حين تم الحول، والمبلغ الذي أخذته قبل تمام الحول، ليس فيه زكاة، لكن الذي تم عليه الحول، بعدما ملكت هذا المال، عليك زكاته، وهي ربع العشر، في كل ألف خمسة وعشرون، فلا زكاة في مال حتى يحول عليه الحول، يعني: النقود وأشباهه كعروض التجارة، وكالإبل، والبقر، والغنم، السائمة، الراعية، كل هذه لا زكاة فيها إلا إذا تمت السنة، كلما تمت السنة؛ وجبت الزكاة. أما الحبوب والثمار فتجب فيها الزكاة إذا استوت ونضجت، الحبوب إذا استوت، واشتدت، ثم حصدها ويرعاها وطابت، ونظفت، تجب فيها الزكاة بعد دريها، وتخليصها مما هي فيه من قصب ونحوه، حتى تصفيها، ويخرج زكاتها. وهكذا الثمار، كالتمر والعنب، يزكيه إذا استوى، ونضج، ووضع في البيدر، يعني في الجرين ، في محل تيبيسه، ثم يخرج زكاته إذا بلغ النصاب، خمسة أوسق، وإذا كان يسقى بالمكائن ونحوها فيه نصف العشر، في الألف خمسون، في الألف وزنة، أو الكيلو خمسون، وفي الألفين مائة، نصف العشر، وإذا كان يسقى بالمطر والأنهار الجارية، يكون فيه العشر، في الألف مائة، وفي الألفين مائتان، وهكذا، هكذا جاءت السنة عن النبي -عليه الصلاة والسلام-، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13306/وقت-اخراج-الزكاة-لمن-ملك-ما-يبلغ-النصاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_642/nour_64207.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":14840,"question":"أجرت رجلًا أرضًا حرثها شعيرًا، ولكنه لما نضج الزرع باعه لشخص آخر، والزرع ما زال في زرعه، ولم يحصد بعد، فعلى من تجب الزكاة على الأول أم على الثاني؟جزاكم الله خيرًا.","title":"على من تجب الزكاة إذا بيع الزرع قبل الحصاد؟","answer":"الجواب: على الأول؛ إذا اشتد الحب وهو في ملكه، عليه الزكاة، نعم. المقدم: جزاكم الله خيرًا.  يسأل ويقول: رجلان اشتركا في حرث قطعة أرض، ولكن الذي قام بالعمل...\nالشيخ: لكن إذا شرطه على المشتري، باعه الزرع وشرط عليه أن الزكاة عليه هذا صارت الزكاة عليه، نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/13339/على-من-تجب-الزكاة-اذا-بيع-الزرع-قبل-الحصاد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_644/nour_64402.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":14845,"question":"في سؤاله الثاني يقول: رجلان اشتركا في حرث قطعة أرض، ولكن الذي قام بالعمل -حتى أصبح المحصول جاهزًا لكي يقتسماه- هو شخص واحد فقط، فعلى من تجب الزكاة على الاثنين أم على الذي لم يقم بجمع المحصول والذي هو الشعير؟الشيخ: أعد أعد.المقدم: يقول: رجلان اشتركا في حرث قطعة أرض، ولكن الذي قام بالعمل -حتى أصبح المحصول جاهزًا- شخص واحد فقط، فعلى من تجب الزكاة على الاثنين أم على الذي لم يقم بجمع المحصول؟","title":"على من تجب الزكاة في المال المشترك؟","answer":"الجواب: ما داما مشتركين، والبذر منهما، والعمل بينهما، ولكن سمح أحدهما بالقيام بالعمل عن صاحبه، فالزكاة عليهما؛ لأن المال مالهما، نعم.","link":"https://binbaz.org.sa/fatwas/13341/على-من-تجب-الزكاة-في-المال-المشترك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_644/nour_64403.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":14850,"question":"نعود مع مطلع هذه الحلقة إلى رسالة المستمع فتحي محمد مؤمن، أخونا فتحي من جمهورية مصر العربية مدينة السلوم، محافظة مطروح، بعث بعدد من الأسئلة من بينها سؤال يقول: ما هو نصاب الأموال التي يزكى عليها؟","title":"ما هو نصاب الأموال التي يزكى عليها؟","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد: فهذا سؤال عام، والأموال أنواع، كل نوع له نصابه، فنصاب الذهب عشرون مثقالًا، ومقداره اثنان وتسعون غرام، ومقداره بالجنيه السعودي والفرنجي إحدى عشر جنيهًا، وثلاثة أسباع جنيه، فإذا بلغ الذهب هذا المقدار وجبت فيه الزكاة، وهي ربع العشر، من كل أربعين جنيه جنيه واحد، وإذا بلغت العملة قيمة ذلك، سواءً كانت بالدولار، أو الجنيه المصري، أو كانت غير ذلك إذا بلغت هذا المقدار، وجبت فيها الزكاة ربع العشر. أما الفضة فنصابها مائة وأربعون مثقالًا، ومقداره بالدرهم السعودي الفضي ستة وخمسون ريالًا، فإذا بلغت العمل هذا المقدار، أو قيمة هذا المقدار، وجبت فيها الزكاة، وهي ربع العشر، من الألف خمسة وعشرون، من الألفين خمسون، وهكذا. أما الحبوب والثمار فنصابها خمسة أوسق، والوسق ستون صاعًا بصاع النبي -عليه الصلاة والسلام-، فإذا بلغ حاصل التمر أو الحبوب من الذرة، أو الحنطة، أو الشعير، أو الأرز ثلاثمائة صاع بصاع النبي ﷺ، يعني: خمسة أوسق، وجبت فيها الزكاة، وصاع النبي ﷺ أربع حفنات باليدين المعتدلتين المملوءتين. والواجب نصف العشر، إذا كان الزرع أو النخل يسقى بمئونة كالمكائن والسواني ففيه نصف العشر، من كل ألف خمسون، من كل ألف وزنة مثلًا، أو كيلو خمسون، وهكذا العنب إذا بلغ منه خمسة أوسق مثل التمر، فيه نصف العشر إذا كان بمئونة بالسواني أو المكائن.  أما إذا كانت الحبوب والثمار تسقى بالمطر أو بالأنهار أو بالعيون الجارية ففيها العشر كاملًا، من كل ألف مائة، من كل ألف صاع، أو ألف كيلو مائة كيلو ومائة صاع، ومن عشرات الآلاف ألف كامل، وهكذا. وعروض التجارة هي السلع التي تعد للبيع من السيارات والأقمشة والأواني ونحوها هذه نصابها نصاب الذهب والفضة، إذا بلغت قيمتها نصاب الذهب والفضة وجبت فيها الزكاة ربع العشر. وأما الإبل والبقر والغنم فلها نصب خاصة، إذا كانت سائمة ترعى غالب الحول، أو كل الحول، فإن فيها زكاة، مقدرة، قدرها النبي ﷺ، في الغنم في أربعين شاة، شاة واحدة، وإذا كانت الغنم أقل من أربعين ما فيها شيء، إلى مائة وعشرين، فإذا زادت عن مائة وعشرين صار فيها شاتان، في المائة وإحدى وعشرين شاتان، إلى مائتين، فإذا زادت عن مائتين ففيها ثلاث شياه، وهكذا في كل مائة شاة بعد ذلك، في أربعمائة أربع شياه، وفي خمسمائة خمس شياه، وهكذا. أما البقر فأقل نصابها ثلاثون تبيع أو تبيعة، قد بلغ كل واحد سنة كاملة، ذكر أو أنثى، سنة كاملة، في التبيع، أو التبيعة، إذا كانت البقرة ثلاثين سائمة ترعى سنة كاملة، ففي الثلاثين تبيع أو تبيعة، قد بلغا سنة واحدة، فإذا بلغت أربعين ففيها مسنة، تم لها سنتان، ثم ليس فيها شيء إلى أن تبلغ ستين، فإذا بلغت ستين ففيها تبيعان، إلى سبعين، فإذا بلغت سبعين ففيها تبيع ومسنة، وهكذا، في كل أربعين مسنة، وفي كل ثلاثين تبيع، فإذا بلغت مائة وعشرين استوى الفرضان، إن شاء أخرج ثلاث مسنات؛ لأن فيها أربعين ثلاث مرات، وإن شاء أخرج أربعة أتبعة؛ لأن فيها ثلاثين أربع مرات. أما الإبل فأنصباؤها متعددة، ففي الخمس شاة واحدة، وفي العشر شاتان، وفي خمسة عشر ثلاث شياه، وفي عشرين أربع شياه، فإذا بلغت خمسًا وعشرين، وهي ترعى غالب السنة، أو كل السنة وجب فيها بنت مخاض، بكرة تم لها سنة، ودخلت في الثانية، إلى ست وثلاثين، فإذا بلغت ستًا وثلاثين، ففيها بنت لبون، أنثى تم لها سنتان، إلى ست وأربعين، فإذا بلغت ستًا وأربعين، ففيها حقة طروقة الجمل، تم لها ثلاث سنين، إلى إحدى وستين، فإذا بلغت إحدى وستين ففيها جذعة، قد تم لها أربع سنين ودخلت في الخامسة، فإذا بلغت ستًا وسبعين ففيها بنتا لبون، كل واحدة قد تم لها سنتان، إلى إحدى وتسعين، فإذا بلغت إحدى وتسعين ففيها حقتان طروقتا الجمل، إلى مائة وعشرين، فإذا بلغت مائة وعشرين ففيها ثلاث بنات لبون، إلى مائة وثلاثين، فإذا بلغت مائة وثلاثين ففيها بنتا لبون وحقة واحدة، بنتا لبون في ثمانين، وحقة عن الخمسين، الجميع حقة وبنتا لبون، في مائة وثلاثين، فإذا بلغت مائة وأربعين ففيها حقتان عن المائة وبنت لبون عن الأربعين، فإذا بلغت مائة وخمسين ففيها ثلاث حقاق، وهكذا، في كل أربعين بنت لبون، وفي كل خمسين حقة، لكن بشرط أن تكون ترعى سائمة غالب السنة، أو كل السنة، في البقر والغنم والإبل جميعًا، فإذا كانت معلفة فليس فيها شيء، إذا كانت تعلف غالب السنة ليس فيها شيء، إلا أن تكون للبيع، للتجارة فإنه يزكيها زكاة التجارة، سواءً كانت إبلًا أو بقرًا أو غنمًا يزكيها زكاة التجارة، إذا كانت للبيع، وإن كان يعلفها، والله ولي التوفيق. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13338/ما-هو-نصاب-الاموال-التي-يزكى-عليها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_644/nour_64401.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":14919,"question":"المستمع أحمد سالم حماد من البحرين، بعث يسأل ويقول: هل تجوز زكاة الفلوس على الأخ والأخت إذا كانت ساكنة بحوزة المزكي، الأخت مطلقة، وتسكن مع أولادها بحوزة المزكي؟","title":"حكم دفع الزكاة للإخوة والأخوات","answer":"الجواب: إذا كانت محتاجة، وكان الأخ محتاجًا جاز صرف الزكاة فيهما؛ لأنهما من أهلها بسبب فقرهم، لكن إذا تيسر للأخ أن يقوم بحالهم، وأن ينفق عليهم من ماله كان هذا أفضل وأحسن، تبعًا لذريته ولعائلته.  وأما إذا خصها بشيء لحاجتها، وحاجة أطفالها في كسوة ونحوها، فإن هذا لا بأس به، أما الأكل فتأكل معهم في طعامهم وشرابهم في البيت؛ لأن الأكل موضوع للجميع، أما إذا كان على حدة، تصنع طعامها على حدة، لها عهدة من البيت على حدة، فإنها تعطى ما يكفيها من الزكاة لها ولأولادها في الكسوة والطعام وغير ذلك بسبب الحاجة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13412/حكم-دفع-الزكاة-للاخوة-والاخوات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_492/49204.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":14931,"question":"هذه رسالة وردتنا من العراق، ويرجو فيها أن يسمع الإجابة، يقول: الاسم (ع. ك) من العراق، يقول: متى تستحق الزكاة؟ وكم زكاة الفلوس العراقية إذا كان المبلغ ألفين ومائتين دينار عراقي؟","title":"مقدار الزكاة ومصارفها","answer":"الجواب: الزكاة مثل غيره، العراق مثل غيره، كلما جمع مال فيه ربع العشر، سواءً دينار عراقي، أو غيره، فالألفان فيهما خمسون، والألف فيه خمسة وعشرون، ربع العشر زكاة، وإذا كان عنده مائة ألف من الدنانير، فيها ربع العشر، ألفين ونصف في المائة الألف ألفين ونصف ربع العشر، وفي المليون خمسة وعشرون ألفًا، وهكذا.  فالمقصود: ربع العشر مما يملكه الإنسان من النقود، سواء كان عراقية أو أردنية أو إنجليزية أو أمريكية أو غير ذلك، ربع العشر من الذهب والفضة، نعم، والأوراق النقدية هذه، نعم. السؤال: سؤاله الثاني يقول: إنني كنت أشتغل في شركة...\nالشيخ: ويعطاها المستحق، الذي يستحق الزكاة يعطاها الفقراء، الفقراء والمحاويج من المسلمين، والإنسان الذي عليه دين يعجز عن أدائه، غارم، يُعطى ما يسدد به دينه، والمؤلف رئيس العشيرة كبار القوم، إذا كانوا فقراء، أو ضعيف إسلامهم، أو يخشى عليهم الردة، يعطون ما يؤلفون به، حتى يقوى إيمانهم، ويقوى إسلامهم، رؤساء العشائر، كبار القوم الذي يرجى في عطيتهم قوة إيمانهم، وقوة إسلامهم، وتعاونهم مع المسلمين، نعم.","link":"https://binbaz.org.sa/fatwas/13445/مقدار-الزكاة-ومصارفها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_647/nour_64709.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":15086,"question":"عبدالرحمن محمد الدخيل، بعث لنا بهذه الرسالة، يسأل عن النيابة في صرف الزكاة، يقول: إن أحد المدرسين من الإخوة المصريين أعطاني خمسين ريالًا، وقال لي: خذ هذه الخمسين، وأعطها أي شخصٍ ترى أنه مستحق لها، فإنها من زكاة مالي، فأخذت الخمسين ريالًا، وأعطيتها شخصًا، تبين بعد ذلك أنه غير مستحق لها. علمًا أن هذه الحادثة وقعت منذ وقتٍ بعيد، وكلما تذكرتها أضيق، ويؤنبني ضميري، فأرجو منكم معالجة هذه المشكلة، وفقكم الله.","title":"حكم إعطاء الزكاة لمن لا يستحقها بدون قصد","answer":"الجواب: إذا كان الشخص الذي دفعت إليه الخمسين ظاهره الفقر والحاجة، ودفعتها إليه بسبب ما ظهر لك من حاجته وفقره؛ فلا حرج في ذلك، وقد وقعت موقعها وأجزأت، والحمد لله. أما إن كنت أعطيته إياها من غير نظر، ولا تأمل، ولم يظهر لك أنه محتاج، وإنما تساهلت في ذلك؛ فإنك تغرمها، وتعطيها شخصًا تعرف حاجته وفقره، نعم.","link":"https://binbaz.org.sa/fatwas/13589/حكم-اعطاء-الزكاة-لمن-لا-يستحقها-بدون-قصد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_655/nour_65507.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":15194,"question":"السؤال التالي بعث به المستمع (س. ع. ن) من الدمام، يقول: لي في ذمة أحد الناس مبلغ من المال، ويرجى سداده، ولكن في الوقت الحاضر لا يتمكن المدين من السداد، وفي نفس الوقت ذلك الشخص المدين يستحق الزكاة، فهل أضع عنه مما لي في ذمته مقابل زكاته له، أم أدفع له من غير ما عنده من الدين؟","title":"حكم إسقاط الدين وجعله من الزكاة","answer":"الجواب: الواجب أنك تعطيه إذا كان مستحقًا، المشروع لك أن تعطيه مما لديك إذا كان من أهل الزكاة.  وأما إسقاط جزء مما عليه عن الزكاة فلا يجزي؛ لأن الزكاة إعطاء ودفع، وليست إبراء، فالدين الذي عليه يمهل إذا كان معسرًا حتى يتيسر له الوفاء؛ لأن الله قال: وَإِنْ كَانَ ذُو عُسْرَةٍ فَنَظِرَةٌ إِلَى مَيْسَرَةٍ [البقرة:280]. وأما الزكاة فلا بأس أن يعطى من الزكاة إذا كان من أهلها، إذا كان فقيرًا، يعطى من الزكاة التي عندك من المال الذي عندك.\nوأما إسقاط شيء مما عليه عن الزكاة فلا يجزئ، نعم.","link":"https://binbaz.org.sa/fatwas/13696/حكم-اسقاط-الدين-وجعله-من-الزكاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_671/nour_67103.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":15268,"question":"أم فوزية من الأحساء، بعثت بهذا السؤال، تقول -سماحة الشيخ- تذكر بأنها امرأة مطلقة، وليس عندها أي دخل مادي، وتذكر بأن زوجها لا يعطيها إلا القليل من المساعدة لها ولأولادها، فتقول: أصبحت أبيع مما عندي من مجوهرات وألماس وأي شيء أملكه، هل على ذلك زكاة فيما أبيع؟","title":"حكم الزكاة في النقود التي بيع بها الحلي","answer":"الجواب: إذا حال عليها الحول والنقود عندك زكيها، إذا حال الحول على النقود زكيها، وأما إذا أنفقتيها قبل أن يحول الحول ما فيها زكاة، نعم.","link":"https://binbaz.org.sa/fatwas/13767/حكم-الزكاة-في-النقود-التي-بيع-بها-الحلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_565/56514.mp3","categories":["زكاة النقدين"]},{"id":15282,"question":"سؤالها الآخر تقول فيه: لقد كثر الاختلاف في وجوب زكاة الذهب الذي يلبس وليس للإعارة أو الإيجار، فما هو رأي الدين في ذلك؟","title":"حكم زكاة الذهب الذي يلبس للزينة","answer":"الجواب: العلماء اختلفوا في الذهب والفضة الذي تتحلى به المرأة، وتلبسه عند الحاجة، هل يزكى أم لا يزكى؟ وهل تكفي العارية؟ على أقوال لأهل العلم، والأرجح والأصح أنه يزكى، وأنه تجب فيه الزكاة إذا بلغ النصاب، والنصاب عشرون مثقالًا، ومقداره بالجنيه السعودي إحدى عشر جنيه ونصف بالجنيه السعودي، والفرنجي أيضًا، إحدى عشر جنيهًا وثلاثة أسباع جنيه، يعني: إحدى عشر جنيه ونصف أوضح للسامع، إحدى عشر جنيهًا ونصف هذا النصاب. فإذا بلغ حلي المرأة من الذهب إحدى عشر جنيهًا ونصف وجبت عليها الزكاة، في الألف خمسة وعشرون ريالًا، في الألف الريال خمسة وعشرون ريالًا، في الذهب الذي قيمته ألف خمسة وعشرون ريالًا مثلًا، وهكذا.\nالمقدم: ربع العشر، يعني.\nالشيخ: ربع العشر، كسائر أنواع الذهب والفضة؛ ربع العشر، أما إن كان أقل من عشرين مثقالًا، يعني: أقل من إحدى عشر جنيهًا ونصف فلا شيء فيه، هذا هو الصواب، وهذا هو الأرجح من أقوال أهل العلم؛ لأنه ثبت عنه ﷺ أنه دخلت عليه امرأة وفي يدها سواران مسكتان من ذهب، فقال: أتعطين زكاة هذا؟ قالت: لا، قال: أيسرك أن يسورك الله بهما يوم القيامة سوارين من نار؟ فألقتها وقالت: هما لله ولرسوله.  وقالت له أم سلمة: يا رسول الله -وكانت تلبس أوضاحًا من ذهب- هل في هذا زكاة؟ فقال: ما بلغ أن يزكى فزكي فليس بكنز سألته: هل هذا كنز؟ فقال: ما بلغ أن يزكى فزكي فليس بكنز. ولعموم الحديث: ما من صاحب ذهب ولا فضة لا يؤدي زكاتها إلا إذا كان يوم القيامة صفحت له صفائح من نار... الحديث، فإنه يعم هذه الحلي، نعم.","link":"https://binbaz.org.sa/fatwas/13789/حكم-زكاة-الذهب-الذي-يلبس-للزينة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_675/nour_67508.mp3","categories":["الصداق","زكاة النقدين","قضايا المرأة"]},{"id":15336,"question":"(ع. أ. م) السائل من حفر الباطن، أرسل بسؤال كتبه بأسلوبه الخاص، يقول -يا سماحة الشيخ-: بأنه شاب متزوج، ولديه أولاد، ويحمد الله على ذلك، دخله الشهري محدود، ويعيش في بيت والده، وإخوانه جميعًا، والسؤال يبقى يقول: هو أن أحد الإخوة يعلم بدخلي الشهري المحدود، وقام بمساعدتي بمبلغ من المال، ورفضت أن آخذ في البداية هذا المبلغ، لكنه ألح علي، فقبلته كمساعدة.علمًا بأنه أخبرني بأن ذلك من الزكاة، فهل يحل لي هذا المال؟ علمًا بأنني مطالب بدفع مبلغ من المال وقدره ثمانية عشر ألفًا ريال لدى إحدى الجهات بعد سنتين من هذا اليوم، ولا أملك هذا المبلغ، فأفيدوني، مأجورين.","title":"حكم إعطاء الزكاة لمن راتبه محدودًا","answer":"الجواب: أنت أعلم بنفسك، إذا كنت محتاجًا إليه، فقيرًا إليه، فلا بأس، إذا كان الدخل الذي يدخل عليك لا يكفي مئونة أهلك، مئونتك فلا بأس أن تأخذ، وإذا كان عليك دين فأنت غارم تأخذ لأجل الغرم؛ لأن الله جعل للغارمين حقًا في الزكاة، ولو كان الدين مؤجلًا إلا إذا كان له وفاء، إذا كان له وفاء لا تأخذ الزكاة، أما إذا كان ما له وفاء تأخذ وتؤديه لصاحب الدين، ولو عجلته قبل الحل، فعليك الحذر من أخذ الزكاة بغير حق، فإن كنت محتاجًا إليه؛ لأن الراتب لا يكفي لحاجاتك فلا بأس، أو أخذته لغرم لأنك ما عندك مال تؤدي منه الدين، فلك أن تأخذه، وتسدد منه الدين، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/13831/حكم-اعطاء-الزكاة-لمن-راتبه-محدودا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_566/56613.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":15359,"question":"سماحة الشيخ، هذه سائلة تقول: ما مقدار زكاة الذهب؟ وهل ذهب الزينة له زكاة؟بينوا لنا ذلك، مأجورين.","title":"نصاب زكاة الذهب وحكم زكاة الحلي","answer":"الجواب: زكاة الذهب ربع العشر، وهكذا الفضة ربع العشر، من كل مائة اثنان ونصف ومن الألف خمسة وعشرون.\nوهي واجبة في الحلي التي تلبسها المرأة على الصحيح، فإذا كانت تبلغ النصاب وجبت فيها الزكاة، سواء كانت قلائد أو أسورة، أو حزامًا، أو غير ذلك، الواجب فيها الزكاة، والنصاب عشرون مثقالاً من الذهب، يعني: مقداره أحد عشر جنيهًا ونصف من الجنيهات السعودية، اثنان وتسعون غرامًا من الغرامات، فإذا كان عند المرأة نصاب من الحلي وجبت فيها الزكاة إذا حال عليها الحول، فإذا كانت الحلي تبلغ مثلًا عشرين ألفًا، عليها الزكاة ربع العشر خمسمائة؛ لأن عشر العشرين ألفان، ربع العشر خمسمائة، فإذا كانت تبلغ خمسين ألفًا الحلي، صار فيها ربع العشر عشرها خمسة آلاف، ربع العشر ألف ومائتان وخمسون، سواء ذهب أو فضة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13862/نصاب-زكاة-الذهب-وحكم-زكاة-الحلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_499/49902.mp3","categories":["الصداق","زكاة النقدين","قضايا المرأة"]},{"id":15366,"question":"هذه السائلة أم البراء الرياض، تقول: رجل يسكن منزلًا مؤجرًا بعشرين ألف ريال، له أطفال راتبه الشهري حوالي خمسة آلاف ريال، هل يجوز له أن يأخذ الزكاة؟مع العلم بأنه ليس عليه ديون، ولكنه يريد أن يجمع كي يشتري منزلًا، وما حكم الفلوس التي أخذها من أعمامه وأقاربه هل يقوم بإرجاعها أم ماذا يفعل؟وجهونا، مأجورين.","title":"حكم إعطاء الزكاة للموظف","answer":"الجواب: لا يجوز له الحق في أخذ الزكاة، ما دام هذا المبلغ الذي يصل إليه يكفيه في السكن، وفي الحاجة، في النفقة إذا كان راتبه يكفيه لحاجة النفقة وحاجة الأجرة، فلا يجوز له أن يدفع له شيء من الزكاة لشراء المنزل أو الاستئجار.  أما إذا كان لا راتبه ما يكفيه لكثرة العائلة والنفقة، فله أن يأخذ من الزكاة من أجل أن يشتري به سكنًا أو يستأجر. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/13869/حكم-اعطاء-الزكاة-للموظف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_499/49909.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":15452,"question":"هذا سؤال أيضًا من المستمع عواض علي عائض القرني، من الدمام، يقول: أعمل لمدة ثلاث سنوات متتالية، وأتقاضى من عملي مبلغًا وقدره ستة آلاف ريال تقريبًا، ولكنني منذ عملت إلى الآن لم أزك منها شيئًا إلا أنني إذا وجدت أي متسول أعطيه شيئًا بسيطًا، وأيضًا النساء من أقاربي أعطيهم كلما زرتهم، لذلك أسأل هل علي ذنب في ذلك؟ وهل أزكي الآن؟ وكيف أحصر رواتبي؟أفيدوني، جزاكم الله خيرًا.","title":"حكم زكاة الراتب","answer":"الجواب: إذا كانت هذه الرواتب تنفق وتصرف ولا تبقى سنة، بل تنفقها في حاجاتك وصدقاتك النافلة، فلا زكاة عليك، أما إن كان يبقى منها شيء يحول عليه الحول، فإن ما حال عليه الحول منها يزكى، وعليك أن تحفظ ذلك، وأن تعتني بالذي ينفق والذي يبقى، فيكون للمدخر محل أو دفتر أو صندوق خاص، وما كان للنفقة يكون له محل آخر حتى لا يشتبه الأمر، فما حال عليه الحول من المدخرات من هذا الراتب زكيته ربع العشر من كل ألف خمسة وعشرون، وما أنفقته قبل الحول فليس عليك فيه زكاة، وما دفعته إلى السائلين أو إلى قراباتك بنية الزكاة وهم فقراء احتسب من الزكاة، إذا كنت نويته عند الدفع أنه من الزكاة، وهن فقيرات النساء اللاتي أعطيتهن فقيرات فإنه يحسب من الزكاة، وهكذا ما تعطيه السائلين الشحاذين إذا كنت تحتسبه من الزكاة فإنه من الزكاة.  أما ما أعطيت قراباتك أو السائلين من المال بغير نية الزكاة، فإنه لا يحسب من الزكاة؛ لقول النبي ﷺ: إنما الأعمال بالنيات، وإنما لكل امرئ ما نوى نعم.","link":"https://binbaz.org.sa/fatwas/13974/حكم-زكاة-الراتب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_701/nour_70101.mp3","categories":["زكاة النقدين"]},{"id":15483,"question":"أم نواف من الرياض تقول: هل ينفع أن تدفع كفالة اليتيم كاملة، أو جزءًا منها من زكاة المال، حيث إنه يوافق دفع قسط كفالة اليتيم وقت دفع الزكاة؟","title":"حكم كفالة اليتيم من الزكاة","answer":"الجواب: إذا كان اليتيم فقيرًا فلا بأس، من الزكاة وغيرها، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14010/حكم-كفالة-اليتيم-من-الزكاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_569/56904.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":15502,"question":"السؤال الثاني يقول: أنا أعمل هنا بالمملكة، وقد تغربت عن بلدي بحثًا للرزق الحلال، والحمد لله، فقد جمعت مبلغًا من المال، وأدخره إلى حين عودتي إلى أهلي الذين هم في أمس الحاجة إليه، فهل تجب علي فيه زكاة أم لا نظرًا لحاجة أهلي الماسة إليه؟","title":"حكم زكاة المال المدخر للنفقة أو قضاء دين","answer":"الجواب: إذا جمع المسلم مالًا يبلغ نصاب الزكاة، وأرصده لقضاء دين، أو للزواج، أو ليذهب به إلى أهله، أو ليشتري به مسكنًا، أو لغير ذلك، فإن هذا المال تجب فيه الزكاة إذا حال عليه الحول، ولا يكون إرصاده من أجل الزواج أو قضاء الدين أو الذهاب إلى الأهل لا يكون عذرًا في إسقاط الزكاة، ولا مسوغًا لذلك، هذا هو المعروف من الأدلة الشرعية، ومن كلام أهل العلم.  فعليك -يا أيها السائل- أن تؤدي زكاة المال إذا حال عليه الحول، ولو كنت أرصدته لتذهب به إلى بلادك للإنفاق على والديك أو للزواج أو لأسباب أخرى، نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/14034/حكم-زكاة-المال-المدخر-للنفقة-او-قضاء-دين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_702/nour_70204.mp3","categories":["زكاة النقدين"]},{"id":15514,"question":"تقول هذه السائلة يا سماحة الشيخ: اشتريت ذهبًا يبلغ النصاب في شهر صفر، ثم اشتريت ذهبًا آخر أيضًا يبلغ النصاب في شهر رمضان، كيف أخرج الزكاة؟ وهل في الذهب المستعمل زكاة؟","title":"حكم زكاة الحلي وكيفية إخراجها","answer":"الجواب: الصواب الحلي فيها الزكاة، هذا هو الراجح، فالذي اشتريتيه في صفر زكيه إذا جاء صفر، والذي في رمضان إذا جاء رمضان، كل واحد إذا حال عليه الحول، الذهب الذي في صفر يزكى في صفر إذا حال عليه الحول، والذي في رمضان يزكى في رمضان إذا كان نصابًا، والنصاب إحدى عشر جنيهًا ونصف، إحدى عشر جنيهًا وثلاثة أسباع جنيه، عشرون مثقالًا من الذهب، فإذا بلغ النصاب الذي ملكته في صفر زكيه، ويضم إليه الذي ملكته في رمضان يزكى إذا جاء رمضان، نعم. المقدم: حفظكم الله.","link":"https://binbaz.org.sa/fatwas/14052/حكم-زكاة-الحلي-وكيفية-اخراجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_691/nour_69107.mp3","categories":["الصداق","زكاة النقدين","قضايا المرأة"]},{"id":15532,"question":"سؤاله الثاني يقول: تحتفظ زوجتي بقدر من الذهب بقصد الزينة، فهل تجب عليه الزكاة، خاصة وأننا سمعنا في هذا الموضوع آراء عدة؟أفتونا، جزاكم الله خيرًا.","title":"حكم الزكاة في الحلي المعد للزينة","answer":"الجواب: اختلف العلماء في الحلي المعدة للبس والملبوسة، والصواب في ذلك أن فيها الزكاة، هذا هو الصواب؛ لعدة أحاديث وردت في الباب، فإذا بلغ مجموع الحلي من قلائد وأسورة ونحو ذلك نصاب الزكاة وهو عشرون مثقالًا من الذهب؛ وجبت فيها الزكاة، ومقدارها بالعملة الموجودة أحد عشر جنيه سعودي ونصف، هي ثلاثة أسباع جنيه، لكن الثلاثة الأسباع قرب النصف، والنصف أوضح للناس.  فالحصيلة: أنها أحد عشر جنيه ونصف، إذا بلغت الحول بهذا المقدار أو أكثر من ذلك؛ ففيها الزكاة، فإن كانت أقل من هذا فلا زكاة فيها، ولو كانت ملبوسة، هذا هو الصواب من قولي العلماء، نعم.","link":"https://binbaz.org.sa/fatwas/14070/حكم-الزكاة-في-الحلي-المعد-للزينة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_703/nour_70304.mp3","categories":["الصداق","زكاة النقدين","قضايا المرأة"]},{"id":15564,"question":"من أسئلة هذه السائلة تسأل: هل زكاة الذهب ضروري، وإذا كان لبسه في المناسبات وليس للبيع والشراء؟ أفيدونا بذلك.","title":"حكم إخراج الزكاة عن الذهب المعد للبس","answer":"الجواب: الصحيح وجوب الزكاة في الحلي من الذهب والفضة، هذا هو الراجح من أقوال العلماء؛ إذا بلغ النصاب، وحال عليه الحول، على المرأة أن تزكي ذهبها فضةً أو ذهبًا إذا حال عليه الحول، وكان نصابًا، نعم. المقدم: حفظكم الله يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/14100/حكم-اخراج-الزكاة-عن-الذهب-المعد-للبس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_691/nour_69131.mp3","categories":["الصداق","زكاة النقدين","قضايا المرأة"]},{"id":15577,"question":"لها سؤال آخر تقول: ما هو الحكم بالنسبة لزكاة الحلي: الذهب أو الفضة إذا وجبت الزكاة فيهما، فما هو النصاب؟ وهل يقدر على أساس الوزن، أم العيار؟","title":"حكم زكاة الحلي ونصابها","answer":"الجواب: الذهب والفضة من الأموال الزكوية، ويقدر النصاب بالوزن، فنصاب الذهب عشرون مثقالًا، ومقدار ذلك أحد عشر جنيهًا ونصف الجنيه من الجنيه السعودي، واثنان وتسعون غرامًا بالغرام.  ومقدار نصاب الفضة مائة وأربعون مثقالًا، ومقدار ذلك ستة وخمسون ريالًا بالفضة، فإذا بلغ النصاب ما ذكر وجبت الزكاة، ولو كانت حليًا من الذهب أو الفضة، فإنها تزكى متى بلغت النصاب وجب أن تزكى وإن كانت حليًا تلبس على الصحيح من أقوال العلماء؛ لما ورد في هذا من الأحاديث الصحيحة؛ ومن جملتها: حديث عبد الله بن عمرو بن العاص -رضي الله عنهما-: «أن امرأة أتت النبي ﷺ وعليها مسكتان من ذهب فقال: أتعطين زكاة هذا؟ قالت: لا، قال: أيسرك أن يسورك الله بهما يوم القيامة سوارين من نار؟ فألقتهما، وقالت: هما لله ولرسوله، وهكذا حديث ما من صاحب ذهب ولا فضة لا يؤدي زكاتها إلا إذا كان يوم القيامة صفحت له صفائح من نار الحديث، وهكذا حديث أم سلمة: «أنها كانت تلبس أوضاحًا من ذهب فقالت: يا رسول الله، أكنز هذا؟ فقال: ما بلغ أن يزكى فزكي فليس بكنز. فدل ذلك على أن ما لم يزك من الحلي وغيرها من الذهب والفضة، فإنه يسمى كنزًا، يعذب صاحبه، نسأل الله السلامة. فالخلاصة: أن الحلي تزكى، ولو كانت تلبس من الذهب والفضة، إذا بلغت النصاب، وهو أحد عشر جنيهًا ونصف من الذهب، ومائة وأربعون مثقالًا من الفضة، وبالمثاقيل في الذهب عشرون مثقالًا من الذهب، وبالغرامات اثنان وتسعون غرامًا من الذهب، فإذا بلغ هذا زكي، فالاعتبار بالوزن. أما من جهة القيمة فينظر قيمته وقت الحول في السوق ماذا يساوي الذهب في السوق؟ فيزكى حسب القيمة، وإن كان كثيرًا وزكاه من الذهب كفى، فلو كانت الحلي تبلغ أربعين جنيهًا زكاها بجنيه واحد ربع العشر، فإن عشر أربعة الجنيهات عشرها الربع، فيها واحد، فإذا أخرج جنيهًا واحدًا وأعطاه بعض الفقراء كفى، وإن أخرج قيمته من النقود ووزعه بين الفقراء كفى، نعم. المقدم: نعم.","link":"https://binbaz.org.sa/fatwas/14118/حكم-زكاة-الحلي-ونصابها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_692/nour_69203.mp3","categories":["الصداق","زكاة النقدين","قضايا المرأة"]},{"id":15619,"question":"تقول السائلة من اليمن في آخر أسئلتها: سماحة الشيخ، هل في حلي المرأة المستعمل للزينة زكاة؟","title":"حكم زكاة الحلي المستعملة","answer":"الجواب: الحلي من الذهب والفضة فيها خلاف بين العلماء، كثير من أهل العلم يرون أنه لا زكاة فيها؛ لأنها مستعملة ليست للنماء، وذهب آخرون من أهل العلم إلى أن فيها الزكاة، وهو الأصح، وهو الأرجح، إذا بلغت النصاب، وحال عليها الحول ففيها الزكاة؛ لأن النبي ﷺ أمر امرأة عليها الحلي أن تؤدي الزكاة، وقالت له أم سلمة لما عرضت عليه حليها: أفي هذا زكاة؟ قال: ما بلغ أن يزكى فزكي فليس بكنز لما قالت له: أكنز هذا؟ قال: ما بلغ أن يزكى فزكي فليس بكنز فدل على أن الحلي تزكى، وأنها إذا لم تزك فهي كنز، هذا هو الأرجح، وهذا هو الأحوط، نعم.\nالمقدم: أحسن الله إليكم. الشيخ: إذا بلغت الحلي النصاب ذهبًا أو فضة، نعم.","link":"https://binbaz.org.sa/fatwas/14157/حكم-زكاة-الحلي-المستعملة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_571/57105.mp3","categories":["زكاة النقدين"]},{"id":15620,"question":"ونعرض عليه أول سؤال ورد من المستمع عبدالواحد محمد من العراق، محافظة الأنبار.سؤاله أو هما في الواقع سؤالان:سؤاله الأول يقول: رجل عنده منزلان قديمان، فباع أحدهما، وهدم الآخر على أن يجدد بناءه، ولكن لعدم توفر المواد المطلوبة للبناء، فقد تأخر فيه إلى أن حال الحول على قيمة البيت الذي باعه، وبعد حولان الحول وجد المواد اللازمة لبناء البيت، وقام بإنشاء البيت الجديد، وأكمل بناءه، وسكن فيه، فهل يلزمه دفع زكاة عن المبلغ الذي حال عليه الحول من قيمة البيت المباع، والتي رصدها لبناء البيت الجديد؟ أفيدونا، أثابكم الله.","title":"حكم الزكاة عن المال المعد للبناء","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله رب العالمين، والعاقبة للمتقين، والصلاة والسلام على عبده ورسوله وخيرته من خلقه، وأمينه على وحيه، نبينا وإمامنا وسيدنا محمد بن عبد الله وعلى آله وأصحابه ومن سلك سبيله واهتدى بهداه إلى يوم الدين، أما بعد: فالجواب عن هذا السؤال أن النقود التي يرصدها المسلم لتعمير بيت، أو لقضاء دين، أو للزواج، أو لأغراض أخرى متى حال عليها الحول وجب عليه زكاتها؛ لعموم الأدلة، الأدلة دالة على أن جميع النقود التي يحول عليها الحول وهكذا جميع السلع والأمتعة التي يحول عليها الحول وهي للتجارة للبيع كلها فيها الزكاة إذا حال عليها الحول ولو كان صاحبها -أي: النقود- أرصدها ليعمر بها بيتًا لسكن، أو ليشتري بها حاجات للبيت، أو ليتزوج منها، أو ليقضي بها ديونًا، أو غير ذلك، فالصواب أن فيها الزكاة لعموم الأدلة، نعم.","link":"https://binbaz.org.sa/fatwas/14158/حكم-الزكاة-عن-المال-المعد-للبناء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_696/nour_69601.mp3","categories":["زكاة النقدين"]},{"id":15629,"question":"هذه سائلة للبرنامج تقول -سماحة الشيخ-: تذكر بأنها امرأة توفي عنها الزوج، وتعمل بمدرسة أهلية، وتحمد الله، وتستلم من ذلك راتب يكفيها، ويكفي أبناءها، والحمد لله. تقول السائلة: وقد ترك لي زوجي مبلغًا من المال، وفي بلدي ما يكفيني ويكفي أبنائي، ولدي طفل صغير عمره ما يقارب من سنتين، ويأتي بعض الإخوان جزاهم الله خيرًا ببعض الأغراض والمال ويعطونه لهذا الصغير، فأرفض ذلك أنا؛ لأنني لست بحاجة إليه، والحمد لله، وهناك من يستحق هذا، وهذا مما يضايقني ويجرح مشاعري، وعندما أجلس مع نفسي أخشى أن أكون قد عصيت الله في قوله: يَسْأَلُونَكَ مَاذَا يُنفِقُونَ قُلْ مَا أَنفَقْتُمْ مِنْ خَيْرٍ فَلِلْوَالِدَيْنِ وَالأَقْرَبِينَ وَالْيَتَامَى وَالْمَسَاكِينِ وَابْنِ السَّبِيلِ [البقرة:215] فهل أكون منعت مال هذا اليتيم وعصيت الله؟","title":"حكم الامتناع عن أخذ ما يهدى لليتيم، وكيفية زكاة أمواله","answer":"الجواب: المشروع لك ألا ترديه، النبي ﷺ قال لـعمر: ما جاءك من هذا المال وأنت غير مشرف ولا سائل فاقبله، وما لا فلا تتبعه نفسك فأنت إذا جاء للطفل احفظيه للطفل، هذه العادة بين المسلمين إعطاء الأطفال، وتقديم الهدايا المناسبة للأطفال، فهذه عادة معروفة، فإذا جاء للطفل شيء فاقبليه واحفظيه واجعليه من ماله، نعم. المقدم: أحسن الله إليكم، تقول السائلة: ترك لي زوجي مبلغًا من المال وقسمته على أبنائي حسب الشريعة الإسلامية، ولكن مال هذا الصغير أود أن أحتفظ به حتى يبلغ، هل أدفع عنه زكاة أم لا؟ وإن كان هناك زكاة فقد ترك زوجي المال في ذي الحجة فهل أدفع ذلك في رمضان أم في ذي الحجة؟\nالشيخ: إذا حفظت المال عندك، وحال عليه الحول ادفعي المال في تمام الحول على رأس الحول، فإذا كان المال حصل بأن مات الزوج في رمضان فالزكاة تكون في رمضان على المال الذي بقي، والنقود التي بقيت إلى رمضان، وإذا مات في ذي الحجة فالزكاة في ذي الحجة، وهكذا على رأس السنة. وإن قدمت الزكاة قبل تمام نصف الحول فلا حرج، إذا قدمت فلا بأس ليعطاها الفقراء، والزكاة عنك وعن أموال أولادك إذا كان لهم أموال تزكين أموالهم إذا كان لهم أموال من النقود -ذهب أو فضة- زكيها، وهكذا إذا كان لهم أراضٍ للبيع معدة للبيع تزكى إذا حال عليها الحول، سواء كانوا بالغين أو غير بالغين الزكاة على الجميع، إذا حال الحول على المال بعد موت الميت يزكيه صاحبه، إن كان ذهب أو فضة يزكى إذا حال الحول، وإن كان عقارًا للبيع يزكى على رأس الحول، ومن قدم الزكاة قبل تمام الحول قدمها للمصلحة رأى فقراء وقدم لهم الزكاة فلا بأس لا حرج. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14170/حكم-الامتناع-عن-اخذ-ما-يهدى-لليتيم-وكيفية-زكاة-امواله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_571/57112.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":15643,"question":"هذا سؤال من الأخت المستمعة (أ. ص. ع) من جمهورية مصر العربية، تقول: أملك حليًا ذهبية وألبسها، وقد اشتريتها منذ زمن، ولكني كل فترة أزيد عليها إلى أن بلغ ثمنها الآن حوالي ألف وخمسمائة جنيه مصري، فهل يحق دفع زكاة على هذه الحلي؟ أم أنها تعتبر زينة أتحلى بها؟وكذلك لي طفلة صغيرة اشتريت لها ذهبًا؛ لكي تلبسه، وأنا أحتفظ لها بهذا الذهب حتى تكبر فتلبسه، أي: أنه يكون مثل المال المركون، وثمنه حوالي ثمانمائة جنيه مصري، فهل يجب عليه دفع زكاة لهذا الذهب؛ لأن الله  توعد الذين يكنزون الذهب والفضة بعذاب أليم إن لم يخرجوا زكاتهما، وإذا لم يكن عليه زكاة فما معنى الكنز إذًا؟","title":"حكم إخراج الزكاة عن الذهب المعد للزينة","answer":"الجواب: هذه المسألة فيها خلاف بين أهل العلم في حلي المرأة التي تلبسها، والصواب أن فيها الزكاة، هذا هو الأرجح من أقوال أهل العلم، أن فيها الزكاة في حلي المرأة، وحلي البنت جميعًا إذا بلغ كل منهما النصاب، والنصاب عشرون مثقالًا من الذهب مقداره اثنان وتسعون غرامًا وهو بالجنيه السعودي أحد عشر جنيهًا ونصف الجنيه، فإذا كان الذهب الذي لديك يبلغ هذا المقدار ففيه الزكاة، وهكذا الذي عند ابنتك إذا كان بلغ هذا المقدار فيه الزكاة وهي ربع العشر من كل ألف خمسة وعشرون، من كل ألف خمس وعشرون، هذا هو الزكاة في الذهب ولو كان يلبس ولو كان للزينة، هذا هو المختار؛ لقول النبي ﷺ للمرأة التي جاءت إليه وفي يد ابنتها مسكتان من ذهب: أتعطين زكاة هذا؟ قالت: لا. قال: أيسرك أن يسورك الله بهما يوم القيامة سوارين من نار؟ فألقتهما وقالت: هما لله ولرسوله».\nوكانت أم سلمة -رضي الله عنها- تلبس أوضاحًا من ذهب فقالت: «يا رسول الله، أكنز هذا؟ فقال: ما بلغ أن يزكى فزكي فليس بكنز فدل ذلك على أن الحلي تعتبر كنزًا إذا لم تزك. فالواجب عليك إخراج الزكاة عن حليك وعن حلي البنت إذا بلغ كل منهما النصاب الذي سمعتيه؛ وهو عشرون مثقالًا من الذهب، وبعبارة أخرى: اثنان وتسعون غرامًا، وبعبارة ثالثة: أحد عشر جنيهًا ونصف ذهب سعودي أو فرنجي الموجود الآن، هذا هو مقدار النصاب، فإذا كان أقل من هذا فليس فيه زكاة. والواجب ربع العشر، يعني: سهم من أربعين، من كل ألف خمسة وعشرون، هذا هو الواجب في الذهب والفضة، نعم.","link":"https://binbaz.org.sa/fatwas/14188/حكم-اخراج-الزكاة-عن-الذهب-المعد-للزينة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_697/nour_69704.mp3","categories":["الصداق","زكاة النقدين","قضايا المرأة"]},{"id":15663,"question":"سؤاله الآخر يقول: منذ خمس سنوات تقريبًا بدأت أقترض من أحد الأشخاص إلى أن بلغ ما له في ذمتي ما يقارب خمسين ألف ليرة، فهل يجب علي دفع زكاتها أنا أم صاحبها يزكيها؟","title":"من يدفع زكاة الدين؟","answer":"الجواب: الديون التي على الإنسان زكاتها على صاحبها، وليس على الغريم زكاة، إنما الزكاة على من له الدين، إذا كانت الأموال التي اقترضها قد صرفها في حاجاته غير موجودة لديه يكون قد صرفها في حاجاته، اشترى بها مثلًا سيارة يستعملها لحاجته، يستعملها تكسي مثلًا، اشترى بها أرضًا للسكن، اشترى بها فرشًا لبيته، أو ما أشبه ذلك هذه ليس فيها زكاة، أما إذا كانت الديون عنده بأعيانها أخذها قرضًا، ولكنها باقية الفلوس عنده، الدراهم عنده موجودة، ما أنفقها، فعليها الزكاة إذا حال عليها الحول، يزكيها هو إذا حال عليها الحول. أما صاحبها الذي أقرضه إياها فهذا ينظر فيه، فإن كان من عليه الدين مليئًا زكاها صاحبها أيضًا، وإن كان معسرًا أو مماطلًا فلا زكاة عليها بالنسبة إلى صاحبها. أما بالنسبة إلى الذي أخذها واقترضها، فالأمر كما تقدم......، وإنما الزكاة على المقرض إذا كان المقرض مليئًا غير مماطل، فإن على المقرض أن يزكيها إذا حال عليها الحول، نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/14206/من-يدفع-زكاة-الدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_700/nour_70002.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":15768,"question":"يقول: إلى أي وقت يمكن تأخير أداء الزكاة بعذر، وهل يمكن التعجل فيها ومتى؟","title":"حكم تأخير الزكاة وتعجيلها","answer":"الجواب: المعذور يؤدي الزكاة متى كان العذر، فإذا مثلًا حلت الزكاة في رمضان، وليس عنده مال، ثم يسر الله المال في شوال، أو في ذي القعدة أخرج الزكاة، أو في إبله أو غنمه، وليس عنده النصاب ليس عنده الزكاة الواجبة يطلبها يلتمسها من هاهنا وهاهنا، فإذا وجدها أخرجها، سلمها للعمال، إن كان العمال يأتونه، وإلا تصدق بها. المقصود: أنه متى وجد الزكاة بادر بها، وعليه السعي إلى تحصيلها من حين الرجوع؛ لكي تجب من حين يتم الحول، يسعى ويجتهد حتى يحصل الواجب ويخرجه، ولا يتساهل، وإن عجلها فلا بأس، إن عجل الزكاة قبل وقتها، والنصاب موجود، وعجل الزكاة، فلا بأس، لا حرج في ذلك. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14361/حكم-تاخير-الزكاة-وتعجيلها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_741/nour_74114.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":15771,"question":"يقول: إلى أي وقت يمكن تأخير أداء الزكاة بعذر، وهل يمكن التعجل فيها ومتى؟","title":"حكم تأخير الزكاة وتعجيلها","answer":"الجواب: المعذور يؤدي الزكاة متى كان العذر، فإذا مثلًا حلت الزكاة في رمضان، وليس عنده مال، ثم يسر الله المال في شوال، أو في ذي القعدة أخرج الزكاة، أو في إبله أو غنمه، وليس عنده النصاب ليس عنده الزكاة الواجبة يطلبها يلتمسها من هاهنا وهاهنا، فإذا وجدها أخرجها، سلمها للعمال، إن كان العمال يأتونه، وإلا تصدق بها. المقصود: أنه متى وجد الزكاة بادر بها، وعليه السعي إلى تحصيلها من حين الرجوع؛ لكي تجب من حين يتم الحول، يسعى ويجتهد حتى يحصل الواجب ويخرجه، ولا يتساهل، وإن عجلها فلا بأس، إن عجل الزكاة قبل وقتها، والنصاب موجود، وعجل الزكاة، فلا بأس، لا حرج في ذلك. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14361/حكم-تاخير-الزكاة-وتعجيلها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_741/nour_74114.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":15789,"question":"مستمع من السودان هو محمد الحوري -فيما يبدو- بعث برسالة وضمنها سؤالًا واحدًا يقول فيه: أملك ستة آلاف ريال، ولها عندي ستة أشهر، وبعثتها إلى السودان، هل عليها زكاة؟","title":"وجوب الزكاة بتمام الحول وبلوغ النصاب","answer":"الجواب: إذا تم عليها الحول، إذا مكثت في السودان وتم عليها سنة زكيها، أما إذا أرسلتها للسودان لتصرف في حاجات أهلك، أو لقضاء دين، أو في تعمير مسكنك، أو ما أشبه ذلك، فلا زكاة فيها؛ لأنه ما تم عليها الحول، ستة أشهر ليس بحول، الحول اثنا عشر شهرًا، فإذا تم عليها الحول وهي عندك أو عند وكيلك فعليك الزكاة، فإن صرفت في حاجاتك قبل تمام الحول، أو في قضاء دين، أو نحو ذلك مما تصرف فيه هذه الدراهم، فإنه لا زكاة فيها، كما لو بنى بها وكيلك شيء في بيتك حاجة، أو أصلح أخراب في بيتك، أو أنفقها على عيالك قبل تمام الحول، أو أنفقتها أنت قبل تمام الحول فلا شيء فيها، إنما الزكاة تجب فيها إذا بقيت حتى تم عليها الحول، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14374/وجوب-الزكاة-بتمام-الحول-وبلوغ-النصاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_742/nour_74211.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":15812,"question":"يقول: يا سماحة الشيخ، أنا أعمل في المملكة، وكل شهر أستلم مرتبي، فعندما يحول الحول كيف أخرج الزكاة؟ هل عن الشهر الأول الذي حال عليه الحول، أم عن مرتب السنة كلها التي عملتها من أول شهر إلى آخر الشهر الذي أخرج فيه الزكاة؟","title":"كيفية إخراج الزكاة من الراتب","answer":"الجواب: كلما حال الحول على الراتب فزكه، الشهر الأول يزكى أولًا، والشهر الثاني هكذا، والثالث هكذا، كلما تم الحول على الراتب وجبت فيه الزكاة، إلا إذا أردت تقديم الزكاة عن الأحوال المتأخرة قدمتها مع الأول، فلا حرج عليك، لا بأس، يجوز تقديم الزكاة، لكن لا يلزمك إلا إذا تم الحول على كل راتب، نعم. المقدم: جزاكم الله خيرًا، بمعنى: يزكي راتب محرم في محرم، وصفر في صفر، وهكذا.\nالشيخ: وهكذا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14400/كيفية-اخراج-الزكاة-من-الراتب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_743/nour_74314.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":15827,"question":"السائل يقول في هذا  حفظكم الله بأنه موظف، ويحتفظ بمبلغ من المال في كل شهر من راتبه لوقت الحاجة أو للزواج، فهل يجب على ما ادخره زكاة؟","title":"حكم إخراج الزكاة من المال المدخر","answer":"الجواب: نعم عليه زكاة، كل جزء حال عليه الحول يزكيه، كل جزء ادخره وحال عليه الحول يزكيه، وإن زكى الجميع تبعًا للجزء الأول فلا بأس، طيب جزاه الله خيرًا، وإلا كل جزء عليه زكاته إذا حال حوله في رمضان، ادخر ألفًا عليه زكاته إذا جاء رمضان، في شوال ادخر ألفًا ثانيًا عليه زكاته إذا جاء شوال، في ذي القعدة ادخر ألفًا ثالثًا إذا جاء ذي القعدة يزكيه، وهكذا، ولو زكاهم جميعًا في الحول الأول في رمضان، كفى، والحمد لله، جزاه الله خيرًا، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14416/حكم-اخراج-الزكاة-من-المال-المدخر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_575/57519.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":15870,"question":"هل في الذهب الذي يلبس زكاة أم لا؟أفيدونا، جزاكم الله خيرًا.","title":"زكاة الذهب الملبوس","answer":"الجواب: إذا بلغ الذهب الذي يلبس، أو الفضة النصاب، ففيه الزكاة على الراجح من أقوال العلماء، فيه خلاف بين أهل العلم، منهم من رأى فيه الزكاة، ومنهم من رأى عدم الزكاة، والصحيح الذي نفتي به أنه يزكى إذا بلغ النصاب، سواء كان أسورة أو قلائد أو غير ذلك، إذا بلغ النصاب ذهب أو فضة يزكى، في الألف خمسة وعشرين ربع العشر؛ لأن الرسول ﷺ رأى على امرأة أسورة، فقال: أتعطين زكاة هذا؟ قالت: لا. قال: أيسرك أن يسورك الله بهما يوم القيامة بسوارين من نار فألقتهما، وقالت: هما لله ورسوله» وكانت أم سلمة أم المؤمنين -رضي الله عنها- تلبس أوضاحًا من ذهب، فقالت: «يا رسول الله، أكنز هذا؟ فقال: ما بلغ أن يزكى فزكي فليس بكنز ولم يقل لها: الحلي ما فيه زكاة، وإنما إذا بلغ النصاب يزكى، فإذا ما زكي فهو كنز؛ يكوى ويعذب به صاحبه. فالمقصود: أن الراجح أن الحلي من الذهب والفضة إذا بلغت النصاب، وحال عليها الحول، ففيها: الزكاة.  والنصاب: عشرون مثقالًا من الذهب، أحد عشر جنيه ونصف سعودي، ومن الفضة: مائة وأربعون مثقالًا، يعني: ستة وخمسين ريالًا فضة، وما يعادلها، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14466/زكاة-الذهب-الملبوس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_744/nour_74413.mp3","categories":["زكاة النقدين"]},{"id":15946,"question":"هذه السائلة الأخت أم ياسر من الرياض تقول -سماحة الشيخ-: هل يجوز أن أعطي زكاة المال لامرأة لا تصلي؟","title":"حكم إعطاء الزكاة لتارك الصلاة","answer":"الجواب: لا يعطى، لا تعطيها الزكاة، أعطيها امرأة تصلي، ابحثي عن الفقراء الطيبين، الذي ما يصلي كافر، نعوذ بالله، يقول النبي ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر ولا يعطى الكفرة إلا المؤلفة قلوبهم، يعطوا من الزكاة، المؤلفة قلوبهم من رؤساء العشائر، وكبار الناس الذين إذا هداهم الله هدى الله بهداهم غيرهم، وحصل بهداهم نفع كبير للناس، أما أفراد الناس الكفرة لا، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14552/حكم-اعطاء-الزكاة-لتارك-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_578/57809.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":15951,"question":"تقول أم عبد العزيز في سؤالها الثاني -يا سماحة الشيخ-: هل يجوز أن أعطي زكاة المال لشخص متزوج، وله بنت صغيرة عنده سيارة أجرة، يكتسب منها في الشهر حوالي سبعمائة جنيه، ويمر شهر آخر تكون معطلة السيارة؟ علمًا بأنه موظف حكومي مرتبه مائة وخمسين جنيه.","title":"حكم إعطاء الزكاة لمن له مصدر دخل","answer":"الجواب: إذا كنت تعلمين أنه فقير، وأنه عرض له حاجة وفقر فلا بأس، وإلا فالذي عنده أسباب تقوم بحاله لا يعطى الزكاة، ولكن إذا عرض عارض، وعرفت أنه فقير، فلا بأس أن تعطيه من الزكاة، وإلا فالأصل أن من كان له أسباب تقوم بحاله لا يعطى من الزكاة. المقدم: لعلكم -يا سماحة الشيخ- حفظك الله، تبينون من هم أهل الزكاة الذين تجوز إعطاؤهم.\nالشيخ: مثلما قال الله -جل وعلا-: إِنَّمَا الصَّدَقَاتُ لِلْفُقَرَاءِ وَالْمَسَاكِينِ وَالْعَامِلِينَ عَلَيْهَا وَالْمُؤَلَّفَةِ قُلُوبُهُمْ وَفِي الرِّقَابِ وَالْغَارِمِينَ وَفِي سَبِيلِ اللَّهِ وَاِبْنِ السَّبِيلِ [التوبة:60].\nهؤلاء هم أهل الزكاة: (الفقراء) معروفون.\nوالمساكين هم الذين لا يجدون ما يكفيهم في السنة، أسبابهم ضعيفة، أو ليس لهم أسباب؛ هؤلاء هم الفقراء والمساكين.\nوالعاملين عليها هم العمال الذين يبعثهم ولي الأمر يخرصون النخيل والثمار والغنم والإبل، ويأخذون زكاة الإبل والغنم، هذه يقال لهم: عمال يبعثهم ولي الأمر يعطيهم من الزكاة، أو من بيت المال.\nوالمؤلفة قلوبهم: هم الرؤساء والسادة من الناس الذين إذا أسلموا هداهم الله، ولو كانوا كفرة يعطون، أو كانوا مسلمين يعطون يرجى بعطيتهم إسلام نظرائهم أو قوة إيمانهم، هؤلاء هم المؤلفة قلوبهم، السادة الكبار المطاعون في عشائرهم الذين يرجى بعطائهم قوة إيمانهم أو إسلام نظرائهم.\nوفي الرقاب: عتق الرقاب، ويشترى من الزكاة رقاب تعتق، وهكذا المكاتبون الذين اشتروا أنفسهم من السادة بدين في الذمة يعطى المكاتب ما يسد به الدين الذي عليه الذي اشترى به نفسه من سيده.\nوالغارمين: أهل الدين الذين عليهم ديون، وهم عاجزون سواء كانت الديون لإصلاح ذات البين أو لحاجاتهم، فإذا كانوا عاجزين عن قضاء الديون هؤلاء هم الغارمون يعطوا من الزكاة للدين لقضاء الدين.\nوفي سبيل الله: الجهاد، يعطى الغزاة ما يعينهم على الغزو.\nوابن السبيل الذي يمر بالبلد وينقطع، ما عنده شيء، يعطى ولو كان غنيًا في بلاده، إذا مر بالبلد وأنت تعلم أنه منقطع، أو قال: إنه منقطع، وأنت لا تعرف حاله، وقال: إنه منقطع؛ تعطيه من الزكاة، نعم. المقدم: أحسن الله إليكم، وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/14561/حكم-اعطاء-الزكاة-لمن-له-مصدر-دخل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_578/57810.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":15974,"question":"لها سؤال آخر تقول فيه: امرأة لديها سبائك من الفضة، أو أساور من الفضة، ومضى عليها زمن قديم، وهي تحتفظ بها، وليس الغرض منها المتاجرة ولا اللبس، وإنما تحتفظ بها كتحف وآثار، فهل عليها زكاة أم لا؟ وإذا كانت تجب فيها الزكاة فكم النصاب الذي يجب إخراجه، وماذا تفعل في زكاة الأعوام الماضية؟","title":"هل على الفضة المحتفظ بها كتحف وآثار زكاة؟","answer":"الجواب: الحلي فيها الزكاة ولو كانت للبس، ولو كانت للاحتفاظ للحاجات الأخرى، لا بد من الزكاة فيها إذا بلغت النصاب على الصحيح من أقوال العلماء، ولو كانت للبس أو العارية أو الادخار، عليها أن تزكيها إذا بلغت النصاب، والنصاب في الذهب عشرون مثقالًا، ومقداره من الجنيه السعودي إحدى عشر جنيه ونصف سعودي، أو إفرنجي، إذا بلغ هذا فعليها الزكاة، وما كان أقل من ذلك فليس فيه زكاة، والزكاة ربع العشر، من كل ألف خمس وعشرون ريالًا، والعشرة الآلاف فيها مائتان وخمسون، فيها ربع العشر، هذه الزكاة في الذهب والفضة، والفضة نصابها مائة وأربعون مثقالًا، ومقدارها بالريال السعودي ستة وخمسون ريالًا، فعليها أن تزكي الفضة ربع العشر، والذهب ربع العشر، ولو كانت حلي على الصحيح من أقوال العلماء؛ لقول النبي ﷺ: ما من صاحب ذهب ولا فضة لا يؤدي زكاتها إلا إذا كان يوم القيامة صفحت له صفائح من نار.\nفينبغي أداء الزكاة مطلقًا هذا هو الصواب ولو كانت للبس، ولما ثبت عنه ﷺ «أن امرأة دخلت عليه، وعليها مسكتان من ذهب، فقال: أتعطين زكاة هذا؟ قالت: لا، قال: أيسرك أن يسورك الله بهما يوم القيامة سوارين من نار؟! فألقتهما وقالت: هما لله ولرسوله» نعم.\nالسائلة الأولى عن الحلي تسأل أيضًا عما مضى من الأعوام، والجواب عما مضى من الأعوام ليس عليها شيء، ما دام ما علمت فليس عليها مما مضى شيء ولكن تستقبل، تزكي في المستقبل بعدما علمت. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14610/هل-على-الفضة-المحتفظ-بها-كتحف-واثار-زكاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_680/nour_68005.mp3","categories":["زكاة النقدين"]},{"id":16078,"question":"يقول: الرجل يشتغل عند عمه سنة، وإجار عمله كله عند عمه، كيف يزكي؟ جزاكم الله خيرًا؟","title":"كيفية زكاة أجرة العامل التي عند صاحب العمل","answer":"الجواب: إذا كان المال الذي عند العم يبلغ النصاب، وحال عليه الحول؛ عليه أن يزكيه، وإن كان عند عمه إذا كان مليئًا ليس بمعسر، ولا مماطل؛ فإن العامل يزكي. أما إن كان عمه معسرًا، ما يقدر يسلم الدين، أو مماطلًا، يطلبه حقه، ولا يعطيه حقه، فليس عليه زكاة حتى يقبضه، فإذا قبضه؛ استقبل به حولًا جديدًا هذا العامل. أما إن كان عمه مستعدًا يعطيه، ولكنه جلس عنده، كالأمانة؛ فإنه يزكيه كلما حال عليه الحول، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14711/كيفية-زكاة-اجرة-العامل-التي-عند-صاحب-العمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_749/nour_74908.mp3","categories":["زكاة النقدين"]},{"id":16123,"question":"يقول: سماحة الشيخ! أعرف أن هناك كثيرًا من النساء لديهن ذهب كثير، ولا يلبسنه إلا في المناسبات، فهل في مثل هذا الذهب زكاة، أم يعتبر من الادخار؟ جزاكم الله خيرًا.","title":"هل الذهب الذي لا يلبس إلا في المناسبات فيه زكاة؟","answer":"الجواب: الموضوع فيه خلاف بين العلماء، منهم من رأى أن لا زكاة فيه إذا كان يستعمل، ومنهم من رأى أن فيه الزكاة؛ لعموم الأدلة الشرعية في ذلك، وهذا هو الصواب الذي نرجحه، ونفتي به، أن في الحلي الزكاة إذا بلغ النصاب، وحال عليه الحول لعموم الأدلة الدالة على وجوب الزكاة في الذهب والفضة، وعدم الدليل على استثناء ذلك، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14784/هل-الذهب-الذي-لا-يلبس-الا-في-المناسبات-فيه-زكاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_749/nour_74918.mp3","categories":["زكاة النقدين"]},{"id":16351,"question":"تسأل سماحتكم شيخ عبدالعزيز فتقول: هل أزكي الحلي التي أتحلى بها غالب الأحيان؟","title":"زكاة الحلي المستعمل","answer":"الجواب: الحلي من الذهب والفضة فيها خلاف بين العلماء، جماعة من العلماء يقولون: لا زكاة فيها إذا كانت تستعمل، وآخرون يقولون: فيها الزكاة، ولو أنها تستعمل إذا بلغت النصاب، وهذا القول أصح، الأصح من أقوال العلماء أنها تزكى، إذا بلغت النصاب؛ لأنه جاء في الأحاديث ما يدل على ذلك.. جاءته امرأة في يدها مسكتان -يعني سوارين- من ذهب فقال: أتعطين زكاة هذا؟ قالت: لا، قال: أيسرك أن يسورك الله بهما يوم القيامة سوارين من نار؟. وقال لعائشة لما كان عندها فتخات لا تزكيها هي حسبك من النار. وقال لأم سلمة، وكانت تلبس أوضاحًا من ذهب قالت: أكنز هما؟ فقال: ما زكي فليس بكنز فدل على أن هذه الحلي تزكى، وإن لم تزك؛ فهي كنز، يعذب به صاحبه. فالواجب على النساء إذا كان عندهن حلي من الذهب والفضة تبلغ النصاب الواجب عليهن الزكاة في أصح قولي العلماء إذا كانت الحلي تبلغ النصاب، والنصاب أحد عشر جنيهًا ونصفًا، يعني عشرين مثقالًا، اثنين وتسعين غرامًا تقريبًا، فإذا كانت الحلي تبلغ هذا؛ وجبت الزكاة في الذهب، أما الفضة فنصابه مائة وأربعون مثقالًا، يعني ستة وخمسون ريالًا، بالريال السعودي الفضة، إذا بلغت الفضة هذا النصاب يعني: ستة وخمسون ريالًا، يعني: مائة وأربعون مثقالًا فإنها تزكى، هذا هو الصواب، هذا هو الأرجح، وهذا هو الحق، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15045/زكاة-الحلي-المستعمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_714/nour_71414.mp3","categories":["الصداق","زكاة النقدين","قضايا المرأة"]},{"id":16399,"question":"من ليبيا إحدى الأخوات بعثت برسالة وقعت في نهايتها بقولها: ابنتكم عزة بون خيلة، تسأل وتقول: هل تجوز الزكاة في الأقارب، مثل البنت، والأخت والعم والعمة، والدي يعطي كل سنة من الزكاة بناته، وإخوته، وأخواته، وسمعت من قال: لا تجوز الزكاة في البنات؛ لأنهن سيرثن والدهن بعد موته، علمًا بأن أخواتي متزوجات، وبعضهن حالة زوجها المادية ضعيفة، أفيدونا في هذا الموضوع إفادة كافية؟ جزاكم الله خيرًا.","title":"ما حكم دفع الزكاة للأقارب؟","answer":"الجواب: الأقارب فيهم تفصيل، فإذا كان القريب من الفروع كالأولاد، وأولاد البنين، وأولاد البنات، والبنات أنفسهن لا يعطون من الزكاة، هذا الذي عليه أهل العلم، ولكن ينفق عليهم والدهم إذا كانوا فقراء، ينفق عليهم من ماله، وهكذا الآباء، والأجداد، والأمهات لا يعطوا من الزكاة.  أما بقية الأقارب كالإخوة، والأعمام، وبني العم، وبني الخال، وبني الخالة، وأشباههم، فيعطون الزكاة إذا كانوا فقراء، أو غارمين، عليهم ديون، ما يستطيعون أداءها، لقوله سبحانه: إِنَّمَا الصَّدَقَاتُ لِلْفُقَرَاءِ وَالْمَسَاكِينِ وَالْعَامِلِينَ عَلَيْهَا وَالْمُؤَلَّفَةِ قُلُوبُهُمْ وَفِي الرِّقَابِ وَالْغَارِمِينَ وَفِي سَبِيلِ اللَّهِ وَاِبْنِ السَّبِيلِ [التوبة:60] وتكون صدقة، وصلة كما قال النبي ﷺ: الصدقة على ذي الرحم صدقة وصلة. وأما الآباء، والأجداد، والأمهات، والذرية؛ فليسوا من أهل الزكاة، لا يعطون من الزكاة؛ لأنهم شيء واحد، فالأولاد بضعة منه، وهو بضعة من أبيه وأمه، فالواجب عليه أن ينفق عليهم من صلب ماله، لا من الزكاة نعم، إذا كانوا فقراء، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15115/ما-حكم-دفع-الزكاة-للاقارب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_811/nour_81112.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":16427,"question":"من المستمع سفيان أحمد من القاهرة العريش رسالة، وضمنها سؤالين، في سؤاله الأول يقول: نحن نقوم ببناء مسجد بالجهود الذاتية، ونجمع زكاة المال، وننفقها في هذا المسجد، فهل هذا يجوز؟","title":"حكم صرف الزكاة في بناء المساجد ونحوها","answer":"الجواب: الصواب أنه لا تنفق الزكاة للمساجد، الصواب عند جمهور أهل العلم أن الزكاة لا تصرف في المساجد، تصرف في الأصناف الثمانية التي بينها الله، في قوله : إِنَّمَا الصَّدَقَاتُ أي: الزكوات إِنَّمَا الصَّدَقَاتُ لِلْفُقَرَاءِ وَالْمَسَاكِينِ وَالْعَامِلِينَ عَلَيْهَا وَالْمُؤَلَّفَةِ قُلُوبُهُمْ وَفِي الرِّقَابِ وَالْغَارِمِينَ وَفِي سَبِيلِ اللَّهِ وَاِبْنِ السَّبِيلِ [التوبة:60] هذه مصارف الزكاة، ليس منها المساجد، والمدارس، لا، في سبيل الله الجهاد. فالواجب على المؤمن والمؤمنة أن يتقوا الله في صرف الزكاة، وألا تصرف إلا في أهلها، لا في المساجد، ولا في الأغنياء، ولا في أولادك، ولا في آبائك، ولكن تعطيها الفقراء من إخوتك الفقراء، أو أخوالك، أو أعمامك، أو بني عمك الفقراء، أو غيرهم من الناس الفقراء المسلمين، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15125/حكم-صرف-الزكاة-في-بناء-المساجد-ونحوها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_715/nour_71506.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":16429,"question":"أحد الإخوة المستمعين رمز إلى اسمه بالحروف (ع. م) يقول في سؤال ربما يكون فيه شيء من الغرابة: كيف هي زكاة الراتب الشهري إذا لم أوفر منه شيئًا، وأنفقه على الوجه الشرعي؟","title":"حكم الزكاة في الراتب الشهري","answer":"الجواب: إذا كان الراتب لا يتوفر منه شيء، بل ينفق في وقته؛ فليس فيه زكاة، أما إذا كان يبقى شيء حتى حال عليه الحول؛ فإنه يزكى، إذا كان نصابًا... يزكى، في كل مائة اثنان ونصف، والألف خمسة وعشرون، وأما إذا كان الراتب ينفق في وقته، ولا يبقى شيء، فليس فيه زكاة، الحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15137/حكم-الزكاة-في-الراتب-الشهري","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_755/nour_75510.mp3","categories":["زكاة النقدين"]},{"id":17070,"question":"سماحة الشيخ! هذه الأخت السائلة: (ح. م. ش) من الرياض تقول: هل في الحلي الملبوس للزينة زكاة؟ وإذا وقع خلاف بين العلماء حول مسألةٍ ما بأي قولٍ آخذ وأعمل؟ أفتونا بذلك مأجورين.","title":"حكم زكاة الحلي الملبوس","answer":"الجواب: الصواب أن فيها الزكاة، الحلي من الذهب والفضة فيها الزكاة، هذا الصواب، وبعض أهل العلم لا يرى فيها الزكاة، لكن الصواب أنه فيها الزكاة، إذا بلغت النصاب، وحال عليها الحول تزكي من الذهب، أو الفضة، ربع العشر، في المائة ريالين ونص، وللذهب إذا كان مائة جنيه جنيهًا ونصف، يعني ربع العشر، هذا هو الواجب، وهذا هو الصواب. وإذا اختلف العلماء فالواجب الأخذ بالدليل، الذي معه الدليل من القرآن، أو السنة هو الذي يجب اتباعه؛ لأن الله يقول سبحانه: فَإِنْ تَنَازَعْتُمْ فِي شَيْءٍ فَرُدُّوهُ إِلَى اللَّهِ وَالرَّسُولِ [النساء:59] فإذا تنازع العلماء في شيء فالواجب الرد إلى القرآن والسنة، وقد دلت السنة على أن الحلي فيها الزكاة، وقد بين النبي ﷺ أن الذهب فيه الزكاة والفضة فيها الزكاة، ورأى امرأةً عليها حلي، فقال: أتؤدين زكاتها؟ قالت: لا، قال: أيسرك أن يسورك الله بهما يوم القيامة سوارين من نار؟ دل على وجوب الزكاة، ولما سألته أم سلمة عن حلي لها: «أهي كنزٌ؟ قال: إذا أديت زكاتها فليست بكنز. نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/15875/حكم-زكاة-الحلي-الملبوس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_588/58810.mp3","categories":["الصداق","زكاة النقدين","قضايا المرأة"]},{"id":17134,"question":"يسأل سماحتكم فيقول: ماذا أصنع في أخ، أو قريب، أو جار، وهو في حاجة إلى الزكاة، والصدقة، لكنه لا يصوم، ولا يصلي، هل يستحق مني أن أعطيه مما ذكرت؟ وجهوني، جزاكم الله خيرًا.","title":"حكم الزكاة والصدقة لقريب تارك للصلاة والصيام","answer":"الجواب: نعم، تنصحه لله، وتعطيه من مالك ما ترى أنه من أسباب دعوته للإسلام، وتركه ما هو عليه من الباطل، والزكاة لا تعطيه الزكاة، أعط الزكاة من هو معروف بالاستقامة، والإسلام من الفقراء، لكن تعطيه من مالك غير الزكاة، تؤلف قلبه؛ لعل الله يهديه، تعطيه إذا كان فقيرًا لعله يتوب إلى الله، ويصلي، ويصوم؛ لأن ترك الصلاة كفر أكبر -نعوذ بالله- في أصح قولي العلماء، حتى ولو كان ما يجحد وجوبها. أما إذا جحد وجوبها؛ كفر عند جميع العلماء، لكن إذا كان يقر بوجوبها، ولكن يتكاسل بعض الأحيان، فلا يصلي فإنه يكفر بذلك عند جمع من أهل العلم، وهو الأصح من أقوال العلماء، وقال آخرون: بل يكون عاصيًا، أتى كبيرة عظيمة، وقد أتى كفرًا دون كفر، ولا يكفر كفرًا أكبر، ولكن الصحيح من حيث الدليل أنه يكفر كفرًا أكبر. لكن إذا أعطيته من الصدقة غير الزكاة، ونصحته لله، ووجهته إلى الخير، فأنت على خير، وإذا كان كبيرًا، أو رئيسًا، أو مطاعًا في قومه، وأعطيته من الزكاة من باب التأليف؛ جاز أيضًا؛ لأن المؤلفة قلوبهم لهم حق في الزكاة. فالكافر يعطى من الزكاة إذا كان يرجى بهذا تأليف قلبه، ودخوله في الإسلام، أو إسلام نظيره، أو كف شره عن الناس، لكن لا حرج لك أن تعطيه من غير الزكاة لقول الله : لا يَنْهَاكُمُ اللَّهُ عَنِ الَّذِينَ لَمْ يُقَاتِلُوكُمْ فِي الدِّينِ وَلَمْ يُخْرِجُوكُمْ مِنْ دِيَارِكُمْ أَنْ تَبَرُّوهُمْ وَتُقْسِطُوا إِلَيْهِمْ [الممتحنة:8] فالكافر الذي لا يقاتلنا لا مانع أن نعطيه من الصدقة حتى نؤلف قلبه بذلك، ونحسن إليه لعله يتوب لعله يهتدي.  وقد ثبت في الصحيح أن أم أسماء بنت أبي بكر -رضي الله عنهما- قدمت المدينة في وقت الصلح بين النبي ﷺ وبين أهل مكة، وقت الهدنة، جاءت إلى بنتها أسماء تطلب الرفد، والمساعدة، وهي كافرة على دين قومها من أهل مكة، فسألت أسماء النبي ﷺ عن ذلك، فقال النبي ﷺ: صليها فأمرها أن تصليها وهي كافرة؛ لأن في هذا برًا لها، ولأنه وسيلة إلى إسلامها. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15961/حكم-الزكاة-والصدقة-لقريب-تارك-للصلاة-والصيام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_722/nour_72210.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":17298,"question":"تقول السائلة أم نواف من الرياض: عندي حلي جزء منها يلبس، وجزء لا يلبس، فهل عليها زكاة، علمًا بأن عندي هذا منذ عدة سنوات؟","title":"حكم زكاة الذهب المعد للزينة أو للادخار","answer":"الجواب: الصواب أنها تزكى كلها، كلها تزكى، هذا هو الصواب، السنيين الماضية إذا كنت لا تعلمين ما عليك شيء، تزكيه في المستقبل، أما إذا كنت تعلمين، قد أُفتيت أن عليك زكاة، وتساهلت أدي عن ما مضى، أما إذا كنت جاهلة فزكي عن المستقبل، من حين سمعتي الفتوى الآن، تزكي عن السنة الحاضرة، والسنوات المستقبلة، هذا هو الصواب، هذا هو الأرجح، إذا بلغ النصاب، وحال عليها الحول، والنصاب: أحد عشر جنيهًا وثلاثة أسباع جنيه، يعني: حوالي النصف، أحد عشر جنيهًا ونص، فإذا كان الذهب يبلغ هذا المقدار، أو أكثر يزكى. المقدم: أحسن الله إليكم يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16139/حكم-زكاة-الذهب-المعد-للزينة-او-للادخار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_593/59311.mp3","categories":["زكاة النقدين"]},{"id":17356,"question":"من المنامة في دولة البحرين رسالة بعث بها المستمع محمد فؤاد يقول: أرجو من سماحتكم الرأي والمشورة، أنا والحمد لله ميسور الحال ماديًا، ولدي أموال أريد إخراج الزكاة عليها، ولي أخ يعمل موظفًا في إحدى الشركات، ومتزوج، وله أولاد، ولكن مشكلته أنه موظف في إحدى الشركات، وراتبه ضعيف، وليس لديه سكن، هل لي أن أعطيه زكاة مالي ليبحث بها عن مسكن له؟ جزاكم الله خيرًا.","title":"حكم إعطاء الأخ من الزكاة لشراء مسكن له","answer":"الجواب: لا حرج في أن تعينه في السكن، تأمره أن يشتري، وإذا اشترى، وثبت الدين تسدد عنه كما تعطيه ما يساعده في حاجاته، وقضاء دينه الآخر، ما دام لا يستطيع؛ لأن راتبه ضعيف، ولا يستطيع به الأجرة، أو الشراء، لا حرج في ذلك أن تعطيه الأجرة، أو يشتري، ثم تعطيه الثمن.. لا تعطيه حتى يشتري لئلا تضيع الدراهم.. الزكاة، إذا اشترى، ولزم الدين سلم له الدين؛ لأنه فقير. نعم. المقدم: جزاكم الله خيرًا، يقول في نهاية رسالته: إن زوجته ربما تشاركه في هذا الأمر، فتدفع ثمن المنزل أيضًا لأخيهم الفقير هذا؟ الشيخ: لا بأس إذا شاركته -جزاها الله خيرًا- ما دام فقيرًا يستحق العون لفقره، أو لأنه غريم اشترى البيت ولزمه الثمن وصار غريمًا يعطى منك ومنها ما يسدد به الثمن من الزكاة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16228/حكم-اعطاء-الاخ-من-الزكاة-لشراء-مسكن-له","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_834/nour_83410.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":17369,"question":"المستمع خالد بن علي ...... من الرياض يقول: سماحة الشيخ حفظكم الله ورعاكم، هل على الزكاة التي دار عليها الحول زكاة؟","title":"حكم المال المعزول للزكاة إذا حال عليه الحول","answer":"الجواب: المال يزكى، المال إذا دار عليه الحول يزكى، وعليه أن يخرجه من حين يتم الحول، ولا تكون زكاة إلا إذا أخرجها، المال كله يزكى إذا حال عليه الحول يحسبه، ويخرج زكاته ربع العشر، أما لو عزلها يعطها الفقراء، ولا أعطها الفقراء، وحال عليها الحول يزكيها؛ لأنها ما خرجت عن ماله، لو كان عنده مثلًا أربعون ألفًا، وعزل ألفًا يعطيه للفقراء، وحال الحول وهو ما أخرجه يزكيه؛ لأنه ماله، ما راح، ما ذهب للفقراء، يزكي للألف خمسة وعشرين ريالًا زكاة الألف، ربع العشر. نعم.  المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16211/حكم-المال-المعزول-للزكاة-اذا-حال-عليه-الحول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_593/59329.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":17371,"question":"المستمعة أم نواف من الرياض تسأل وتقول: بأن لديها مبلغًا من المال، ووضعته في مصرف لشراء بيت لها، ودار عليه الحول، فهل عليه زكاة أيضًا؟","title":"حكم الأموال المودعة بالبنوك إذا حال عليها الحول","answer":"الجواب: نعم عليه الزكاة، إذا جعلته في مصرف وغيره تنتظر شراء البيت، ثم حال عليه الحول قبل أن تشتري؛ عليها الزكاة تزكيه؛ لأنه تم الحول وهو موجود، ما صرف في البيت. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16214/حكم-الاموال-المودعة-بالبنوك-اذا-حال-عليها-الحول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_593/59330.mp3","categories":["زكاة النقدين"]},{"id":17372,"question":"سماحة الشيخ هذه سائلة من الرياض لها مجموعة من الأسئلة، تبدأ هذه الأسئلة بهذا السؤال وتقول: سماحة الشيخ! لدي مجموعة من الذهب المستعمل، وأردت أن أخرج عنه الزكاة، وعندما ذهبت لوزنه وجدته يزن تسعة وسبعين جرامًا تقريبًا أي: دون النصاب البالغ خمسة وثمانين جرامًا، ولكنني في نفس اليوم الذي وزنت فيه الذهب القديم اشتريت ذهبًا آخر يزن ثلاثة وعشرين جرامًا فأصبح مجموع وزن الذهب الجديد والقديم حوالي مائة واثنين جرامًا، والسؤال هو يا سماحة الشيخ: هل أضيف مجموع وزن الذهب الذي اشتريته مع وزن القديم، وأخرج عنه الزكاة، أم أنتظر حتى يحول الحول عليه على الذهب الجديد، فأخرج الزكاة عن هذا الذهب القديم، والجديد معًا؟ أفيدوني مأجورين.","title":"شروط وجوب الزكاة في الذهب","answer":"الجواب: نعم ليس عليك زكاة في الحول الحاضر، ولكن بعد ضم الجديد إلى القديم إذا حال الحول تزكينه، أما قبل ذلك فلا؛ لأنه ناقص، لكن بعد ما يحول الحول على الجديد، والقديم تزكين والحمد لله. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16233/شروط-وجوب-الزكاة-في-الذهب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_770/nour_77010.mp3","categories":["الصداق","زكاة النقدين","قضايا المرأة"]},{"id":17375,"question":"المستمعة أم نواف من الرياض تسأل وتقول: بأن لديها مبلغًا من المال، ووضعته في مصرف لشراء بيت لها، ودار عليه الحول، فهل عليه زكاة أيضًا؟","title":"حكم الأموال المودعة بالبنوك إذا حال عليها الحول","answer":"الجواب: نعم عليه الزكاة، إذا جعلته في مصرف وغيره تنتظر شراء البيت، ثم حال عليه الحول قبل أن تشتري؛ عليها الزكاة تزكيه؛ لأنه تم الحول وهو موجود، ما صرف في البيت. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16214/حكم-الاموال-المودعة-بالبنوك-اذا-حال-عليها-الحول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_593/59330.mp3","categories":["زكاة النقدين"]},{"id":17409,"question":"هل يجوز دفع الزكاة للأقارب إذا كانوا فقراء، وهم: الأب، والأم ،والأخ، والأخت؟","title":"حكم دفع الزكاة للأقارب","answer":"الجواب: يجوز دفع الزكاة للفقراء من الأقارب صدقة، وصلة؛ لأن النبي ﷺ لما سئل قال: الصدقة على الفقير صدقة، وعلى ذي الرحم اثنتان، صدقة وصلة فلا بأس أن يعطي أخاه، وعمه، وخاله إذا كان فقيرًا من زكاته، أو صدقة تطوع، صدقة وصلة، لكن إذا كان الفقير من آبائه، أو أجداده، أو أمهاته لا؛ لأنه عليه أن ينفق عليهم، أو كانوا من ذريته لا يعطيهم من الزكاة، ينفق عليهم؛ لأن الولد أحق على أبيه أن ينفق عليه، والأم كذلك إذا كان عاجزًا وهي قادرة. المقصود: الأولاد -الذرية- لا يعطوا من الزكاة، بل ينفق عليهم أبوهم، وأمهم من ماله إذا كانوا فقراء، وهكذا الآباء، والأمهات، والأجداد، والجدات لا يعطون من الزكاة، يعطون من غير الزكاة، نعم.  المقدم: يقول يا شيخ: هل صحيح أن الزكاة لا تدفع للذي يرثك؟ الشيخ: لا ما هو بلازم، إذا كان ..... إذا كان أخًا له يعطيه من الزكاة إذا كان فقيرًا على الصحيحن لا بأس، إنما المنع في الأصول والفروع، الأصول الآباء والأمهات، والأجداد والجدات، أو الفروع كالأولاد وأولاد الأولاد، وأولاد البنات، نعم.","link":"https://binbaz.org.sa/fatwas/16269/حكم-دفع-الزكاة-للاقارب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_771/nour_77109.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":17426,"question":"مستمع من العراق هو حسن إسماعيل حسين العبيدي بعث برسالة، وضمنها قضية يقول فيها: يقع كثيرًا في هذا الزمان أن يتزوج الرجل المرأة على مهر مقدم ألف دينار مثلًا، والمؤخر عشرة آلاف دينار، ثم يترك المؤخر زمانًا طويلًا لا يؤديه إلى الزوجة، أو إلى أن يموت، فكيف الحال بالنسبة للزكاة؟","title":"حكم زكاة المؤجل من المهر","answer":"الجواب: ليس عليها زكاة إذا كان معسرًا به، إذا كان معسرًا ليس عليها زكاة، أما إذا كان مؤسرًا؛ فإن عليها أن تزكي المهر المؤجل؛ لأنها متى طلبته؛ فلها أخذه، وتأجيله برضاها، فعليها الزكاة إذا كان مؤسرًا، أما إن كان معسرًا فلا زكاة عليها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16290/حكم-زكاة-الموجل-من-المهر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_835/nour_83518.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":17465,"question":"يسأل أخونا سؤاله الثاني، فيقول: بالنسبة لزينة المرأة من الذهب، هل لها مقدار معين، وإذا كانت ذات وزن كبير مثلًا، فكيف تكون الزكاة؟ جزاكم الله خيرًا.","title":"هل لحلي المرأة مقدار معين؟ وحكم زكاته","answer":"الجواب: ليس للحلي للمرأة مقدار معين فيما نعلم، بل لا بأس أن تتزين بما يسر الله لها من الزينة من الأساور، والقلائد، والخواتم ونحو ذلك، وإذا بلغت هذه الزينة من الذهب النصاب عشرين مثقالًا، يعني: أحد عشر جنيهًا ونصف بالجنيه السعودي، وبالغرام اثنان وتسعين غرامًا، متى بلغت النصاب هذا وجب عليها الزكاة في أصح قولي العلماء، أنها تزكي في الألف خمسة وعشرون، يعني ربع العشر، هذا هو الصواب. وقال بعض أهل العلم: إن الحلي ليس فيها زكاة، والصواب أن فيها الزكاة؛ لأنه ورد في ذلك أحاديث صحيحة صريحة تدل على ذلك، والله ولي التوفيق، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/16333/هل-لحلي-المراة-مقدار-معين-وحكم-زكاته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_725/nour_72502.mp3","categories":["الصداق","زكاة النقدين","قضايا المرأة"]},{"id":17516,"question":"ما قولكم يحفظكم الله في تمويل المدارس بالزكاة لتعميرها، وإذا كانت الزكاة تصرف إلى طلبة العلم فمن باب أولى فيما أرى أن تصرف على المدارس؟","title":"حكم بناء المدارس من الزكاة","answer":"الجواب: المدارس لا تعمر بالزكاة، وهكذا المساجد وهكذا الربط لا تعمر بالزكاة، الزكاة لها مصارف بينها الله جل وعلا في قوله سبحانه: إِنَّمَا الصَّدَقَاتُ لِلْفُقَرَاءِ وَالْمَسَاكِينِ وَالْعَامِلِينَ عَلَيْهَا وَالْمُؤَلَّفَةِ قُلُوبُهُمْ وَفِي الرِّقَابِ وَالْغَارِمِينَ وَفِي سَبِيلِ اللَّهِ وَاِبْنِ السَّبِيلِ فَرِيضَةً مِنَ اللَّهِ [التوبة:60]، هؤلاء أهل الزكاة. والمقصود في سبيل الله، يعني: الجهاد، هكذا قال جمهور أهل العلم: المراد به الجهاد، فلا تصرف أموال الزكاة في تعمير المساجد ولا تعمير المدارس والربط ولا غيرها من المشاريع الخيرية كإصلاح الطرقات أو إصلاح السفن لنقل الفقراء أو ما أشبه ذلك. لكن إذا دفعها للفقراء المحاويج من الطلبة في المدرسة، إذا كان فيها فقراء.. طلبة فقراء وأعطاهم من الزكاة أو مدرسين فقراء ليس لهم رواتب يقوم بحالهم وأعطاهم من الزكاة يعينهم على تدريس أبناء المسلمين، هذا كله طيب لا حرج، فيه مصلحتان: مصلحة أنهم فقراء ومصلحة أنهم يطلبون العلم أو يعلمون الناس. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16454/حكم-بناء-المدارس-من-الزكاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_837/nour_83710.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":17608,"question":"ما حكم دفع الزكاة إلى والدتي ووالدي وأخي وأختي؟","title":"حكم دفع الزكاة إلى الوالدين والإخوة","answer":"الجواب: دفع الزكاة للوالدين والأولاد لا يجزي عند جمهور أهل العلم بل حكاه بعضهم إجماع أهل العلم، أما دفعها للأخ أو الأخت أو العم أو العمة أو الأخوال أو بقية الأقارب فلا بأس إذا كانوا فقراء إذا كانوا من أهل الزكاة، أما الوالدان تنفق عليهما من مالك غير الزكاة، وهكذا أولادك وزوجتك تنفق عليهما من مالك.. عليهم من مالك لا من الزكاة، الزكاة لا تدفع للوالدين ولا للزوجة ولا للأولاد ولكن لبقية الأقارب إذا كانوا فقراء من إخوة أو أعمام أو أخوال أو بني عم أو غيرهم لا بأس إذا كانوا فقراء. نعم. صدقة وصلة.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16544/حكم-دفع-الزكاة-الى-الوالدين-والاخوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_842/nour_84207.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":17616,"question":"ما حكم دفع الزكاة إلى والدتي ووالدي وأخي وأختي؟","title":"حكم دفع الزكاة إلى الوالدين والإخوة","answer":"الجواب: دفع الزكاة للوالدين والأولاد لا يجزي عند جمهور أهل العلم بل حكاه بعضهم إجماع أهل العلم، أما دفعها للأخ أو الأخت أو العم أو العمة أو الأخوال أو بقية الأقارب فلا بأس إذا كانوا فقراء إذا كانوا من أهل الزكاة، أما الوالدان تنفق عليهما من مالك غير الزكاة، وهكذا أولادك وزوجتك تنفق عليهما من مالك.. عليهم من مالك لا من الزكاة، الزكاة لا تدفع للوالدين ولا للزوجة ولا للأولاد ولكن لبقية الأقارب إذا كانوا فقراء من إخوة أو أعمام أو أخوال أو بني عم أو غيرهم لا بأس إذا كانوا فقراء. نعم. صدقة وصلة.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16544/حكم-دفع-الزكاة-الى-الوالدين-والاخوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_842/nour_84207.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":17836,"question":"يقول السائل: هل يزكي الإنسان على ما أنفقه على نفسه علمًا بأنه أنفقه قبل حلول الحول عليه؟","title":"حكم زكاة ما أُنفق قبل تمام الحول","answer":"الجواب: المال الذي ينفق قبل تمام الحول ما فيه زكاة سواء كان نقودًا أو غيره، فلا بد في الزكاة من تمام الحول، فإذا كان عنده نقود وأنفقها في حاجاته قبل تمام الحول لا زكاة فيها، أو عنده غنم أو إبل أو بقر فلم يتم عليها الحول ماتت مثلاً أو باعها فلا زكاة فيها ولكن يزكي ثمنها إذا حال الحول يزكي ثمنها، نعم. ثمنها إذا حال الحول. نعم.\nالمقدم: بارك الله فيكم وجزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16829/حكم-زكاة-ما-انفق-قبل-تمام-الحول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_779/nour_77909.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":17933,"question":"المستمع (م. ناجي عيسى) من جيزان بعث يسأل ويقول: إذا كان لي عند أحد الأشخاص مبلغًا من المال، ولم يستطع تسديده فهل لي أن أتركه له وأنا أنوي أنه زكاة عن جزء آخر من أموالي؟","title":"حكم احتساب دين المعسر من الزكاة","answer":"الجواب: ليس لك ذلك ولكن تمهله وتنظره حتى يوفيك إن شاء الله وتسامحه وتعفو عنه جزاك الله خيرًا، أما أن تجعل الدين الذي على المعسرين زكاة لك فلا، لا يصلح ذلك. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16955/حكم-احتساب-دين-المعسر-من-الزكاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_847/nour_84705.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":18016,"question":"المستمع محمد سعد مصري يسأل ويقول: لدي مبلغ من المال ومضى عليه عام، ولي أقارب هل يجوز أن أبعث إليهم بزكاة مالي؟ جزاكم الله خيرًا.","title":"حكم دفع الزكاة للأقارب","answer":"الجواب: إذا كانوا فقراء فلا مانع أن تبعث إليهم؛ لأن لك في ذلك صلة وصدقة، يجتمع لك اثنان، يجتمع لك في ذلك اثنتان: صدقة وصلة كما قاله النبي ﷺ، يقول النبي ﷺ: الصدقة على المسكين صدقة وعلى ذي الرحم اثنتان؛ صدقة وصلة فإذا بعثت إليهم زكاتك لشدة حاجتهم فلا حرج، وإن أنفقتها في الفقراء الذين لديك في البلد فلا حرج. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17054/حكم-دفع-الزكاة-للاقارب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_850/nour_85007.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":18021,"question":"سماحة الشيخ! كثير من إخواننا يسألون هل يجوز أن تصرف الزكاة إلى ذوي المعاصي من المسلمين؟","title":"حكم إعطاء أهل المعاصي من الزكاة","answer":"الجواب: نعم، يجوز صرفها في ذوي المعاصي من المسلمين لكن لا تصرف في الكفرة غير المؤلفة، أما المؤلفة قلوبهم من الكفرة فيعطون أيضًا من الزكاة كما قال الله جل وعلا: إِنَّمَا الصَّدَقَاتُ لِلْفُقَرَاءِ وَالْمَسَاكِينِ وَالْعَامِلِينَ عَلَيْهَا وَالْمُؤَلَّفَةِ قُلُوبُهُمْ [التوبة:60] الآية، أما العاصي فهو خير من الكافر فإن أعطاه لعل الله يهديه بسبب العطية.. الصدقة، لعل الله يهديه ويرده إلى الصواب بسبب إحسان قريبه إليه بالزكاة إذا كان فقيرًا، ولكن كونه يعتني بالطيبين المعروفين بالخير من الفقراء أولى من العصاة، هم أحق بالزكاة من العصاة، وإن صرفها لهم للعصاة يرجو بذلك أن يهديهم الله ويؤلفهم بهذا على الخير فهو مشكور مأجور. ولكن مهما كانت الحال فإنه يلتمس الأفضل فالأفضل من الفقراء من أقاربه حتى يعطيهم الزكاة ليعينهم على طاعة الله وليسد حاجتهم عن الحاجة إلى الناس، وإذا صرفها للفقير من العصاة بقصد صالح لعل الله يهديه، لعل الله يمن عليهم بالرجوع إلى الحق فهذا أمر حسن. نعم. المقدم: جزاكم الله خيرًا إذا كانوا من القبوريين أو كانوا من تاركي الصلاة؟ الشيخ: لا يعطون من الزكاة إلا إذا كان من السادة من الرؤساء الذين إذا أعطوا يرجى إسلامهم أو يرجى إسلام نظرائهم معهم، أو يرجى قوة إيمانهم إذا كانوا مسلمين فهم من المؤلفة، إذا كان يرجى في عطيته دخوله في الإسلام إن كان كافرًا أو قوة إيمانه إن كان ضعيف الإيمان، أو إسلام نظرائه إذا أعطوا، إذا أعطي قال نظراؤه سوف يعطونا إذا أسلمنا فيسلمون. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17056/حكم-اعطاء-اهل-المعاصي-من-الزكاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_850/nour_85008.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":18128,"question":"أخونا له سؤال آخر يقول: هل الزكاة تجوز في بناء وتعمير المساجد أم لا؟","title":"حكم صرف الزكاة في تعمير المساجد","answer":"الجواب: لا يجوز تعمير المساجد من الزكاة عند جمهور أهل العلم، بل هو كالإجماع من أهل العلم، وإنما أجاز هذا بعض المتأخرين، وليس عليه دليل، بل الصواب: أن الزكاة تصرف في مصارفها الثمانية، وليس من ذلك تعمير المساجد ولا المدارس ولا غيرها، بل الزكاة تصرف في الجهات الثمانية المذكورة في قوله جل وعلا: إِنَّمَا الصَّدَقَاتُ لِلْفُقَرَاءِ وَالْمَسَاكِينِ وَالْعَامِلِينَ عَلَيْهَا وَالْمُؤَلَّفَةِ قُلُوبُهُمْ وَفِي الرِّقَابِ وَالْغَارِمِينَ وَفِي سَبِيلِ اللَّهِ وَاِبْنِ السَّبِيلِ فَرِيضَةً مِنَ اللَّهِ وَاللَّهُ عَلِيمٌ حَكِيمٌ [التوبة:60]. قال جمهور أهل العلم: معنى قوله: في سبيل الله: يعني: الجهاد، وبعض المتأخرين قال: في سبيل الله يعم الجهاد والمساجد والمدارس والربط.. وأشباه ذلك من المشاريع الخيرية كالقناطر وإصلاح الطرق أو نحو ذلك، ولكن الذي عليه أكثر أهل العلم وهو الأرجح: أن في سبيل الله يخص الجهاد والدعوة إلى الله سبحانه؛ لأنها من الجهاد، أما المساجد والمدارس والقناطر والربط.. ونحو ذلك، هذه تعمر من بيت المال، ومن مساعدة المسلمين ومساهمة المسلمين؛ لأنها مصالح عامة. نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/17180/حكم-صرف-الزكاة-في-تعمير-المساجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_852/nour_85205.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":18248,"question":"هذا سائل لم يذكر الاسم في هذه الرسالة يقول سماحة الشيخ: لي أولاد أخ من أبي غير شقيق هل يجوز أن أصرف لهم الزكاة من باب: أَوْلَى لَكَ فَأَوْلَى[القيامة:34] وهل يجوز أن أعمل لهم راتبًا شهريًا من هذه الزكاة وليس دفعة واحدة، أي: على مدار العام، أفيدونا سماحة الشيخ؟الشيخ: أعد أعد.المقدم: يقول: لي أولاد أخ من أبي غير شقيق، هل يجوز أن أصرف لهم الزكاة؟ وهل يجوز أن أعمل لهم راتبًا شهريًا من هذه الزكاة وليس دفعة واحدة أي: على مدار العام مأجورين؟","title":"حكم دفع الزكاة إلى أولاد الأخ غير الشقيق","answer":"الجواب: إذا كانوا فقراء فلا بأس، وليسوا في حضانتك، ليسوا في عيالك، بل هم مستقلون، وهم فقراء لا مانع أن يعطوا من الزكاة. أما ترتيبها لهم فلا بأس إذا كان معجلة، أما تأخيرها لا، الواجب البدار بصرف الزكاة، لكن إذا كانت معجلة تعجلها لهم قبل وقتها فلا بأس، أما التأخير لا، بل متى حال الحول وجب صرف الزكاة فيهم وفي غيرهم، من المستحقين للزكاة، وعدم تأجيلها. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/17297/حكم-دفع-الزكاة-الى-اولاد-الاخ-غير-الشقيق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_783/nour_78304.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":18281,"question":"الاسم: بشير الطاهر جبريل، من السودان، يسأل الأخ بشير ويقول: لي صديق طلب مني مبلغًا قدره ثلاثة آلاف وثمانمائة جنيه، وقال لي: أسلمك هذا المبلغ في خلال شهر أو شهرين، وأنا سلمته ذلكم المبلغ في عام ستة وثمانين، والآن نحن في عام ثمانية وثمانين، ولم أستلم المبلغ؛ هل تجب علي زكاته؟ أو كيف أتصرف؟","title":"هل يجب إخراج الزكاة على الدين؟","answer":"الجواب: هذا فيه تفصيل: إذا كان الذي عنده المبلغ موسرًا، ولو طلبته المال لأعطاك فإنك تزكيه، أما إذا كان يماطلك، أو معسرًا فلا زكاة عليك، إذا كنت طلبته فأبى وماطل حتى مضت المدة، فإنه لا زكاة عليك، أما إذا كان التأخير منك وإلا هو مليء فعليك الزكاة لكل الأعوام، أما إذا كان مماطلًا أو معسرًا فلا زكاة عليك. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17330/هل-يجب-اخراج-الزكاة-على-الدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_910/nour_91017.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":18351,"question":"السائل الذي رمز لاسمه بـ (أ. أ)، يقول: هل يجوز الصرف على المساجد، وذلك لترميمها وفرشها الفرش الطيب ونحو ذلك وذلك من الزكاة؟","title":"حكم الصرف على المساجد من الزكاة","answer":"الجواب: المساجد ليست من مصارف الزكاة لا بناؤها، ولا فرشها، مصارف الزكاة وضحها الرب جل وعلا في قوله سبحانه: إِنَّمَا الصَّدَقَاتُ لِلْفُقَرَاءِ وَالْمَسَاكِينِ وَالْعَامِلِينَ عَلَيْهَا وَالْمُؤَلَّفَةِ قُلُوبُهُمْ وَفِي الرِّقَابِ وَالْغَارِمِينَ وَفِي سَبِيلِ اللَّهِ وَاِبْنِ السَّبِيلِ[التوبة:60]. فليست المساجد من مصارف الزكاة لا بناء ولا فرشًا ولا غير ذلك، وفي سبيل الله يعني: الجهاد، فالزكاة لا تصرف في المساجد لا في تعميرها، ولا في فرشها. نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17409/حكم-الصرف-على-المساجد-من-الزكاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_783/nour_78319.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":18373,"question":"سماحة الشيخ! السائل: (أ. ش) من حلب يقول: هل تجوز الزكاة على زوج البنت، أو على زوجة الولد إذا كانوا بحاجة؟","title":"حكم دفع الزكاة لزوج البنت","answer":"الجواب: إذا كانوا فقراء لا بأس، إذا كانوا فقراء زوج البنت، وزوج الخالة، وزوج الأخت. نعم.","link":"https://binbaz.org.sa/fatwas/17433/حكم-دفع-الزكاة-لزوج-البنت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_913/nour_91328.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":18480,"question":"في آخر أسئلة هذا السائل سمير يقول في السؤال الأخير: هل يصح أن أخرج عن زوجتي زكاة حليها التي تلبسه للزينة؟ وما القول الراجح في ذلك سماحة الشيخ؟","title":"حكم إخراج الزوج الزكاة عن زوجته","answer":"الجواب: لا بأس أن تخرج عنها الزكاة إذا رضيت، إذا سمحت لك بإخراج زكاة حليها لا بأس، والراجح أن الحلي فيها زكاة هذا الراجح، إذا بلغت النصاب وحال عليها الحول من الذهب والفضة فالراجح أن فيها الزكاة، هذا هو الأرجح من أقوال العلماء، وإذا سمحت لزوجها، أو لأبيها، أو لأخيها؛ أن يخرج الزكاة من ماله عنها فلا بأس.\nالمقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17567/حكم-اخراج-الزوج-الزكاة-عن-زوجته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_785/nour_78516.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":18541,"question":"هل تجب الزكاة للذهب الذي أعد للزينة واللبس؟ علمًا بأنه مع مرور الزمن على هذا الحلي تبيعه لتستبدل غيره؟جزاكم الله خيرًا.","title":"هل تجب الزكاة للذهب الذي أعد للزينة واللبس؟","answer":"الجواب: الصواب أن فيه زكاة، الحلي المعد للزينة واللبس فيه خلاف بين العلماء، ولكن الصواب الذي نفتي به أن فيه الزكاة، كل ما حال عليه الحول، إذا بلغ النصاب، وهو أحد عشر جنيه ونصف، إذا كان من الذهب في كل ألف خمسة وعشرون، ربع العشر، هذا هو الصواب الذي دلت عليه السنة سنة الرسول ﷺ. وبعض أهل العلم يرى أنه إذا كان معدًا للبس لا زكاة فيه، ولكن هذا قول مرجوح، والصواب أن فيه الزكاة؛ لأنه ﷺ أمر امرأة عليها بعض الأسورة، بما يدل على وجوب الزكاة، قال لها لما رأى عليها سوارين: أتؤدين زكاة هذا؟ قالت: لا. قال: أيسرك أن يسورك الله بهما يوم القيامة سوارين من نار فألقتهما، وقالت: هما لله ولرسوله.  فالوعيد على عدم الزكاة بالنار يدل على وجوب الزكاة، وكذلك قال لأم سلمة لما سألته وكانت تلبس أوضاحًا من ذهب: أكنز هذا؟ قال: ما بلغ أن يزكى فزكي فليس بكنز فجعل الحلية ليست بكنز إذا أديت الزكاة. المقدم: جزاكم الله خيرًا. كونها تلبسه لفترة ثم تبيعه لتستبدله بغيره هل يسقط هذا الزكاة؟ الشيخ: الصواب إذا باعته قبل تمام الحول ما عليه زكاة، لكن إذا عادت وشرت يبتدي الحول، نعم ...، لكن كانت الدراهم عندها فالزكاة باقية، إذا كانت باعت الذهب بالدراهم؛ فالزكاة باقية في الدراهم على الحول السابق تزكيها، لكن لو باعت الحلي واشترت بالدراهم حاجات أخرى مثل سيارة للركوب، مثل ملابس، مثل فرش للبيت؛ انقطع الحول، صار ما فيه زكاة؛ لأنه ما هو للتجارة، فإذا عاد..... أخرى يكون فيها الزكاة إذا حال عليها الحول. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17642/هل-تجب-الزكاة-للذهب-الذي-اعد-للزينة-واللبس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_733/nour_73314.mp3","categories":["زكاة النقدين"]},{"id":18553,"question":"يسأل أخونا ويقول: ما هي الكيفية التي يجب أن أزكي بها راتبي الشهري، مع العلم بأني موظف، وليس لدي من الأموال غير هذا الراتب الذي أتقاضاه، هل أزكي كل راتب ساعة استلامه شهرًا بشهر كزكاة الزروع والثمار، أم أنتظر حتى يحول الحول على كل شهر، ثم أزكي رصيده في نفس الشهر من العام المقبل أم ماذا أفعل؟جزاكم الله خيرًا.","title":"كيفية زكاة الراتب الشهري","answer":"الجواب: الواجب أن يزكى الراتب وغير الراتب إذا حال حوله، فإذا حصل لك في رمضان عشرة آلاف ريال، وبقيت إلى الحول زكيتها، أو بقي نصفها زكيت الباقي، وهكذا في شوال، وهكذا في ذي القعدة، وهكذا في ذي الحجة، كل شهر بشهره، إذا حال حوله تزكي ما بقي منه، وتضبط الأمور بالكتابة حتى تحفظ ما يجب عليك، هذا الواجب عليك، ولا يجب إخراج الزكاة من حين وصول مرتبك إليك، لا، الواجب إذا حال الحول كما قال ابن عمر وغيره: «من استفاد مالًا فلا زكاة عليه حتى يحول عليه الحول»، وجاء مرفوعًا عن النبي ﷺ من حديث علي : لا زكاة في مال حتى يحول عليه الحول هذا هو الصواب. أما قول من قال: إنه يزكي ما حصل له من هبة، أو مرتب من حين استلامه بدون حول؛ فهذا قول ضعيف مرجوح، والصواب: أنه لا يجب في الإرث ولا فيما يهدى إليك، ولا في مرتبك زكاة حتى يحول الحول على ذلك، على نصيبك من المال في الإرث إذا كان نقود من الذهب والفضة، حتى يحول الحول. وهكذا لا يجب عليك الزكاة فيما وهبك أحد إخوانك، أو أهدى إليك أحد إخوانك ليس عليك زكاتها حتى يحول عليها الحول، فإذا أنفقته قبل ذلك فلا شيء عليك، وهكذا المرتب إنما تجب زكاته إذا حال عليه الحول، نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/17661/كيفية-زكاة-الراتب-الشهري","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_916/nour_91604.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":18573,"question":"في آخر أسئلة هذا السائل -أبو محمد- يقول: سمعت في شهر رمضان من يقول: بأن الواجب في الزكاة هو اثنين ونص، وأن من يدفع ثلاثة بالمائة، فإنه يكون محادًا لله أو محادًا لله ولرسوله، وأنا في بعض الأحيان أدفع أكثر من اثنين ونص، وليس قصدي المحادة لله ولا للرسول، وإنما قصدي الرغبة في الخير -إن شاء الله- فما رأي سماحتكم في ذلك؟","title":"حكم من دفع زيادة عن الواجب في الزكاة","answer":"الجواب: الواجب اثنان ونصف في المائة، يعني: ربع العشر في الزكاة، خمسة وعشرون في الألف، واحد ألف في أربعين ألفًا، ربع العشر، هذا الواجب، وإذا أحب يخرج الزيادة تطوعًا منه مأجور، ولا حرج في ذلك. أما إذا كان يعتقد أن هذا الربع لا يجزئ، وأن الشرع ناقص؛ هذا غلط، الشرع كامل والحمد لله، فإذا اعتقد أن الشرع ناقص، وأنه يريد أزيد مما شرع الله، يظن أن الشرع ناقص هذا غلط كبير. أما إذا أراد التطوع والزيادة في الفضل فهذا مأجور، ولا بأس، فإذا كانت عليه زكاة ألف وأخرج ألفين، ألف تطوع وألف زكاة؛ فهذا مأجور، وله فضل عظيم، وأجر عظيم، وهكذا إذا كان عليه خمسة آلاف أو أكثر، وأخرج عشرة كله طيب. المقصود: إذا كانت الزيادة عن رغبة في الخير، وعن مرحمة للفقراء، وأنه يعلم أن ما شرعه الله كافٍ؛ فلا حرج، مأجور، ومثاب، ومخلوف عليه. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/17689/حكم-من-دفع-زيادة-عن-الواجب-في-الزكاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_786/nour_78617.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":18574,"question":"في آخر أسئلة هذا السائل -أبو محمد- يقول: سمعت في شهر رمضان من يقول: بأن الواجب في الزكاة هو اثنين ونص، وأن من يدفع ثلاثة بالمائة، فإنه يكون محادًا لله أو محادًا لله ولرسوله، وأنا في بعض الأحيان أدفع أكثر من اثنين ونص، وليس قصدي المحادة لله ولا للرسول، وإنما قصدي الرغبة في الخير -إن شاء الله- فما رأي سماحتكم في ذلك؟","title":"حكم من دفع زيادة عن الواجب في الزكاة","answer":"الجواب: الواجب اثنان ونصف في المائة، يعني: ربع العشر في الزكاة، خمسة وعشرون في الألف، واحد ألف في أربعين ألفًا، ربع العشر، هذا الواجب، وإذا أحب يخرج الزيادة تطوعًا منه مأجور، ولا حرج في ذلك. أما إذا كان يعتقد أن هذا الربع لا يجزئ، وأن الشرع ناقص؛ هذا غلط، الشرع كامل والحمد لله، فإذا اعتقد أن الشرع ناقص، وأنه يريد أزيد مما شرع الله، يظن أن الشرع ناقص هذا غلط كبير. أما إذا أراد التطوع والزيادة في الفضل فهذا مأجور، ولا بأس، فإذا كانت عليه زكاة ألف وأخرج ألفين، ألف تطوع وألف زكاة؛ فهذا مأجور، وله فضل عظيم، وأجر عظيم، وهكذا إذا كان عليه خمسة آلاف أو أكثر، وأخرج عشرة كله طيب. المقصود: إذا كانت الزيادة عن رغبة في الخير، وعن مرحمة للفقراء، وأنه يعلم أن ما شرعه الله كافٍ؛ فلا حرج، مأجور، ومثاب، ومخلوف عليه. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/17689/حكم-من-دفع-زيادة-عن-الواجب-في-الزكاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_786/nour_78617.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":18736,"question":"يقول السائل في رسالته أو في سؤاله: هل يجوز إخراج زكاة المال في كل شهر، فقد أفتى لنا بعض الإخوة في ذلك؟ مأجورين.","title":"حكم إخراج زكاة المال في كل شهر","answer":"الجواب: نعم، إذا رأى المصلحة في ذلك عجلها، إذا رأى المصلحة في ذلك، لا بأس، قد كان النبي ﷺ يتعجل من العباس بعض زكاته . فالمقصود: أنه إذا رأى التعجيل فيه مصلحة فهو مسارعة إلى الخيرات، مثل زكاته التي في رمضان، ولكن رأى فقراء محتاجين وعجلها لهم في رجب أو في جمادى فهو مأجور لا بأس، نعم. المقدم: أليس شرطًا يا سماحة الشيخ أن يحول عليه الحول؟ الشيخ: ما هو بشرط، لا. المقدم: ليس شرطًا. الشيخ: شرط للوجوب، لا تجب عليه حتى يحول عليه الحول، لكن لو عجلها قبل أن يحول طلبًا للفضل فهو مأجور. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17861/حكم-اخراج-زكاة-المال-في-كل-شهر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_789/nour_78912.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":18797,"question":"يقول هذا السائل (أ. أ) الرياض أقرضت رجلًا مبلغًا من المال، وقد تأخر عنده هذا المبلغ، وهو كامل النصاب، فهل أقوم بتزكيته؟","title":"حكم إخراج الدائن زكاة ماله الذي في ذمة المدين","answer":"الجواب: إذا كان الذي عليه المال مليء متى طلبته أعطاك عليك الزكاة، أما إن كان معسرًا، أو مماطلًا طلبته، ولم يعطك مماطلًا فليس عليك الزكاة؛ لأنك غير قادر عليه، أما إذا كان مليًا وليس بمماطل، ولكن أنت تساهلت فإنك تزكي. أما الديون على المعسرين فلا زكاة فيها حتى تقبضها، وهكذا المماطل الذي تطلبه حقك ولا يعطيك فليس عليك زكاته حتى تقبض وتبتدي حولًا، نعم. المقدم: يزكي عنه كم سنة -يا شيخ- إذا كان مر عليه أكثر من سنة؟ الشيخ: إذا كان على معسر ما فيه زكاة، أو على مماطل لم يعطه حقه لا زكاة فيه، أما إذا كان مليء، ولكن هو يتساهل يزكيه جميع السنين. المقدم: جميع السنين؟ الشيخ: نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17930/حكم-اخراج-الداىن-زكاة-ماله-الذي-في-ذمة-المدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_791/nour_79115.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":18818,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين، سوداني مقيم بالطائف واسمه (ع. س. أبو موسى) أخونا كتب رسالته بلهجته العامية، فهمت منها ما يلي: يسأل عن صرف الزكاة إلى الأخت من الأب وأبنائها، وإلى الأب وإخواني من أبي، ويسأل أيضًا عن بعث الزكاة إلى بلده لكثرة الفقراء هناك.","title":"صرف الزكاة للأقربين","answer":"الجواب: لا مانع من صرف الزكاة لإخوتك الذكور والإناث إذا كانوا محاويج فقراء، هذا فيه الصلة والزكاة جميعًا صلة وصدقة، يقول النبي ﷺ: الصدقة على الفقير صدقة، وعلى ذي الرحم اثنتان صدقة وصلة فإذا كان أخو الإنسان فقيرًا أو أخته فقيرة أو عمه أو خاله أو نحو ذلك فالصدقة فيهم أولى من غيرهم؛ لأنها تجمع أمرين: الصلة والصدقة جميعًا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17941/صرف-الزكاة-للاقربين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_921/nour_92104.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":18828,"question":"أعطيت زكاة مالي لإخوتي الذين ليس لهم القدرة على تكاليف الزواج هذه الأيام من سكن وغيره؛ وذلك حتى يستطيعوا التزوج، فهل يجزئ ذلك؟","title":"حكم إعطاء الزكاة للإخوة لإعانتهم على الزواج","answer":"الجواب: نعم، صدقة الإخوان والمساعدة في الزواج إذا كانوا فقراء من أفضل القرب، ولا بأس أن يكون من الزكاة، إذا كانوا فقراء مثل ما قلت، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17961/حكم-اعطاء-الزكاة-للاخوة-لاعانتهم-على-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_736/nour_73606.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":18889,"question":"هل يمكن أن نعطي الزكاة أو الصدقة للخادمة؟","title":"حكم إعطاء الخادمة الزكاة أو الصدقة","answer":"الجواب: إذا كانت فقيرة تعلم حالها، وأعطيتها من الزكاة لا بأس، لكن الاحتياط أن يكفيها راتبها، وتعطي ناسًا تعرف حالهم وفقرهم، تواسيهم تحسن إليهم. أما الخادمة فقد يختلف في أمرها، قد لا تعلم حالها كما ينبغي، ولعل في راتبها ما يكفي، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/18031/حكم-اعطاء-الخادمة-الزكاة-او-الصدقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_736/nour_73619.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":18910,"question":"رسالة وصلت إلى البرنامج من مدينة تمير، وباعثها الأخ راجح بن حمد المانع الفيصل، أخونا يقول: درسنا في الفقه أن زكاة النقدين الذهب والفضة هي: في الذهب عشرون مثقالًا، أي: ما يعادل اثني عشر جنيه، ونصاب الفضة مائتا درهم أي: ما يعادل ستة وخمسين ريالًا سعوديًا. فأرجو التوضيح لهذه المسألة، وهل الريال المراد به الريال الورقي أم الفضة؟ وكذلك توضيح الذهب بالجرام وأقل النصاب في ذلك أو بالورق السعودي؟جزاكم الله خيرًا.","title":"نصاب الذهب والفضة","answer":"الجواب: أما الذهب فالنصاب عشرون مثقالًا، الذهب نصابه عشرون مثقالًا، وبالجرام اثنان وتسعون جرامًا، وبالذهب والجنيه السعودي أحد عشر جنيه ونصف، أحد عشر جنيه وثلاثة أسباع يعني: نصف إلا يسيرًا، فأحد عشر جنيه ونصف هذا هو النصاب بالجنيه السعودي، وبالمثاقيل عشرون مثقالًا، وبالجرام اثنان وتسعون جرامًا، هذا هو النصاب، ما كان أقل من هذا فليس فيه زكاة. أما الفضة فهي مائة وأربعون مثقالًا، وبالريال السعودي ستة وخمسون ريالًا من الفضة، أو ما يعادلها من الورق، وبالريال في عهد النبي ﷺ مائتا درهم، وفي عهدنا ستة وخمسون ريالًا من الفضة، وما يقوم مقامها من الورق والعمل الأخرى، هذا هو النصاب، فإذا حال عليها الحول وجبت فيه الزكاة ربع العشر، في المائة اثنان ونصف، وفي الألف خمسة وعشرون من الذهب والفضة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18047/نصاب-الذهب-والفضة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_923/nour_92310.mp3","categories":["زكاة النقدين"]},{"id":19029,"question":"تقول: أريد أن أعرف بالضبط الزكاة على الذهب، كم هي من الجرامات؟ وهل أدفع كل سنة؟ أم مرة واحدة تجزئ؟ جزاكم الله خيرًا.","title":"زكاة الذهب والفضة ونصابهما","answer":"الجواب: الزكاة تكرر كل سنة، والواجب ربع العشر في الذهب والفضة جميعًا، في الألف خمسة وعشرون، والمائة اثنان ونصف، ومائة الألف ألفان ونصف - ألفان وخمسمائة يعني -. وبالجرام.. الواجب في الزكاة ربع العشر بالجرام وغير الجرام، لكن نصاب الذهب بالجرام اثنان وتسعون جرام، وبالمثاقيل عشرين مثقال، وبالجنيه إحدى عشر جنيه ونص - جنيه سعودي - إحدى عشر جنيه ونص سعودي. مقداره بالجرام اثنان وتسعون جرام، بالمثاقيل عشرون مثقالاً. أما الفضة فمائة وأربعون مثقالًا، ومقداره بالريال السعودي الفضة ستة وخمسون ريال من الفضة، فما يعادل ستة وخمسين ريال من العمل يكون نصابًا، يكون أول نصاب، وما يعادل أحد عشر جنيه ونص من الذهب يكون نصابًا. وهكذا عروض التجارة، من أواني أو ملابس أو فرش أو غير ذلك التي يراد بيعها، معدل البيع إذا بلغت قيمتها ستة وخمسين ريال فضة، أو بلغت قيمتها أحد عشر جنيه سعودي ونص؛ فإن فيها الزكاة كلما حال عليها الحول، ما دامت منوية للتجارة يعني: مقصودًا بها التجارة والبيع والشراء، سواء كانت أواني، أو أراضي، أو ملابس أو غير ذلك. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18233/زكاة-الذهب-والفضة-ونصابهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_796/nour_79610.mp3","categories":["زكاة النقدين"]},{"id":19065,"question":"سماحة الشيخ هذا سائل يقول: ما معنى \"كل قرض جر نفعًا فهو ربا\"؟","title":"معنى قول: (كل قرض جر نفعًا فهو ربا)","answer":"الجواب: كل قرض يجر عليك نفعًا إذا أقرضت زيد ألف ريال وأعطاك كسوة، أو أهدى إليك فاكهة، أو ما أشبه ذلك، هذا من الربا، أو أسكنك في البيت بدون أجرة، أو أعطاك السيارة تستعملها بدون أجرة، هذا جر ربا هذا من الربا؛ لأن ما أعطاك إلا من أجل القرض. نعم. المقدم: أحسن الله إليكم، وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/18272/معنى-قول-كل-قرض-جر-نفعا-فهو-ربا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_883/nour_88329.mp3","categories":["الربا والصرف","زكاة النقدين","قضايا المرأة","شروح الحديث"]},{"id":19221,"question":"إحدى الأخوات بعثت تسأل سماحتكم فتقول: أملك خمسة وثمانين جرامًا من الذهب، ما هو مقدار الزكاة؟ وجهوني حول هذا الموضوع جزاكم الله خيرًا.","title":"حكم الزكاة في خمسة وثمانين جرامًا من الذهب ومقدارها","answer":"الجواب: الزكاة ربع العشر، في أربعين جنيه واحد جنيه، فإذا كنت تملكين خمسًا وثمانين جرام؛ فهو في الأصح أقل من النصاب قليلًا، فإن أديت الزكاة عنه احتياطًا؛ لأن بعض أهل العلم يقول: إن الخمسة والثمانين تبلغ النصاب، وقد حررنا هذا فوجدنا النصاب اثنين وتسعين إلا كسرًا يسيرًا، اثنين وتسعين غرام، يعني: عشرين مثقال، أحد عشر جنيه ونصف سعودي، فإذا بلغت الذهب عندك هذا المقدار أحد عشر جنيه سعودي ونصف؛ فأدي زكاته ربع العشر، يعني: جنيه واحد من أربعين جنيه، ونصف الجنيه من عشرين جنيه هذا ربع العشر، أما خمسة وثمانون غرام فهي فيما حررنا أقل من النصاب، وإن أديت زكاتها احتياطًا فحسن. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/18409/حكم-الزكاة-في-خمسة-وثمانين-جراما-من-الذهب-ومقدارها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_738/nour_73802.mp3","categories":["زكاة النقدين"]},{"id":19324,"question":"المستمع (ف. ع. أ) بعث برسالة يقول فيها: إنني أعمل بمزرعة، وأقتضي راتبًا شهريًا، فهل هذا المال الذي أجمعه تجب فيه الزكاة، مع العلم بأنني شاب في سن الزواج، وفي احتياج هذا المال؛ لأنني أقوم حاليًا ببناء منزل تمهيدًا للزواج، ولا أحد يساعدني من أسرتي؟ جزاكم الله خيرًا.","title":"حكم إخراج الزكاة عن الراتب","answer":"الجواب: عليك أن تزكي ما جمعت إذا حال عليه الحول، كلما حال الحول على شيء تزكيه، ولو أنك أعددته للزواج أو لبناء مسكن أو غير ذلك، إذا حال الحول على الراتب الأول زكه، وهكذا الراتب الثاني، وهكذا، كلما حال الحول على راتب زكه بربع العشر في المائة ريالان ونصف في الألف خمسة وعشرون، وأبشر بالخير؛ فالزكاة طهرة لك ولمالك، ومن أسباب النماء والبركة والحفظ.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18521/حكم-اخراج-الزكاة-عن-الراتب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_739/nour_73917.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":19325,"question":"من المدينة المنورة رسالة باعثها مستمع من هناك يقول: (ح. س. ن) أخونا يقول: هل تجوز الزكاة لأسرة فقيرة أحد أفرادها لا يصلي؟ وهو يأكل معهم؟ فإذا لم تجب فهل يجب إعادة الزكاة كلها؟ أم جزء منها بنسبة هذا الفرد إلى عدد أسرته؟","title":"حكم إخراج الزكاة لأسرة فقيرة أحد أفرادها لا يصلي","answer":"الجواب: الزكاة يعطاها من يستحقها من المسلمين، ولو أكل معهم شخص آخر غير مسلم، المقصود يعطاها المسلمون والفقراء المحتاجون إليها، ولا يضرهم كونه يوجد بينهم من قد يحكم بكفره، إذا كانت معطاة ومسلمة للمسلم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18522/حكم-اخراج-الزكاة-لاسرة-فقيرة-احد-افرادها-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_739/nour_73918.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":19335,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يسأل جمعًا من الأسئلة، وهذا المستمع لم يذكر اسمه إنما أسئلته كالتالي يقول في سؤاله الأول: هل تجب الزكاة على المال المستودع في البنك لحاجته عند الضرورة وليس للتجارة؟","title":"حكم زكاة المال المدخر في البنك","answer":"الجواب: نعم، تجب الزكاة في المال المودع في البنوك أو غير البنوك إذا بلغ النصاب، وحال عليه الحول سواءً كان مودعًا في البنك، أو عند بعض الثقات، أو في أي مكان.","link":"https://binbaz.org.sa/fatwas/18551/حكم-زكاة-المال-المدخر-في-البنك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_941/nour_94110.mp3","categories":["زكاة النقدين"]},{"id":19431,"question":"إذا تصدق رجل بمبلغ معين للأيتام شهريًا، ولم يخرج زكاة ماله، مع العلم أن الصدقة التي يتصدق بها أكبر من الزكاة المستحقة بكثير، فهل يجزيه ذلك عن الزكاة حتى إذا لم ينو أن تكون هذه الصدقة هي زكاة ماله؟","title":"وجوب استحضار النية عند إخراج الزكاة","answer":"الجواب: إذا كان الأيتام فقراء، ونوى ما صرفه فيهم زكاة؛ فلا بأس، أما إذا كان ما نوى، وإنما تصدق عليهم، وأنفق عليهم احتسابًا؛ ولم ينوه زكاة، فإنها لا تجزئ لا تكون زكاة إلا بالنية لقول المصطفى عليه الصلاة والسلام: إنما الأعمال بالنيات وإنما لكل امرئ ما نوى. فإذا أعطى فقيرًا أو يتيمًا فقيرًا مالًا ولم ينوه زكاة، وإنما نواه صدقة، ومساعدة؛ فإنه لا يكون من الزكاة، ولا يحسب من الزكاة إلا إذا نوى ما صرفه لليتيم الفقير أو للسائل الفقير إذا نواه زكاة صار زكاة، الأعمال بالنيات، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18680/وجوب-استحضار-النية-عند-اخراج-الزكاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_944/nour_94403.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":19437,"question":"مستمع بعث برسالة ضمنها مجموعة من الأسئلة هو الأخ (ح. أ. ي. ع) من جدة، أخونا يقول في سؤاله الأول: لقد توفي والدي منذ زمن ونحن ستة إخوة، ولقد رزقنا الله بمبلغ لا بأس به من المال، وهو عندنا منذ سنة، مع العلم أنه لا يدر علينا ربحًا، بل هو محفوظ هل عليه زكاة؟ وما هو نصاب زكاة المال أو العملة الورقية؟ جزاكم الله خيرًا.","title":"ما نصاب زكاة المال (العملة الورقية)؟","answer":"الجواب: نعم، إذا كان حال عليه الحول فعليكم الزكاة، سواء كان حصل لكم بالإرث أو بغير الإرث، والواجب ربع العشر، في كل ألف خمسة وعشرون، وفي عشرين ألف خمسون[1]، وهكذا ربع العشر، في الألف الواحد خمسة وعشرون ريال، يعني: ربع العشر، وفي الألفين خمسون وهكذا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18672/ما-نصاب-زكاة-المال-العملة-الورقية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_938/nour_93802.mp3","categories":["زكاة النقدين"]},{"id":19438,"question":"مستمع بعث برسالة يقول فيها: الراسل عبد الناصر أحمد عامر والجنسية مصري، ويعمل عامل بالقصيم في بريدة، أخونا يقول: أنا أملك مبلغ حوالي عشرين ألف ريال، منها عشرة آلاف سلف لدى شخص، وعشرة آلاف حسابي في البنك، وكل من المبلغين مر عليهم عام، وأنا أحتاجهم لكي أعمر بيت لأولادي بمصر، وأنا لم أنزل من عامين لمصر من أجل توفير هذا المبلغ لأولادي، رجاء علمي هل يصح عليهم الزكاة أم لا؟","title":"حكم زكاة المال المدخر والدين","answer":"الجواب: نعم، العشرة المحفوظة في البنك عليك زكاتها ربع العشر وربع العشر مائتان وخمسون من عشرة الآلاف مائتان وخمسون؛ لأن عشرها ألف وربعه مائتان وخمسون. أما التي عند بعض الإخوان على سبيل القرض فهذا إن كان مؤسرًا ليس بمماطل بل متى طلبتها أعطاك إياها فعليك زكاتها أيضًا مثل العشرة الأخرى مائتان وخمسون، أما إن كان معسرًا عاجزًا عنها لا يستطيع ردها إليك أو مماطلًا لا يبادر بتسليمها لك، بل يماطلك ويؤذيك ولا يعطيك إياها فإنك لا تلزمك زكاتها حتى تقبضها، فإذا قبضتها فاستقبل بها حولًا جديدًا، وإن زكيتها عن عام واحد عن العام فلا بأس لكن لا يجب عليك، فإذا زكيتها واحتطت فلا بأس. المقصود أنه لا زكاة عليك إذا كان معسرًا أو مماطلًا أما إن كان موسرًا متى طلبتها أعطاك فإن عليك زكاتها كالعشرة التي في البنك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18679/حكم-زكاة-المال-المدخر-والدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_938/nour_93805.mp3","categories":["زكاة النقدين"]},{"id":19440,"question":"يسأل أخونا ويقول: وهل يصح أن أرسل الزكاة إلى إخوتي في مصر؛ لأنهم في الحاجة؟","title":"حكم إرسال المزكي زكاته إلى إخوته المحاويج","answer":"الجواب: لا حرج إن شاء الله لا بأس ، نعم، ترسلها إلى إخوتك المحاويج لا بأس، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18681/حكم-ارسال-المزكي-زكاته-الى-اخوته-المحاويج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_938/nour_93806.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":19479,"question":"هذا سائل يقول: سماحة الشيخ! رجل يرغب في الزواج وهو غير مستطيع، هل تجوز له الزكاة ليتمكن من الزواج؟","title":"حكم صرف الزكاة لمن عجز عن الزواج","answer":"الجواب: نعم، العاجزون عن الزواج يعطون من الزكاة ما يعينهم على الزواج، إذا كانوا عاجزين يشرع أن يعطوا من الزكاة ما يعينهم على الزواج. نعم.","link":"https://binbaz.org.sa/fatwas/18726/حكم-صرف-الزكاة-لمن-عجز-عن-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_939/nour_93914.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":19481,"question":"هل تجوز الزكاة للأخ والعم والخال والأخت والعمة، إذا كانوا في حاجة للزكاة؟","title":"حكم دفع الزكاة للإخوة والأعمام والأخوال","answer":"الجواب: نعم إذا كان أخوه مستقلًا ليس في نفقته، وهكذا الخالة والعمة مستقلين يعطون من الزكاة إذا كانوا فقراء، صدقة وصلة، الزكاة فيهم صدقة وصلة في العم والخال والأخ وابن الأخ وابن الخال إذا كانوا فقراء مستقلين. نعم.","link":"https://binbaz.org.sa/fatwas/18727/حكم-دفع-الزكاة-للاخوة-والاعمام-والاخوال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_939/nour_93915.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]}]
